local config = {
  str_homestory_800601001_0_dialog_content = "カレン…",
  str_homestory_800601001_1_dialog_content = "あら、PlayerName。",
  str_homestory_800601001_2_dialog_content = "カレン、何してるの？",
  str_homestory_800601001_3_dialog_content = "ただのひとり言よ。",
  str_homestory_800601001_4_dialog_content = "「願い事」をしてるんでしょ？",
  str_homestory_800601001_5_dialog_content = "…",
  str_homestory_800601001_6_dialog_content = "そうよ、おかしな話よね。",
  str_homestory_800601001_7_dialog_content = "そんなことないよ。\n願い事は誰だってするでしょ？",
  str_homestory_800601001_8_dialog_content = "刀を握れない子どもは、大人に庇護を求める。",
  str_homestory_800601001_9_dialog_content = "不治の病をわずらう者は、\n神に健康を求めて祈る。",
  str_homestory_800601001_10_dialog_content = "自分で解決する能力をもっているのなら、\n「願い事」に頼る必要はないわ。",
  str_homestory_800601001_11_dialog_content = "（同意する）",
  str_homestory_800601001_12_dialog_content = "残酷なようだけど、一理ある…",
  str_homestory_800601001_13_dialog_content = "運命を自分の手で握っていられるのなら、\n他者に頼る必要はないね。",
  str_homestory_800601001_14_dialog_content = "けれど、この世界には自分では\nどうしようもないことが、たくさん存在する。\nPlayerName、あなたの言った通り…",
  str_homestory_800601001_15_dialog_content = "それが運命ね。",
  str_homestory_800601001_16_dialog_content = "自分ではくつがえせないものを、\n私たちは運命と呼んでいる。そうすることで、\n少しは気が楽になるからかもしれないわ。",
  str_homestory_800601001_17_dialog_content = "でも、私にとって、運命は変えられるものなのよ。",
  str_homestory_800601001_18_dialog_content = "（否定する）",
  str_homestory_800601001_19_dialog_content = "白夜城には、光の神に祈る習慣があるんじゃないの？",
  str_homestory_800601001_20_dialog_content = "カレンも、他の人も、皆そうだと僕は思ってたよ。",
  str_homestory_800601001_21_dialog_content = "確かにその通りよ。私たちは日々、\n光の神に考えを告白し、\nあるいは、望みを伝えているわ。",
  str_homestory_800601001_22_dialog_content = "でも、私にとって、\nそれは気休めに過ぎないの。",
  str_homestory_800601001_23_dialog_content = "祈りが終わっても、目の前にある困難は\n変わらず解決されることを待っている。\nその点は、何も変わらないわ。",
  str_homestory_800601001_24_dialog_content = "…",
  str_homestory_800601001_25_dialog_content = "でも、そう思うと、自分は幸運に思えて来たわね。",
  str_homestory_800601001_26_dialog_content = "幸運？どうして？",
  str_homestory_800601001_27_dialog_content = "私は一人で立ち向かう必要がないからよ。",
  str_homestory_800601001_28_dialog_content = "皆と仲間になれて、本当によかったと思っているの。",
  str_homestory_800601001_29_dialog_content = "僕もそう思うよ。\n一緒に冒険してくれる仲間が側にいてくれて、\n本当によかった。",
  str_homestory_800601001_30_dialog_content = "そうね。",
  str_homestory_800601001_31_dialog_content = "カレン、今日は何だか、感傷的だね？",
  str_homestory_800601001_32_dialog_content = "きっと、この場所のせいね。\nここは…考えごとにはふさわしい。",
  str_homestory_800601001_33_dialog_content = "終わりの見えない戦いもない。\n口うるさい王侯貴族もいない。\n一切が静けさに包まれているわ。",
  str_homestory_800601001_34_dialog_content = "それなら、僕もジャマしないでおくよ。\nもう少し一人でいたいんだよね？",
  str_homestory_800601001_35_dialog_content = "ありがとう、PlayerName。",
  str_homestory_800601001_36_dialog_content = "当然のことだよ、カレン。",
  str_homestory_800201001_0_dialog_content = "ヒイロさん。",
  str_homestory_800201001_1_dialog_content = "ここへは何を？",
  str_homestory_800201001_2_dialog_content = "あなたもまさか、願い事ですか？",
  str_homestory_800201001_3_dialog_content = "ええと、そうなんです。",
  str_homestory_800201001_4_dialog_content = "ちょうど見かけたので、\nあいさつしておこうと思ったんです。",
  str_homestory_800201001_5_dialog_content = "そうですか。",
  str_homestory_800201001_6_dialog_content = "ヒイロさんは…瞑想ですか？",
  str_homestory_800201001_7_dialog_content = "願い事をしています。<sprite=emo_mojing size=60 />",
  str_homestory_800201001_8_dialog_content = "え？",
  str_homestory_800201001_9_dialog_content = "驚いているようですね。",
  str_homestory_800201001_10_option_content = "（認める）",
  str_homestory_800201001_11_dialog_content = "そうですね…\n願い事をするタイプだとは思いませんでした。",
  str_homestory_800201001_12_option_content = "（否定する）",
  str_homestory_800201001_13_dialog_content = "驚いたというより、\n衝撃を受けたと言った方が正確です…",
  str_homestory_800201001_14_dialog_content = "ヒイロさんは強いですし…\nそう簡単には悩むようにも見えないので…",
  str_homestory_800201001_15_dialog_content = "そう思われるのは光栄ですね。",
  str_homestory_800201001_16_dialog_content = "ですが、私はおのれ自身に願い事をしていたのです。\n何かの神に祈っていたわけではありません。",
  str_homestory_800201001_17_dialog_content = "自分に願い事、ですか？",
  str_homestory_800201001_18_dialog_content = "よく分からないんですが…",
  str_homestory_800201001_19_dialog_content = "最近、たくさんの人が\nここで願い事をしていると聞きました。",
  str_homestory_800201001_20_dialog_content = "そこで思ったのです。\n人の真の願いとは、願い事をする瞬間に\nよりはっきりと見えてくるのではないかと。",
  str_homestory_800201001_21_dialog_content = "ここで願い事をすれば、\n自分が望んでいるものは何か、\nはっきりと分かるかもしれないと思ったのです。",
  str_homestory_800201001_22_dialog_content = "なるほど…僕にも分かりました。",
  str_homestory_800201001_23_dialog_content = "「自分が本当にやりたいことを見つける」っていうのと、\n似たような感覚ですか？",
  str_homestory_800201001_24_dialog_content = "そうです。",
  str_homestory_800201001_25_dialog_content = "それで…ヒイロさんは、見つかりましたか？",
  str_homestory_800201001_26_dialog_content = "はい。",
  str_homestory_800201001_27_dialog_content = "私の「願い」は想像していたほど\n明確ではありませんでしたが…\n少なくとも大まかな方向は見えました。",
  str_homestory_800201001_28_dialog_content = "というと、今までは\n方向も見えていなかったんですか？",
  str_homestory_800201001_29_dialog_content = "客観的には、はっきりしていました。",
  str_homestory_800201001_30_dialog_content = "しかし、主観的な方向性や\n自分の願いといったものは、\nぼんやりとしたままでした。",
  str_homestory_800201001_31_dialog_content = "ここに来て、ようやく分かりました。\nなぜ多くの人が、熱心に願い事をするのか。",
  str_homestory_800201001_32_dialog_content = "そうですね…",
  str_homestory_800201001_33_dialog_content = "ヒイロさんのような強い人にとっては、\n願い事は自分の心の向かうべきところを見つけるためのものなんですね。",
  str_homestory_800201001_34_dialog_content = "そして、懸命に毎日の暮らしを生きている人たちにとっては、\n単に祈って、願いを何かに託す行為なのかもしれません。",
  str_homestory_800201001_35_dialog_content = "それが、願いの泉の存在意義…",
  str_homestory_800201001_36_dialog_content = "ここを作るために、あなたもバイスもさぞ苦労したことでしょう。",
  str_homestory_800201001_37_dialog_content = "（なんだか、上司と会話してるみたいな雰囲気になってきた…）",
  str_homestory_800201001_38_dialog_content = "それでは、私は邪魔をしないようにします。\nどうぞ、心行くまま願い事をしていってください。",
  str_homestory_800201001_39_dialog_content = "では。",
  str_homestory_800201001_40_dialog_content = "あ…は、はい！…さようなら！",
  str_homestory_802501001_0_dialog_content = "詩でも作ってるのかな…？",
  str_homestory_802501001_1_dialog_content = "なかなかだ…",
  str_homestory_802501001_2_dialog_content = "なかなか？",
  str_homestory_802501001_3_dialog_content = "うむ、私は認めずにはいられない…",
  str_homestory_802501001_4_dialog_content = "なかなかだ！この舞台は実によい！<sprite=emo_yinfu size=60 />",
  str_homestory_802501001_5_dialog_content = "舞台？",
  str_homestory_802501001_6_dialog_content = "おお、PlayerName！\nちょうどいいところに来た！",
  str_homestory_802501001_7_dialog_content = "どうだ、この風の塔近くの広場だが…",
  str_homestory_802501001_8_dialog_content = "人々を感動の渦に巻き込む芝居に、\nふさわしいではないか！",
  str_homestory_802501001_9_dialog_content = "PlayerName、これ程までに素晴らしい\n光線と空間を無駄にしてはならない。",
  str_homestory_802501001_10_dialog_content = "ここでぜひとも私に、\n後世まで語り継がれる伝説と\nなるであろう作品を上演させてくれ！",
  str_homestory_802501001_11_option_content = "（承知する）",
  str_homestory_802501001_12_dialog_content = "ううん…あまり大騒ぎしないのなら、まぁ…",
  str_homestory_802501001_13_dialog_content = "それではダメだ。",
  str_homestory_802501001_14_dialog_content = "列車！炎！血染めの杯！\nヘヴィメタルにレコード、\nそれからアンプも欠かせない！",
  str_homestory_802501001_15_dialog_content = "芝居を谷の隅々まで響きわたらせねば！",
  str_homestory_802501001_16_dialog_content = "…そんなことしたら、みんなに迷惑だよ…",
  str_homestory_802501001_17_dialog_content = "なんと？この地の住民は、\nまったく芸術が分からないというのか…？",
  str_homestory_802501001_18_dialog_content = "アハハ…そ、そういうわけではないよ…",
  str_homestory_802501001_19_dialog_content = "本当の芸術って、\n分かる人しか楽しめないものでしょ。",
  str_homestory_802501001_20_dialog_content = "僕は夜の静かな時間が、\nカロンのお芝居と雰囲気があってて\n一番いいと思うな…",
  str_homestory_802501001_21_dialog_content = "じゃあ、そういう訳だから…",
  str_homestory_802501001_22_option_content = "（断る）",
  str_homestory_802501001_23_dialog_content = "なんと、どうしたことか？",
  str_homestory_802501001_24_dialog_content = "君の、その氷のごとく固く冷たい拒絶が、\nかえって私のインスピレーションの炎を\n燃え上がらせた！",
  str_homestory_802501001_25_dialog_content = "インスピレーションがせめぎあい、\nうなり、叫び声を上げながら手綱の外れた\n野生馬のように、私の魂の中を駆け巡っている！",
  str_homestory_802501001_26_dialog_content = "いったい、何がうめいているのか…\nそうだ、芸術だ、\n束縛から解き放たれた素晴らしい芝居が――",
  str_homestory_802501001_27_dialog_content = "今、この時、天空ノ谷じゅうに響き渡ろうとしている！",
  str_homestory_802501001_28_dialog_content = "（断っても、まったく意味がないみたいだ…）",
  str_homestory_802501001_29_dialog_content = "日を改めたらどうかな？",
  str_homestory_802501001_30_dialog_content = "…日を改める？",
  str_homestory_802501001_31_dialog_content = "ううむ…突如襲った憂いが、\n私の心の中で反響している…",
  str_homestory_802501001_32_dialog_content = "どうやら、PlayerNameも\n人のあしらい方を覚えてきたようだ…",
  str_homestory_802501001_33_dialog_content = "そういうことなら、\n私も君を芝居の中で「冷淡な人物」として\n登場させることを考えてみよう。",
  str_homestory_802501001_34_dialog_content = "…",
  str_homestory_810501001_0_dialog_content = "イブ、忙しそうだね！",
  str_homestory_810501001_1_dialog_content = "ナビゲーターも来たんだね…！<sprite=emo_aixin size=60 />",
  str_homestory_810501001_2_dialog_content = "もう少ししたら、一緒に遊ぼうよ。\n今は何か欲しいものが無いか、考えてるんだ…",
  str_homestory_810501001_3_dialog_content = "うん、分かったよ！",
  str_homestory_810501001_4_dialog_content = "ところで、何か足りないものがあるの？\n探すの手伝おうか？",
  str_homestory_810501001_5_dialog_content = "ううん、そうじゃないの。\nもう、いろんなものを十分もらってるよ！",
  str_homestory_810501001_6_dialog_content = "私はプレゼントを作りたいだけなんだ。",
  str_homestory_810501001_7_dialog_content = "刺しゅうか、ドリンクホルダーを作るなら、\nどんな色の布がいいかなって、考えてたところ。",
  str_homestory_810501001_8_dialog_content = "刺しゅう？ドリンクホルダー？",
  str_homestory_810501001_9_dialog_content = "そうだよ～。",
  str_homestory_810501001_10_dialog_content = "ドーンにお洋服を作ってあげたから<sprite=emo_qunzi size=60 />、\nそこにヨアケバナの模様を縫ってあげようと思って。",
  str_homestory_810501001_11_dialog_content = "でね…ドリンクホルダーは、\nお兄ちゃんがいつも私に飲ませる\nお水を持ち歩いてるでしょ…",
  str_homestory_810501001_12_dialog_content = "だから、お兄ちゃんに水筒をぶら下げる\nかわいいのを作ってあげたいなって思ったの。",
  str_homestory_810501001_13_dialog_content = "えへへ…ナビゲーターはどう思う？",
  str_homestory_810501001_14_dialog_content = "すごくいいと思うよ！",
  str_homestory_810501001_15_dialog_content = "どっちもいいプレゼントだと思う。\nきっと喜ぶよ。",
  str_homestory_810501001_16_dialog_content = "うん、よかった…",
  str_homestory_810501001_17_dialog_content = "でも、何色の布がいいと思う？",
  str_homestory_810501001_18_dialog_content = "ヨアケバナは白いお花だけど、\nほかの色もステキじゃないかなって思うの…",
  str_homestory_810501001_19_dialog_content = "ドリンクホルダーも、\n赤がいいかな？黒がいいかな？\nお兄ちゃんは、どっちが好きだろ？",
  str_homestory_810501001_20_dialog_content = "ううん、悩んじゃうな～。",
  str_homestory_810501001_21_dialog_content = "そうだね…",
  str_homestory_810501001_22_dialog_content = "ドーンにプレゼントする洋服は何色なの？",
  str_homestory_810501001_23_dialog_content = "黒いお洋服だよ！",
  str_homestory_810501001_24_dialog_content = "それならやっぱり、白いヨアケバナがいいんじゃないかな？",
  str_homestory_810501001_25_dialog_content = "花を少し立体的にして、\nドーンが触った時に\nヨアケバナだと分かるようにしてみたら？",
  str_homestory_810501001_26_dialog_content = "白い、立体的なヨアケバナ…",
  str_homestory_810501001_27_dialog_content = "あっ…それ、すっごくいい考え！",
  str_homestory_810501001_28_dialog_content = "参考になったなら、よかった。",
  str_homestory_810501001_29_dialog_content = "それじゃあ…お兄ちゃんのホルダーの色は、\n何かいい考え、ある？",
  str_homestory_810501001_30_option_content = "あるよ",
  str_homestory_810501001_31_dialog_content = "もし、黒か赤かで悩んでるんだったら、\n黒と赤のツートーンにしてみたら、どうかな。",
  str_homestory_810501001_32_dialog_content = "でも、イブ…",
  str_homestory_810501001_33_option_content = "ないよ",
  str_homestory_810501001_34_dialog_content = "正直に言うと、イブ…",
  str_homestory_810501001_35_dialog_content = "どんなものをプレゼントしようと、\nたぶんすごく喜んでくれると思うよ。",
  str_homestory_810501001_36_dialog_content = "適当に拾ってきた葉っぱとか砂とかでも、\n君がプレゼントしたものなら、伝説の秘宝みたいに\n大切にして、皆に自慢してまわると思う。",
  str_homestory_810501001_37_dialog_content = "うーん…",
  str_homestory_810501001_38_dialog_content = "ナビゲーターの言う通りかも…",
  str_homestory_810501001_39_dialog_content = "分かった！じゃあ、\n自分の好きな色を選ぶことにするね、えへへ。",
  str_homestory_810501001_40_dialog_content = "うん、それがいいと思う。",
  str_homestory_810501001_41_dialog_content = "そう言えば、イブ…ドーンとサメヤマに\n色々準備してるみたいだけど、\n自分には何も準備しないの？",
  str_homestory_810501001_42_dialog_content = "え…？ごめん、言ってる意味がよく分からないよ。",
  str_homestory_810501001_43_dialog_content = "なんで私が自分に何か準備しないといけないの？",
  str_homestory_810501001_44_dialog_content = "ええと、僕が言いたいのはね…",
  str_homestory_810501001_45_dialog_content = "この前、培養土とヨアケバナの種が\nほしいって言ってたけど、\nそれはドーンのためだよね？",
  str_homestory_810501001_46_dialog_content = "ドーンを喜ばせたかったんだよね。",
  str_homestory_810501001_47_dialog_content = "それから、バイスにR・Wの料理を頼んだのも、\nサメヤマのお酒のおつまみにするものとかだよね？",
  str_homestory_810501001_48_dialog_content = "ナビゲーター、気付いてたんだね…",
  str_homestory_810501001_49_dialog_content = "その通りだよ…",
  str_homestory_810501001_50_dialog_content = "でも…",
  str_homestory_810501001_51_dialog_content = "自分には、何も準備しないの？",
  str_homestory_810501001_52_dialog_content = "ううん…イブがお兄ちゃんとドーンにいろいろ用意したのは、\n2人には、ここで楽しく過ごしてほしいから。",
  str_homestory_810501001_53_dialog_content = "でも、イブは…2人が一緒にいてくれれば、十分嬉しいんだよ。",
  str_homestory_810501001_54_dialog_content = "あっ…それから、ナビゲーターとバイスもね！",
  str_homestory_810501001_55_dialog_content = "みんなと一緒に居られれば、\nイブはもう、とっても幸せ！",
  str_homestory_810501001_56_dialog_content = "だから…自分には何もいらないんだ。",
  str_homestory_810501001_57_dialog_content = "…そうだったんだね。",
  str_homestory_810501001_58_dialog_content = "イブは優しいね…",
  str_homestory_810501001_59_dialog_content = "ナビゲーターもね！",
  str_homestory_810501001_60_dialog_content = "うう…ううう…",
  str_homestory_810501001_61_dialog_content = "ど、どうしたの？",
  str_homestory_810501001_62_dialog_content = "ナビゲーター、どうして急に泣き出したの？",
  str_homestory_810501001_63_dialog_content = "うう…僕にもイブみたいな妹がいたら…<sprite=emo_daku size=60 />",
  str_homestory_811201001_0_dialog_content = "スモーキー！？",
  str_homestory_811201001_1_dialog_content = "スモーキー、ど、どうしたの…？",
  str_homestory_811201001_2_dialog_content = "なんでそんなに怒ってるの？",
  str_homestory_811201001_3_dialog_content = "ねえ、ナビゲーター。",
  str_homestory_811201001_4_dialog_content = "この店の品ぞろえ、少なすぎるっしょ？<sprite=emo_shengqi size=60 />",
  str_homestory_811201001_5_dialog_content = "えっ！？それで怒ってたの？",
  str_homestory_811201001_6_dialog_content = "何が足りないのかな？教えて。",
  str_homestory_811201001_7_dialog_content = "マジであたしに言わせるワケ？",
  str_homestory_811201001_8_dialog_content = "うん、言ってみてよ。",
  str_homestory_811201001_9_dialog_content = "分かった、じゃあハッキリ言わせてもらうよ。",
  str_homestory_811201001_10_dialog_content = "まず、アクセサリー用の洗剤がないし。",
  str_homestory_811201001_11_dialog_content = "その次に、この店のボタンのデザイン、\nフツーすぎてつまんない！",
  str_homestory_811201001_12_dialog_content = "誰もこんなボタン、服につけたがらないっつーの。",
  str_homestory_811201001_13_dialog_content = "…あ、啓光のヤツらはそうでもないか。",
  str_homestory_811201001_14_dialog_content = "ボタンか…使えれば、いいんじゃないの？",
  str_homestory_811201001_15_dialog_content = "そりゃそう言うだろーね…\nまっ、アンタはさ、\n本物のファッションなんて分かんないだろうし…",
  str_homestory_811201001_16_dialog_content = "だからって、ヒクツになることもないよ。\nあたしが教えてあげっから。",
  str_homestory_811201001_17_dialog_content = "…それは、ありがとう？",
  str_homestory_811201001_18_dialog_content = "それから、ここはさ…\n影ノ街より日差しが強いんだよね。",
  str_homestory_811201001_19_dialog_content = "日よけのパラソルはあるけどさ、\n日焼け止めクリームとか、サングラスとか、\n日焼け対策のグッズがここには全然ないじゃん。",
  str_homestory_811201001_20_dialog_content = "あ…それもそうだね…",
  str_homestory_811201001_21_dialog_content = "（でも…店の品ぞろえが悪いなんて思うのは、\nスモーキーぐらいだろうな…）",
  str_homestory_811201001_22_dialog_content = "（どうしようかな…1人1人聞いていったら、\n時間もかかっちゃうし…）",
  str_homestory_811201001_23_dialog_content = "なにブツブツ言ってんの？",
  str_homestory_811201001_24_dialog_content = "あたしのこと、めんどくさいとか思ってるワケ？\n他の奴らもあたしみたいに\nめんどくさいとイヤだと思ってるとか？",
  str_homestory_811201001_25_option_content = "（うなずく）",
  str_homestory_811201001_26_dialog_content = "度胸あるじゃん？正直に認めるなんてさ。",
  str_homestory_811201001_27_dialog_content = "面倒臭いというより、辛いって方が正確かも…",
  str_homestory_811201001_28_option_content = "（首を振る）",
  str_homestory_811201001_29_dialog_content = "いや、スモーキー、面倒臭くはないよ…",
  str_homestory_811201001_30_dialog_content = "実際、面倒とかそういう問題じゃないんだ。",
  str_homestory_811201001_31_dialog_content = "ただ、他の人もたぶん、\n君と同じような考えだろうと思うんだけど、\nどうすれば…",
  str_homestory_811201001_32_dialog_content = "注文できるようにすればいいじゃん？",
  str_homestory_811201001_33_dialog_content = "誰かが何か足りないと思った時、\n定期的にアストラ大陸のどっかに\n発注できるようにしとけばいいっしょ。",
  str_homestory_811201001_34_dialog_content = "配送方法は…アンタたちの特殊な技術でも\n使えばいいんじゃない？",
  str_homestory_811201001_35_dialog_content = "それかクーリエ隊<sprite=emo_gezitou size=60 />とか、蛍灯でもさ。",
  str_homestory_811201001_36_dialog_content = "あ…なるほど…",
  str_homestory_811201001_37_dialog_content = "そうすれば、いちいち聞きに行かなくても済むし、\n今みたいにじかで苦情言われることもないじゃん。",
  str_homestory_811201001_38_dialog_content = "それに、光霊によっては、\n特殊な要望があるヤツもいるっしょ。",
  str_homestory_811201001_39_dialog_content = "カンオケとか、型番の違う絵筆とか…\nそれからヘンな虫とかさ…",
  str_homestory_811201001_40_dialog_content = "それから、やけにジュネヴァが好きな奴もいるし。",
  str_homestory_811201001_41_dialog_content = "ん、ちょっと待って、ジュネヴァ？",
  str_homestory_811201001_42_dialog_content = "ジュヌヴィエーヴのこと？",
  str_homestory_811201001_43_dialog_content = "この世界で、酒好きはアイツだけかっつーの？",
  str_homestory_811201001_44_dialog_content = "…何考えてんのか、\nマジよく分かんないんですけど！",
  str_homestory_811201001_45_dialog_content = "分かった分かった…だったら、人違いだね。\n他のジュネヴァが好きな人のことなんだね！",
  str_homestory_811201001_46_dialog_content = "当然じゃん！酒好きなんていっぱいいるでしょ？<sprite=emo_nuhuo size=60 />",
  str_homestory_811201001_47_dialog_content = "分かった、分かったから…怒らないで！火を点けないで…",
  str_homestory_811201001_48_dialog_content = "フン…",
  str_homestory_811201001_49_dialog_content = "とにかく、本当にありがとう、スモーキー！",
  str_homestory_811201001_50_dialog_content = "君の意見、参考にするよ！",
  str_homestory_811201001_51_dialog_content = "そ、じゃ、そーゆーことで。",
  str_homestory_811201001_52_dialog_content = "あっ、うん、バイバイ！",
  str_homestory_807101001_0_dialog_content = "タキのたこが…",
  str_homestory_807101001_1_dialog_content = "あの、タキ…",
  str_homestory_807101001_2_dialog_content = "あ？PlayerNameか？",
  str_homestory_807101001_3_dialog_content = "あの…君のたこが…",
  str_homestory_807101001_4_dialog_content = "落ちちゃったね。",
  str_homestory_807101001_5_dialog_content = "…ああ。",
  str_homestory_807101001_6_dialog_content = "けど、すぐに拾ったぜ。",
  str_homestory_807101001_7_dialog_content = "…？<sprite=emo_yihuo size=60 />",
  str_homestory_807101001_8_dialog_content = "（それでいいのかな…）",
  str_homestory_807101001_9_dialog_content = "そ、そうだね。でも、君のたこ上げの腕は、その…",
  str_homestory_807101001_10_option_content = "なかなかだね！",
  str_homestory_807101001_11_dialog_content = "なぐさめてるつもりか？",
  str_homestory_807101001_12_dialog_content = "いや、僕ははげまそうと思って…",
  str_homestory_807101001_13_dialog_content = "気持ちはありがてぇが、\nそういうウソっぱちのほめ言葉はいらねぇな。",
  str_homestory_807101001_14_dialog_content = "うん…分かった。\nもし、自信を失くしてないようなら…",
  str_homestory_807101001_15_option_content = "まったくできないの？",
  str_homestory_807101001_16_dialog_content = "よければ、教えてあげるよ。",
  str_homestory_807101001_17_dialog_content = "おお、じゃあ、教えてもらおうか。",
  str_homestory_807101001_18_dialog_content = "え？そんなにあっさり？",
  str_homestory_807101001_19_dialog_content = "当然だろ。",
  str_homestory_807101001_20_dialog_content = "腕のいいヤツに教えてもらって何が悪い。",
  str_homestory_807101001_21_dialog_content = "分からねぇなら正直に言やぁいい。\nその方が、コミュニケーションもラクになる。\n特に商売人にとってはそうだ。",
  str_homestory_807101001_22_dialog_content = "さすがは何でも屋だね！",
  str_homestory_807101001_23_dialog_content = "たこ上げのコツ、教えろよ。",
  str_homestory_807101001_24_dialog_content = "うん、まずは風向きを見極めて、\n風を背に立つんだ。",
  str_homestory_807101001_25_dialog_content = "向かい風じゃないと上がらないからね。",
  str_homestory_807101001_26_dialog_content = "たこが上に上がっていったら、\nゆっくりと糸をゆるめるんだ。\n風が弱い時は、素早く糸をたぐって戻すんだよ。",
  str_homestory_807101001_27_dialog_content = "たこをあげてる間は、ゆっくり走りながら、常に状態を確認して…",
  str_homestory_807101001_28_dialog_content = "高く、安定して飛んでいるようなら…",
  str_homestory_807101001_29_dialog_content = "糸を木や道路標識に結んで、自分はどこかいい場所をさがして、\nゆっくりたこを鑑賞すればいいよ。",
  str_homestory_807101001_30_dialog_content = "ううん…風向き…風力…走る…たこの様子を気に掛ける…<sprite=emo_wuyu size=60 />",
  str_homestory_807101001_31_dialog_content = "え？暗記しようとしてる？",
  str_homestory_807101001_32_dialog_content = "必要なら、もう一度説明しようか…？",
  str_homestory_807101001_33_dialog_content = "いや、もう覚えたさ。",
  str_homestory_807101001_34_dialog_content = "え？だったら、何を考えてたの？",
  str_homestory_807101001_35_dialog_content = "ええと、つまり…実際にやってみたら？",
  str_homestory_807101001_36_dialog_content = "「たこ上げのコツ」って本にして、見た目をどうすれば\nもっと売れるか、考えてたんだ。",
  str_homestory_807101001_37_dialog_content = "…え？",
  str_homestory_807101001_38_dialog_content = "そうだな、もし何でも屋でたこを売って、\n宣伝に力を入れるとしたら…",
  str_homestory_807101001_39_dialog_content = "期間限定で指導を受けられる、とかにするか。",
  str_homestory_807101001_40_dialog_content = "で、指導が終わっても、まだできるようにならなかったら、\nそこで「たこ上げのコツ」って本を売ればいい。",
  str_homestory_807101001_41_dialog_content = "デザインは、いろんなもんを揃えねぇとな。\nシャドウマスターの顔とかは…",
  str_homestory_807101001_42_dialog_content = "ちょ、ちょっと待った！",
  str_homestory_807101001_43_dialog_content = "君がここでたこ上げをしてて、僕にコツを教わったのは…",
  str_homestory_807101001_44_dialog_content = "全部、お金もうけのためなの！？",
  str_homestory_807101001_45_dialog_content = "そうさ。",
  str_homestory_807101001_46_dialog_content = "俺は商売人だぜ？",
  str_homestory_807101001_47_dialog_content = "何か問題でもあるか？",
  str_homestory_807101001_48_dialog_content = "いや、ないけど…",
  str_homestory_807101001_49_dialog_content = "僕はただ、その商売に対する\n嗅覚がうらやましいだけだよ。",
  str_homestory_807101001_50_dialog_content = "僕にも身の回りの物事を活かしてお金を稼ぐ力があったら、\n今みたいに毎日赤字ってこともなくなるだろうし…",
  str_homestory_807101001_51_dialog_content = "ああ、そんなことを心配してたのか。",
  str_homestory_807101001_52_dialog_content = "んじゃ、こうしよう。この件は、お前から発想をもらった…",
  str_homestory_807101001_53_dialog_content = "だから、本当に何でも屋でこの商売を始めたら、\n利益の半分をお前に分けてやるよ。",
  str_homestory_807101001_54_dialog_content = "…！？",
  str_homestory_807101001_55_dialog_content = "ほ、本当に！？",
  str_homestory_807101001_56_dialog_content = "ああ、だが、そう興奮するな。",
  str_homestory_807101001_57_dialog_content = "うまくいかないってことだってあるんだ。",
  str_homestory_807101001_58_dialog_content = "構わないよ！僕は君を信じる！！",
  str_homestory_807101001_59_dialog_content = "よし、じゃあ、俺はたこ上げの練習を続けるとするか。",
  str_homestory_807101001_60_dialog_content = "お前は…忙しいだろ。戻ってもいいぞ。",
  str_homestory_807101001_61_dialog_content = "頑張ってね！タキ！",
  str_homestory_807101001_62_dialog_content = "（…よし！決めた！）",
  str_homestory_807101001_63_dialog_content = "（一日でも早く分け前をもらうために、\nタキの練習の様子を毎日見に来よう…）<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_0_dialog_content = "バイス？",
  str_homestory_803301001_1_dialog_content = "息をして…バイス、大丈夫よ！",
  str_homestory_803301001_2_dialog_content = "深呼吸…息をして…<sprite=emo_tanqi size=60 />",
  str_homestory_803301001_3_dialog_content = "息をする？",
  str_homestory_803301001_4_dialog_content = "バイス…呼吸の練習をしてるの？",
  str_homestory_803301001_5_dialog_content = "あ、PlayerName？",
  str_homestory_803301001_6_dialog_content = "…呼吸の練習？",
  str_homestory_803301001_7_dialog_content = "ああ、そうじゃないわ…",
  str_homestory_803301001_8_dialog_content = "だったら、何をしてたの？",
  str_homestory_803301001_9_dialog_content = "ただ帳簿の計算をしてただけよ。",
  str_homestory_803301001_10_dialog_content = "ああ…これだけの支出、考えただけで頭が痛いわ…",
  str_homestory_803301001_11_dialog_content = "いっそ自分が呼吸の練習をしてたって思いたいぐらいよ…",
  str_homestory_803301001_12_dialog_content = "少なくとも、呼吸の練習にお金はかからないものね…",
  str_homestory_803301001_13_option_content = "（何かできるか聞く）",
  str_homestory_803301001_14_dialog_content = "手伝おうか？",
  str_homestory_803301001_15_dialog_content = "昨日の夜、僕も帳簿を見たんだ。",
  str_homestory_803301001_16_dialog_content = "僕は計算はあまりできないけど…少しは手伝えると思う。",
  str_homestory_803301001_17_option_content = "（沈黙する）",
  str_homestory_803301001_18_dialog_content = "急に黙り込んで、どうしたの？",
  str_homestory_803301001_19_dialog_content = "あ、別にあなたを責めてるわけじゃないの…",
  str_homestory_803301001_20_dialog_content = "分かってるよ。僕はただ、どうすれば手伝えるかなって考えてたんだ。",
  str_homestory_803301001_21_dialog_content = "昨日の夜、僕も帳簿を見たけど、確かに支出が多い…",
  str_homestory_803301001_22_dialog_content = "バイスには…本当に苦労をかけちゃってる。",
  str_homestory_803301001_23_dialog_content = "昨日の夜見た帳簿には、何て書いてあったかな…",
  str_homestory_803301001_24_dialog_content = "「願いの泉、広場、山のモニュメントの3か所だけで、高額の費用がかかってる」",
  str_homestory_803301001_25_dialog_content = "「家とミュージアムには、大量のこまごまとした物資が必要…」",
  str_homestory_803301001_26_dialog_content = "「それから、仲間たちそれぞれの好みにも気を配らなければならない…」",
  str_homestory_803301001_27_dialog_content = "「例えば、木馬、ハンモック、彫像…」",
  str_homestory_803301001_28_dialog_content = "「こういう小物は、単価は安いけど、積み重なると、大きな支出になる」",
  str_homestory_803301001_29_dialog_content = "「職人さんたちと交流をもつのも一種の学問だ。\nこうした物を設置することは、確かに難しい」",
  str_homestory_803301001_30_dialog_content = "「でも…入居した時、\nここは安心できる心地よい所だって思ってもらえれば、\n私とPlayerNameのしたことも、ムダじゃないわよね？」",
  str_homestory_803301001_31_dialog_content = "あ…それも全部見たのね。",
  str_homestory_803301001_32_dialog_content = "いろんなノートやメモに絵やら書き込みやら、\nあとはグチやらを書くクセが、抜けてないみたい…ハハハ。",
  str_homestory_803301001_33_dialog_content = "正直言って、バイスはすごいよ！",
  str_homestory_803301001_34_dialog_content = "ナビゲーター、どうしたの…急にお世辞なんて？",
  str_homestory_803301001_35_dialog_content = "今のは心からの誉め言葉だよ。",
  str_homestory_803301001_36_dialog_content = "君は施工図を書くだけじゃなくって、\nその計画の手配やら、区割りなんかも考えなきゃいけない…",
  str_homestory_803301001_37_dialog_content = "僕なんて、図面は描けないし、君みたいな細かい計画づくりも手配もできない。",
  str_homestory_803301001_38_dialog_content = "天空ノ庭が今の姿になったのは、本当に君のおかげだよ。",
  str_homestory_803301001_39_dialog_content = "…え？そ、そんな…",
  str_homestory_803301001_40_dialog_content = "そんなにかしこまらなくていいのよ？",
  str_homestory_803301001_41_dialog_content = "別にかしこまってるわけじゃないよ。\n君にまた元気を出してほしいだけ。",
  str_homestory_803301001_42_dialog_content = "一緒にどうするか考えよう。\nどうしたら、収支を健全な状態にできるんだろう…？",
  str_homestory_803301001_43_dialog_content = "そうね、あなたの言う通りよ！",
  str_homestory_803301001_44_dialog_content = "あっ、今思いついたんだけど…天空ノ庭では、買い物が大変でしょ…",
  str_homestory_803301001_45_dialog_content = "だから、お店で販売してる物を10倍の価格で売るっていうのはどう？<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_46_dialog_content = "…そ、それはやめた方が…",
  str_homestory_803301001_47_dialog_content = "えへへ、冗談よ！",
  str_homestory_803301001_48_dialog_content = "でも…どうすれば、お金を稼げるのかしら？\nよく考えないと…",
  str_homestory_804101001_0_dialog_content = "Ms.ブラン…",
  str_homestory_804101001_1_dialog_content = "あら、PlayerNameさん。",
  str_homestory_804101001_2_dialog_content = "いい天気ですね<sprite=emo_pugongying size=60 />。",
  str_homestory_804101001_3_dialog_content = "そうですね。",
  str_homestory_804101001_4_dialog_content = "お散歩中ですか？それとも、何か用事の途中ですか？",
  str_homestory_804101001_5_option_content = "散歩です",
  str_homestory_804101001_6_dialog_content = "それは結構ですね。",
  str_homestory_804101001_7_dialog_content = "ここは風景も素晴らしいですし、\n娯楽もたくさんあります…",
  str_homestory_804101001_8_dialog_content = "私がお会いしたことのない方も、\nたくさんいらっしゃいますね。",
  str_homestory_804101001_9_option_content = "魚釣りに行くところです",
  str_homestory_804101001_10_dialog_content = "そうですか。魚釣りの腕はいかがですか？",
  str_homestory_804101001_11_option_content = "超得意です",
  str_homestory_804101001_12_dialog_content = "本当ですか？",
  str_homestory_804101001_13_dialog_content = "それは釣果を見せていただかないといけませんね…",
  str_homestory_804101001_14_dialog_content = "問題ないですよ！",
  str_homestory_804101001_15_dialog_content = "あらあら、若者らしい自信ですね。",
  str_homestory_804101001_16_option_content = "普通です…",
  str_homestory_804101001_17_dialog_content = "魚釣りというのは…辛抱が必要です。",
  str_homestory_804101001_18_dialog_content = "まだお若いのに、そのような趣味があったのですね。",
  str_homestory_804101001_19_dialog_content = "はい…魚釣りをしていると、集中力が高まる気がするんです。",
  str_homestory_804101001_20_dialog_content = "そうですねぇ…",
  str_homestory_804101001_21_dialog_content = "普通は、日常生活の中で「集中できない」と\n感じた時にだけ、集中力を高めるのに\n効果があることをするものですが…",
  str_homestory_804101001_22_dialog_content = "長期的に訓練することも、確かに有効です。",
  str_homestory_804101001_23_dialog_content = "はい…",
  str_homestory_804101001_24_dialog_content = "ところで、どうしてずっと、\nこの標識の下に立ってるんですか？",
  str_homestory_804101001_25_dialog_content = "この地を観察しているのです。",
  str_homestory_804101001_26_dialog_content = "観察ですか？",
  str_homestory_804101001_27_dialog_content = "職業病かもしれませんね。",
  str_homestory_804101001_28_dialog_content = "たくさんの目新しい建物と道路を見ていたら、\nどうしても、それを覚えたくなってしまったのです。",
  str_homestory_804101001_29_dialog_content = "そういうことでしたか。",
  str_homestory_804101001_30_dialog_content = "でも、ここは道も複雑ではないし、\nMs.ブランも時どき休んだ方がいいと思いますよ。",
  str_homestory_804101001_31_dialog_content = "休む？",
  str_homestory_804101001_32_dialog_content = "実にぜいたくな願いです…",
  str_homestory_804101001_33_dialog_content = "しかし、あなたのご提案とあらば、\n採用することとしましょう。",
  str_homestory_804101001_34_dialog_content = "PlayerNameさんも、\nきちんと休んでくださいね。",
  str_homestory_804101001_35_dialog_content = "過度の疲労は、人を老けさせてしまいますから。<sprite=emo_guilian size=60 />",
  str_homestory_804101001_36_dialog_content = "は、はい…",
  str_homestory_804101001_37_dialog_content = "きちんと休みます！",
  str_homestory_813801001_0_dialog_content = "シヴォーンさん！",
  str_homestory_813801001_1_dialog_content = "PlayerNameさん？",
  str_homestory_813801001_2_dialog_content = "ああ…あなたでよかったです…<sprite=emo_tanqi size=60 />",
  str_homestory_813801001_3_dialog_content = "どうしたんですか、疲れてるみたいですね。",
  str_homestory_813801001_4_dialog_content = "一晩中…夜更かししたからです。\nようやくミュージアムの所蔵品\nすべてを見終わりました。",
  str_homestory_813801001_5_dialog_content = "天空ノ谷の歴史と空の末裔たちの使用していた\n科学技術が見事に記録された所蔵品ばかりです…",
  str_homestory_813801001_6_dialog_content = "あなたたちの科学技術は\n実に高い水準に達していたと\n言わざるを得ません。",
  str_homestory_813801001_7_dialog_content = "そうですか？でも、啓光の科学技術もすごいですよね？",
  str_homestory_813801001_8_dialog_content = "どうしてか分かりませんが、私にはなぜだか…",
  str_homestory_813801001_9_dialog_content = "空の末裔の科学技術と啓光の科学技術は、\n全く違った考え方から\n作られているように思えてなりません。",
  str_homestory_813801001_10_dialog_content = "啓光の科学技術は、\n機械の巧妙な組み合わせによって成り立ち、\n慎重に知識と機器を運用して造り出されたもの…",
  str_homestory_813801001_11_dialog_content = "一方、空の末裔の科学技術は…\n何かこう、生き生きとした感覚を覚えます。",
  str_homestory_813801001_12_dialog_content = "ですが、古代科学技術と…\n手法は違っていても、\n共通点があるように思います。",
  str_homestory_813801001_13_dialog_content = "僕にはよく分かりません…",
  str_homestory_813801001_14_dialog_content = "あ…",
  str_homestory_813801001_15_dialog_content = "やはり少し眠いですね…<sprite=emo_xuanyun size=60 />",
  str_homestory_813801001_16_dialog_content = "だったら、どうしてまだここに立ってるんですか？\n早く戻って休んだ方がいいですよ。",
  str_homestory_813801001_17_dialog_content = "見学の時に書いた記録を整理しているんです。\n以前読んだ資料と結びつけられたら、\n何か新しい発見があるのではないかと…",
  str_homestory_813801001_18_dialog_content = "もしかしたら、\nずいぶんと昔に大陸の他の場所にも、\n空の末裔の痕跡が残されていたかも知れません…",
  str_homestory_813801001_19_dialog_content = "ただ、当時の人々は、それが空の末裔とは知らず、\n古代科学技術と空の末裔の\n科学技術を区別できていないかも…",
  str_homestory_813801001_20_dialog_content = "…あはは、やめましょう。",
  str_homestory_813801001_21_dialog_content = "自分の考えが少し\n現実離れしているように思えてきました。\nやはり、眠気のせいでしょうか？",
  str_homestory_813801001_22_dialog_content = "シヴォーンさんの様子、ちょっと心配になります。",
  str_homestory_813801001_23_dialog_content = "どうしてそんなに急いで\n分析しなきゃいけないんですか？",
  str_homestory_813801001_24_dialog_content = "そんな状態でやっても、\nいい結果はでないでしょう…？",
  str_homestory_813801001_25_dialog_content = "ここには…白夜城の人たちもたくさんいますから。",
  str_homestory_813801001_26_dialog_content = "ここは空の末裔の領分ですし、\nミュージアムを壊すようなことは\nしないとは思いますが…",
  str_homestory_813801001_27_dialog_content = "どうしても心配になるんです。",
  str_homestory_813801001_28_dialog_content = "どうしても今、急いでやらなければ\nならない気がして…見たものを全部記録に取り、\n分析してからでないと、安心できないのです。",
  str_homestory_813801001_29_dialog_content = "科学技術に反感を抱く人たちがここをどう思うか、\n誰にも分からないでしょう？",
  str_homestory_813801001_30_dialog_content = "なるほど…",
  str_homestory_813801001_31_dialog_content = "でも、安心してください。\n僕の知る限り、白夜城にも\nたくさん博物館はあります。",
  str_homestory_813801001_32_dialog_content = "それに、白夜城の人たちも、\nここにはお客さんとして来ています。\n心配するようなことにはなりませんよ。",
  str_homestory_813801001_33_dialog_content = "私の考えすぎでしょうか？",
  str_homestory_813801001_34_dialog_content = "まさか…長時間仕事をし過ぎて、\n余計なことを考えてしまっているのかも…<sprite=emo_sikao size=60 />",
  str_homestory_813801001_35_dialog_content = "疲れてるんだと思います。",
  str_homestory_813801001_36_dialog_content = "少し休んでから続けたらどうですか？",
  str_homestory_813801001_37_dialog_content = "そうですね、では、そのようにしましょう…\nPlayerName。",
  str_homestory_813801001_38_dialog_content = "私は休むことにしますが、あなたはどうしますか？",
  str_homestory_813801001_39_dialog_content = "あなたもここのところ、お疲れなのでは？",
  str_homestory_813801001_40_option_content = "（同意する）",
  str_homestory_813801001_41_dialog_content = "はい、確かに疲れてます。",
  str_homestory_813801001_42_dialog_content = "ただ…",
  str_homestory_813801001_43_option_content = "（否定する）",
  str_homestory_813801001_44_dialog_content = "身体は疲れていても、気持ちはとっても満たされています！",
  str_homestory_813801001_45_dialog_content = "皆がここで楽しく暮らしてくれさえすれば、\n少しぐらい疲れても、何てことありません。",
  str_homestory_813801001_46_dialog_content = "まだ若いのに、上に立つ者の意識を\n立派にもっているようですね…",
  str_homestory_813801001_47_dialog_content = "あ、ありがとうございます？",
  str_homestory_813801001_48_dialog_content = "ああ…どういうわけか、\n川辺に行きたくなってきました。\nですが、もう眠いので、お先に失礼しますね。",
  str_homestory_813801001_49_dialog_content = "起きたら、また空の末裔の科学技術について、\nお話しましょう。",
  str_homestory_813801001_50_dialog_content = "はい、ゆっくり休んでください、シヴォーンさん。",
  str_homestory_814501001_0_dialog_content = "何を見てるんだろう…？",
  str_homestory_814501001_1_dialog_content = "アメモリ？",
  str_homestory_814501001_2_dialog_content = "シッ。<sprite=emo_baiyan size=60 />",
  str_homestory_814501001_3_dialog_content = "…？",
  str_homestory_814501001_4_dialog_content = "何してるの？",
  str_homestory_814501001_5_dialog_content = "観察だ。",
  str_homestory_814501001_6_dialog_content = "この土地を観察しておる。",
  str_homestory_814501001_7_dialog_content = "ここに…何かあるの？",
  str_homestory_814501001_8_dialog_content = "天空ノ庭の設計は非常に巧妙だとは思わぬか？",
  str_homestory_814501001_9_dialog_content = "拙者も幼い頃、このような場所を\n造りたいと夢見たものだ。",
  str_homestory_814501001_10_dialog_content = "攻めるに易く、守るに固い。\n志を同じくする者たちが集まるのだ。",
  str_homestory_814501001_11_dialog_content = "へぇ…",
  str_homestory_814501001_12_dialog_content = "小さい頃から将来を計画してたの？",
  str_homestory_814501001_13_dialog_content = "そのような想像が、当時の拙者にとって、\n「生き続ける」動力だったからに\nすぎぬかもしれんがな。",
  str_homestory_814501001_14_dialog_content = "だが、今、こうしてここで暮らすのも、悪くない。",
  str_homestory_814501001_15_dialog_content = "あ…ごめん。",
  str_homestory_814501001_16_dialog_content = "案内してあげようか？",
  str_homestory_814501001_17_dialog_content = "必要ない。",
  str_homestory_814501001_18_dialog_content = "ここに到着した初日に、調べはつけてある。",
  str_homestory_814501001_19_dialog_content = "さすがの偵察能力だね！",
  str_homestory_814501001_20_dialog_content = "忍者の本能にすぎん。",
  str_homestory_814501001_21_dialog_content = "だが実のところ、\n拙者の知りたいことはただ一つだけなのだ…\nここを設計した者は、一体何者だ？",
  str_homestory_814501001_22_dialog_content = "貴殿はご存じか？",
  str_homestory_814501001_23_option_content = "知ってるよ",
  str_homestory_814501001_24_dialog_content = "バイスが僕と職人さんたちの意見を合わせて設計したんだよ。",
  str_homestory_814501001_25_option_content = "知らない",
  str_homestory_814501001_26_dialog_content = "でも、バイスに聞いておいてあげるよ。",
  str_homestory_814501001_27_dialog_content = "僕も確かに設計には関わったけど…\n全体的な計画は、バイスが一番詳しいから。",
  str_homestory_814501001_28_dialog_content = "でも、アメモリ、そんなこと聞いてどうするの？",
  str_homestory_814501001_29_dialog_content = "まさか…雲島にも似たような場所を造るつもり？",
  str_homestory_814501001_30_dialog_content = "確かにその考えはある。",
  str_homestory_814501001_31_dialog_content = "考えてもみよ、雲島にこの水準の家ができたのなら、\n人々はきっとよりよい暮らしを過ごせるであろう。",
  str_homestory_814501001_32_dialog_content = "もちろん、それだけではないが…",
  str_homestory_814501001_33_dialog_content = "拙者らがこれだけ進んだ技術を習得すれば、\nより自在に敵に立ち向かうことができよう。",
  str_homestory_814501001_34_dialog_content = "空の末裔の科学技術とこれ程までに巧妙な計画性…\n拙者どもも学ぶべきだろう。",
  str_homestory_814501001_35_dialog_content = "そういうことだったのか…分かったよ。",
  str_homestory_814501001_36_dialog_content = "ちゃんと聞いといてあげるね！",
  str_homestory_814501001_37_dialog_content = "感謝する。",
  str_homestory_814601001_0_dialog_content = "あそこで首を振ってるのは…",
  str_homestory_814601001_1_dialog_content = "集いし光霊多くして…",
  str_homestory_814601001_2_dialog_content = "天空ノ庭にて膝を交える。",
  str_homestory_814601001_3_dialog_content = "…？",
  str_homestory_814601001_4_dialog_content = "門は平地に高々とそびえ…",
  str_homestory_814601001_5_dialog_content = "手には肉まんを握る！<sprite=emo_yaosu size=60 />",
  str_homestory_814601001_6_dialog_content = "…",
  str_homestory_814601001_7_dialog_content = "ヨウ、今の…詩吟？",
  str_homestory_814601001_8_dialog_content = "アイヤ！ナビゲーター、来てたの？",
  str_homestory_814601001_9_dialog_content = "違う違う、今のは詩吟じゃないよ。",
  str_homestory_814601001_10_dialog_content = "詩を自作してたの！どう？",
  str_homestory_814601001_11_option_content = "いいと思う！",
  str_homestory_814601001_12_dialog_content = "よかった！",
  str_homestory_814601001_13_dialog_content = "ヨウは大詩人だね！",
  str_homestory_814601001_14_option_content = "な、なかなか…",
  str_homestory_814601001_15_dialog_content = "ええと…カロンとバイスの間くらいのレベル…かな？",
  str_homestory_814601001_16_dialog_content = "大げさすぎず、写実的過ぎず、\n何気ない行間に作者のあこがれが垣間見える…",
  str_homestory_814601001_17_dialog_content = "…いや、それより、門と中華まんに何の関係があるの？",
  str_homestory_814601001_18_dialog_content = "この門を見てみてよ、アタシの未来の中華まん屋に似てると思わない？",
  str_homestory_814601001_19_dialog_content = "中華まん屋を開くつもりなの？",
  str_homestory_814601001_20_dialog_content = "どうしたの、遊侠の旅は終わり？",
  str_homestory_814601001_21_dialog_content = "もちろん、したいよ。どっちもやりたいの。",
  str_homestory_814601001_22_dialog_content = "中華まん屋をいつか隠居する場所で開けたら、いいと思わない？",
  str_homestory_814601001_23_dialog_content = "キミも知ってるでしょ、伝説の大侠客って、\n大体騒がしい街の中で隠居してるんだよ…",
  str_homestory_814601001_24_dialog_content = "で、自分が世間に残した伝説を人が話してるところをこっそり聞いてるの！",
  str_homestory_814601001_25_dialog_content = "大侠客って…そんなにヒマだったのかな…？",
  str_homestory_814601001_26_dialog_content = "ヒマかどうかなんてどうでもいいの。\nまずはアタシの計画を聞いて！",
  str_homestory_814601001_27_dialog_content = "分かった分かった、聞いてるから、話して。",
  str_homestory_814601001_28_dialog_content = "まず、中華まん屋は三階建てがいいな。",
  str_homestory_814601001_29_dialog_content = "1階は半分をアンズとモモに譲って、おいしいものを売ってもらうの。\n残りの半分はアタシのお店、そこでももちろん、おいしいものを売るの！",
  str_homestory_814601001_30_dialog_content = "2階は旅館として使おうかな。そうすれば、\nアタシの友だちも住むところに困らないし、一晩中おしゃべりできちゃう！",
  str_homestory_814601001_31_dialog_content = "でもって、3階はアタシの住むところ！",
  str_homestory_814601001_32_dialog_content = "もちろん、アタシの部屋だけじゃないよ。\nアメモリとリンネの部屋でしょ、それからナビゲーターに、バイスの部屋も…",
  str_homestory_814601001_33_dialog_content = "あとカヤノの部屋、リン家の友だちの部屋、\n義姉さんの部屋、父さんと母さんの部屋も用意しなくっちゃ…",
  str_homestory_814601001_34_dialog_content = "タキにも1部屋用意した方がいいかな？\n女の子ばっかりだけど、来てくれるかな？<sprite=emo_sikao size=60 />",
  str_homestory_814601001_35_dialog_content = "ダイナとロビンの部屋も…",
  str_homestory_814601001_36_dialog_content = "ヨウ、ちょっと待ってよ。\nそんなのいくら稼いでも足りないんじゃ…",
  str_homestory_814601001_37_dialog_content = "友だちの部屋を用意するだけでも、\n相当にお金がかかるよ？",
  str_homestory_814601001_38_dialog_content = "それに、一人が好きな人もいるんじゃないかな。\nそんなにたくさんの人と一緒に暮らすのは好きじゃないかも…",
  str_homestory_814601001_39_dialog_content = "お金は問題じゃないわ！",
  str_homestory_814601001_40_dialog_content = "ううん…でも、「好み」は確かに問題ね…",
  str_homestory_814601001_41_dialog_content = "でも、アタシが友だちだって思う人には、\n当然部屋を用意しておいてあげなくちゃ。",
  str_homestory_814601001_42_dialog_content = "来るか来ないかは、本人次第。\n部屋を準備するのは、アタシの問題だもんね！",
  str_homestory_814601001_43_dialog_content = "へへへ、これでどっちの問題も解決でしょ？\nみんな、お互い無理強いはなしだよ。",
  str_homestory_814601001_44_dialog_content = "うん、確かに君の言う通りだね…",
  str_homestory_814601001_45_dialog_content = "お金持ちの人だけに許された解決方法だけどね…",
  str_homestory_816301001_0_dialog_content = "絵を描いてるの？",
  str_homestory_816301001_1_dialog_content = "うおお！<sprite=emo_wuzui size=60 />\nこれはこれは、飛行船のダンナじゃありませんか。",
  str_homestory_816301001_2_dialog_content = "やっと会えましたね！ずいぶんと探したんですよ…",
  str_homestory_816301001_3_dialog_content = "えっ？僕に何か用？",
  str_homestory_816301001_4_dialog_content = "あちこち仕事を依頼してる途中で、\nここに置かれてる画板を見つけましてね…",
  str_homestory_816301001_5_dialog_content = "バイスさんに聞きましたが、\nこの画板はあなたが皆さんの疑問を押し切って、購入したものだそうですね。",
  str_homestory_816301001_6_dialog_content = "ということは…",
  str_homestory_816301001_7_dialog_content = "先生はようやく、『白XX光』に絵を描いてくださる気になったと\n理解してよろしいですかね？<sprite=emo_yaosu size=60 />",
  str_homestory_816301001_8_option_content = "（肯定する）",
  str_homestory_816301001_9_dialog_content = "うん、そう思ってるんだ。",
  str_homestory_816301001_10_dialog_content = "うおお！ようやく自身の才能に向き合う気になってくださいましたか！",
  str_homestory_816301001_11_dialog_content = "うん…ちょっとでもお金になるなら考えないといけなくてね…",
  str_homestory_816301001_12_dialog_content = "ただ、僕のレベルじゃ、すぐにうまくはなれないよ。",
  str_homestory_816301001_13_dialog_content = "だから、やっぱり絵を描くのが好きな人に使ってもらおうと思ってるんだ。\n例えば、君とか…",
  str_homestory_816301001_14_option_content = "（否定する）",
  str_homestory_816301001_15_dialog_content = "いやいや、僕は自分のレベルがどんなものか、よく分かってる…",
  str_homestory_816301001_16_dialog_content = "画板を置いたのは、\n絵が好きな人に描く場所を作ってあげたいと思ったからだよ。",
  str_homestory_816301001_17_dialog_content = "飛行船のダンナ、自分の胸に手を当ててみてください。",
  str_homestory_816301001_18_dialog_content = "絵画を愛する心臓の音が聞こえますでしょ？",
  str_homestory_816301001_19_dialog_content = "絵画への愛情なら、君にかなう人はいないと思うよ…",
  str_homestory_816301001_20_dialog_content = "聞きたいんだけど…",
  str_homestory_816301001_21_dialog_content = "…！",
  str_homestory_816301001_22_dialog_content = "ずっと昼夜を問わず、ゲーム制作の仕事を依頼してるらしいけど…\n最後にしっかり休んだの、いつ？",
  str_homestory_816301001_23_dialog_content = "ゲーム制作のためなら、不眠不休だって構いませんよ。",
  str_homestory_816301001_24_dialog_content = "じゃあ、最後に心のままに絵を描いたのは、いつ？",
  str_homestory_816301001_25_dialog_content = "むむむ…",
  str_homestory_816301001_26_dialog_content = "まさか、私を口車に乗せて\nこの画板で絵を描かせようというのですか？<sprite=emo_yihuo size=60 />",
  str_homestory_816301001_27_dialog_content = "アストラ大陸中で名の知れた君が、\nここに作品を残してくれたら…",
  str_homestory_816301001_28_dialog_content = "それ以上嬉しいことはないよ！",
  str_homestory_816301001_29_dialog_content = "まずは相手の弱みを探ってなぐさめ、\nその後相手を持ち上げて、自分の要求を突きつける…<sprite=emo_sikao size=60 />",
  str_homestory_816301001_30_dialog_content = "一点のスキもない心理戦術ではありませんか？",
  str_homestory_816301001_31_dialog_content = "無数の仕事を依頼してきた私が、まさか反対に仕事を依頼されそうになるなんて。\nこれは、面白い…！",
  str_homestory_816301001_32_dialog_content = "さすがはスポンサーご指名の主人公です！",
  str_homestory_816301001_33_dialog_content = "あなたさえいれば、\nストーリーの今後は約束されたようなものですね。",
  str_homestory_816301001_34_option_content = "（スポンサーについて尋ねる）",
  str_homestory_816301001_35_dialog_content = "スポンサー？？？",
  str_homestory_816301001_36_dialog_content = "力があって、かつあなたを見込んだえらい人たちですよ。",
  str_homestory_816301001_37_dialog_content = "誰かなんてことは、\nあなたが気にする必要はありません。",
  str_homestory_816301001_38_option_content = "（主人公について尋ねる）",
  str_homestory_816301001_39_dialog_content = "主人公？？",
  str_homestory_816301001_40_dialog_content = "ゲームのストーリーの中心人物ですよ。\n誰もがついて行きたいと思う絶対的スターです。",
  str_homestory_816301001_41_dialog_content = "主人公というのは、誰でもなれるものじゃありません。",
  str_homestory_816301001_42_dialog_content = "聞けば聞くほど、訳がわからないよ。",
  str_homestory_816301001_43_dialog_content = "とにかく、飛行船のダンナ。",
  str_homestory_816301001_44_dialog_content = "あなたのために無料で天空ノ庭絵巻を描いて差し上げましょう！",
  str_homestory_816301001_45_dialog_content = "仕事依頼に使える心理術のお礼ということにしておきます。",
  str_homestory_816301001_46_dialog_content = "今後ともよろしくお願いしますよ。<sprite=emo_guilian size=60 />",
  str_homestory_816301001_47_dialog_content = "こ、こちらこそ…？",
  str_homestory_816301001_48_dialog_content = "よかった。それでは、絵の構想をじっくり練らないといけませんね。",
  str_homestory_816301001_49_dialog_content = "普段は3秒で済みますが、\n飛行船のダンナのために描くとなれば、最高の誠意を示さねば！",
  str_homestory_816301001_50_dialog_content = "ううん…",
  str_homestory_816301001_51_dialog_content = "どう描きましょう…",
  str_homestory_816301001_52_dialog_content = "じゃあ、僕は…ジャマしないことにするね…",
  str_homestory_816301001_53_dialog_content = "（もう僕の話が聞こえないみたいだ）",
  str_homestory_816301001_54_dialog_content = "（今のうちに立ち去ろう）",
  str_homestory_814801001_0_dialog_content = "来てたの？",
  str_homestory_814801001_1_dialog_content = "アズール…",
  str_homestory_814801001_2_dialog_content = "あら？",
  str_homestory_814801001_3_dialog_content = "誰のお顔かしら、ずいぶんかわいいわね～。",
  str_homestory_814801001_4_dialog_content = "いらっしゃい、お姉さんが感触を確かめてあげるわ…",
  str_homestory_814801001_5_dialog_content = "ちょちょ、<sprite=emo_yundao size=60 />…ちょっと待って！",
  str_homestory_814801001_6_dialog_content = "ぼ、僕だよ、PlayerNameだよ。",
  str_homestory_814801001_7_dialog_content = "PlayerName？聞いたことのある名前ね。",
  str_homestory_814801001_8_dialog_content = "なんてね、思い出したわ！",
  str_homestory_814801001_9_dialog_content = "あたしのかわいいボーイフレンド、\n空の末裔のボーヤの名前だったわね？",
  str_homestory_814801001_10_option_content = "（認める）",
  str_homestory_814801001_11_dialog_content = "…そうだよ、僕だよ。",
  str_homestory_814801001_12_dialog_content = "あら、認めるの？",
  str_homestory_814801001_13_dialog_content = "認めたからには、責任とってもらうわよ？",
  str_homestory_814801001_14_option_content = "（否定する）",
  str_homestory_814801001_15_dialog_content = "アズール、変なこと言わないで…",
  str_homestory_814801001_16_dialog_content = "誰かに聞かれて、本気にされたらどうするの？",
  str_homestory_814801001_17_dialog_content = "あら？何を心配してるの？",
  str_homestory_814801001_18_dialog_content = "啓光の龍の尻尾を生やしたお嬢ちゃんかしら？",
  str_homestory_814801001_19_dialog_content = "それとも白夜城のクールビューティーなお姫様？",
  str_homestory_814801001_20_dialog_content = "…",
  str_homestory_814801001_21_dialog_content = "まあ、顔を赤くして、怒ってるのかしら…\nますますかわいいわね～。",
  str_homestory_814801001_22_dialog_content = "ぼ、僕はもう行くよ…<sprite=emo_hanshui size=60 />",
  str_homestory_814801001_23_dialog_content = "はいはい、もうからかわないであげるわ。",
  str_homestory_814801001_24_dialog_content = "それで、あたしに何か用？",
  str_homestory_814801001_25_dialog_content = "ただ居ごこちを聞きたかっただけだよ…ここには慣れた？",
  str_homestory_814801001_26_dialog_content = "あら、あたしのボーヤったら、気づかいを覚えたのね。\n感動しちゃうわ。",
  str_homestory_814801001_27_dialog_content = "ええ、あなたのおかげで、とても楽しく過ごせてるわね。",
  str_homestory_814801001_28_dialog_content = "熱いし乾燥してる砂漠と違って、\nここは、緑でいっぱいね。",
  str_homestory_814801001_29_dialog_content = "気温もちょうどいいし、空気もおいしいわ。\n風までやさしく吹いてる気がするわね。",
  str_homestory_814801001_30_dialog_content = "イヤなヤツも少ないし。",
  str_homestory_814801001_31_dialog_content = "ほんと、天然のエステみたいなところね…",
  str_homestory_814801001_32_dialog_content = "どう、最近あたし、きれいになったと思わない？",
  str_homestory_814801001_33_option_content = "（肯定する）",
  str_homestory_814801001_34_dialog_content = "確かに前よりもずっときれいになった。\nこれ以上ないぐらいに…",
  str_homestory_814801001_35_option_content = "（否定する）",
  str_homestory_814801001_36_dialog_content = "もともと、それ以上ないくらいきれいだよ。",
  str_homestory_814801001_37_dialog_content = "あら、小さなお口にハチミツでも塗ったの？\nずいぶん甘い言葉を吐けるのね。",
  str_homestory_814801001_38_dialog_content = "どうやら、もうしばらくここに居ないと、\nボーヤの情熱的なおもてなしに応えてあげられなさそうね。",
  str_homestory_814801001_39_dialog_content = "ねえ、空の末裔のボーヤ、\nあたしにここにずっと住んでいてほしい？",
  str_homestory_814801001_40_option_content = "（肯定する）",
  str_homestory_814801001_41_dialog_content = "ええと…好きなだけ居てくれればいいよ。",
  str_homestory_814801001_42_dialog_content = "この谷の扉は、いつでもアズールのために開いてるから。",
  str_homestory_814801001_43_option_content = "（否定する）",
  str_homestory_814801001_44_dialog_content = "ぼ、僕は誰にも、そんなこと言わないよ…",
  str_homestory_814801001_45_dialog_content = "皆、好きなように出入りしてくれればいいんだ。",
  str_homestory_814801001_46_dialog_content = "あなたがそう言うなら、本当に遠慮しないわよ？",
  str_homestory_814801001_47_dialog_content = "あ。でも、お店にもっといいお酒を入れて。",
  str_homestory_814801001_48_dialog_content = "お姉さん、もう待ちきれないの。\n分かるでしょ？",
  str_homestory_814801001_49_dialog_content = "うん…",
  str_homestory_814801001_50_dialog_content = "だったら、急いでね！<sprite=emo_emo size=60 />",
  str_homestory_814801001_51_dialog_content = "今すぐ行ってくる！",
  str_homestory_815001001_0_dialog_content = "…ぜんぜん動いてない…",
  str_homestory_815001001_1_dialog_content = "PlayerName、こんにちは。<sprite=emo_heimao size=60 />",
  str_homestory_815001001_2_dialog_content = "レノーアは、あなたに会えて、嬉しいです。",
  str_homestory_815001001_3_dialog_content = "レノーア、どうしてこんなところで立ってるの？",
  str_homestory_815001001_4_dialog_content = "色んな所を散歩してみたりしたくならない？",
  str_homestory_815001001_5_dialog_content = "散歩…？",
  str_homestory_815001001_6_dialog_content = "それは、PlayerNameからレノーアへの、新しい命令ですか？",
  str_homestory_815001001_7_dialog_content = "具体的には、どこに行って歩けば、いいのですか？",
  str_homestory_815001001_8_dialog_content = "レノーア、これは命令じゃないよ。\n君に提案したんだ。",
  str_homestory_815001001_9_dialog_content = "提案と命令は、何が違うのですか？",
  str_homestory_815001001_10_dialog_content = "ううん…そうだなあ。",
  str_homestory_815001001_11_dialog_content = "命令は…他の人が君に何かを必ずさせること。",
  str_homestory_815001001_12_dialog_content = "提案は、他の人が君にしてもいいこと、\nしてはいけないことを教えることだよ。",
  str_homestory_815001001_13_dialog_content = "レノーア、分かりました。",
  str_homestory_815001001_14_dialog_content = "PlayerNameはレノーアに散歩を提案しました。\nこれは提案です。",
  str_homestory_815001001_15_dialog_content = "つまり、レノーアは散歩をすることを選んでも、\nしないことを選んでもいいということです。",
  str_homestory_815001001_16_dialog_content = "すぐに理解できてるね！レノーアは賢いよ！",
  str_homestory_815001001_17_dialog_content = "PlayerName、誉めてくれてありがとうございます。",
  str_homestory_815001001_18_dialog_content = "どういたしまして。",
  str_homestory_815001001_19_dialog_content = "…",
  str_homestory_815001001_20_dialog_content = "…",
  str_homestory_815001001_21_dialog_content = "…",
  str_homestory_815001001_22_dialog_content = "ええと、レノーア？",
  str_homestory_815001001_23_dialog_content = "散歩しないの？",
  str_homestory_815001001_24_dialog_content = "提案ではないのですか？",
  str_homestory_815001001_25_dialog_content = "レノーアは散歩しなくてもいいのです。",
  str_homestory_815001001_26_dialog_content = "ええと…",
  str_homestory_815001001_27_dialog_content = "この数日、きれいな花や木をたくさん植えて、\n楽しい場所もたくさん用意したんだ。",
  str_homestory_815001001_28_dialog_content = "見に行ってみたくない？",
  str_homestory_815001001_29_dialog_content = "レノーアは、見に行ってみたくなるべきですか？",
  str_homestory_815001001_30_option_content = "（命令する）",
  str_homestory_815001001_31_dialog_content = "ううん…仕方ない。じゃあ、こうしよう。\n僕はレノーアにいろんな所を見て回るよう命令するよ。",
  str_homestory_815001001_32_dialog_content = "分かりました。レノーアは成し遂げます！",
  str_homestory_815001001_33_option_content = "（提案する）",
  str_homestory_815001001_34_dialog_content = "自画自賛になるけど、\n自分ではなかなかうまく出来たと思ってるんだ。",
  str_homestory_815001001_35_dialog_content = "だから…君も見に行ってみるといいと思うよ？",
  str_homestory_815001001_36_dialog_content = "PlayerNameがそう言うのなら、\nレノーアは、そうすることにします。",
  str_homestory_815001001_37_dialog_content = "うん、見てきて。",
  str_homestory_815001001_38_dialog_content = "ですが、レノーアはどこへ行ったらいいのでしょうか？",
  str_homestory_815001001_39_dialog_content = "PlayerNameは、レノーアがどこに行くべきか、提案はありますか？",
  str_homestory_815001001_40_dialog_content = "えっ…！？",
  str_homestory_815001001_41_dialog_content = "PlayerName、どうしましたか？",
  str_homestory_815001001_42_dialog_content = "いや、何でもないよ…",
  str_homestory_815001001_43_dialog_content = "レノーアが、本当に「提案」の意味を理解したなんて…",
  str_homestory_815001001_44_dialog_content = "ちょっと感動しちゃったよ…",
  str_homestory_801901001_0_dialog_content = "あっ、ビクトリア…",
  str_homestory_801901001_1_dialog_content = "ごきげんよう、PlayerName。",
  str_homestory_801901001_2_dialog_content = "ビクトリア！こんにちは。",
  str_homestory_801901001_3_dialog_content = "楽しげな水の流れを鑑賞してるの。\n一緒にいかがかしら？",
  str_homestory_801901001_4_dialog_content = "水の流れを鑑賞する…？",
  str_homestory_801901001_5_dialog_content = "ええと…流れる水に、鑑賞するようなことがあるの？",
  str_homestory_801901001_6_dialog_content = "この水は何も知らないまま、\n終わりのない循環の中を流れているのよ。",
  str_homestory_801901001_7_dialog_content = "光霊に似ているところが多いと思わないかしら。",
  str_homestory_801901001_8_option_content = "（うなずく）",
  str_homestory_801901001_9_dialog_content = "そんな気もする…",
  str_homestory_801901001_10_dialog_content = "でも、やっぱり分からない気もする…",
  str_homestory_801901001_11_option_content = "（首を振る）",
  str_homestory_801901001_12_dialog_content = "ごめん、ビクトリア…",
  str_homestory_801901001_13_dialog_content = "僕にはよく分からないよ。",
  str_homestory_801901001_14_dialog_content = "それでいいの。\n私もただ、何の意味もない感慨を吐き出したにすぎないわ。",
  str_homestory_801901001_15_dialog_content = "ビクトリアはどう考えてるの？",
  str_homestory_801901001_16_dialog_content = "水の流れは、自分がある種の循環に従って流れていることを知らないわ。",
  str_homestory_801901001_17_dialog_content = "水は自分の意志で流れてはいない。\nただ目的もなく、そうなっているだけ。",
  str_homestory_801901001_18_dialog_content = "なぜ循環するのか、どうすればそこから抜け出せるのか、\nこの循環はいつ終わるのか…何も知らないのよ。",
  str_homestory_801901001_19_dialog_content = "大勢の人の暮らしと似ているでしょう？",
  str_homestory_801901001_20_dialog_content = "もちろん、責めたり、\n哀れんだりするつもりはないわ。",
  str_homestory_801901001_21_dialog_content = "私にとっては、どう暮らそうと大差はない。",
  str_homestory_801901001_22_dialog_content = "私はただ、考えようとしているだけ。",
  str_homestory_801901001_23_dialog_content = "…考えようとしている？",
  str_homestory_801901001_24_dialog_content = "そうよ。",
  str_homestory_801901001_25_dialog_content = "考えるということに敬意を示さないといけないわ。\n私たちに何かをする力を与えてくれるのは、往々にして自分には理解できないことだもの。",
  str_homestory_801901001_26_dialog_content = "…つまり、尊敬の念をもって、未知と対面するべきだってこと？",
  str_homestory_801901001_27_dialog_content = "だいたいそういうことね。",
  str_homestory_801901001_28_dialog_content = "でも、水の流れは今を楽しんでいるのかもしれない。\n私たちが口を挟むようなことではないのかもしれないわ。",
  str_homestory_801901001_29_dialog_content = "循環の中で喜び、楽しめることも、とてもいいことよ。",
  str_homestory_801901001_30_dialog_content = "つまり、ビクトリアみたいに、そのことで深く悩んだりしないってこと？",
  str_homestory_801901001_31_dialog_content = "さて、どうかしらね？",
  str_homestory_801901001_32_dialog_content = "ただ、そういえば…\nここは実に日差しが強いわね<sprite=emo_taiyang size=60 />。",
  str_homestory_801901001_33_dialog_content = "あっ、あっちに日よけのパラソルがあるよ。\n行ってみたら？",
  str_homestory_801901001_34_dialog_content = "お気づかいありがとう、PlayerName。\nでも、私は戻って休むことにするわ。",
  str_homestory_801901001_35_dialog_content = "真理の祝福あれ。",
  str_homestory_800901001_0_dialog_content = "ファウスト？",
  str_homestory_800901001_1_dialog_content = "また会ったね、親愛なるナビゲーター。",
  str_homestory_800901001_2_dialog_content = "そうだね…",
  str_homestory_800901001_3_dialog_content = "昼間に会うとは思ってなかったけど。",
  str_homestory_800901001_4_dialog_content = "誤解しないでくれたまえ。\n確かに僕は夜の方を好んでいるが、\n昼という時がもたらす力を拒んだりもしない。",
  str_homestory_800901001_5_dialog_content = "セティもどうやらここが気に入ったようだ。",
  str_homestory_800901001_6_dialog_content = "…ちょっと待って。\nセティも気に入ったってことは…",
  str_homestory_800901001_7_dialog_content = "まさか、ここにもたくさんの悲しみと絶望があるってこと？",
  str_homestory_800901001_8_dialog_content = "確かそのカバン、前は途方に暮れてる僕を見て、\nよだれを垂らしてたよね…",
  str_homestory_800901001_9_dialog_content = "他の何かがセティを\n心地よくさせているのかもしれないよ。",
  str_homestory_800901001_10_dialog_content = "「悲しい記憶」、「悪夢」、\n「絶望の淵ですがる信仰」、そして「氷水」、\nどれ一つとっても…",
  str_homestory_800901001_11_dialog_content = "え！？",
  str_homestory_800901001_12_dialog_content = "（以前、セティのお世話をした経験からして…<sprite=emo_sikao size=60 />）",
  str_homestory_800901001_13_dialog_content = "（ここに居る皆は、悲しいと感じるどころか、悪夢まで見てるってこと！？）",
  str_homestory_800901001_14_dialog_content = "親愛なるナビゲーター、考えすぎてはいけないよ。",
  str_homestory_800901001_15_dialog_content = "セティが心地よいと感じるのは…",
  str_homestory_800901001_16_dialog_content = "光霊たちの過去の経験のせいであって、\n今の気持ちだとは限らないんだ。",
  str_homestory_800901001_17_dialog_content = "僕の知る限り、\n君の友人には辛い過去をもつ者が多いだろう？",
  str_homestory_800901001_18_dialog_content = "そう言われてみれば…",
  str_homestory_800901001_19_dialog_content = "ううん…確かにそうだ…",
  str_homestory_800901001_20_dialog_content = "でも、僕はやっぱり皆に、\nできる限り楽しく過ごしてもらいたい…",
  str_homestory_800901001_21_dialog_content = "思い出や感情というものは、\n完全に思い通りにできるものではないのだよ。\n親愛なるナビゲーター。",
  str_homestory_800901001_22_dialog_content = "他人に深入りしすぎないことも大切だ。",
  str_homestory_800901001_23_dialog_content = "すべては流れに任せればいい。",
  str_homestory_800901001_24_dialog_content = "…そうだね。",
  str_homestory_800901001_25_dialog_content = "それで、君がここにいるのは、何のため？",
  str_homestory_800901001_26_option_content = "真理を伝えるため？",
  str_homestory_800901001_27_dialog_content = "いいや、そうではないさ、\n親愛なるナビゲーター。",
  str_homestory_800901001_28_option_content = "セティに食事させるため？",
  str_homestory_800901001_29_dialog_content = "その通りさ、親愛なるナビゲーター。",
  str_homestory_800901001_30_dialog_content = "ここは、セティが食事をするには絶好の場所だ…",
  str_homestory_800901001_31_dialog_content = "自由に行き交う人々の感情に触れられるからね。",
  str_homestory_800901001_32_dialog_content = "「自由に感情に触れる」って…",
  str_homestory_800901001_33_dialog_content = "ううん…皆の心の中に、\nそんなに人に言えないほどの苦痛があるのかな？",
  str_homestory_800901001_34_dialog_content = "僕にもそれは断言できないね。",
  str_homestory_800901001_35_dialog_content = "しかし…僕にも断言できることが1つだけある。",
  str_homestory_800901001_36_dialog_content = "え？",
  str_homestory_800901001_37_dialog_content = "それは、セティが出かける前、\n部屋で氷水を存分に飲んだということさ。",
  str_homestory_800901001_38_dialog_content = "…？",
  str_homestory_800901001_39_dialog_content = "つまり、セティが心地よさそうなのは、\n単に氷水をたくさん飲んだからってだけ！？",
  str_homestory_800901001_40_dialog_content = "ということは、皆が悲しみとか、苦しみといった、\n負の感情を抱いてるわけじゃなかったんだね…",
  str_homestory_800901001_41_dialog_content = "…だとすれば…また僕はからかわれたってこと！？",
  str_homestory_800901001_42_dialog_content = "そういうことになるね。",
  str_homestory_800901001_43_dialog_content = "ただ…僕がこんなことをしたのは、\n君も気をもみ過ぎない方がいいと思ったからだ。",
  str_homestory_800901001_44_dialog_content = "すべてのこと、すべての人への応対を\n完璧にこなし、世話する必要はない。そうだろう？",
  str_homestory_800901001_45_dialog_content = "真理の祝福あれ。",
  str_homestory_800901001_46_dialog_content = "…君って人は…<sprite=emo_shengqi size=60 />",
  str_homestory_815101001_0_dialog_content = "この童謡は…",
  str_homestory_815101001_1_dialog_content = "「真っ黒子羊、名前はイサク。モコモコなでなで、やけどした…♪」",
  str_homestory_815101001_2_dialog_content = "ギルス！",
  str_homestory_815101001_3_dialog_content = "おや、ナビゲーターだったのか。",
  str_homestory_815101001_4_dialog_content = "忘れるところだった…君はもう、この童謡を聞いたことがあったね。",
  str_homestory_815101001_5_dialog_content = "新しい歌に変えるべき時がきたかな？",
  str_homestory_815101001_6_dialog_content = "謎に満ちた空の末裔を主人公にした、予言を込めた新作にね…<sprite=emo_baimao size=60 />",
  str_homestory_815101001_7_dialog_content = "えっ…",
  str_homestory_815101001_8_dialog_content = "どうしてそんなにイヤそうなんだい、ナビゲーター？",
  str_homestory_815101001_9_dialog_content = "そんな顔をされたら、僕は傷ついてしまうよ…",
  str_homestory_815101001_10_dialog_content = "君は以前、僕の童謡が一番好きだと言っていなかったかい？",
  str_homestory_815101001_11_dialog_content = "（…そんなこと言ったっけ？）",
  str_homestory_815101001_12_option_content = "もう出来てるの？",
  str_homestory_815101001_13_dialog_content = "インスピレーションさえ湧けば、たちまち出来上がりさ。",
  str_homestory_815101001_14_dialog_content = "インスピレーションの源が、\nちょうど僕の目の前に立っているしね…",
  str_homestory_815101001_15_option_content = "また今度にしてもらえる？",
  str_homestory_815101001_16_dialog_content = "ああ、断る理由さえないのかい？",
  str_homestory_815101001_17_dialog_content = "それは、僕にとってキッパリとした拒絶だよ…",
  str_homestory_815101001_18_dialog_content = "ああ、人を惑わす空の末裔…\n簡単に人の心をさらう、賢い空の末裔…",
  str_homestory_815101001_19_dialog_content = "…あれ、もう始まってる？",
  str_homestory_815101001_20_dialog_content = "「ラララ、ラララ…きれいな部屋にきれいなお花…」",
  str_homestory_815101001_21_dialog_content = "「魚もエビも、そこが家だと思ってる」",
  str_homestory_815101001_22_dialog_content = "「動物も、お花も、女の人も、恐れを知らないあの子を囲んでる」",
  str_homestory_815101001_23_dialog_content = "「ザザザ、ハラハラ、時の雨が一粒一粒落ちていく…」",
  str_homestory_815101001_24_dialog_content = "「高い塔を建てよう、レンガとかわらで守ろう、\nもっと強く、もっと大きくする方法を探そう」",
  str_homestory_815101001_25_dialog_content = "「ラララ、ラララ、そんなあの子はどこ行った？」",
  str_homestory_815101001_26_dialog_content = "「家はもう大きく、高く、ほらほらあの子は雲の上、またたきもせず立っている」",
  str_homestory_815101001_27_dialog_content = "「ラララ、ラララ…きれいな部屋にきれいなお花…」",
  str_homestory_815101001_28_dialog_content = "…そ、それが君の予言？",
  str_homestory_815101001_29_dialog_content = "ただの童謡だよ、ナビゲーター。",
  str_homestory_815101001_30_dialog_content = "何を怖がってるの？僕はただ創作しただけだよ…",
  str_homestory_815101001_31_dialog_content = "うん…分かってる。",
  str_homestory_815101001_32_dialog_content = "ギルスの童謡は、いつもどこか…\n単純なようで難解な部分があるなって思っただけだよ。",
  str_homestory_815101001_33_dialog_content = "童謡は、童謡なんだ。",
  str_homestory_815101001_34_dialog_content = "ナビゲーター、深く考え過ぎちゃダメだよ？",
  str_homestory_815101001_35_dialog_content = "そうだね、やっぱりもっと現実的なことを話そう…",
  str_homestory_815101001_36_dialog_content = "ここはどう？もう慣れた？",
  str_homestory_815101001_37_dialog_content = "僕もイサクも気に入ってるよ。",
  str_homestory_815101001_38_dialog_content = "ここにいると、強烈な創作意欲が湧いてくるんだ…アハハハ！",
  str_homestory_815101001_39_dialog_content = "行き交う人々も、ナビゲーターも…\n僕にとっては、これ以上ない創作の素材だからね！<sprite=emo_emo size=60 />",
  str_homestory_815101001_40_dialog_content = "そう…",
  str_homestory_815101001_41_dialog_content = "メェ～メェメェ～！",
  str_homestory_815101001_42_dialog_content = "さぁ、僕はイサクと2人きりになりたいんだ、ナビゲーター。",
  str_homestory_815101001_43_dialog_content = "お話はまた今度にしよう。",
  str_homestory_815101001_44_dialog_content = "うん…じゃあ、また今度。",
  str_homestory_815301001_0_dialog_content = "大げ…レインハトさん？",
  str_homestory_815301001_1_dialog_content = "ここは生活の基盤が実に整っているな。<sprite=emo_dianzan size=60 />",
  str_homestory_815301001_2_dialog_content = "あ、ありがとうございます…",
  str_homestory_815301001_3_dialog_content = "啓光の厳密に区画された広場を見慣れていると、\nここは、やはり大分違って見える。",
  str_homestory_815301001_4_dialog_content = "啓光は芸術を解さない、美を追求しないと人々は言うが…",
  str_homestory_815301001_5_dialog_content = "残念なことに、その芸術や美にこだわるところでは、\nえてして多くの者が食べることにも困っているものだ。",
  str_homestory_815301001_6_dialog_content = "規則正しく造られた物はコストが低く、効率が良い。\nごく簡単な道理であろうに。",
  str_homestory_815301001_7_dialog_content = "しかし、それでもここは美しい。",
  str_homestory_815301001_8_dialog_content = "美しく、規則正しく整備されている。\nお前とバイスがずいぶんと心血を注いだのだろう？",
  str_homestory_815301001_9_option_content = "（うなずく）",
  str_homestory_815301001_10_dialog_content = "主にバイスが苦労しました…\n僕は建築とか、そういったことはよく分からないので。",
  str_homestory_815301001_11_dialog_content = "フ、自身の不足を認められることもまた、長所だ。",
  str_homestory_815301001_12_option_content = "（首を振る）",
  str_homestory_815301001_13_dialog_content = "そうでもありません。蛍灯がいろいろ助けてくれましたし、\nクーリエ隊の友だちもたくさん助けてくれました。",
  str_homestory_815301001_14_dialog_content = "でも、何より皆が楽しければ、それでいいんです。\n僕たちは何も特別なことはしていません。",
  str_homestory_815301001_15_dialog_content = "それこそまさに、お前たちのもつ最も貴重なものだ。",
  str_homestory_815301001_16_dialog_content = "私から見れば、\n「特別なことをしていない」ことこそが特別なのだ。",
  str_homestory_815301001_17_dialog_content = "お前の手によって、ここでは…",
  str_homestory_815301001_18_dialog_content = "私とバイスが同じような部屋に住み、同じものを食べている。",
  str_homestory_815301001_19_dialog_content = "多くの者の私に対する態度より、この暮らし方はずっといい。",
  str_homestory_815301001_20_dialog_content = "地位の高さによって待遇が変わることなく、\n誰もが平等に扱われる。実に得がたいことだ。",
  str_homestory_815301001_21_dialog_content = "（そんな風に見る人だなんて、意外だった…）",
  str_homestory_815301001_22_dialog_content = "（…正直に話した方がいいかな？）",
  str_homestory_815301001_23_dialog_content = "（うん、やっぱりその方がいいよね…）",
  str_homestory_815301001_24_dialog_content = "あの、実は…",
  str_homestory_815301001_25_dialog_content = "単にもっといい部屋を造るお金がなかっただけで…",
  str_homestory_815301001_26_dialog_content = "知っている。",
  str_homestory_815301001_27_dialog_content = "だが、大事なことは予算がどれだけあるかではない。\n金をいかに使うか――という、根本の計画だ。",
  str_homestory_815301001_28_dialog_content = "なるほど、少し分かった気がします…",
  str_homestory_815301001_29_dialog_content = "分かればいい。",
  str_homestory_815301001_30_dialog_content = "さて、他の啓光の同胞たちの様子でも見に行くとしようか。",
  str_homestory_815301001_31_dialog_content = "では、また会おう。PlayerName。",
  str_homestory_815301001_32_dialog_content = "さ、さようなら！",
  str_homestory_803801001_0_dialog_content = "また、ゲーム？",
  str_homestory_803801001_1_dialog_content = "やあやあ、PlayerName！",
  str_homestory_803801001_2_dialog_content = "へへへ…わざわざ会いに来るなんて、ゲームしたくなったんでしょ？",
  str_homestory_803801001_3_dialog_content = "いや、違うんだ。",
  str_homestory_803801001_4_dialog_content = "ただ、ここはどうかなって、慣れたか聞こうと思って。",
  str_homestory_803801001_5_dialog_content = "う～ん…",
  str_homestory_803801001_6_dialog_content = "いいと思うよ、でも、娯楽がちょっと少ないかな～。",
  str_homestory_803801001_7_dialog_content = "あ、分かった。優しいPlayerNameのことだから、\nあたしの退屈しのぎに付き合ってくれるつもりなんでしょ？",
  str_homestory_803801001_8_dialog_content = "え？…僕は…",
  str_homestory_803801001_9_dialog_content = "へへヘ…じゃあ、簡単なゲームから始めよっか…",
  str_homestory_803801001_10_dialog_content = "何もなくても一緒に遊べる、すごく簡単なゲーム！",
  str_homestory_803801001_11_dialog_content = "それって…ジャンケンとか？",
  str_homestory_803801001_12_dialog_content = "そんなわけないでしょ――クイズだよ！",
  str_homestory_803801001_13_dialog_content = "準備はいい？すぐに始まるよ？",
  str_homestory_803801001_14_dialog_content = "分かったよ…そこまで期待されたら…付き合うよ。",
  str_homestory_803801001_15_dialog_content = "第一問！イエスかノーで答えてね！",
  str_homestory_803801001_16_dialog_content = "「啓光研究室の室長ガルーは、実は――なんと、ロボットだった！」",
  str_homestory_803801001_17_option_content = "イエス",
  str_homestory_803801001_18_dialog_content = "え？あたし、ロボットなんかじゃないよ！",
  str_homestory_803801001_19_option_content = "ノー",
  str_homestory_803801001_20_dialog_content = "ピンポン！正解～！<sprite=emo_dianzan size=60 />",
  str_homestory_803801001_21_dialog_content = "第二問！",
  str_homestory_803801001_22_dialog_content = "ラファエルは昔「王座トーナメント」でガルーを負かしたことがある！",
  str_homestory_803801001_23_option_content = "イエス",
  str_homestory_803801001_24_dialog_content = "ちょっとちょっと、あたしの方がすごいに決まってるでしょ！",
  str_homestory_803801001_25_dialog_content = "ラファエルのオモチャ、あたしが改良してあげてるくらいなんだから！",
  str_homestory_803801001_26_option_content = "ノー",
  str_homestory_803801001_27_dialog_content = "ふっふっふ…正解だ、若者よ～。",
  str_homestory_803801001_28_dialog_content = "じゃあ、第三問！",
  str_homestory_803801001_29_dialog_content = "PlayerNameはここの生活システムの権限をガルーに譲渡する！",
  str_homestory_803801001_30_dialog_content = "ええと…",
  str_homestory_803801001_31_dialog_content = "ちょっと待ってよ。今のってクイズの問題なの？",
  str_homestory_803801001_32_dialog_content = "あれ、ダメなの？",
  str_homestory_803801001_33_dialog_content = "オッホン…当然ダメだよ。",
  str_homestory_803801001_34_dialog_content = "へぇ～？あたしの申し入れを断るっていうのね？",
  str_homestory_803801001_35_dialog_content = "じゃあ、きっとラスボスか何かに操られてるのね！",
  str_homestory_803801001_36_dialog_content = "操られてる？なんでそうなるの？",
  str_homestory_803801001_37_dialog_content = "本物の空の末裔だったら、\nアタシに向かって「ダメ」なんて言うはずないでしょ？",
  str_homestory_803801001_38_dialog_content = "お人好しの空の末裔クンは、\n今まであたしのお願いなら何でも聞いてくれたもんね！",
  str_homestory_803801001_39_dialog_content = "アハハ…",
  str_homestory_803801001_40_dialog_content = "他のものならともかく、巨像とこの場所だけはダメだよ。",
  str_homestory_803801001_41_dialog_content = "ちぇ～…つまんないの。",
  str_homestory_803801001_42_dialog_content = "でも…",
  str_homestory_803801001_43_dialog_content = "正々堂々研究させてくれないっていうなら、\nこっそり研究するしかないね！",
  str_homestory_803801001_44_dialog_content = "いつかきっと…ふふふ…いつかきっと、\nここのシステムがどうやって動いてるのか、明らかにしてみせるから！",
  str_homestory_803801001_45_dialog_content = "が、がんばって…",
  str_homestory_803801001_46_dialog_content = "幸運を祈ってるよ？",
  str_homestory_803801001_47_dialog_content = "新しいゲームの始まりよ！！ワクワクしてきたわ…<sprite=emo_yaosu size=60 />",
  str_homestory_802601001_0_dialog_content = "ウリエル…",
  str_homestory_802601001_1_dialog_content = "…",
  str_homestory_802601001_2_dialog_content = "…",
  str_homestory_802601001_3_dialog_content = "何か…用かしら…",
  str_homestory_802601001_4_dialog_content = "あ、特にこれといった用じゃないんだ…ただ、様子を見に来たんだよ。",
  str_homestory_802601001_5_dialog_content = "ここで慣れないことはないかなと思って。\n巨像でも、よく眠れてなかったでしょ。",
  str_homestory_802601001_6_dialog_content = "特にないわ…",
  str_homestory_802601001_7_dialog_content = "私が慣れているものなんて…炎の輪と羽衣だけだもの…",
  str_homestory_802601001_8_dialog_content = "ええと…じゃあ、何か他に必要なものはない？",
  str_homestory_802601001_9_dialog_content = "例えば、食べ物とか、オモチャとか…他にも、何でもいいよ？",
  str_homestory_802601001_10_dialog_content = "何か要望があれば、僕に言って！",
  str_homestory_802601001_11_dialog_content = "何も欲しいものはないわ…",
  str_homestory_802601001_12_dialog_content = "どうせ、私のせいで全部焼けてしまうから<sprite=emo_nuhuo size=60 />…",
  str_homestory_802601001_13_dialog_content = "いやいや、大丈夫だよ、ウリエル。",
  str_homestory_802601001_14_dialog_content = "ちゃんと防火設備も造ってあるんだ。\nだから、心配しないで。何も気にせず、\nここで暮らしてもらっていいんだよ！",
  str_homestory_802601001_15_dialog_content = "そう…",
  str_homestory_802601001_16_dialog_content = "そうだよ！",
  str_homestory_802601001_17_dialog_content = "何か、思いついた？",
  str_homestory_802601001_18_dialog_content = "…",
  str_homestory_802601001_19_dialog_content = "…ないわ。",
  str_homestory_802601001_20_dialog_content = "オモチャも、娯楽も…喜びをもたらすものは皆、またたく間に消えていくの…",
  str_homestory_802601001_21_dialog_content = "はかなくて、軽い…",
  str_homestory_802601001_22_dialog_content = "そうして一瞬の喜びが過ぎた後、\nすぐに、また終わりなき苦痛が来る…",
  str_homestory_802601001_23_dialog_content = "そんな苦痛に身を焦がされる代償が、\nたった一瞬のはかない喜びなら…",
  str_homestory_802601001_24_dialog_content = "そんなもの…いらないって思うの…",
  str_homestory_802601001_25_dialog_content = "それに…苦痛の後に、必ず「喜び」が待っているとは限らない…",
  str_homestory_802601001_26_dialog_content = "むしろ、そういうはかない「喜び」が、\nすべての苦痛に価値があるという誤解を人々に植え付けてしまうの…",
  str_homestory_802601001_27_dialog_content = "でも、本当はそうじゃない…だって苦しみは無限、「喜び」は有限だもの…<sprite=emo_xinsui size=60 />",
  str_homestory_802601001_28_dialog_content = "…そうでしょう？PlayerName…",
  str_homestory_802601001_29_dialog_content = "（妙に真に迫ってるけど、僕には彼女の言うことが理解できない…）",
  str_homestory_802601001_30_option_content = "正しいね",
  str_homestory_802601001_31_dialog_content = "ある意味、君の言う通りかもしれないね。",
  str_homestory_802601001_32_option_content = "間違ってる",
  str_homestory_802601001_33_dialog_content = "ウリエルの考え方は理解できるけど、\n僕の考え方は君のとはちょっと違う…",
  str_homestory_802601001_34_dialog_content = "（とにかく、まずは彼女の気持ちをなぐさめることが大切だ…）",
  str_homestory_802601001_35_dialog_content = "ウリエルは、苦しみの後の喜びは安っぽくて、\nはかないって思ってるかもしれないけど…",
  str_homestory_802601001_36_dialog_content = "多くの人が、そのほんのわずかな「喜び」のために生きてるんじゃない？",
  str_homestory_802601001_37_dialog_content = "苦しみの後に得る「喜び」って、「希望」とも考えられるよね。",
  str_homestory_802601001_38_dialog_content = "その「希望」が皆に次への期待を与えて、次の「喜び」につながっていく…",
  str_homestory_802601001_39_dialog_content = "例え、1回1回の喜びは短くて、小さいものでも、\n一瞬でもなぐさめになることには変わりない。",
  str_homestory_802601001_40_dialog_content = "「喜び」はそもそも、苦痛の後のごほうびじゃなくて…",
  str_homestory_802601001_41_dialog_content = "人が苦痛に耐え続けられるようになるための、糧なんじゃないかな。",
  str_homestory_802601001_42_dialog_content = "…",
  str_homestory_802601001_43_dialog_content = "…糧…",
  str_homestory_802601001_44_dialog_content = "…そうかもしれないわ…",
  str_homestory_802601001_45_dialog_content = "（ううん、同意はしてもらえなさそうだ…）",
  str_homestory_802601001_46_dialog_content = "まぁ…とにかく、ウリエルは喜ぶことを負担だと思わなければいいんだよ！",
  str_homestory_802601001_47_dialog_content = "…そうね…",
  str_homestory_802601001_48_dialog_content = "…分かったわ、PlayerName…",
  str_homestory_802601001_49_dialog_content = "…気づかってくれて…ありがとう…",
  str_homestory_802601001_50_dialog_content = "いや、それほどでも…",
  str_homestory_802601001_51_dialog_content = "あ…喜びといえば…",
  str_homestory_802601001_52_dialog_content = "（ウリエルは本を読むのが好きだったよね？\n影ノ街で流行しているような…「文学作品」が好きなはず…）",
  str_homestory_802601001_53_dialog_content = "そうだ、ウリエル、代わりに本でも借りてこようか？",
  str_homestory_802601001_54_dialog_content = "タイクツなら、本を読むといいいよ。",
  str_homestory_802601001_55_dialog_content = "安心して。ここにはいろんな人がいるから、\nどんな種類の本も、一通り揃えてあるんだ…",
  str_homestory_802601001_56_dialog_content = "…本、ね…",
  str_homestory_802601001_57_dialog_content = "…",
  str_homestory_802601001_58_dialog_content = "…そうね…",
  str_homestory_802601001_59_dialog_content = "読むわ…",
  str_homestory_802601001_60_dialog_content = "ふぅ…よかった。",
  str_homestory_804401001_0_dialog_content = "ビビアンさん？",
  str_homestory_804401001_1_dialog_content = "ブランコはとても面白いですね、PlayerName！",
  str_homestory_804401001_2_dialog_content = "はい、僕も面白いと思います。",
  str_homestory_804401001_3_dialog_content = "顔の上を風が吹いて、何も考える必要がありません。<sprite=emo_pugongying size=60 />",
  str_homestory_804401001_4_dialog_content = "ブランコが身体の重みをゆっくりと風の中に溶かすようで…",
  str_homestory_804401001_5_dialog_content = "重力が消えたかのように感じますね。",
  str_homestory_804401001_6_dialog_content = "そこまでリラックスしてもらえてるなら、よかったです。",
  str_homestory_804401001_7_dialog_content = "強いて言うなら、ブランコの唯一の欠点は…",
  str_homestory_804401001_8_dialog_content = "遊んだ後、髪が少し乱れることでしょうか。フフフ…",
  str_homestory_804401001_9_dialog_content = "なるほど。",
  str_homestory_804401001_10_dialog_content = "バイスもブランコで遊んだ後、髪を気にしてました。",
  str_homestory_804401001_11_dialog_content = "おや？するとこのブランコは、\nどちらが造ろうと言い出したのですか？",
  str_homestory_804401001_12_option_content = "僕です",
  str_homestory_804401001_13_dialog_content = "ブランコで遊んだこと、ほとんどなかったので…",
  str_homestory_804401001_14_dialog_content = "ここに造ったら、面白いかなと思ったんですが。",
  str_homestory_804401001_15_option_content = "バイスです",
  str_homestory_804401001_16_dialog_content = "バイスがどうしても造りたいって言ったんです！",
  str_homestory_804401001_17_dialog_content = "僕はあんまり乗り気じゃなかったんですが、\nバイスが自信満々に施工図を描き始めたので、それで…",
  str_homestory_804401001_18_dialog_content = "ここにあってもいいか、皆も気に入るかなと思ったんです。",
  str_homestory_804401001_19_dialog_content = "あらあら…",
  str_homestory_804401001_20_dialog_content = "とても素晴らしい決断だと思いますよ！",
  str_homestory_804401001_21_dialog_content = "へへへ…ありがとうございます、ビビアンさん。",
  str_homestory_804401001_22_dialog_content = "しかし、考えてみると…",
  str_homestory_804401001_23_dialog_content = "啓光では、あまりブランコを見なかったように思いますね。",
  str_homestory_804401001_24_dialog_content = "ううん…そうかもしれませんね？",
  str_homestory_804401001_25_dialog_content = "だからバイスもビビアンさんも、ブランコが気に入ってるんでしょうか？",
  str_homestory_804401001_26_dialog_content = "そうですね、珍しいから夢中になっているのかもしれません。",
  str_homestory_804401001_27_dialog_content = "ううん…そうですね…",
  str_homestory_804401001_28_dialog_content = "え？何か思いついたんですか？",
  str_homestory_804401001_29_dialog_content = "いいえ、何でもありません。",
  str_homestory_804401001_30_dialog_content = "私はただ、支出<sprite=emo_baiyebi size=60 />の必要性を、\n計算しているんです。",
  str_homestory_804401001_31_dialog_content = "支出！？",
  str_homestory_804401001_32_dialog_content = "何のですか？",
  str_homestory_804401001_33_dialog_content = "もし啓光のすべての孤児院や学校と…",
  str_homestory_804401001_34_dialog_content = "関連する基地にブランコを設置した場合、\nいくらかかるか考えていたのです。",
  str_homestory_804401001_35_dialog_content = "あ…そうだったんですか。",
  str_homestory_804401001_36_dialog_content = "ですが、ざっと計算しただけでも、予算を越えそうです…",
  str_homestory_804401001_37_dialog_content = "そのまま実行に移せば、\n他の部分で支出を削らなければなりません。",
  str_homestory_804401001_38_dialog_content = "ちょっとした難題ですね。",
  str_homestory_804401001_39_dialog_content = "それなら…設置数を抑えるとか？",
  str_homestory_804401001_40_dialog_content = "その分、場所を厳選したらどうでしょう？",
  str_homestory_804401001_41_dialog_content = "例えば…",
  str_homestory_804401001_42_dialog_content = "例えば、人の多い場所ですね。",
  str_homestory_804401001_43_dialog_content = "各シェルターの境界線や孤児院または学校の中間線…",
  str_homestory_804401001_44_dialog_content = "あなたの言う通りです、PlayerName！",
  str_homestory_804401001_45_dialog_content = "参考になったなら、よかったです。",
  str_homestory_804401001_46_dialog_content = "ただ…",
  str_homestory_804401001_47_dialog_content = "私が予算と言った時、\n妙に緊張していませんでしたか？",
  str_homestory_804401001_48_dialog_content = "あ、アハハ…",
  str_homestory_804401001_49_dialog_content = "バイスが帳簿を見ている時の雰囲気に近かったので…",
  str_homestory_804401001_50_dialog_content = "条件反射で、緊張したんだと思います…",
  str_homestory_804401001_51_dialog_content = "あらあら、バイスとずいぶん仲がいいようですね…<sprite=emo_guilian size=60 />",
  str_homestory_808501001_0_dialog_content = "ジェーン？",
  str_homestory_808501001_1_dialog_content = "こんにちは、PlayerNameさん。",
  str_homestory_808501001_2_dialog_content = "こんにちは！",
  str_homestory_808501001_3_dialog_content = "今…天空ノ庭の記録をとってるの？",
  str_homestory_808501001_4_dialog_content = "ええ、ここで起こったすべてのことを記録するつもりです。",
  str_homestory_808501001_5_dialog_content = "ですが、今は記録していません。単純に頭の中を空っぽにしています。<sprite=emo_pugongying size=60 />",
  str_homestory_808501001_6_dialog_content = "空っぽ？",
  str_homestory_808501001_7_dialog_content = "どうして？何かイヤなことでもあった？",
  str_homestory_808501001_8_dialog_content = "それとも最近、ストレスが大きいとか？",
  str_homestory_808501001_9_dialog_content = "どちらもあります。",
  str_homestory_808501001_10_dialog_content = "PlayerName、プロの「記録者」は、\n物事に口出しや手出しをしてはならないということは、ご存知ですね。",
  str_homestory_808501001_11_dialog_content = "うん、聞いたことあるよ。",
  str_homestory_808501001_12_dialog_content = "それなら…",
  str_homestory_808501001_13_dialog_content = "あなたが「記録者」だったとして、\nある組織の内輪もめで被害者となった人を助けますか？",
  str_homestory_808501001_14_option_content = "助ける",
  str_homestory_808501001_15_dialog_content = "「記録者」っていうのは職業にすぎないし…",
  str_homestory_808501001_16_option_content = "助けない",
  str_homestory_808501001_17_dialog_content = "実を言うと、僕からすれば「絶対的な客観性を保つ」ことは、\nそれほど重要じゃなくて…",
  str_homestory_808501001_18_dialog_content = "僕だったら、すぐに誰かに知らせて助けに来てもらうかな。",
  str_homestory_808501001_19_dialog_content = "それでもやはり、助けるのですね。\n自分の手で助けはしないということでしょうか？",
  str_homestory_808501001_20_dialog_content = "そうだね。",
  str_homestory_808501001_21_dialog_content = "ジェーンはどっちを選ぶの？",
  str_homestory_808501001_22_dialog_content = "僕にそんな質問をして、苦しそうな表情をしてるってことは、\n本当にそういうことがあったんでしょ。",
  str_homestory_808501001_23_dialog_content = "ええ、私はある少女を助けました。",
  str_homestory_808501001_24_dialog_content = "今でも自分のした選択に悩まされています。",
  str_homestory_808501001_25_dialog_content = "何を心配してるの？",
  str_homestory_808501001_26_dialog_content = "私の介入で、事態が本来と異なる方へと、\n発展してしまうのではないかと心配しています。",
  str_homestory_808501001_27_dialog_content = "記録者の立場が揺るげば、記録が中立とは言えなくなります。",
  str_homestory_808501001_28_dialog_content = "あの少女はそもそも消えるべきだったのかもしれません。\nそれが本来の結果だったのですから。",
  str_homestory_808501001_29_dialog_content = "ですが、私は彼女を救ったために…",
  str_homestory_808501001_30_dialog_content = "…記録は中立のものでなくなり、意義を失いました。",
  str_homestory_808501001_31_dialog_content = "でも…何よりもまず、君は感情をもった人だよ。\nその次に「中立」を保つべき「記録者」なんだ。",
  str_homestory_808501001_32_dialog_content = "道理は私も分かっています。",
  str_homestory_808501001_33_dialog_content = "…",
  str_homestory_808501001_34_dialog_content = "…分かったよ。",
  str_homestory_808501001_35_dialog_content = "もしそんなに心配なら、自分のことも記録に書けばいいよ。",
  str_homestory_808501001_36_dialog_content = "私のことを…？",
  str_homestory_808501001_37_dialog_content = "そうだよ…事実をありのままに書けばいい。",
  str_homestory_808501001_38_dialog_content = "記録者が心を動かされ、事態に介入した…\nそれによって結果が変わってしまったかもしれない。",
  str_homestory_808501001_39_dialog_content = "…みたいな感じで。",
  str_homestory_808501001_40_dialog_content = "…",
  str_homestory_808501001_41_dialog_content = "あなたの言うことも間違いではありませんね。",
  str_homestory_808501001_42_dialog_content = "今回のことは、そのように記録してみます。",
  str_homestory_808501001_43_dialog_content = "ありがとうございます。",
  str_homestory_808801001_0_dialog_content = "マギー！",
  str_homestory_808801001_1_dialog_content = "ナビゲーターさん…あ、あなたもお話を聞きにきたんですか？<sprite=emo_wuzui size=60 />",
  str_homestory_808801001_2_dialog_content = "お話？何の？",
  str_homestory_808801001_3_dialog_content = "特に用事があるわけじゃなかったけど、\n今はその話に興味がわいたよ。",
  str_homestory_808801001_4_dialog_content = "た、大変です…うっかり口を滑らせてしまいました…",
  str_homestory_808801001_5_dialog_content = "え？僕に知られたくないことだったの？",
  str_homestory_808801001_6_dialog_content = "い、いえ、そういうわけでは…",
  str_homestory_808801001_7_dialog_content = "分かりました…どうせもう、知ってる人も多いですし…",
  str_homestory_808801001_8_dialog_content = "何かあったの？",
  str_homestory_808801001_9_dialog_content = "あの…数日前に、砂漠で略奪に出かけた時…",
  str_homestory_808801001_10_dialog_content = "何人かの子供たちに会ったんです。",
  str_homestory_808801001_11_dialog_content = "一目で家からこっそり抜け出して、\n砂漠で道に迷ったんだと分かりました…",
  str_homestory_808801001_12_dialog_content = "その場から動かずおろおろしていたようだったので、\n助けがいらないか、たずねたんです…",
  str_homestory_808801001_13_dialog_content = "安全な所まで送り届けた後、私の名前を聞かれて…\n後でお礼をしに来ると言ってくれたんです。",
  str_homestory_808801001_14_dialog_content = "ちょうど名前を教えようとした時、\n子供たちが私のしっぽに気付いて…それで…",
  str_homestory_808801001_15_option_content = "笑われた？",
  str_homestory_808801001_16_dialog_content = "い、いえ、違います…",
  str_homestory_808801001_17_dialog_content = "子供たちは、しっぽがかわいいって言ってくれました…",
  str_homestory_808801001_18_dialog_content = "じゃあ、いいことじゃないの？",
  str_homestory_808801001_19_option_content = "君のことを知ってたの？",
  str_homestory_808801001_20_dialog_content = "いいえ…",
  str_homestory_808801001_21_dialog_content = "フェラールでもありませんし、私の名前なんて知られていません…",
  str_homestory_808801001_22_dialog_content = "で、でも、子供たちは…",
  str_homestory_808801001_23_dialog_content = "わ、私のことを竜だとカン違いしたんです！",
  str_homestory_808801001_24_dialog_content = "…？",
  str_homestory_808801001_25_dialog_content = "私の、その時の反応も、今のあなたとほとんど同じでした…",
  str_homestory_808801001_26_dialog_content = "変わったことを考える子たちだな、と思いました！",
  str_homestory_808801001_27_dialog_content = "しっぽがモコモコした竜は初めて見たとも言われました…",
  str_homestory_808801001_28_dialog_content = "それで、しっぽを触っていいかなんて聞いてきたんです…",
  str_homestory_808801001_29_dialog_content = "その時、私、本当に腹が立って…！<sprite=emo_wuyun size=60 />",
  str_homestory_808801001_30_dialog_content = "どうして？説明すればいいことじゃない？",
  str_homestory_808801001_31_dialog_content = "間違われたことに怒ってるんじゃないんです！\n態度に怒ってるんです！",
  str_homestory_808801001_32_dialog_content = "「しっぽを触ってもいいか」なんて…",
  str_homestory_808801001_33_dialog_content = "ひどいじゃないですか！！",
  str_homestory_808801001_34_dialog_content = "私のことをまるでペットみたいに！",
  str_homestory_808801001_35_dialog_content = "本当に…ムカムカするぜ…",
  str_homestory_808801001_36_dialog_content = "何もかも燃やしてやる<sprite=emo_nuhuo size=60 />！！今すぐに！",
  str_homestory_808801001_37_dialog_content = "（興奮し始めた！？）",
  str_homestory_808801001_38_dialog_content = "ま、待って、マギー！",
  str_homestory_808801001_39_dialog_content = "その子たち、単に君のしっぽが可愛いと思っただけなんじゃないの？",
  str_homestory_808801001_40_dialog_content = "だ、だって、僕もそう思うから！",
  str_homestory_808801001_41_dialog_content = "…僕はしっぽがないマギーなんて想像もできないよ。",
  str_homestory_808801001_42_dialog_content = "…",
  str_homestory_808801001_43_dialog_content = "…ほ、本当ですか？",
  str_homestory_808801001_44_dialog_content = "（ふぅ…少し落ち着いたみたいだ…）",
  str_homestory_808801001_45_dialog_content = "本当だよ、マギー。絶対に！",
  str_homestory_808801001_46_dialog_content = "…そ…そうですか…",
  str_homestory_808801001_47_dialog_content = "あ、そういえば…",
  str_homestory_808801001_48_dialog_content = "さっきはなんで、たくさんの人に知られてるって言ったの？",
  str_homestory_808801001_49_dialog_content = "僕の知る限り、そんな話誰もしてないし、\n知ってる人は数えるほどもいないと思うけど…",
  str_homestory_808801001_50_dialog_content = "そ、それは…",
  str_homestory_808801001_51_dialog_content = "ジョムが出してる短編小説集の最新版でネタにされたので…",
  str_homestory_808801001_52_dialog_content = "…そうなんだ、知らなかったよ…",
  str_homestory_800801001_0_dialog_content = "ヘール？",
  str_homestory_800801001_1_dialog_content = "ハッハッハ！来たか！<sprite=emo_yaosu size=60 />",
  str_homestory_800801001_2_dialog_content = "どうだ、今の見たか？\n俺様、カッコよかっただろ？",
  str_homestory_800801001_3_dialog_content = "…何のこと？",
  str_homestory_800801001_4_dialog_content = "俺様のパンチの動きだよ！\nキレがあって、\nカッコよかっただろ！？",
  str_homestory_800801001_5_dialog_content = "ああ、うん、なかなかだね…",
  str_homestory_800801001_6_dialog_content = "「なかなか」ぁ？\nずいぶんアッサリした\n感想じゃねぇか？",
  str_homestory_800801001_7_dialog_content = "まあ、いい。格闘技はできないだろうしな。\n俺様にシットしてんだろ？",
  str_homestory_800801001_8_dialog_content = "…？",
  str_homestory_800801001_9_dialog_content = "でも、安心しろよ、PlayerName！\nシットされてようが、態度を変えたりはしねぇからな！",
  str_homestory_800801001_10_dialog_content = "別にうらやましいとは思ってないけど…",
  str_homestory_800801001_11_dialog_content = "シーッ…分かってるって。",
  str_homestory_800801001_12_dialog_content = "俺様も小さい時は、\n今の俺様みてえな本物の男にあこがれたもんだ！<sprite=emo_mojing size=60 />",
  str_homestory_800801001_13_dialog_content = "いいか、よく聞け、PlayerName！\nココロザシさえあれば、出来ないことは何もない！",
  str_homestory_800801001_14_dialog_content = "…そ、そうだね…分かったよ、ヘール。",
  str_homestory_800801001_15_dialog_content = "そうかしこまるなって。\n天空ノ庭にエネルギーを注入するのは、\n俺様の責任だからな。",
  str_homestory_800801001_16_dialog_content = "子どもたちの面倒を見るのも得意だぜ。",
  str_homestory_800801001_17_dialog_content = "待って…エネルギー？責任？何の話？",
  str_homestory_800801001_18_dialog_content = "なんだ？俺様がPlayerNameのために\nしてやってること、知らねぇのか？",
  str_homestory_800801001_19_dialog_content = "…詳しく聞かせて。",
  str_homestory_800801001_20_dialog_content = "何日か前に、オティんところに行って、\nターボを虹色に塗りかえてもらおうとしたんだ。",
  str_homestory_800801001_21_dialog_content = "ところが、オティの奴が暗い顔してたんだ。\nで、あんたを手伝ってくれって頼まれてな。",
  str_homestory_800801001_22_dialog_content = "手伝い？",
  str_homestory_800801001_23_dialog_content = "オティが言ってたぜ…",
  str_homestory_800801001_24_dialog_content = "このボクシング用ダミー人形の中に、\nエンジンが入ってて…",
  str_homestory_800801001_25_dialog_content = "…？",
  str_homestory_800801001_26_dialog_content = "そのエンジンが天空ノ庭全体の動力になってるんだろ？",
  str_homestory_800801001_27_dialog_content = "つまり、俺様が毎日こいつを何千回か殴らないと、\nこの天空ノ庭のエネルギーが停まっちまうってわけだ。",
  str_homestory_800801001_28_dialog_content = "おいおい、なんだその顔は！\nエンリョするなって！",
  str_homestory_800801001_29_dialog_content = "それぐらいのこと、喜んでやってやるぜ！",
  str_homestory_800801001_30_dialog_content = "…ええと、ヘール…僕が思うに…",
  str_homestory_800801001_31_option_content = "だまされてるよ",
  str_homestory_800801001_32_dialog_content = "ダミー人形の中は砂が詰まってるだけだよ。\n機械なんか入ってない…",
  str_homestory_800801001_33_dialog_content = "要するに、天空ノ庭のエネルギーとこの人形は、\n何の関係もないよ。",
  str_homestory_800801001_34_dialog_content = "…オッホン、でも！",
  str_homestory_800801001_35_dialog_content = "君が毎日ここでパンチの練習をするのは、健康にいいと思う。",
  str_homestory_800801001_36_option_content = "ありがとう！",
  str_homestory_800801001_37_dialog_content = "オッホン、ただ…",
  str_homestory_800801001_38_dialog_content = "オティは天空ノ庭の構造のこと、\nあまり詳しく分かってないと思うよ。",
  str_homestory_800801001_39_dialog_content = "つまり…僕が言いたいのは…",
  str_homestory_800801001_40_dialog_content = "ダミー人形の中は砂が詰まってるだけだよ。\n機械なんか入ってない…",
  str_homestory_800801001_41_dialog_content = "何！そうだったのか！？",
  str_homestory_800801001_42_dialog_content = "ハッハッハ！\nなんだ、オティにも間違える時があるんだな！",
  str_homestory_800801001_43_dialog_content = "あの、ヘール…",
  str_homestory_800801001_44_dialog_content = "たぶん、オティにからかわれてるんじゃないかな…",
  str_homestory_800801001_45_dialog_content = "俺様もそう思ってるぞ。\nみんないつも、俺様をからかってるからな。",
  str_homestory_800801001_46_dialog_content = "え？怒らないの？",
  str_homestory_800801001_47_dialog_content = "何にだ？",
  str_homestory_800801001_48_dialog_content = "俺様と一緒にふざけんのが好きなんだろ？\nつまり、みんな俺様のことが好きだってことだ！",
  str_homestory_800801001_49_dialog_content = "…うん、それもそうだね。",
  str_homestory_800801001_50_dialog_content = "それに、もし…",
  str_homestory_800801001_51_dialog_content = "俺のことをからかうヤツがいたとしても、\nそれはそいつらが俺様のことを応援してて、\n信用してるからだろ。",
  str_homestory_800801001_52_dialog_content = "…本当にそうかな？",
  str_homestory_800801001_53_dialog_content = "じゃなきゃ、どうして誰も\nサメヤマをからかわねぇんだよ？",
  str_homestory_800801001_54_dialog_content = "「親しみやすさ」ってことじゃ、やっぱり俺様の勝ちってことだ！\nハッハッハッハッハ！<sprite=emo_dianzan size=60 />",
  str_homestory_806501001_0_dialog_content = "タタ…？",
  str_homestory_806501001_1_dialog_content = "うわぁ～！お兄さん…いはったんですね。",
  str_homestory_806501001_2_dialog_content = "タタ、どうしたの？\nなんで僕を見て、そんなにあわててるの？",
  str_homestory_806501001_3_dialog_content = "そ、そないなことは…",
  str_homestory_806501001_4_dialog_content = "ほら、何か落としちゃってるよ。",
  str_homestory_806501001_5_dialog_content = "ありゃ！どこどす？",
  str_homestory_806501001_6_dialog_content = "足元の白くて、モフモフしたもの…",
  str_homestory_806501001_7_dialog_content = "ええと…",
  str_homestory_806501001_8_dialog_content = "わあ！こりゃ、うちの羽どす！",
  str_homestory_806501001_9_dialog_content = "はぁ…うしろめたいことは、したらあきませんな…",
  str_homestory_806501001_10_dialog_content = "うしろめたい？",
  str_homestory_806501001_11_dialog_content = "それでタタの尾っぽが下がってたんだね。",
  str_homestory_806501001_12_dialog_content = "うう…",
  str_homestory_806501001_13_dialog_content = "で、一体どうしたの？話してもらえる？",
  str_homestory_806501001_14_dialog_content = "しょうがおへんな…",
  str_homestory_806501001_15_dialog_content = "うち、今日は配達で来ましてん。",
  str_homestory_806501001_16_dialog_content = "そうなの？もう『止まり木』には届けた？後で見に行くよ！",
  str_homestory_806501001_17_dialog_content = "えと…ちょいと待ってください…",
  str_homestory_806501001_18_dialog_content = "まだ届けてませんねん。",
  str_homestory_806501001_19_dialog_content = "久しぶりに天空ノ庭に来てみて、\nえらく変わったなって思いましてん！",
  str_homestory_806501001_20_dialog_content = "そんであちこち飛び回ってたら、\n配達のこと、忘れてしもて…",
  str_homestory_806501001_21_dialog_content = "後ろめたいことって、それ？",
  str_homestory_806501001_22_option_content = "（怒る）",
  str_homestory_806501001_23_dialog_content = "仕事をすっぽかすのは、確かによくないね。",
  str_homestory_806501001_24_dialog_content = "天空ノ谷の「止まり木」にサインした責任者として、\n何か罰でも言い渡した方がいいのかな？",
  str_homestory_806501001_25_dialog_content = "ば、罰どすか？",
  str_homestory_806501001_26_dialog_content = "尾っぽの羽根が落ちてしまいそうどす…",
  str_homestory_806501001_27_dialog_content = "ええと、じゃあ…",
  str_homestory_806501001_28_option_content = "（なぐさめる）",
  str_homestory_806501001_29_dialog_content = "構わないよ、そんなに急ぐことじゃないし。",
  str_homestory_806501001_30_dialog_content = "タタに天空ノ庭を気に入ってもらえたのも、\nいい知らせの一つだよ。",
  str_homestory_806501001_31_dialog_content = "お兄さん、おおきに。ほんまにええ人やわ！",
  str_homestory_806501001_32_dialog_content = "それで、誰からの手紙だったの？",
  str_homestory_806501001_33_dialog_content = "手紙を見せて。",
  str_homestory_806501001_34_dialog_content = "了解どす！クーリエ隊、使命は必ずやり遂げますぅ！",
  str_homestory_806501001_35_dialog_content = "…ありゃ？どないしたんやろ、手紙がみつからへん…",
  str_homestory_806501001_36_dialog_content = "バッグの中にも…",
  str_homestory_806501001_37_dialog_content = "帽子の中にもありまへん！",
  str_homestory_806501001_38_dialog_content = "あわてないで。どこかに落としたのかも？",
  str_homestory_806501001_39_dialog_content = "タタ、さっきはどこに行ったの？",
  str_homestory_806501001_40_dialog_content = "ええと、天空ノ庭じゅうを…全部まわりましてん。",
  str_homestory_806501001_41_dialog_content = "…探さないといけない範囲が広いなぁ…",
  str_homestory_806501001_42_dialog_content = "どないしましょ！？うち、ドーヴ先輩にはなりとうない――",
  str_homestory_806501001_43_dialog_content = "あれ？尾っぽから何か落ちてきたよ？",
  str_homestory_806501001_44_dialog_content = "羽根がまた落ちてしもたんどすか？\nこれ以上落ちてしもたら、ハゲてまいます！",
  str_homestory_806501001_45_dialog_content = "いや、羽じゃないみたいだ…",
  str_homestory_806501001_46_dialog_content = "ありゃ…",
  str_homestory_806501001_47_dialog_content = "うちが届けようとしてた手紙どす！",
  str_homestory_806501001_48_dialog_content = "尾っぽの中に隠れとりましたわ！",
  str_homestory_805501001_0_dialog_content = "あれは…？",
  str_homestory_805501001_1_dialog_content = "ピアタマン…？",
  str_homestory_805501001_2_dialog_content = "…！",
  str_homestory_805501001_3_dialog_content = "ピアタマンだよね？",
  str_homestory_805501001_4_dialog_content = "オッホン！人違いでしょう。",
  str_homestory_805501001_5_dialog_content = "え？でも、そのやたらキッチリした格好と、\n目の下のクマは…",
  str_homestory_805501001_6_dialog_content = "どう見てもピアタマンだよ。",
  str_homestory_805501001_7_dialog_content = "シーッ…",
  str_homestory_805501001_8_dialog_content = "お声を低く！\n他の方に聞かれては困ります…",
  str_homestory_805501001_9_option_content = "（疑問を示す）",
  str_homestory_805501001_10_dialog_content = "え？白夜城の裁判官なのに、バレたら困ることでもあるの？",
  str_homestory_805501001_11_option_content = "（理解を示す）",
  str_homestory_805501001_12_dialog_content = "あ、分かった。",
  str_homestory_805501001_13_dialog_content = "ここにいることを知られたくないんだね？",
  str_homestory_805501001_14_dialog_content = "まさか、白夜城に指名手配でもされた？",
  str_homestory_805501001_15_dialog_content = "私は品行方正、正々堂々、後ろめたいことなどなく、\n光の神の敬虔なしもべとして、\n白夜城に忠誠を誓っています。",
  str_homestory_805501001_16_dialog_content = "そんな私が、なぜ指名手配されるのでしょう？",
  str_homestory_805501001_17_dialog_content = "例えば…",
  str_homestory_805501001_18_dialog_content = "こっそり木馬で遊んでたから…",
  str_homestory_805501001_19_dialog_content = "…やはりご覧になっていたのですね？<sprite=emo_daomei size=60 />",
  str_homestory_805501001_20_dialog_content = "…本当に遊んでたんだ？",
  str_homestory_805501001_21_dialog_content = "オッホン…私はただ、\nこの木馬の品質を調べていただけです。",
  str_homestory_805501001_22_dialog_content = "近頃、市場に粗悪品があふれているようですから。",
  str_homestory_805501001_23_dialog_content = "消費者をあざむく行為は、我々法廷の者が\n厳しく取り締まらなければなりません。",
  str_homestory_805501001_24_dialog_content = "とはいえ、ここの木馬は\n丈夫な材料で精巧に作られており、\n少なくとも84㎏の重さに耐えられるようです。",
  str_homestory_805501001_25_dialog_content = "どうぞ安心してお使いください。",
  str_homestory_805501001_26_dialog_content = "うん、ありがとう…",
  str_homestory_805501001_27_dialog_content = "でも、ここに木馬が置いてあるのは、\n皆に使ってもらって、気分を楽にしてもらいたいからだし…",
  str_homestory_805501001_28_dialog_content = "乗りたいって思ったなら、\nこそこそ乗る必要なんてないよ。",
  str_homestory_805501001_29_dialog_content = "それは…どういったお心でおっしゃっているのですか？",
  str_homestory_805501001_30_dialog_content = "だって、考えてること、全部顔に出てるよ。",
  str_homestory_805501001_31_dialog_content = "ピアタマン、本当にウソがつけないんだね。ハハハ…",
  str_homestory_805501001_32_dialog_content = "…そうですね。",
  str_homestory_805501001_33_dialog_content = "ですが、どうか、この秘密は\n守ってくださるようお願いいたします。",
  str_homestory_805501001_34_dialog_content = "どうして？そんなこと、秘密にする必要ある…？",
  str_homestory_805501001_35_dialog_content = "僕も木馬は好きだよ。",
  str_homestory_805501001_36_dialog_content = "正義をつかさどる裁判官として、\n私は人々を信服させるだけの品位を保ちたいのです。",
  str_homestory_805501001_37_dialog_content = "私にこのような幼い趣味があると他人に知られたら…",
  str_homestory_805501001_38_dialog_content = "おそらく、私の事件に対する裁定を\n誰も信じなくなるでしょう。",
  str_homestory_805501001_39_dialog_content = "そうかな…？",
  str_homestory_805501001_40_dialog_content = "ですからPlayerName殿、\nこのことは口外無用と言うことで…",
  str_homestory_805501001_41_dialog_content = "分かったよ。木馬で遊ぶことと裁判の信用性に\n関係があるなんて、僕は思えないけど…",
  str_homestory_805501001_42_dialog_content = "ピアタマンがそう望んでる以上、約束は守るよ！",
  str_homestory_805501001_43_dialog_content = "ご理解に感謝いたします。",
  str_homestory_805501001_44_dialog_content = "それから…",
  str_homestory_805501001_45_dialog_content = "もし何らかの粗悪品を購入されてしまわれた場合には、\n私が必ず正義を取り戻して差し上げましょう！<sprite=emo_qingsong size=60 />",
  str_homestory_815501001_0_dialog_content = "剣を収める音かな？",
  str_homestory_815501001_1_dialog_content = "天空ノ谷ってとこは、いいとこばかりだな、PlayerName！",
  str_homestory_815501001_2_dialog_content = "そ、それほどかな…？",
  str_homestory_815501001_3_dialog_content = "空の末裔ってのは、一体あとどれだけ秘密を隠してやがんだろうな？",
  str_homestory_815501001_4_dialog_content = "…すぐにでも知りてえ気分だぜ。",
  str_homestory_815501001_5_dialog_content = "それはそうと、ここは本当にいいところだぜ。",
  str_homestory_815501001_6_dialog_content = "いろんな設備もそろってるし、地形もけわしい。\n守るに易く、攻めるにかたし、ってヤツだ。",
  str_homestory_815501001_7_dialog_content = "もし本当に戦争になったら、\n何の問題もなく、相当長いあいだ軍事基地として機能できそうだ！",
  str_homestory_815501001_8_dialog_content = "バートン、ずいぶん考えてるんだね…",
  str_homestory_815501001_9_dialog_content = "当然だろ！",
  str_homestory_815501001_10_dialog_content = "力を追い求め続けることも大事だが、\n今あるモノをどう使うか考えることも重要だろ。",
  str_homestory_815501001_11_dialog_content = "（バートン、ちょっと変わった…？）",
  str_homestory_815501001_12_dialog_content = "若い時は分からなかったが、この2つは――",
  str_homestory_815501001_13_dialog_content = "――そうだ。お前はどう思う？",
  str_homestory_815501001_14_dialog_content = "まずは強くなることが大事か、\nそれとも手元の資源の使い方を考えて、計画することが大事か？<sprite=emo_sikao size=60 />",
  str_homestory_815501001_15_option_content = "強くなること",
  str_homestory_815501001_16_dialog_content = "例えば、僕が白夜コイン10枚しか持っていなかったら、\nどんな計画を立てても、役に立たない…",
  str_homestory_815501001_17_dialog_content = "だから、当然まずはお金を稼がなきゃ。\n力の話なら、まずは強くならなきゃ。でしょ？",
  str_homestory_815501001_18_option_content = "計画を立てる",
  str_homestory_815501001_19_dialog_content = "例えば、僕が白夜コイン10枚しか持ってなかったら、\nまずはどうやって生きていくかを考えて、その後どうやってお金を稼ぐか考えるよ…",
  str_homestory_815501001_20_dialog_content = "なんだ？それ、今のお前の話じゃねぇだろうな？",
  str_homestory_815501001_21_dialog_content = "まさかとは思うが、本当にコイン10枚しか持ってねえのか？",
  str_homestory_815501001_22_dialog_content = "…ただの例えだよ！！",
  str_homestory_815501001_23_dialog_content = "そうか。",
  str_homestory_815501001_24_dialog_content = "もしお前が本当に金に困ってんなら、\n俺が貸してやってもいいんだぜ。",
  str_homestory_815501001_25_dialog_content = "そう思うと、やっぱ啓光はラクだな。\n金を払わねえでも、いいもんがたくさん手に入る。",
  str_homestory_815501001_26_dialog_content = "…？",
  str_homestory_815501001_27_dialog_content = "おっと、話がそれたな…",
  str_homestory_815501001_28_dialog_content = "俺が言いたかったのは、\n強くなるのも計画を立てるのも、\n同時にやりゃいいって今は思ってるってことだ。",
  str_homestory_815501001_29_dialog_content = "そもそも矛盾するものじゃねぇ。",
  str_homestory_815501001_30_dialog_content = "俺は今まで強くなることばかり考えてきたが、\n多くのことの後ろにある意義を見逃してたんだ。",
  str_homestory_815501001_31_dialog_content = "今あるモノをどう使うか、しっかり計画を立てりゃ、\n俺たちが進むべき方向がもっとハッキリ見えてくる。",
  str_homestory_815501001_32_dialog_content = "自分をとことん知らなきゃいけねえ！\nそれでこそ、これから先の道を正しく選んで、\nもっと強くなれるんだ。",
  str_homestory_815501001_33_dialog_content = "強くなった者にしか、\n語る権利は与えられねえ。",
  str_homestory_815501001_34_dialog_content = "そうだね…ある意味、君の言う通りだと思う。",
  str_homestory_815501001_35_dialog_content = "ってこたぁ、ここを軍事用に貸しだしてくれるってことだな？",
  str_homestory_815501001_36_dialog_content = "…！？",
  str_homestory_815501001_37_dialog_content = "そんなこと言ってないよ！",
  str_homestory_815501001_38_dialog_content = "それに、軍事基地なんて、天空ノ庭には全くそぐわない！",
  str_homestory_815501001_39_dialog_content = "ハハ、そいつはどうかな。\nいつか本当に戦争になるかもしれねえぞ！？",
  str_homestory_815501001_40_dialog_content = "ちょっと、不吉なこと言わないで！？<sprite=emo_shengqi size=60 />",
  str_homestory_815501001_41_dialog_content = "不吉だぁ？\n最低限のリスク管理だろうが！",
  str_homestory_815501001_42_dialog_content = "ううん…そうとなりゃ、\n急いで演習のプランを考えねぇとな。",
  str_homestory_815501001_43_dialog_content = "今、頭ん中にある計画は…\n明日ビビアンに口で伝えりゃいいか。",
  str_homestory_815501001_44_dialog_content = "チッ、書類やら資料探しってのが、一番メンドクセぇ！\nああ、やりたくねえなぁ！",
  str_homestory_815501001_45_dialog_content = "（さっきの考え、撤回しよう…）",
  str_homestory_815501001_46_dialog_content = "（バートンはやっぱりバートンだ。\nちっとも変わってない）",
  str_homestory_801101001_0_dialog_content = "キシローナさん！",
  str_homestory_801101001_1_dialog_content = "ええと…",
  str_homestory_801101001_2_dialog_content = "新しい技の練習ですか？",
  str_homestory_801101001_3_dialog_content = "ああ、そうだ。",
  str_homestory_801101001_4_dialog_content = "ここに来てからも訓練<sprite=emo_yaling size=60 />を欠かさないなんて、\nさすがは正面突破の仕事を負う、第一軍団の軍団長ですね…",
  str_homestory_801101001_5_dialog_content = "それは誤解だ、PlayerName。",
  str_homestory_801101001_6_dialog_content = "この技を試しているのは、\n訓練に取り入れるためではない。",
  str_homestory_801101001_7_dialog_content = "最近、小説を読んでな。\nその中に出てきた技を練習しているのだ。",
  str_homestory_801101001_8_dialog_content = "小説を？",
  str_homestory_801101001_9_dialog_content = "いや、それより…小説の中に出てくる技を練習してるんですか？？？",
  str_homestory_801101001_10_dialog_content = "僕の中のイメージとだいぶ違う気が…",
  str_homestory_801101001_11_dialog_content = "そこまで驚くことか？",
  str_homestory_801101001_12_option_content = "（うなずく）",
  str_homestory_801101001_13_dialog_content = "いつも他のもっと大事なことで忙しそうだから、\n小説なんて読まない人だと思ってました…",
  str_homestory_801101001_14_dialog_content = "あ、いや、もちろん、小説を読む趣味が悪いって\n言ってるわけじゃありません。",
  str_homestory_801101001_15_option_content = "（首を振る）",
  str_homestory_801101001_16_dialog_content = "でも、考えて見ると、\n他人に対する印象を勝手に固めちゃいけないですよね。",
  str_homestory_801101001_17_dialog_content = "ただ、いつも忙しそうだから、\n小説を読む時間なんてなさそうだと思ってたので…",
  str_homestory_801101001_18_dialog_content = "確かに小説を読む方ではない。",
  str_homestory_801101001_19_dialog_content = "…が、「反逆双龍、千年の因縁」という題名が\n気になって読んでみただけだ。",
  str_homestory_801101001_20_dialog_content = "…",
  str_homestory_801101001_21_dialog_content = "その本…どこで見つけたのか、聞いてもいいですか…？",
  str_homestory_801101001_22_dialog_content = "誰かに売りつけられたとか…",
  str_homestory_801101001_23_dialog_content = "影ノ街の商人から買ったのだ。",
  str_homestory_801101001_24_dialog_content = "怒ってはいないんですね…",
  str_homestory_801101001_25_dialog_content = "内容はそこまでひどくなかったんですか…？",
  str_homestory_801101001_26_dialog_content = "買った時に聞いた売り文句だが――",
  str_homestory_801101001_27_dialog_content = "「伝統が絶えて久しい龍族の秘技」がどうとか\n「古代の血が織りなす愛情の物語」とか言っていたな。",
  str_homestory_801101001_28_dialog_content = "そういうのって、腹が立ったりしないんですか？",
  str_homestory_801101001_29_dialog_content = "いや…",
  str_homestory_801101001_30_dialog_content = "仮に腹を立てたところで、私にできることはない。",
  str_homestory_801101001_31_dialog_content = "生産から販売までのルートは、ほぼすべて影ノ街にある。\n私の手が及ぶ場所ではない。",
  str_homestory_801101001_32_dialog_content = "それに、私にとって本の内容は\n取るに足らない娯楽でしかないが...",
  str_homestory_801101001_33_dialog_content = "作者はそれで生計を立てているのかもしれん。",
  str_homestory_801101001_34_dialog_content = "…ううん、言われてみれば…",
  str_homestory_801101001_35_dialog_content = "やっぱり、上に立つ者として素晴らしい冷静さですね。",
  str_homestory_801101001_36_dialog_content = "本の中に出てくる「龍族の秘技」は、\n現実離れしてはいるが…",
  str_homestory_801101001_37_dialog_content = "少しは身体を鍛えられる。",
  str_homestory_801101001_38_dialog_content = "一緒にやってみるか？",
  str_homestory_801101001_39_dialog_content = "本によると、まずは軽く200回のスクワットから初めて――",
  str_homestory_801101001_40_dialog_content = "いやいやいや…",
  str_homestory_801101001_41_dialog_content = "ぼ、僕はやっぱり、空の末裔としての能力を磨くことにします…",
  str_homestory_801101001_42_dialog_content = "それでは、訓練のジャマにならないようにしますね…で、ではまた！",
  str_homestory_801101001_43_dialog_content = "ああ。",
  str_homestory_810301001_0_dialog_content = "何してるの？",
  str_homestory_810301001_1_dialog_content = "エルシー、お店には行かないの？",
  str_homestory_810301001_2_dialog_content = "ショッピングが好きって言ってたよね。",
  str_homestory_810301001_3_dialog_content = "PlayerName、あたしの趣味を覚えてたのなら…",
  str_homestory_810301001_4_dialog_content = "なんでこんなにしょっぱいの？\nお店がたった1軒？",
  str_homestory_810301001_5_dialog_content = "それには、いろいろ理由があって…",
  str_homestory_810301001_6_dialog_content = "言ってみなさい？",
  str_homestory_810301001_7_dialog_content = "ごまかすようなら、眼帯を取って…",
  str_homestory_810301001_8_dialog_content = "私の「空虚な瞳」<sprite=emo_baimao size=60 />を見て、\nよく思い出してもらってもいいのよ。",
  str_homestory_810301001_9_option_content = "（説明する）",
  str_homestory_810301001_10_dialog_content = "分かったよ、言うよ！",
  str_homestory_810301001_11_dialog_content = "主な理由は予算に限りがあったからだよ…",
  str_homestory_810301001_12_dialog_content = "建てなきゃいけないものがたくさんあるんだ。\n最初から何でもそろってるってわけには行かないよ。",
  str_homestory_810301001_13_option_content = "（説明しない）",
  str_homestory_810301001_14_dialog_content = "尋問してもムダだよ…",
  str_homestory_810301001_15_dialog_content = "予算に限りがあって、\nそんなにたくさんお店を造れないってだけだから…",
  str_homestory_810301001_16_dialog_content = "正直…1軒でもお店があるだけで、すごいことだと思ってるよ！",
  str_homestory_810301001_17_dialog_content = "あら、開き直り？",
  str_homestory_810301001_18_dialog_content = "小さいお店が1軒しかないけど、\n何でもそろえてるんだよ！",
  str_homestory_810301001_19_dialog_content = "がんばって、影ノ街のいろんな商会と連絡を取ったんだ…",
  str_homestory_810301001_20_dialog_content = "それから、クーリエ隊にもお願いして、\n不定期でここに商品を運んでもらってる。",
  str_homestory_810301001_21_dialog_content = "入って見てみてよ？\n何か足りないものがあれば、僕が探してくるから。",
  str_homestory_810301001_22_dialog_content = "必要ないわ、もう見たから。",
  str_homestory_810301001_23_dialog_content = "あと、お店の商品、全部買ったわ。",
  str_homestory_810301001_24_dialog_content = "全部！？",
  str_homestory_810301001_25_dialog_content = "そうよ。",
  str_homestory_810301001_26_dialog_content = "今日釣れたばかりの魚も…？",
  str_homestory_810301001_27_dialog_content = "あの妙にカラフルな魚のこと？\n買ったわよ、かわいかったし。",
  str_homestory_810301001_28_dialog_content = "ただ、ちょうどいい水槽がなかったから、\n近くの川に放してあげたわ。",
  str_homestory_810301001_29_dialog_content = "あの誰も買わなさそうなボロボロの革靴も…？",
  str_homestory_810301001_30_dialog_content = "革靴？…ああ、買ったわ。\n最新デザインの植木鉢じゃなかったの？",
  str_homestory_810301001_31_dialog_content = "もうクーリエ隊に頼んで、\n真理結社に届けておいてもらったわ。",
  str_homestory_810301001_32_dialog_content = "それから…僕が手書きした天空ノ谷の地図も？",
  str_homestory_810301001_33_dialog_content = "ああ、あの迷路みたいな線が引かれたヤツ？",
  str_homestory_810301001_34_dialog_content = "あなたが描いたものだったの？\n後でコーティングして壁に飾っておきましょ。",
  str_homestory_810301001_35_dialog_content = "ありがとう、エルシー…開店以来、一番太っ腹なお客さんだよ！",
  str_homestory_810301001_36_dialog_content = "お礼なんていらないわよ。\nショッピングはハデにやらないと楽しくないでしょ？",
  str_homestory_810301001_37_dialog_content = "でも、1軒見終わったら、\nもう見るところがなくなっちゃったのよ。\nこれじゃ不完全燃焼だわ。",
  str_homestory_810301001_38_dialog_content = "店以外のところも回ってみたら？",
  str_homestory_810301001_39_dialog_content = "あっちにはミュージアムがあるし、願いの泉もあるんだ…",
  str_homestory_810301001_40_dialog_content = "ここでしか見られないものであることは、僕が保証するよ。",
  str_homestory_810301001_41_dialog_content = "へー、面白そうじゃない。",
  str_homestory_810301001_42_dialog_content = "だったら、こうしましょ。\nあなたを買うわ<sprite=emo_baiyebi size=60 />。",
  str_homestory_810301001_43_dialog_content = "え！？僕を…買う！？",
  str_homestory_810301001_44_dialog_content = "あなたの1日の時間を買うわ。\nそれで、いろんなところを案内してちょうだい。",
  str_homestory_810301001_45_dialog_content = "値段は、好きに決めていいわ。",
  str_homestory_810301001_46_dialog_content = "わ、分かった！喜んで案内するよ！",
  str_homestory_802301001_0_dialog_content = "クラリン…？",
  str_homestory_802301001_1_dialog_content = "やさしい光ですね…",
  str_homestory_802301001_2_dialog_content = "クラリン、何を話してたの？",
  str_homestory_802301001_3_dialog_content = "な、ナビゲーターさん！？<sprite=emo_wuzui size=60 />",
  str_homestory_802301001_4_dialog_content = "ひ、ひとりごとです、お構いなく…",
  str_homestory_802301001_5_dialog_content = "…あ、い、いえ、そうじゃないです…",
  str_homestory_802301001_6_dialog_content = "構っていただいてもいいんでした…\nわ、私、今「鈍感になる訓練」をしていて…",
  str_homestory_802301001_7_dialog_content = "「鈍感になる訓練」？",
  str_homestory_802301001_8_dialog_content = "は、はい…バイスさんに教わったんです…",
  str_homestory_802301001_9_dialog_content = "ここは明るくて、\nあまり落ち着かなかったのですが…",
  str_homestory_802301001_10_dialog_content = "バイスさんが、隅にいる私を見て…",
  str_homestory_802301001_11_dialog_content = "助けてくれたって事？",
  str_homestory_802301001_12_dialog_content = "はい…",
  str_homestory_802301001_13_dialog_content = "ここで他人の目を気にせず、自分の好きなことをやっていればいいって、\n教えてくれたんです…",
  str_homestory_802301001_14_dialog_content = "あるいは、ここがホリデーカフェだと思って、\n他の人はお客様だと考えればいいって…",
  str_homestory_802301001_15_dialog_content = "それで、がんばってるんです…",
  str_homestory_802301001_16_option_content = "やってみて、感じはどう？",
  str_homestory_802301001_17_dialog_content = "以前より…よくなった気がします…",
  str_homestory_802301001_18_dialog_content = "もともと巨像にも、たくさんの人がいましたから…",
  str_homestory_802301001_19_option_content = "無理することないよ",
  str_homestory_802301001_20_dialog_content = "部屋の中の方が落ち着くなら、\nそうしてても構わないよ。",
  str_homestory_802301001_21_dialog_content = "ナビゲーター…実は、私、話したいことがあるんです…",
  str_homestory_802301001_22_dialog_content = "どんなこと？",
  str_homestory_802301001_23_dialog_content = "バイスさんの話を聞いてから、\n私、ここで「アントン」と一緒に1曲演奏<sprite=emo_yinfu size=60 />したんです…",
  str_homestory_802301001_24_dialog_content = "そうしたら…白夜城風の服を着た女性が来て、\n私を誉めてくれたんです…",
  str_homestory_802301001_25_dialog_content = "私…",
  str_homestory_802301001_26_dialog_content = "こういう明るい所もいいって思えた？",
  str_homestory_802301001_27_dialog_content = "やっぱり誉められるって、\nすごく効き目があるんだね。",
  str_homestory_802301001_28_dialog_content = "僕もクラリンはすごいと思うよ！",
  str_homestory_802301001_29_dialog_content = "おいしいコーヒーをいれられるし、\n戦いでも強いし、性格だって優しいし…",
  str_homestory_802301001_30_dialog_content = "ありがとうございます、ナビゲーター。\nわ、私…何と言ったらいいか、わかりません…",
  str_homestory_802301001_31_dialog_content = "でも、その人からのほめ言葉は…\nナビゲーターさんの言葉とは、少し違うんです。",
  str_homestory_802301001_32_dialog_content = "ナビゲーターさんとバイスさんは、\nクラリンのよいお友だちですから…",
  str_homestory_802301001_33_dialog_content = "2人とも私を励ましたいと思ってくれています…\nだから、いつもなぐさめたり、ほめたりしてくださるんですよね…",
  str_homestory_802301001_34_dialog_content = "でも…その人は知らない人で…",
  str_homestory_802301001_35_dialog_content = "なるほど、純粋なほめ言葉だから嬉しかったんだね。",
  str_homestory_802301001_36_dialog_content = "は、はい…そういうことです…",
  str_homestory_802301001_37_dialog_content = "とにかく…ナビゲーターさん、\n私の代わりにバイスさんにお礼を伝えておいてくれますか？",
  str_homestory_802301001_38_dialog_content = "バイスさんの助言がなかったら、\n私は今頃、まだ部屋の中に縮こまっていたと思いますので…",
  str_homestory_802301001_39_dialog_content = "任せて！",
  str_homestory_802301001_40_dialog_content = "それと、ありがとうございます…ナビゲーターさん！",
  str_homestory_802301001_41_dialog_content = "今から…「アントン」と一緒に\nもう少し練習してみようかと思います…",
  str_homestory_802301001_42_dialog_content = "新しい曲も試してみるといいかもね？",
  str_homestory_802301001_43_dialog_content = "誰か知らないけど、その女の人もきっと聞きたがってるよ。",
  str_homestory_802301001_44_dialog_content = "あ…そうですね…",
  str_homestory_802301001_45_dialog_content = "それでは、私は先に行って練習しますね…！",
  str_homestory_802301001_46_dialog_content = "頑張ってね！",
  str_homestory_803001001_0_dialog_content = "サメヤマだ…",
  str_homestory_803001001_1_dialog_content = "こんにちは、サメヤマ！",
  str_homestory_803001001_2_dialog_content = "おう！<sprite=emo_yaosu size=60 />、\n我らが空の末裔、PlayerNameじゃねえか！",
  str_homestory_803001001_3_dialog_content = "調子はどうだ？",
  str_homestory_803001001_4_dialog_content = "僕はいい感じだよ。\n君は？ここにはもう慣れた？",
  str_homestory_803001001_5_dialog_content = "そうだな、まあまあだ。",
  str_homestory_803001001_6_dialog_content = "動物も寄り付かなかったような場所を、\nあっという間にここまで建て直しちまうなんてよ…",
  str_homestory_803001001_7_dialog_content = "さすがは俺が見込んだだけある、ハハハハハ！",
  str_homestory_803001001_8_dialog_content = "で、そろそろお前の考えはまとまったか？",
  str_homestory_803001001_9_dialog_content = "一体いつになったら、R・Wに入るんだ？",
  str_homestory_803001001_10_dialog_content = "それは…",
  str_homestory_803001001_11_dialog_content = "それはそうと、R・Wのモノサシで言うなら…",
  str_homestory_803001001_12_dialog_content = "ここには思いっきりケンカしたり、クルマを飛ばす場所がねえな！",
  str_homestory_803001001_13_option_content = "（断る）",
  str_homestory_803001001_14_dialog_content = "天空ノ庭では、どんなもめ事も起こってほしくないから…",
  str_homestory_803001001_15_dialog_content = "暴力行為につながりそうなことには、\n場所を作らないよ。",
  str_homestory_803001001_16_dialog_content = "冷てぇな。これで断られるのは何回目か、もう分かんなくなってきたぜ。",
  str_homestory_803001001_17_dialog_content = "だが、PlayerName…\n考え方がまだまだ甘ちゃんだな。",
  str_homestory_803001001_18_dialog_content = "俺の言うことをよく聞いとけ。\nダメだって言われるとな、かえってやりたくなっちまうもんだ。",
  str_homestory_803001001_19_dialog_content = "どうしてそうなるのか、なんて聞くんじゃねぇぞ？",
  str_homestory_803001001_20_dialog_content = "…",
  str_homestory_803001001_21_option_content = "（承知する）",
  str_homestory_803001001_22_dialog_content = "そんな計画はなかったけど…",
  str_homestory_803001001_23_dialog_content = "もし好き勝手にケンカしたり、暴走されたりしたら、\n苦労して建てた家が壊れちゃうかもしれないね。",
  str_homestory_803001001_24_dialog_content = "そのための場所を作ることは考えておくよ。",
  str_homestory_803001001_25_dialog_content = "ハハハ、ずいぶん成長したじゃねえか。",
  str_homestory_803001001_26_dialog_content = "他人の意見を取り入れるようになったな！",
  str_homestory_803001001_27_dialog_content = "そうだ、天空ノ庭の女用の家を案内してくれよ。",
  str_homestory_803001001_28_dialog_content = "えっ！？",
  str_homestory_803001001_29_dialog_content = "なんだ、その目は？",
  str_homestory_803001001_30_dialog_content = "…女の子用の部屋に何の用？",
  str_homestory_803001001_31_dialog_content = "もちろん、見学に決まってるだろうが？",
  str_homestory_803001001_32_dialog_content = "見学！？",
  str_homestory_803001001_33_dialog_content = "ああ<sprite=emo_qingsong size=60 />、イブが泊まるのにふさわしいかどうか、\n見せてもらわねえとな。",
  str_homestory_803001001_34_dialog_content = "ビックリした…そういうことか…",
  str_homestory_803001001_35_dialog_content = "ベッドの柔らかさだろ…",
  str_homestory_803001001_36_dialog_content = "それから枕元の照明が目に優しいかどうか…",
  str_homestory_803001001_37_dialog_content = "シーツはイブの好きな柄かどうか…",
  str_homestory_803001001_38_dialog_content = "イブのかわいい服を入れるクローゼットがあるかどうか…",
  str_homestory_803001001_39_dialog_content = "そうそう、それから…一番大事なことだ！\n保温のできる水筒があるかどうかも、きちんと調べさせてもらうぞ！",
  str_homestory_803001001_40_option_content = "（承知する）",
  str_homestory_803001001_41_dialog_content = "バイスに確認してもらうよ…",
  str_homestory_803001001_42_dialog_content = "ハハハ、頼んだぜ！",
  str_homestory_803001001_43_option_content = "（承知しない）",
  str_homestory_803001001_44_dialog_content = "サメヤマ、イブにもいいかげん、自分だけの時間と空間をあげないと…",
  str_homestory_803001001_45_dialog_content = "何だと！？",
  str_homestory_803001001_46_dialog_content = "わ、分かったよ！バイスに確認してもらうから…",
  str_homestory_811601001_0_dialog_content = "この機械をいじる音は…",
  str_homestory_811601001_1_dialog_content = "ナビゲーター、何か修理でも必要かい？",
  str_homestory_811601001_2_dialog_content = "ちょうどいい！今日はまだ何も頼まれてないからな。",
  str_homestory_811601001_3_dialog_content = "修理？",
  str_homestory_811601001_4_dialog_content = "貨物の集積所で…わざわざ注文を受けてるの？",
  str_homestory_811601001_5_dialog_content = "そうさ。ここで客を集めて、戻って部屋で修理してるんだ。",
  str_homestory_811601001_6_dialog_content = "あ、でも安心してくれよ。金はとってないから。",
  str_homestory_811601001_7_dialog_content = "だったら、なんで？",
  str_homestory_811601001_8_dialog_content = "どうしてそんなことしてるのかって？",
  str_homestory_811601001_9_dialog_content = "そうだよ。部屋にこもって好きなことをしてればいいんじゃないの…？",
  str_homestory_811601001_10_dialog_content = "いろんな部品の研究とか。",
  str_homestory_811601001_11_dialog_content = "ここ、いろんな場所から\nたくさん人が集まってるだろ？<sprite=emo_sikao size=60 />",
  str_homestory_811601001_12_dialog_content = "修理に頼まれる物にも、\nそれぞれの場所で違いがあって、面白いんだ。",
  str_homestory_811601001_13_dialog_content = "例えば、カロンにレコードプレイヤー<sprite=emo_yinfu size=60 />の音量を\nもっと上げられるようにしてくれと頼まれたんだが…",
  str_homestory_811601001_14_dialog_content = "最初は単なる啓光の機械だし、ちょっと修理すれば直ると思ってたんだ。",
  str_homestory_811601001_15_dialog_content = "それが、あのレコードプレイヤー、啓光のものじゃないどころか、\nどこで生産されたかも分からない骨董品だったんだ！",
  str_homestory_811601001_16_dialog_content = "それで俺は、あのレコードプレーヤーを\nずいぶん研究させてもらったってわけさ、ハハハ。",
  str_homestory_811601001_17_dialog_content = "え？…だったら…\nほんとにカロンのレコードプレイヤー、大音量が出るようにしちゃったの？",
  str_homestory_811601001_18_dialog_content = "ああ…うん、そうだ。ほんのちょっとだけな。\nそう頼まれた以上は、研究材料のお礼としてな…",
  str_homestory_811601001_19_dialog_content = "まあ、あの人がたまにすごい大音量で音楽を流すのは知ってるから、\n本当にほんのちょっとだけだぜ。",
  str_homestory_811601001_20_dialog_content = "そうなんだ…ここでうまくやってくれてるみたいだね。",
  str_homestory_811601001_21_dialog_content = "もちろんさ！",
  str_homestory_811601001_22_dialog_content = "いろんな技術、最新式の部品に設備、全部に触れられるんだからな…\n本当にいい所だ！<sprite=emo_aixin size=60 />",
  str_homestory_811601001_23_dialog_content = "なじんでもらえてよかったよ。",
  str_homestory_811601001_24_dialog_content = "ああ！新しいロボの完成もそう遠くない気がするよ！",
  str_homestory_811601001_25_dialog_content = "…やっぱり、そのためだったんだね！？",
  str_homestory_811601001_26_dialog_content = "それだけじゃないさ、もちろんキミのことも気にしてるよ！\nキミが来る前、この集積所の構造を調べてたんだ。",
  str_homestory_811601001_27_dialog_content = "レンチとドライバーで軽く叩いてみたが…\nかなり丈夫な構造だった。俺が手を入れる必要はなさそうだ。",
  str_homestory_811601001_28_dialog_content = "天空ノ谷の素材で造られてるからね。",
  str_homestory_811601001_29_dialog_content = "そうか、ここに居れば、天空ノ谷の技術も研究できる。\n最高だな！",
  str_homestory_811601001_30_dialog_content = "そういうことなら、僕はジャマしないでおくよ…\nあ、ここで依頼を受けてるんだっけ？",
  str_homestory_811601001_31_dialog_content = "ジャマなんかじゃないさ。\nなんなら、見学してくか？",
  str_homestory_811601001_32_option_content = "（承知する）",
  str_homestory_811601001_33_dialog_content = "そうだね…みんながどんな修理を頼むのか、見てみたいな。",
  str_homestory_811601001_34_dialog_content = "構わないぜ！",
  str_homestory_811601001_35_dialog_content = "…でも、今日はあまり人が来ないな。",
  str_homestory_811601001_36_dialog_content = "…もし、ずっと誰も修理を頼みに来なかったら？",
  str_homestory_811601001_37_option_content = "（断る）",
  str_homestory_811601001_38_dialog_content = "いや、まだやることがあるんだ…",
  str_homestory_811601001_39_dialog_content = "あ、そういえば…",
  str_homestory_811601001_40_dialog_content = "もし、ずっと誰も修理を頼みに来なかったら？",
  str_homestory_811601001_41_dialog_content = "ここにずっと突っ立ってるの？",
  str_homestory_811601001_42_dialog_content = "そうさ。",
  str_homestory_811601001_43_dialog_content = "だが、1つだけ訂正させてもらうよ。",
  str_homestory_811601001_44_dialog_content = "ただ「突っ立ってる」ワケじゃない。\n俺の頭の中では、いつだってロボット大戦が繰り広げられてるからな！",
  str_homestory_811601001_45_dialog_content = "キミが来るまで、ちょうど俺はメカPlayerName号とメカオティ号の\n戦いの結果について考えてたんだ。",
  str_homestory_811601001_46_dialog_content = "メカPlayerName号の攻撃は素早く、柔軟性がある。\n対するメカオティは、武装の種類が豊富なタイプだ…",
  str_homestory_811601001_47_dialog_content = "いやぁ、激戦だったぜ！",
  str_homestory_811601001_48_dialog_content = "そうなんだ…僕、本当に君のジャマをしたくなくなったよ…",
  str_homestory_811701001_0_dialog_content = "グラム？",
  str_homestory_811701001_1_dialog_content = "お店で何をしてるの？",
  str_homestory_811701001_2_dialog_content = "あれ…何か物思いにふけってる？",
  str_homestory_811701001_3_dialog_content = "それとも、何か足りない物があったかな？",
  str_homestory_811701001_4_dialog_content = "おう、若いの。",
  str_homestory_811701001_5_dialog_content = "俺はただ、スパイスを探してるだけさ。\n賞味期限が近い配給の肉を串焼きにしようと思ってな。",
  str_homestory_811701001_6_dialog_content = "賞味期限が近い肉<sprite=emo_rou size=60 />…？",
  str_homestory_811701001_7_dialog_content = "近いだけさ、過ぎてねぇぞ。\nもちろん食える。",
  str_homestory_811701001_8_dialog_content = "それになぁ、料理の質ってーのは食材の良し悪しじゃねぇんだ。\nコックの腕ひとつで決まんだよ！",
  str_homestory_811701001_9_dialog_content = "グラムが言うと説得力があるね！",
  str_homestory_811701001_10_dialog_content = "そう言えば、グラムの作った串焼きは食べたことがないなぁ…",
  str_homestory_811701001_11_dialog_content = "そのうち食えるさ。",
  str_homestory_811701001_12_dialog_content = "串焼きなんて、大した料理でもないしな。",
  str_homestory_811701001_13_dialog_content = "…大した料理じゃない？",
  str_homestory_811701001_14_dialog_content = "やっぱり、グラムは料理の才能があるんだね…",
  str_homestory_811701001_15_dialog_content = "料理の才能？そりゃ初耳だな。",
  str_homestory_811701001_16_dialog_content = "フン、最近の若ぇ連中はすぐ才能才能って強調しやがる！",
  str_homestory_811701001_17_dialog_content = "成果ってのはな、ほとんどが苦労と努力と地道な練習からできてるんだ。\n才能なんてモン、頼りにはならねぇよ！",
  str_homestory_811701001_18_dialog_content = "俺の料理がうまいのは、厨房で何年もやってるからだ。",
  str_homestory_811701001_19_dialog_content = "料理の腕なんて、それこそ一番「才能」に頼れねえ技術の一つだぞ。",
  str_homestory_811701001_20_option_content = "よく分からない",
  str_homestory_811701001_21_dialog_content = "僕も料理してみたことあるけど、\nレシピの指示をしっかり守って作っても…",
  str_homestory_811701001_22_dialog_content = "そんなにおいしくできなかったよ。",
  str_homestory_811701001_23_option_content = "分かる気がする",
  str_homestory_811701001_24_dialog_content = "料理の腕は練習しないと上がらない、だよね…？",
  str_homestory_811701001_25_dialog_content = "どんなことでもそうさ。",
  str_homestory_811701001_26_dialog_content = "強いて言うなら、うまいもんを作りたけりゃ、\nまずは「気持ち」ってのがねえとな。",
  str_homestory_811701001_27_dialog_content = "気持ち？",
  str_homestory_811701001_28_dialog_content = "うーん、じゃあ、バイスが作った料理は…",
  str_homestory_811701001_29_dialog_content = "まったく気持ちがこもってないのかな？\nそれとも、気持ちが多すぎてあふれ出ちゃってる？",
  str_homestory_811701001_30_dialog_content = "そりゃ、手順と指示にとらわれすぎて、\n気持ちの部分がすっ飛んでるんだろ。",
  str_homestory_811701001_31_dialog_content = "それで、考え過ぎてどっちもダメにしてんじゃねぇか？",
  str_homestory_811701001_32_dialog_content = "ううん、僕自身もそうな気がする…",
  str_homestory_811701001_33_dialog_content = "失敗したくないけど、おいしいものを作りたいって気持ちも強くて、\nそうすると、余計にあせっちゃうんだ…",
  str_homestory_811701001_34_dialog_content = "いちばん簡単な話をしてやるよ。",
  str_homestory_811701001_35_dialog_content = "おれが調理をやらされてた頃は、どんなに戦場に出たい気持ちがあろうと、\nうまい料理を作ってやろうって思えた理由は一つだけだった。",
  str_homestory_811701001_36_dialog_content = "兄弟たちにうまいもんを食ってほしかったからだよ。\nいいもんを食えば、戦う力も出るってもんだ。",
  str_homestory_811701001_37_dialog_content = "今、俺がここで料理してる理由も同じだ。",
  str_homestory_811701001_38_dialog_content = "ここの若い奴らには全員、うまいもんを食ってほしいんだ！\nいいもんを食えば、戦う元気が出る、そうだろ？",
  str_homestory_811701001_39_dialog_content = "そういう単純なことなんだよ。",
  str_homestory_811701001_40_dialog_content = "決められた手順と指示を守って、\n余計な考えは、捨てちまえばいいのさ。",
  str_homestory_811701001_41_dialog_content = "考えすぎると、かえって間違える。分かったか？",
  str_homestory_811701001_42_dialog_content = "うん！分かったよ！",
  str_homestory_811701001_43_dialog_content = "君の言う通りだよ、グラム！",
  str_homestory_811701001_44_dialog_content = "いや、むしろもっと…本でも出すべきだと思うよ。\n料理のコツ、みんなに広めるために。",
  str_homestory_811701001_45_dialog_content = "R・W砂漠の料理人って人だって本を出してるんだし…\nグラムも大丈夫だよ！",
  str_homestory_811701001_46_dialog_content = "もしよければ、僕が影ノ街の人に連絡をとってあげるよ。",
  str_homestory_811701001_47_dialog_content = "考えとくよ。",
  str_homestory_811701001_48_dialog_content = "串焼きができたら、お前も一緒に食うか？",
  str_homestory_811701001_49_dialog_content = "う、うん！",
  str_homestory_807701001_0_dialog_content = "女王陛下？",
  str_homestory_807701001_1_dialog_content = "あの…",
  str_homestory_807701001_2_dialog_content = "来たか。未来を抱く者よ。",
  str_homestory_807701001_3_option_content = "よ、ようこそ…",
  str_homestory_807701001_4_dialog_content = "遠路はるばる来ていただけるなんて、光栄です…",
  str_homestory_807701001_5_dialog_content = "PlayerName、そうかしこまらずともよい。",
  str_homestory_807701001_6_dialog_content = "先程から、この風の塔を眺めていた。",
  str_homestory_807701001_7_option_content = "何か気になりましたか？",
  str_homestory_807701001_8_dialog_content = "とても集中してるみたいでしたが…",
  str_homestory_807701001_9_dialog_content = "そうだ、この風の塔を眺めている。",
  str_homestory_807701001_10_dialog_content = "何か変わったところでも？",
  str_homestory_807701001_11_dialog_content = "そうだな…この風の塔は、\n空の末裔にとって、並々ならぬ意義がある。",
  str_homestory_807701001_12_dialog_content = "そうです！とっても大きな建物でしょう…",
  str_homestory_807701001_13_dialog_content = "ここからだとそう見えないかもしれませんが、\n実はとても大きくて、中も広々としてるんです！",
  str_homestory_807701001_14_dialog_content = "巨像の生産や修理する機能もあったって言うぐらいですしね。",
  str_homestory_807701001_15_dialog_content = "資料によると、多くの空の末裔がここで教育を受けていたそうです。",
  str_homestory_807701001_16_dialog_content = "巨像のナビゲーターを育成する家のような場所だったみたいですね。",
  str_homestory_807701001_17_dialog_content = "家…か。",
  str_homestory_807701001_18_dialog_content = "見よ。この塔は空の下で\nひときわ目立ち、輝いている。",
  str_homestory_807701001_19_dialog_content = "空の末裔の…精神の象徴だ。",
  str_homestory_807701001_20_dialog_content = "PlayerName、人と人とが引き合う力は\nいかにして生まれるか、\nそなたは知っているか？",
  str_homestory_807701001_21_dialog_content = "そんなこと、突然聞かれても…",
  str_homestory_807701001_22_dialog_content = "ごめんなさい、きちんと考えたことはありません。",
  str_homestory_807701001_23_dialog_content = "構わん。かつてのそなたには重要ではなかったことだ。",
  str_homestory_807701001_24_dialog_content = "だが、今のそなたは違う。\n新たな角度から、この大陸を見なければならない。",
  str_homestory_807701001_25_dialog_content = "この地の生きとし生ける者の中には、\n背の高い者も、低い者も、強靭な体の者も、\nやせ細ったひ弱な者も、年寄りも子供もいる。",
  str_homestory_807701001_26_dialog_content = "それでも、同じ信仰、同じ信念があれば…",
  str_homestory_807701001_27_dialog_content = "一つにまとまることができるのだ。",
  str_homestory_807701001_28_dialog_content = "私たちは一人で戦ったところで、\n自然の生物にさえ勝つことはできぬ。",
  str_homestory_807701001_29_dialog_content = "鋭い爪や牙はない。\n岩のように固い肌も、空を飛ぶ翼もない。",
  str_homestory_807701001_30_dialog_content = "しかし、団結すれば、想像を超えた力を発揮できる…",
  str_homestory_807701001_31_dialog_content = "そう言われてみれば…",
  str_homestory_807701001_32_dialog_content = "さっきの「精神の象徴」みたいなものですね。",
  str_homestory_807701001_33_dialog_content = "…",
  str_homestory_807701001_34_dialog_content = "確かにそうだ。",
  str_homestory_807701001_35_dialog_content = "私の周りに集う者たちは、\n私への信頼や敬慕の念によって…\nあるいは単に、庇護を求めて来る。",
  str_homestory_807701001_36_dialog_content = "それは悪い事ではない。",
  str_homestory_807701001_37_dialog_content = "団結した者は、\nばらばらの砂には持ち得ぬ力を持つのだ。",
  str_homestory_807701001_38_dialog_content = "啓光であろうと、白夜城であろうと、\nそれぞれが正しいと思う方法で、\nその団結を守っている。",
  str_homestory_807701001_39_dialog_content = "そうですね…そのことは、僕もよく理解できるようになりました。",
  str_homestory_807701001_40_dialog_content = "そなたも成長したということだな。\n未来を抱く空の末裔よ。",
  str_homestory_807701001_41_dialog_content = "この純白の塔――空の末裔の象徴は、お前自身と同様…",
  str_homestory_807701001_42_dialog_content = "人々を団結させる力を持っている。",
  str_homestory_807701001_43_dialog_content = "僕でも皆を団結させて、天空ノ谷を守れるんでしょうか…\nあっ、失礼ながら、一つ質問をしていいですか…？",
  str_homestory_807701001_44_dialog_content = "構わぬ、話してみよ。",
  str_homestory_807701001_45_dialog_content = "あなたが見た未来に…今日の天空ノ谷は出てきましたか？",
  str_homestory_807701001_46_dialog_content = "…無論だ。だが、それだけではない…",
  str_homestory_804201001_0_dialog_content = "バートン！",
  str_homestory_804201001_1_dialog_content = "おう、ナビゲーター！",
  str_homestory_804201001_2_dialog_content = "バートン――",
  str_homestory_804201001_3_dialog_content = "シーッ…俺と一緒に観察しやがれ。<sprite=emo_mojing size=60 />",
  str_homestory_804201001_4_dialog_content = "…観察？",
  str_homestory_804201001_5_dialog_content = "何を？",
  str_homestory_804201001_6_dialog_content = "ここは人材だらけだぜ！ナビゲーター！",
  str_homestory_804201001_7_dialog_content = "どうして巨像に居る時には、気付かなかったんだろうな？",
  str_homestory_804201001_8_dialog_content = "…そうか、ここは巨像より広いからかも知れねえな。\n身体を動かしてるヤツがずいぶん多い！",
  str_homestory_804201001_9_dialog_content = "…人材？",
  str_homestory_804201001_10_dialog_content = "啓光に誘うつもり…？",
  str_homestory_804201001_11_dialog_content = "啓光に誘う？いや、その必要はねえよ。",
  str_homestory_804201001_12_dialog_content = "聞くが、PlayerName…\n俺が指揮してるのは第何軍団か、知ってるか？",
  str_homestory_804201001_13_option_content = "第二軍団",
  str_homestory_804201001_14_dialog_content = "そうだ！",
  str_homestory_804201001_15_option_content = "第四軍団",
  str_homestory_804201001_16_dialog_content = "なに？<sprite=emo_shengqi size=60 />\n俺の部下は、あの女の部下よりずっと多いんだぞ！？",
  str_homestory_804201001_17_dialog_content = "フン、ラスの精鋭予備隊なんざ、比べ物にならねぇぜ！",
  str_homestory_804201001_18_dialog_content = "俺が指揮してるのは第二軍団、兵力も一番デカい。覚えたか？",
  str_homestory_804201001_19_dialog_content = "お、覚えたよ…",
  str_homestory_804201001_20_dialog_content = "じゃ、大元帥直々に俺が託されてる役目は何か、知ってるか？",
  str_homestory_804201001_21_option_content = "迅速な支援？",
  str_homestory_804201001_22_dialog_content = "…それはヒイロとかバイスあたりの役目だ。",
  str_homestory_804201001_23_dialog_content = "おいおい、そんなことも覚えてねえのか？",
  str_homestory_804201001_24_dialog_content = "俺の役目は守備だ！",
  str_homestory_804201001_25_dialog_content = "…これで分かったな？",
  str_homestory_804201001_26_dialog_content = "う、うん…",
  str_homestory_804201001_27_option_content = "守備",
  str_homestory_804201001_28_dialog_content = "よし！普段から教えてやってることもムダじゃなかったようだな！",
  str_homestory_804201001_29_dialog_content = "それが分かってるなら、\n俺が今ここで何をしてるかも、分かるはずだぞ。",
  str_homestory_804201001_30_dialog_content = "考えてみろ、ここにはいい腕を持った奴らが、\nこれだけいる…",
  str_homestory_804201001_31_dialog_content = "そんで、しょっちゅうケンカになる…",
  str_homestory_804201001_32_dialog_content = "何でもアリだ！\n不意打ち！隠し武器！体術！ってな！",
  str_homestory_804201001_33_dialog_content = "俺でも驚かされてばっかりだぜ。",
  str_homestory_804201001_34_dialog_content = "だが、そういうヤツらを啓光に誘う必要はない、分かるか？",
  str_homestory_804201001_35_dialog_content = "ここで奴らの「やり方」を観察できりゃ、それでいいんだ。",
  str_homestory_804201001_36_dialog_content = "いろんな所から集まった奴らから、俺自身が覚えるだけじゃねえ。\nそれを俺の兵士に教えることもできる！",
  str_homestory_804201001_37_dialog_content = "どれもこれも貴重な資料ってワケだ！",
  str_homestory_804201001_38_dialog_content = "そんなことを考えてたなんて…",
  str_homestory_804201001_39_dialog_content = "…いやちょっと待って。今さらだけど、\nしょっちゅうケンカになるってどういうこと！？",
  str_homestory_804201001_40_dialog_content = "そりゃ、お互いのことが気に入らねえ奴らなんて、多いだろ？",
  str_homestory_804201001_41_dialog_content = "巨像でも毎日バカスカやってたろ、\nお前もとっくに慣れてるもんだと思ってたがな。",
  str_homestory_804201001_42_dialog_content = "でも――",
  str_homestory_804201001_43_dialog_content = "訓練のための、ただの手合わせだとでも思っとけ！",
  str_homestory_804201001_44_dialog_content = "それより、俺は昨日見た技について考えなきゃなんねえ…",
  str_homestory_804201001_45_dialog_content = "アイツ、一体どうやって、あの女のケリを受け流したんだ…？",
  str_homestory_804201001_46_dialog_content = "ううん、何としても、早いとこ習得しなきゃならねえな。\nそうすりゃ、今度ラスが俺を挑発してきた時に…",
  str_homestory_804201001_47_dialog_content = "一泡吹かせられるってもんだ…ヘヘヘ！<sprite=emo_nuhuo size=60 />",
  str_homestory_804201001_48_dialog_content = "…分かったよ、じゃあ、がんばってね、バートン…",
  str_homestory_807601001_0_dialog_content = "クレーケン…",
  str_homestory_807601001_1_dialog_content = "ああ、航行する勇者よ、ようやく着陸したようだね。",
  str_homestory_807601001_2_dialog_content = "やあ、クレーケン。",
  str_homestory_807601001_3_dialog_content = "この滝の岩が気に入った？いつもこの近くにいるよね…",
  str_homestory_807601001_4_dialog_content = "ここには水があるからね。",
  str_homestory_807601001_5_dialog_content = "実に豊かな流れだ。\n僕は感動で涙が出そうなほど<sprite=emo_hanshui size=60 />だよ。",
  str_homestory_807601001_6_dialog_content = "皮肉で言ってるよね？",
  str_homestory_807601001_7_dialog_content = "だってここ、観賞用に少し水を流してるだけだから…",
  str_homestory_807601001_8_dialog_content = "君がよく言う「海」とか「溺れる」とかのイメージとは、\nかけ離れてるでしょ。",
  str_homestory_807601001_9_dialog_content = "僕はね、君に感謝しているんだよ。",
  str_homestory_807601001_10_dialog_content = "…どうして？",
  str_homestory_807601001_11_dialog_content = "君はまもなく僕の「のぞき見の術」が本物であることを\n見届けることになるからさ。",
  str_homestory_807601001_12_dialog_content = "君の可愛い頭の中をのぞいて、\n最近何をしたかを見ることができるんだよ…",
  str_homestory_807601001_13_dialog_content = "君のステキな瞳を見つめるだけで、\n僕には答えが分かるんだ。",
  str_homestory_807601001_14_dialog_content = "最初の目撃者になってくれることに感謝するよ。",
  str_homestory_807601001_15_dialog_content = "えっ…",
  str_homestory_807601001_16_option_content = "のぞき見の術？",
  str_homestory_807601001_17_dialog_content = "興味を持ったようだね、相棒…",
  str_homestory_807601001_18_option_content = "断ってもいいかな？",
  str_homestory_807601001_19_dialog_content = "構わないよ。",
  str_homestory_807601001_20_dialog_content = "でも、僕の背中の素早い子たちが、君を見逃してくれるかな？",
  str_homestory_807601001_21_dialog_content = "この子たち、熟睡している時の君を\n観察するのが一番好きなんだよ、PlayerName…",
  str_homestory_807601001_22_dialog_content = "（…想像しただけでも恐ろしい…）",
  str_homestory_807601001_23_dialog_content = "分かった…ちょっとの間だけだよ。\n僕も忙しいんだ。",
  str_homestory_807601001_24_dialog_content = "「のぞき見の術」って何？",
  str_homestory_807601001_25_dialog_content = "今説明するよ、勇者クン。",
  str_homestory_807601001_26_dialog_content = "君は最近、影ノ街に行ったね…",
  str_homestory_807601001_27_dialog_content = "君は街をぶらぶらと歩いていた。\nそこで可憐な少女を見つけた。",
  str_homestory_807601001_28_dialog_content = "少女は、君に道沿いにあるレストランの価格を\n見に来てくれるよう頼んだ…",
  str_homestory_807601001_29_dialog_content = "少女はお金をあまり持っていなかったので、\n軽々しくレストランに入れなかった。",
  str_homestory_807601001_30_dialog_content = "うっかり入って注文がパンを1つだけでは、店員にどんな顔をされるか…",
  str_homestory_807601001_31_dialog_content = "君は少女を連れて1軒1軒レストランを回り、\n料理の値段を1つ1つ教えてあげた。",
  str_homestory_807601001_32_dialog_content = "しかし、少女は首を振るばかり。",
  str_homestory_807601001_33_dialog_content = "結局、君はガマンできなくなって、少女においしいものを食べさせてあげた…",
  str_homestory_807601001_34_dialog_content = "しかし、少女は食事を終えて、君に一言お礼を言うと、飛ぶように逃げて行った。\nそして、テーブルには食事代が残されていた。",
  str_homestory_807601001_35_dialog_content = "…どうして知ってるの！？",
  str_homestory_807601001_36_dialog_content = "（…「のぞき見の術」、本当に使えるの？）",
  str_homestory_807601001_37_dialog_content = "とにかく…僕には、よく分かってないんだ。",
  str_homestory_807601001_38_dialog_content = "食事代を払えるなら、\nあの子はどうしてさっさとどこかに入ろうとしなかったんだろう？",
  str_homestory_807601001_39_dialog_content = "君の言う通り…あの子、影ノ街のほぼ全部のレストランの、\n料理の値段を見たんだよ！",
  str_homestory_807601001_40_dialog_content = "ハハハハハ…<sprite=emo_guilian size=60 />。",
  str_homestory_807601001_41_dialog_content = "それは、僕がそうさせたからさ。",
  str_homestory_807601001_42_dialog_content = "そもそも、僕がシャドウマスターに仕事を頼まれていたのさ…",
  str_homestory_807601001_43_dialog_content = "「影ノ街の飲食物の価格調査」をね。",
  str_homestory_807601001_44_dialog_content = "それで、いつも面倒を見ている女の子にちょっと手伝ってもらったのさ。\nそうすれば、彼女は自分が「役に立つ」んだと思えるし…",
  str_homestory_807601001_45_dialog_content = "同時に、何もすることのない空の末裔が、僕の代わりに仕事をしてくれる。\n最高だろう？",
  str_homestory_807601001_46_dialog_content = "何しろ…街中を歩いて調べるなんてこと、\n僕にとっては、ひどく骨の折れることだからね。",
  str_homestory_807601001_47_dialog_content = "…",
  str_homestory_807601001_48_dialog_content = "さあ、これが「のぞき見の術」の真実と言うわけさ、PlayerName。",
  str_homestory_807601001_49_dialog_content = "そのガッカリした表情…実に面白いね。",
  str_homestory_804601001_0_dialog_content = "あの子は…",
  str_homestory_804601001_1_dialog_content = "ナビゲーター来て来て、ナビゲーター来た来た♪",
  str_homestory_804601001_2_dialog_content = "ナビゲーターがパイルに笑いかけた、\nでもパイルは悪ふざけがしたい♪",
  str_homestory_804601001_3_dialog_content = "お店を見てるの？",
  str_homestory_804601001_4_dialog_content = "お店を見てる、PlayerName様は\nパイルがお店を見てるって思ってる<sprite=emo_yinfu size=60 />。",
  str_homestory_804601001_5_dialog_content = "ディアムが違うと言った、カーラはそうだと言った、\nニールはそんなとこだよと言った…\nでもパイルは「ハハハ！」としか言わない。<sprite=emo_muji size=60 />",
  str_homestory_804601001_6_dialog_content = "PlayerName様は、僕がなんて言ったと思う？",
  str_homestory_804601001_7_dialog_content = "…",
  str_homestory_804601001_8_dialog_content = "やっぱりダメだ、なぞなぞはあきらめるよ…",
  str_homestory_804601001_9_dialog_content = "僕はここの居ごこちはどうか、聞きたかっただけなんだけど…",
  str_homestory_804601001_10_dialog_content = "でも、君の悪だくみしてそうな様子を見て、安心したよ。",
  str_homestory_804601001_11_dialog_content = "PlayerName様がキーティンを気に掛けてくれて、\nパイルは嬉しい♪",
  str_homestory_804601001_12_dialog_content = "PlayerName様、\n僕が最近誰に会ったか興味ない？",
  str_homestory_804601001_13_dialog_content = "…どうして、イヤな予感がするんだろう…？<sprite=emo_tanqi size=60 />",
  str_homestory_804601001_14_dialog_content = "誰に会ったの？",
  str_homestory_804601001_15_dialog_content = "君以外に、他の子たちも少し注意してね。\nここでは誰にでも皮肉をぶつけていいわけじゃないんだ。",
  str_homestory_804601001_16_dialog_content = "ここは白夜城とは違って、すぐ怒る光霊もいるし…",
  str_homestory_804601001_17_dialog_content = "敏感な光霊もいて、君たちに何か言われたら泣いちゃうかも…",
  str_homestory_804601001_18_dialog_content = "PlayerName様、僕たちが心配、\nPlayerName様、仲間が心配♪",
  str_homestory_804601001_19_dialog_content = "僕たち、長いしっぽの整備士に会った、\nトリをつかめるロボットアーム、作ってくれた♪",
  str_homestory_804601001_20_dialog_content = "僕たち、まん丸小鳥に会った、\nまん丸雪玉たくさんくれた♪",
  str_homestory_804601001_21_dialog_content = "僕たち、スーツのワンちゃんに会った、\nニセモノの絵が売れない、悩んでた♪",
  str_homestory_804601001_22_dialog_content = "パイルは背の低いナビゲーター様に会った、\n僕の前で、友だちの心配をしてる♪",
  str_homestory_804601001_23_dialog_content = "…よかった、特に騒ぎは起こしてないみたいだね。",
  str_homestory_804601001_24_dialog_content = "でも、実際のところ、\n君たちが一番当たりさわりのないことしか、言わなかったからだろうね…",
  str_homestory_804601001_25_dialog_content = "当たりさわりのない言葉には、\nたいてい理由があるんだよ。",
  str_homestory_804601001_26_dialog_content = "本棚にはディアムの好きな本♪",
  str_homestory_804601001_27_dialog_content = "部屋の中にはニールのメガネ拭き♪",
  str_homestory_804601001_28_dialog_content = "レストランにはカーラの帽子かけ♪",
  str_homestory_804601001_29_dialog_content = "それから芝生に、ララとパイルの大好きなおやつ♪",
  str_homestory_804601001_30_dialog_content = "PlayerName様はとっても優しいね、\nPlayerName様は僕たちの理解者♪",
  str_homestory_804601001_31_dialog_content = "PlayerName様は明日の星♪",
  str_homestory_804601001_32_dialog_content = "必ず背は伸びるよ♪",
  str_homestory_804601001_33_dialog_content = "…最後の一言がなければ…",
  str_homestory_804601001_34_dialog_content = "PlayerName様、これから何するの？",
  str_homestory_804601001_35_option_content = "戻って休むよ",
  str_homestory_804601001_36_dialog_content = "少し寝ようと思うんだ。",
  str_homestory_804601001_37_option_content = "適当にブラブラする",
  str_homestory_804601001_38_dialog_content = "他の皆が何してるか、見に行ってくるよ。",
  str_homestory_804601001_39_dialog_content = "分かった、パイルは知ってるよ。",
  str_homestory_804601001_40_dialog_content = "パイルは本当はどうでもいいけど、\nやっぱり一言、PlayerName様に言っとくよ。",
  str_homestory_804601001_41_dialog_content = "ララは今、PlayerName様のために、\nお花畑の近くで肥料をまいてるよ♪",
  str_homestory_804601001_42_dialog_content = "…！？",
  str_homestory_804601001_43_dialog_content = "肥料？",
  str_homestory_804601001_44_dialog_content = "パイルの好意、教えてあげたよ。\n早く見に行って♪",
  str_homestory_804601001_45_dialog_content = "…今回は、素直に感謝しておくよ！",
  str_homestory_805701001_0_dialog_content = "これは…猫の毛？",
  str_homestory_805701001_1_dialog_content = "ふわ～ああ～…",
  str_homestory_805701001_2_dialog_content = "あれ、フィリス？",
  str_homestory_805701001_3_dialog_content = "すぅ…すぅ…<sprite=emo_kun size=60 />",
  str_homestory_805701001_4_dialog_content = "…フィリス？",
  str_homestory_805701001_5_dialog_content = "すぅ…すぅ…ふにゃあ！？",
  str_homestory_805701001_6_dialog_content = "にゃんだ、PlayerNameだったにゃん。",
  str_homestory_805701001_7_dialog_content = "フィリスは今、寝てるんだにゃ。",
  str_homestory_805701001_8_dialog_content = "何か用があるにゃら…起きてからにしてにゃ。",
  str_homestory_805701001_9_dialog_content = "今から、このぬっくぬくの干し草の山の中に入って…\n気持ちよ～くひと眠りするにゃ…",
  str_homestory_805701001_10_dialog_content = "ちょ、ちょっと待って、フィリス！話があるんだ！",
  str_homestory_805701001_11_dialog_content = "すぅ…すぅ…にゃ～！？",
  str_homestory_805701001_12_dialog_content = "まったく…一体何の話にゃ。",
  str_homestory_805701001_13_dialog_content = "大事なことじゃにゃいなら、怒るにゃ～！",
  str_homestory_805701001_14_dialog_content = "あの…実は、他の光霊から聞いたんだけど…",
  str_homestory_805701001_15_dialog_content = "フィリス、君は最近…",
  str_homestory_805701001_16_option_content = "具合が悪いんじゃない？",
  str_homestory_805701001_17_dialog_content = "例えば…体がかゆいとか…",
  str_homestory_805701001_18_dialog_content = "食欲がないって感じはない？",
  str_homestory_805701001_19_dialog_content = "にゃに言ってるのにゃ。",
  str_homestory_805701001_20_dialog_content = "フィリスには、言ってることがまったく分からないにゃ。",
  str_homestory_805701001_21_option_content = "毛の生え変わる時期じゃない？",
  str_homestory_805701001_22_dialog_content = "生え変わる…？",
  str_homestory_805701001_23_dialog_content = "何にゃ、それは？",
  str_homestory_805701001_24_dialog_content = "（明らかにとぼけてる！）",
  str_homestory_805701001_25_dialog_content = "と、とにかく、フィリスは全く自覚がないの？",
  str_homestory_805701001_26_dialog_content = "（フィリスのしっぽを触ってみよう）",
  str_homestory_805701001_27_dialog_content = "にゃ～！",
  str_homestory_805701001_28_dialog_content = "PlayerName、どうして急に、レディのしっぽにさわるのにゃ！",
  str_homestory_805701001_29_dialog_content = "ちょ、ちょっと気持ちいいけど…イケナイのにゃ！",
  str_homestory_805701001_30_dialog_content = "フィリス、震えたらもっと毛が落ちるよ！",
  str_homestory_805701001_31_dialog_content = "こ、これは違うにゃ…！",
  str_homestory_805701001_32_dialog_content = "ううん…ううにゃあ、でも、どうしろっていうのにゃ！",
  str_homestory_805701001_33_dialog_content = "毎年この季節になると…毛が生え変わる、いや、違うにゃ！",
  str_homestory_805701001_34_dialog_content = "毛が太陽の力を吸って、まったく新しい進化をとげてるのにゃ！",
  str_homestory_805701001_35_dialog_content = "全部生え変わったら…スーパーフィリスになってるのにゃ！",
  str_homestory_805701001_36_dialog_content = "でも…飛び散る猫の毛をそのままにしてたら…",
  str_homestory_805701001_37_dialog_content = "アレルギー体質の光霊が、辛い思いをするよ？",
  str_homestory_805701001_38_dialog_content = "うう…だったら、どうすればいいにゃ。",
  str_homestory_805701001_39_dialog_content = "フィリスだって、毛をまき散らしたくはないにゃ。<sprite=emo_tanqi size=60 />",
  str_homestory_805701001_40_dialog_content = "そうだね…どうすればいいかな…",
  str_homestory_805701001_41_dialog_content = "そうだ！僕がブラッシングしてあげるよ。",
  str_homestory_805701001_42_dialog_content = "こまめにブラッシングしていれば、\nあちこちに飛び散ることもなくなるよ。",
  str_homestory_805701001_43_dialog_content = "イスタバンさんが教えてくれたんだ。",
  str_homestory_805701001_44_dialog_content = "ううん…天空ノ谷の気持ちいい干し草の山に免じて…",
  str_homestory_805701001_45_dialog_content = "特別にブラッシングを許可してあげるにゃ！",
  str_homestory_803601001_0_dialog_content = "ヒドライ？",
  str_homestory_803601001_1_dialog_content = "何してるの？",
  str_homestory_803601001_2_dialog_content = "見て分からないか？",
  str_homestory_803601001_3_dialog_content = "立ってんだよ。",
  str_homestory_803601001_4_dialog_content = "…そ、それは見て分かるよ。",
  str_homestory_803601001_5_dialog_content = "…",
  str_homestory_803601001_6_dialog_content = "…",
  str_homestory_803601001_7_dialog_content = "おい。",
  str_homestory_803601001_8_dialog_content = "え？",
  str_homestory_803601001_9_dialog_content = "昨日ケガをしてな。",
  str_homestory_803601001_10_dialog_content = "…！？",
  str_homestory_803601001_11_option_content = "大丈夫？",
  str_homestory_803601001_12_dialog_content = "死んじゃいねえだろ。",
  str_homestory_803601001_13_option_content = "どこで？",
  str_homestory_803601001_14_dialog_content = "あんたが何を心配してるかは分かってるよ。",
  str_homestory_803601001_15_dialog_content = "ここでケガしたわけじゃない。",
  str_homestory_803601001_16_dialog_content = "いや…君の身体を心配してるんだよ。",
  str_homestory_803601001_17_dialog_content = "今はどう？少しは良くなった？",
  str_homestory_803601001_18_dialog_content = "ほぼ平気だ。",
  str_homestory_803601001_19_dialog_content = "影狼のおかげで早く治った。",
  str_homestory_803601001_20_dialog_content = "そうなんだ…それで、どうしてケガしたの？",
  str_homestory_803601001_21_dialog_content = "ケガするのが好きなわけじゃないでしょ？",
  str_homestory_803601001_22_dialog_content = "物の取り合いになってな。",
  str_homestory_803601001_23_dialog_content = "影ノ街の闇市だ。",
  str_homestory_803601001_24_dialog_content = "争うほど大事だったの？一体どんな物？",
  str_homestory_803601001_25_dialog_content = "古代文明の産物らしい。",
  str_homestory_803601001_26_dialog_content = "「らしい」？",
  str_homestory_803601001_27_dialog_content = "つまり、それが本物かどうかも知らなかったってこと？",
  str_homestory_803601001_28_dialog_content = "それでも試すしかない。",
  str_homestory_803601001_29_dialog_content = "…一体何が…？",
  str_homestory_803601001_30_dialog_content = "「幻術」とか「影魔術」でできる霊体のたぐいを完全に実体化できる装置だ。",
  str_homestory_803601001_31_dialog_content = "え…でも、君の影狼はいつも側にいるでしょ？",
  str_homestory_803601001_32_dialog_content = "ああ。だが、俺はアイツらの毛に触ってみたいんだ。",
  str_homestory_803601001_33_dialog_content = "きちんと生えてる、本物の毛をな。\n換毛期に落ちる、バラバラの毛じゃないやつだ。",
  str_homestory_803601001_34_dialog_content = "なるほどね…",
  str_homestory_803601001_35_dialog_content = "（ヒドライ…さみしいのかな？）",
  str_homestory_803601001_36_dialog_content = "だが、たぶんニセモノだろうな。",
  str_homestory_803601001_37_dialog_content = "その装置のこと？",
  str_homestory_803601001_38_dialog_content = "ああ。",
  str_homestory_803601001_39_dialog_content = "そんなもの、今まで聞いたことがない。",
  str_homestory_803601001_40_dialog_content = "（ニセモノだったら、少しは気持ちも楽になるかな？）",
  str_homestory_803601001_41_dialog_content = "ううん、僕もそれはインチキだと思うな。",
  str_homestory_803601001_42_dialog_content = "もし本当にそんなものがあるなら、\nとうの昔にどこかの家宝になってるよ…",
  str_homestory_803601001_43_dialog_content = "闇市に出回るはずないと思う。",
  str_homestory_803601001_44_dialog_content = "…まぁな。",
  str_homestory_803601001_45_dialog_content = "お前もそう言うことだ…",
  str_homestory_803601001_46_dialog_content = "俺は行くよ。",
  str_homestory_803601001_47_dialog_content = "あっ、うん、バイバイ！",
  str_homestory_803601001_48_dialog_content = "（もし本当にそんなものがあるなら…僕は何に使うかな？）",
  str_homestory_811401001_0_dialog_content = "この馬は…",
  str_homestory_811401001_1_dialog_content = "あら、ごきげんよう。",
  str_homestory_811401001_2_dialog_content = "アンナが道を塞いでしまったかしら？",
  str_homestory_811401001_3_dialog_content = "それとも、私に用があるの？",
  str_homestory_811401001_4_dialog_content = "ごめんあそばせ。花のいい香りがしたものだから、\n思わず足を止めてしまったわ…",
  str_homestory_811401001_5_dialog_content = "いや、僕は特に用はないから、\n君は好きなだけここで花を楽しんで。",
  str_homestory_811401001_6_dialog_content = "この花、こんなに早く着いたんだね…",
  str_homestory_811401001_7_dialog_content = "数も想像していたよりずっと多いなあ。",
  str_homestory_811401001_8_dialog_content = "あら？何の話？",
  str_homestory_811401001_9_dialog_content = "あ、この花のことだよ。",
  str_homestory_811401001_10_dialog_content = "この花、クーリエ隊<sprite=emo_gezitou size=60 />に\n届けてもらえるように頼んであったんだ。",
  str_homestory_811401001_11_dialog_content = "ここはどこもかしこも岩と木ばかりでしょ。\n少しお花があったほうがいいかと思って。",
  str_homestory_811401001_12_dialog_content = "あら？私と同じ考えのようね。",
  str_homestory_811401001_13_dialog_content = "アンナとも話していたのよ。\nここには、もっとお花があった方がいいわ。",
  str_homestory_811401001_14_dialog_content = "うん、そうでしょ。\nそれで僕も、クーリエ隊に届けてもらったんだよ。",
  str_homestory_811401001_15_dialog_content = "でも、見た感じ、予定よりちょっと多いみたいだ…",
  str_homestory_811401001_16_dialog_content = "それは、私もついでにお花を買っておいたからよ。",
  str_homestory_811401001_17_dialog_content = "そうだったんだ…",
  str_homestory_811401001_18_dialog_content = "でも、ここは本当に素敵だわ。",
  str_homestory_811401001_19_dialog_content = "お店に、私の一番好きなジュネヴァがちゃんとあったわ…",
  str_homestory_811401001_20_dialog_content = "それから、カクテルに使う植物やシロップに、香料まであったわね。",
  str_homestory_811401001_21_dialog_content = "フフフ、本当に予想外だったわ！",
  str_homestory_811401001_22_dialog_content = "昔よりおもてなしが行き届くようになったんじゃない？",
  str_homestory_811401001_23_dialog_content = "そ、そうかな…",
  str_homestory_811401001_24_dialog_content = "あの坊やが、一体何を経験したら、\nこんなに気が利くようになるのかしらね？",
  str_homestory_811401001_25_dialog_content = "お店にジュネヴァがあったこと？",
  str_homestory_811401001_26_dialog_content = "それだけじゃないわよ。\n小鳥ちゃんたちに頼んで、お花も植えようとしてくれてるでしょ。",
  str_homestory_811401001_27_dialog_content = "その事なんだけど、実は…",
  str_homestory_811401001_28_dialog_content = "僕にお店にジュネヴァを置いたり、\n花を頼んだりするように言ったのは…",
  str_homestory_811401001_29_dialog_content = "…スモーキーなんだ。",
  str_homestory_811401001_30_dialog_content = "…へえ？",
  str_homestory_811401001_31_dialog_content = "まあ、他にもいろいろ言われたから、\n全部が君のためってワケじゃないんだろうけど…",
  str_homestory_811401001_32_dialog_content = "そう言われてみれば…アンナと話してた時、\n焼けるような気配を感じたわね。",
  str_homestory_811401001_33_dialog_content = "火<sprite=emo_nuhuo size=60 />を使う人なんてここには\nたくさんいるから、アイツだとは思わなかったわね。",
  str_homestory_811401001_34_dialog_content = "…アイツ…",
  str_homestory_811401001_35_dialog_content = "たぶん、アイツも私には知られたくないんでしょ？",
  str_homestory_811401001_36_dialog_content = "僕が思うに…",
  str_homestory_811401001_37_option_content = "知ってほしいんじゃないかな",
  str_homestory_811401001_38_dialog_content = "だって、スモーキーなら、\n自分でジュネヴァや花を持ってくることはできるでしょ…",
  str_homestory_811401001_39_dialog_content = "僕を通す必要は必ずしもないんだよ。",
  str_homestory_811401001_40_option_content = "知られたくないんじゃないかな",
  str_homestory_811401001_41_dialog_content = "僕がジュネヴァは君のためかって聞いたら、\n強く否定されたよ…",
  str_homestory_811401001_42_dialog_content = "そう。",
  str_homestory_811401001_43_dialog_content = "やっぱり、ひねくれてるわね。",
  str_homestory_811401001_44_dialog_content = "どちらでもいいけど、\nあなたはこの会話、アイツに知られないようにすることね。",
  str_homestory_811401001_45_dialog_content = "私が知ったことまではともかく、\n他の人に言いふらされでもしたら…",
  str_homestory_811401001_46_dialog_content = "照れ隠しで火を点けたり、暴れたりするでしょうから。",
  str_homestory_811401001_47_dialog_content = "うん、分かったよ…",
  str_homestory_811401001_48_dialog_content = "それにしても、スモーキーのこと、よく分かってるね。",
  str_homestory_811401001_49_dialog_content = "そうかしら？私はそう思わないけど。",
  str_homestory_801801001_0_dialog_content = "この荒々しい気配は…",
  str_homestory_801801001_1_dialog_content = "気になどするな！！！",
  str_homestory_801801001_2_dialog_content = "……野郎など語るな！",
  str_homestory_801801001_3_dialog_content = "愚か者があふれてる！灼熱の炎よ！燃えろ！<sprite=emo_nuhuo size=60 />",
  str_homestory_801801001_4_dialog_content = "（すごい熱中ぶりだ！）",
  str_homestory_801801001_5_dialog_content = "レジーナ！",
  str_homestory_801801001_6_dialog_content = "ナビゲーター、どうだ？私の新曲のデモは！",
  str_homestory_801801001_7_dialog_content = "一瞬ごまかしたところ…汚い言葉でも入るんだよね？",
  str_homestory_801801001_8_dialog_content = "やっぱり分かったか？",
  str_homestory_801801001_9_dialog_content = "分かるよ！",
  str_homestory_801801001_10_dialog_content = "フン、分からないようにしたつもりだったが…",
  str_homestory_801801001_11_dialog_content = "まさか、聞き取られちまうとは…",
  str_homestory_801801001_12_dialog_content = "ナビゲーター、お前も相当ワルに染まったな！",
  str_homestory_801801001_13_dialog_content = "…？",
  str_homestory_801801001_14_dialog_content = "いや、それはないよ…",
  str_homestory_801801001_15_dialog_content = "そうか、ならいい。どっちでもいいことさ！",
  str_homestory_801801001_16_dialog_content = "そういうわけで、新曲はまだ完成してないんだ。\n何かアイディアはないか？\n燃え上がるような意見をくれ！",
  str_homestory_801801001_17_dialog_content = "テーマでも、リリックでも、リズムでもいいぜ？",
  str_homestory_801801001_18_dialog_content = "僕は…音楽は本当によく分からないんだ。",
  str_homestory_801801001_19_dialog_content = "だから何だってんだ？\n私は音楽にしきいを作るような\n古クセーヤツが一番きらいだ！",
  str_homestory_801801001_20_dialog_content = "何でもいいから言ってみな！",
  str_homestory_801801001_21_dialog_content = "…",
  str_homestory_801801001_22_option_content = "バーバラ最高！",
  str_homestory_801801001_23_dialog_content = "はあ？何だってぇ！？",
  str_homestory_801801001_24_dialog_content = "ああ、なるほど。皮肉ってことだな。",
  str_homestory_801801001_25_option_content = "メタルは不滅！",
  str_homestory_801801001_26_dialog_content = "よく言った！！",
  str_homestory_801801001_27_dialog_content = "覚えておくぜ！",
  str_homestory_801801001_28_dialog_content = "空の末裔のインスピレーションも混ざれば、\nきっと他のヤツらの曲よりずっと燃え上がるぜ！",
  str_homestory_801801001_29_dialog_content = "ああ、やっぱり別ジャンルのバーバラだけじゃなくて、\n同じジャンルの人たちとも争ってたんだ？",
  str_homestory_801801001_30_dialog_content = "おいおい、音楽やってるヤツはな、\nみんな自分が一番なんだよ！<sprite=emo_shengqi size=60 />",
  str_homestory_801801001_31_dialog_content = "特にメタルじゃ、何も分かってねぇのに、\n知ったかぶりするヤツが多すぎる！",
  str_homestory_801801001_32_dialog_content = "ロックを一番分かってるみてぇな顔をしやがって、\nフタを開けてみりゃ、\n1曲も自分で書いたことねぇってヤツらがな！",
  str_homestory_801801001_33_dialog_content = "ふん、そういうヤツらに会うたび、\nエセロッカーどもを全部まとめて、\nきれいに焼きはらっちまいたくなる…",
  str_homestory_801801001_34_dialog_content = "アイツらなんかと「メタルを語る」くらいなら、\nバーバラの新曲を聞く方がまだマシだぜ！",
  str_homestory_801801001_35_dialog_content = "…あ、バーバラのこと、そこまで嫌いじゃなかったんだ？",
  str_homestory_801801001_36_dialog_content = "…2秒だ。",
  str_homestory_801801001_37_dialog_content = "…？",
  str_homestory_801801001_38_dialog_content = "バーバラの新曲は、2秒までしか耐えられない。",
  str_homestory_801801001_39_dialog_content = "そ、そうなんだ…",
  str_homestory_809201001_0_dialog_content = "あれは…",
  str_homestory_809201001_1_dialog_content = "君だったんだね、セファー。",
  str_homestory_809201001_2_dialog_content = "私じゃなかったら、誰だっていうのよ？<sprite=emo_baiyan size=60 />",
  str_homestory_809201001_3_dialog_content = "ええと、ここのブランコが好きな人、けっこう多いから…",
  str_homestory_809201001_4_dialog_content = "ってことは、君もブランコが好きなの？",
  str_homestory_809201001_5_dialog_content = "そう聞かれると、私もハッキリとは答えられないわね。",
  str_homestory_809201001_6_dialog_content = "まず、「好き」を詳しく定義しないといけないわ。",
  str_homestory_809201001_7_option_content = "（定義する）",
  str_homestory_809201001_8_dialog_content = "「好き」ってことは、もっとやりたいってことじゃないかな。",
  str_homestory_809201001_9_dialog_content = "「もっと」というのは、どれぐらい？\nぼんやりしてるわね。",
  str_homestory_809201001_10_dialog_content = "一日中、そのことをしたいって思うとか？",
  str_homestory_809201001_11_dialog_content = "それとも、ヒマになった時だけ？",
  str_homestory_809201001_12_dialog_content = "それとも、いつもは意識しないけど、時どき思い出してするってこと？",
  str_homestory_809201001_13_dialog_content = "（誰か助けて…軽い気持ちで話しかけただけなのに…）",
  str_homestory_809201001_14_dialog_content = "たぶん、ヒマになったら、やりたいって思うくらいかな？",
  str_homestory_809201001_15_option_content = "（拒否する）",
  str_homestory_809201001_16_dialog_content = "「好き」は「好き」だよ…定義する必要なんてある？",
  str_homestory_809201001_17_dialog_content = "僕も時間ができたら、あちこち歩いて回りたくなる。\nそういう感じでしょ。",
  str_homestory_809201001_18_dialog_content = "時間が出来た時にやりたいと思うってこと？",
  str_homestory_809201001_19_dialog_content = "わかったわ。",
  str_homestory_809201001_20_dialog_content = "その定義からすると、私は確かにブランコに座っているのが好きね。",
  str_homestory_809201001_21_dialog_content = "宙に浮いたイスが、かすかな無重力感を与えてくれる…",
  str_homestory_809201001_22_dialog_content = "私はそこに、言葉にできない喜びを感じるの。",
  str_homestory_809201001_23_dialog_content = "本当に？それはよかった！",
  str_homestory_809201001_24_dialog_content = "このブランコを造る時、まだ少し迷ってたんだ。",
  str_homestory_809201001_25_dialog_content = "セファーがそんなに気に入ってくれて、僕も安心したよ。",
  str_homestory_809201001_26_dialog_content = "でも、面倒なこともあるわ。",
  str_homestory_809201001_27_dialog_content = "「ボアストーン」が後ろから押してくれるんだけど、\nいつも力加減がうまくいかないの。",
  str_homestory_809201001_28_dialog_content = "上から落とされたこともあったわ！",
  str_homestory_809201001_29_dialog_content = "アハハ…",
  str_homestory_809201001_30_dialog_content = "今、私のことを笑ったでしょ！？<sprite=emo_shengqi size=60 />",
  str_homestory_809201001_31_option_content = "（否定する）",
  str_homestory_809201001_32_dialog_content = "違う、違うよ…",
  str_homestory_809201001_33_dialog_content = "「違う」？じゃあ、口角が上がってるのはどういうこと？\n説明してもらえるわよね。",
  str_homestory_809201001_34_option_content = "（認める）",
  str_homestory_809201001_35_dialog_content = "ごめん…",
  str_homestory_809201001_36_dialog_content = "つい、様子を頭に思い浮かべてしまって…",
  str_homestory_809201001_37_dialog_content = "ええと、ケガはしなかった？",
  str_homestory_809201001_38_dialog_content = "ご覧の通りよ。私がそんな簡単にケガなんてすると思う？",
  str_homestory_809201001_39_dialog_content = "それならよかった！\nでも、そんなにブランコが好きなら…",
  str_homestory_809201001_40_dialog_content = "僕が後ろから押そうか？",
  str_homestory_809201001_41_dialog_content = "え？いいの…？",
  str_homestory_809201001_42_dialog_content = "「ボアストーン」ほどの力がなくてもイヤじゃないなら。",
  str_homestory_809201001_43_dialog_content = "それは、「イヤ」という言葉の定義によるわね。",
  str_homestory_809201001_44_dialog_content = "えっ…",
  str_homestory_809201001_45_dialog_content = "もう、そんなことより、ブランコで遊ぼう！",
  str_homestory_809201001_46_dialog_content = "…仕方ないわね。\nあんたの誠意に免じて、行ってあげなくもないわ。",
  str_homestory_809901001_0_dialog_content = "アイリーナ…",
  str_homestory_809901001_1_dialog_content = "あ、PlayerNameさん…",
  str_homestory_809901001_2_dialog_content = "ご招待、ありがとうございます。\n私…楽しいです！",
  str_homestory_809901001_3_dialog_content = "お礼なんていらないよ！",
  str_homestory_809901001_4_dialog_content = "この辺りはまだ不慣れだよね。\n案内しようか？",
  str_homestory_809901001_5_dialog_content = "本当に、いいんですか？",
  str_homestory_809901001_6_dialog_content = "もちろんだよ、僕はここに一番詳しいんだ。",
  str_homestory_809901001_7_dialog_content = "でも…",
  str_homestory_809901001_8_dialog_content = "わ、私、やっぱり部屋に戻ります。",
  str_homestory_809901001_9_dialog_content = "え？外の景色は好きじゃないの？",
  str_homestory_809901001_10_dialog_content = "いいえ、そうではなくて…ここの景色は、大好きです！",
  str_homestory_809901001_11_dialog_content = "こんなに静かで心地のいい所、今まで知りませんでした。",
  str_homestory_809901001_12_option_content = "（感謝する）",
  str_homestory_809901001_13_dialog_content = "ありがとう！",
  str_homestory_809901001_14_dialog_content = "でも、静かで心地いい場所だけじゃないよ、\nにぎやかな所もあるんだ。",
  str_homestory_809901001_15_dialog_content = "いろいろ見せてあげるよ。",
  str_homestory_809901001_16_dialog_content = "でも、私…",
  str_homestory_809901001_17_option_content = "（質問する）",
  str_homestory_809901001_18_dialog_content = "そんなに急いで部屋に戻るって、何かあったの？",
  str_homestory_809901001_19_dialog_content = "それは…",
  str_homestory_809901001_20_dialog_content = "私の身体の呪いと黒いトゲで…\nこの景色を台無しにするのが怖いんです。",
  str_homestory_809901001_21_dialog_content = "そんなことになったら、\nPlayerNameさんに迷惑をかけてしまいます…",
  str_homestory_809901001_22_dialog_content = "アイリーナ、気づかいありがとう。",
  str_homestory_809901001_23_dialog_content = "でも、僕はそんなこと思わないよ。",
  str_homestory_809901001_24_dialog_content = "えっ？",
  str_homestory_809901001_25_dialog_content = "僕たちは知り合ってもう長いけど、\n君の呪いは僕に移ったりしてないよね？",
  str_homestory_809901001_26_dialog_content = "でも、黒いトゲが…",
  str_homestory_809901001_27_dialog_content = "それは呪いを抑えてくれている、君の友だち。\nだったよね？",
  str_homestory_809901001_28_dialog_content = "はい…",
  str_homestory_809901001_29_dialog_content = "アイリーナの友だちは、僕の友だちだよ！",
  str_homestory_809901001_30_dialog_content = "それに…",
  str_homestory_809901001_31_dialog_content = "君はずっと、その呪いを解く方法を探しているんだよね。",
  str_homestory_809901001_32_dialog_content = "ここを探検したら、呪いを解く方法が見つかるかもしれないよ？",
  str_homestory_809901001_33_dialog_content = "フフフ…PlayerNameさんの言うことでも、\nそれはあまり信じられませんね。",
  str_homestory_809901001_34_dialog_content = "もう長い間探してるんです。そんな簡単に見つかるわけが…",
  str_homestory_809901001_35_dialog_content = "今まで、仕事以外では、ほとんど出かけてないんじゃない？",
  str_homestory_809901001_36_dialog_content = "そうですね…",
  str_homestory_809901001_37_dialog_content = "外で大自然に触れると、気持ちが晴れるんだよ。",
  str_homestory_809901001_38_dialog_content = "気分がよくなれば、呪いなんて、本当に弱まっちゃうかもしれないよ！",
  str_homestory_809901001_39_dialog_content = "…",
  str_homestory_809901001_40_dialog_content = "アハハ…",
  str_homestory_809901001_41_dialog_content = "ありがとうございます。\n私、本当にとても気分がよくなりました。<sprite=emo_aixin size=60 />",
  str_homestory_809901001_42_dialog_content = "だったら…採掘場を見に行きたいんです。いいですか？",
  str_homestory_809901001_43_dialog_content = "えっ？",
  str_homestory_801601001_0_dialog_content = "カフカ？",
  str_homestory_801601001_1_dialog_content = "待って、カフカ…\n地面のこの、水滴のあと<sprite=emo_hanshui size=60 />は何？",
  str_homestory_801601001_2_dialog_content = "ああ…すまない、フランツ<sprite=emo_goutou size=60 />のヨダレだ。\n今、拭いたばかりなんだ。",
  str_homestory_801601001_3_dialog_content = "フランツの奴、最近嬉しいとすぐ\nヨダレをたらすようになってな。\nやっとのことで、クセを直したんだが…",
  str_homestory_801601001_4_dialog_content = "…まぁ、少なくとも私のベッドに\nヨダレをたらす回数は、\n大幅に減ったんだ。",
  str_homestory_801601001_5_dialog_content = "そうなんだ。誉めるべきことかもね…\nでも、フランツはずっと聞き分けのいい犬だよね？",
  str_homestory_801601001_6_dialog_content = "そんな風にほめたら、調子に乗るぞ。",
  str_homestory_801601001_7_dialog_content = "だが、私には分かる。フランツの奴、ここで楽しく過ごしてるようだ。",
  str_homestory_801601001_8_dialog_content = "え？ここの方が巨像よりも広いから？",
  str_homestory_801601001_9_dialog_content = "ここではいつも、おかしな奴らに会えるからだろうな…",
  str_homestory_801601001_10_dialog_content = "知ってるだろう、フランツは「おかしな」ものが大好きなんだ。",
  str_homestory_801601001_11_dialog_content = "おかしなもの？",
  str_homestory_801601001_12_dialog_content = "「おかしなヤツら」と言った方が正確だろうな。",
  str_homestory_801601001_13_dialog_content = "おかしな…",
  str_homestory_801601001_14_dialog_content = "あ、分かった。",
  str_homestory_801601001_15_option_content = "ツアードッグのこと？",
  str_homestory_801601001_16_dialog_content = "おう、確か、そんな名前だったかな。\nあまり話したことはないが。",
  str_homestory_801601001_17_dialog_content = "フランツはそいつを見かけると、すごい勢いでしっぽを振るんだ。\n耳を噛もうとしたこともあったな。",
  str_homestory_801601001_18_dialog_content = "それで、相手の反応は？",
  str_homestory_801601001_19_dialog_content = "いや、特に何も。ペンを握ったまま、\nしばらくフランツをじっと見つめて、何か言おうとしてたな。",
  str_homestory_801601001_20_dialog_content = "（…まさか、フランツに絵を描かせるつもりだったんじゃ…）",
  str_homestory_801601001_21_dialog_content = "結局、フランツの手を見て、\n残念そうに首を振りながら、行っちまったよ。",
  str_homestory_801601001_22_dialog_content = "そうなんだ…なら、よかった…",
  str_homestory_801601001_23_dialog_content = "そういや、触りがいのありそうな耳だったな。",
  str_homestory_801601001_24_dialog_content = "次に会った時には触ってみてもいいかもな…",
  str_homestory_801601001_25_option_content = "ハチとギン？",
  str_homestory_801601001_26_dialog_content = "あの毛むくじゃらの悪ガキ2人か。\n大人っぽく見せようと着飾ってはいるが…",
  str_homestory_801601001_27_dialog_content = "あいつら、フランツを見たとたん、\n「わあ！本物の犬だ！」って叫んでたぞ。",
  str_homestory_801601001_28_dialog_content = "フランツもたぶん、アイツらのことが好きなんだろう。\nずっとパタパタしっぽを振ってたからな。",
  str_homestory_801601001_29_dialog_content = "きっとヘンな光景だろうね…",
  str_homestory_801601001_30_dialog_content = "不思議と見てみたい気もするけど…",
  str_homestory_801601001_31_dialog_content = "まぁ、フランツはここで楽しくやってるってことだ。",
  str_homestory_801601001_32_dialog_content = "だが…ナビゲーターも最近、いつもフランツと一緒にいるんじゃないか？",
  str_homestory_801601001_33_dialog_content = "え？そんなことないでしょ…",
  str_homestory_801601001_34_dialog_content = "だったら、なんでいつもフランツに、\nお前の匂いが付いてるんだ？",
  str_homestory_801601001_35_dialog_content = "フランツがこっそり部屋に\n潜りこんだってのか？",
  str_homestory_801601001_36_dialog_content = "ううん…その可能性もなくはないけど…",
  str_homestory_801601001_37_dialog_content = "いや、待って……",
  str_homestory_801601001_38_dialog_content = "さっき何て言った！？",
  str_homestory_801601001_39_dialog_content = "フランツが君のベッドに\nヨダレ<sprite=emo_hanshui size=60 />を垂らす回数が減ったって…",
  str_homestory_801601001_40_dialog_content = "何…？まさか…",
  str_homestory_801601001_41_dialog_content = "…どうりで最近、僕のシーツがいつも湿ってるわけだ！",
  str_homestory_801601001_42_dialog_content = "そういうことか…",
  str_homestory_801601001_43_dialog_content = "どうやら、フランツに気に入られてるようだな。",
  str_homestory_801601001_44_dialog_content = "…喜んでいいのかな…",
  str_homestory_801601001_45_dialog_content = "私に聞いてるのか？",
  str_homestory_801601001_46_dialog_content = "はぁ…今すぐ戻って、シーツを洗うことをおすすめしておく。",
  str_homestory_804501001_0_dialog_content = "何の音？",
  str_homestory_804501001_1_dialog_content = "ネイルス？",
  str_homestory_804501001_2_dialog_content = "シーッ…もうしばしお待ちを…",
  str_homestory_804501001_3_dialog_content = "ああ！あなたの光沢ある美しい磁器皿に、\n私のけがれた身体が映っている…",
  str_homestory_804501001_4_dialog_content = "あなたの瞳は奥深い夜空のように、私の心の中の弱さを見抜く…",
  str_homestory_804501001_5_dialog_content = "どうか、私の罪をお許しください…",
  str_homestory_804501001_6_dialog_content = "あるいは…私があなたに恥をかかせたことを、\nお許しくださいと言うべきでしょうか？",
  str_homestory_804501001_7_dialog_content = "…",
  str_homestory_804501001_8_dialog_content = "申し訳ありません、PlayerName。",
  str_homestory_804501001_9_dialog_content = "私の声で驚かせてしまいましたか？",
  str_homestory_804501001_10_dialog_content = "誠に申し訳ございません…\n私の声はこれほどまでに聞くにたえないというのに、なんと罪深い…",
  str_homestory_804501001_11_dialog_content = "そんなふうに思わないで！\n別に驚いてないよ！",
  str_homestory_804501001_12_dialog_content = "ただ、興味があって。誰と話してたの？",
  str_homestory_804501001_13_dialog_content = "誤解です。私は誰かと話をしているのではありません。\n我が身の罪を懺悔しているのです。",
  str_homestory_804501001_14_dialog_content = "そのことに関しては、あなたに感謝をせねばなりません…",
  str_homestory_804501001_15_dialog_content = "このように懺悔ができる場所を造ってくださったことに、\n感謝いたします。",
  str_homestory_804501001_16_dialog_content = "ここでは、ビクトリア様にご迷惑をかけることなく…\n懺悔ができるのです。",
  str_homestory_804501001_17_option_content = "（否定する）",
  str_homestory_804501001_18_dialog_content = "僕は懺悔できる場所を造った覚えはないんだけど…",
  str_homestory_804501001_19_dialog_content = "そう謙虚になさらずとも…この壮大な噴水と池には、\nあなたもきっと、お心を尽くされたはず。",
  str_homestory_804501001_20_dialog_content = "だけど、これは願いの泉だよ。",
  str_homestory_804501001_21_option_content = "（認める）",
  str_homestory_804501001_22_dialog_content = "お礼なんて必要ないよ。気に入ってもらえればいいんだ…",
  str_homestory_804501001_23_dialog_content = "いや、待って…今、何て言った？懺悔する場所？",
  str_homestory_804501001_24_dialog_content = "もしかして、この願いの泉のこと？",
  str_homestory_804501001_25_dialog_content = "願いの泉、なんと優しい響きでしょう。",
  str_homestory_804501001_26_dialog_content = "私は皆さんがここで手を合わせ、懺悔する姿を見たことがあるだけですので…\n名前は存じ上げませんでした。",
  str_homestory_804501001_27_dialog_content = "私は罪を犯しました、私は懺悔しなければ…",
  str_homestory_804501001_28_dialog_content = "まさか、そんな風に解釈されるなんて…\nたぶん、他の皆はここで願い事をしてたんだと思うよ。",
  str_homestory_804501001_29_dialog_content = "私もPlayerNameに代わって懺悔を…",
  str_homestory_804501001_30_dialog_content = "えっ！？",
  str_homestory_804501001_31_dialog_content = "懺悔は、中断してはなりません…",
  str_homestory_804501001_32_dialog_content = "私が前もって、PlayerNameにそのことを\n説明していなかったのがいけないのです。",
  str_homestory_804501001_33_dialog_content = "願いの泉に宿る真理よ…",
  str_homestory_804501001_34_dialog_content = "ネイルスが再び懺悔することをお許しください…",
  str_homestory_804501001_35_dialog_content = "私は罪を犯しました、私は懺悔しなければなりません。\nどうか、私を罰してください…",
  str_homestory_804501001_36_option_content = "（罰を与える）",
  str_homestory_804501001_37_dialog_content = "あっ！今、願いの泉が反応したのを感知したよ！",
  str_homestory_804501001_38_dialog_content = "なんと？真理がついに降臨したというのですか！？",
  str_homestory_804501001_39_dialog_content = "ええと、願いの泉が言うには…",
  str_homestory_804501001_40_option_content = "（なぐさめる）",
  str_homestory_804501001_41_dialog_content = "ネイルス、それは本当に懺悔の必要なんてないことだと思うよ。",
  str_homestory_804501001_42_dialog_content = "ここで懺悔するより…次は何をすべきか、考えた方がいいと思うよ。",
  str_homestory_804501001_43_dialog_content = "！！！",
  str_homestory_804501001_44_dialog_content = "私はどうして思い至らなかったのでしょう…",
  str_homestory_804501001_45_dialog_content = "やはり…私は罪深い…",
  str_homestory_804501001_46_dialog_content = "これは…",
  str_homestory_808601001_0_dialog_content = "この見慣れた白い花は……",
  str_homestory_808601001_1_dialog_content = "PlayerName。",
  str_homestory_808601001_2_dialog_content = "天空ノ谷がこれ程美しいとは思ってもいませんでした。",
  str_homestory_808601001_3_dialog_content = "見渡す限りに広がる緑…白夜城では見られない景色です。",
  str_homestory_808601001_4_dialog_content = "この白い花<sprite=emo_huaduo size=60 />までもが、\n天空ノ谷を気に入っているようですね…",
  str_homestory_808601001_5_dialog_content = "そうだね…実は僕もちょっと意外なんだ。",
  str_homestory_808601001_6_dialog_content = "おや？あなたこそ天空ノ谷の一員でしょう？",
  str_homestory_808601001_7_dialog_content = "ああ、そういえば…",
  str_homestory_808601001_8_dialog_content = "以前、あなたが…小さい頃に天空ノ谷を\n離れざるを得なくなったと話してくださったことを、思い出しました。",
  str_homestory_808601001_9_dialog_content = "そうなんだよ。ソラヴァンが教えてくれた知識で、\n天空ノ谷のことは知ってるけど…",
  str_homestory_808601001_10_dialog_content = "実際に天空ノ谷に来て、きれいな谷の景色を見た時は、\nやっぱり胸に熱いものが沸き上がったよ。<sprite=emo_pugongying size=60 />",
  str_homestory_808601001_11_dialog_content = "何度見ても、同じ気持ちになるんだ。",
  str_homestory_808601001_12_dialog_content = "もしかしたら、これが…「家」ってことなのかな。\n天空ノ谷が僕自身とつながってるように感じるんだ。",
  str_homestory_808601001_13_dialog_content = "そうですね…ここでは、すべてのものに不思議な力がみなぎっているようです。\n自然と空の末裔の建築も見事に調和し、共存しています。",
  str_homestory_808601001_14_dialog_content = "普段、常に「去った」者に触れているからでしょうか、\n私は感じるのです…",
  str_homestory_808601001_15_dialog_content = "ここは「生命の根源の美」が満ちた所だと。",
  str_homestory_808601001_16_dialog_content = "命を歌い、たたえる人なら誰でも、\n天空ノ谷を気に入ることでしょう。",
  str_homestory_808601001_17_dialog_content = "PlayerNameの家は、本当に美しい所です。",
  str_homestory_808601001_18_dialog_content = "あなたがこのような家を持てたことを私も嬉しく思っています。",
  str_homestory_808601001_19_dialog_content = "ありがとう、ユーライア。",
  str_homestory_808601001_20_dialog_content = "君が天空ノ谷をそこまで高く評価してくれるなんて、僕もうれしいよ。",
  str_homestory_808601001_21_option_content = "（頼みごとをする）",
  str_homestory_808601001_22_dialog_content = "実は…ユーライアに頼みたいことがあるんだ。\n手を貸してもらえるかな？",
  str_homestory_808601001_23_dialog_content = "ふふ…PlayerName、急にかしこまりましたね。",
  str_homestory_808601001_24_dialog_content = "このように厳粛で、それでいてあいまいな空気…",
  str_homestory_808601001_25_dialog_content = "私をデートに誘うだけでは足りず、今度はプロポーズですか？",
  str_homestory_808601001_26_dialog_content = "えっ！？",
  str_homestory_808601001_27_dialog_content = "ち、違うよ！",
  str_homestory_808601001_28_dialog_content = "フフフ…かわいい反応ですね。",
  str_homestory_808601001_29_dialog_content = "か、からかわないで…",
  str_homestory_808601001_30_option_content = "（歓迎する）",
  str_homestory_808601001_31_dialog_content = "これからも天空ノ谷に遊びにきてね。\nユーライアをいつでも歓迎するよ。",
  str_homestory_808601001_32_dialog_content = "もちろん、そうさせていただきます。",
  str_homestory_808601001_33_dialog_content = "この地の美しさは人の心を奪います。\nそして、あなたの故郷です。",
  str_homestory_808601001_34_dialog_content = "これから先、あなたがここをどれほど偉大な故郷にしていくのか、\n私も楽しみにしています。",
  str_homestory_808601001_35_dialog_content = "それで…ユーライアは修道女で、死んだ人のために祈り、\n魂を安らかに眠らせるのが仕事なんだよね？",
  str_homestory_808601001_36_dialog_content = "その通りです。それが私の白夜城での仕事です。",
  str_homestory_808601001_37_dialog_content = "…なるほど。\n頼みごとが何か分かりました。",
  str_homestory_808601001_38_dialog_content = "うん、僕の一族の…安らかな眠りを祈りたいんだ。",
  str_homestory_808601001_39_dialog_content = "やはり、そうでしたか…",
  str_homestory_808601001_40_dialog_content = "あなたが成長し、生と死を心穏やかに\n受け止められるようになっていたことは、意外ですね。",
  str_homestory_808601001_41_dialog_content = "私、修道女ユーライアが、\n天空ノ谷の魂の安息を祈りましょう。",
  str_homestory_808601001_42_dialog_content = "彼らの魂が安らかなることを、\nそして白き花が天空ノ谷を埋め尽くさんことを祈ります。",
  str_homestory_808601001_43_dialog_content = "ありがとう。",
  str_homestory_810201001_0_dialog_content = "この電流は…",
  str_homestory_810201001_1_dialog_content = "テッサ？",
  str_homestory_810201001_2_dialog_content = "もし眠いようなら、天空ノ庭の家で休むといいよ。",
  str_homestory_810201001_3_dialog_content = "ふわあ…<sprite=emo_kun size=60 />",
  str_homestory_810201001_4_dialog_content = "はんだ、はんたか。",
  str_homestory_810201001_5_dialog_content = "え？何て言ったの？",
  str_homestory_810201001_6_dialog_content = "ああ、ロリポップを口から出さないと、\nあたしの言ってることが分からないわけ？",
  str_homestory_810201001_7_dialog_content = "うん…まぁ、僕はただ、外で寝てると\nカゼひくよって言いたかっただけなんだ。",
  str_homestory_810201001_8_dialog_content = "は？寝るのは家の中って、決まってるワケ？",
  str_homestory_810201001_9_dialog_content = "いや、確かに決まりはないけど…",
  str_homestory_810201001_10_dialog_content = "そんな決まりがあったとしたって、\nあたしは気にしないけどね。",
  str_homestory_810201001_11_dialog_content = "あたしは、寝たい所で寝る。",
  str_homestory_810201001_12_option_content = "（同意する）",
  str_homestory_810201001_13_dialog_content = "もちろん、それでいいよ！",
  str_homestory_810201001_14_dialog_content = "テッサのそういう生活スタイル、\n本当にうらやましいなあ。",
  str_homestory_810201001_15_dialog_content = "あたしはただ静かにしてたいだけ、\n誰かにうらやましがってもらおうなんて、\n思ってないよ。",
  str_homestory_810201001_16_option_content = "（同意できない）",
  str_homestory_810201001_17_dialog_content = "テッサの考え方は理解できるけど…",
  str_homestory_810201001_18_dialog_content = "あたしはただ静かにしてたいだけ、\n誰かに理解してもらおうなんて、\n思ってないよ。",
  str_homestory_810201001_19_dialog_content = "そっか…",
  str_homestory_810201001_20_dialog_content = "お店に日よけのパラソルとテントがあるから、\n必要なら、いつでも僕に言ってね。",
  str_homestory_810201001_21_dialog_content = "別に必要ないよ。木かげにいれば、十分だし。",
  str_homestory_810201001_22_dialog_content = "あ、そうだ。ここのお店って、ロリポップおいてる？",
  str_homestory_810201001_23_dialog_content = "もうすぐ食べ終わっちゃうんだよね。",
  str_homestory_810201001_24_dialog_content = "あることはあるよ。でも…",
  str_homestory_810201001_25_dialog_content = "まだ、家の中には入って見たことないんじゃない？",
  str_homestory_810201001_26_dialog_content = "はぁ…中にいる気分じゃないんだよね。",
  str_homestory_810201001_27_dialog_content = "それに、ロリポップと何か関係あるの？",
  str_homestory_810201001_28_dialog_content = "実は、テッサを歓迎するために…",
  str_homestory_810201001_29_dialog_content = "僕、大量のロリポップを用意してたんだ…",
  str_homestory_810201001_30_dialog_content = "そうなの？",
  str_homestory_810201001_31_dialog_content = "さっき見に行った時には、もう1本も残ってなかったから…",
  str_homestory_810201001_32_dialog_content = "テッサだと思ってたんだけど、\n別の人が持っていっちゃったみたいだね。",
  str_homestory_810201001_33_dialog_content = "そういうことは、早く言ってくれない？",
  str_homestory_810201001_34_dialog_content = "僕はてっきり、誰でもまずは天空ノ庭の家に行って、\n休憩するものと思ってたから…",
  str_homestory_810201001_35_dialog_content = "ふーん。ま、いいや。",
  str_homestory_810201001_36_dialog_content = "また買えばいいから。",
  str_homestory_810201001_37_dialog_content = "（テッサ、意外と話が通じるんだなあ…）",
  str_homestory_810201001_38_dialog_content = "あんたんとこに、なんか仕事ない？\nカネになるやつ。",
  str_homestory_810201001_39_dialog_content = "え、休憩しに行くんじゃないの？\nどうして急に仕事の話なんか？",
  str_homestory_810201001_40_dialog_content = "お店に行こうと思ったけど、\nお金持ってないって気付いたんだよ。",
  str_homestory_810201001_41_dialog_content = "仕事がなかったら、ツケにするしかないかな。",
  str_homestory_810201001_42_dialog_content = "…",
  str_homestory_810201001_43_dialog_content = "だったら、天空ノ庭の家の…\n電気配線を点検してもらえるかな。",
  str_homestory_810201001_44_dialog_content = "分かった。",
  str_homestory_801501001_0_dialog_content = "めずらしいね…",
  str_homestory_801501001_1_dialog_content = "君がギンと一緒じゃないなんて。",
  str_homestory_801501001_2_dialog_content = "ああ～…PlayerName、あんたには分かるか？この匂い！",
  str_homestory_801501001_3_dialog_content = "白夜コイン<sprite=emo_baiyebi size=60 />の匂いだ、\nそこらじゅう、全部おぜぜの匂いだぜ！",
  str_homestory_801501001_4_option_content = "（疑う）",
  str_homestory_801501001_5_dialog_content = "そんな匂いしないよ？",
  str_homestory_801501001_6_dialog_content = "それに、白夜コインに匂いなんてないでしょ…",
  str_homestory_801501001_7_dialog_content = "PlayerName、これはな、芸術的な表現方法ってヤツだ。\nただ、大事なのはな…",
  str_homestory_801501001_8_dialog_content = "ここには、コイン数億枚分に相当するプロジェクトがお前を待ってるってことだ！",
  str_homestory_801501001_9_dialog_content = "数億！？",
  str_homestory_801501001_10_option_content = "（匂いについて聞く）",
  str_homestory_801501001_11_dialog_content = "白夜コインって、どんな匂いなの？",
  str_homestory_801501001_12_dialog_content = "鉄さびの赤い、甘い匂いが3割、しょっぺえ汗の匂いが4割…",
  str_homestory_801501001_13_dialog_content = "それから、5割の…クンクン…",
  str_homestory_801501001_14_dialog_content = "みずみずしい果樹の香りだ！",
  str_homestory_801501001_15_dialog_content = "それだと合計12割にならない？",
  str_homestory_801501001_16_dialog_content = "12割、まさにオレとPlayerNameの商談にある誠意そのものじゃねえか。",
  str_homestory_801501001_17_dialog_content = "そうだ、念のため言っとくがよ、\n10割で満点だ。割合だからな。",
  str_homestory_801501001_18_dialog_content = "また、何か企んでるの…？",
  str_homestory_801501001_19_dialog_content = "僕も先に言っておくよ。\n僕の絵は売らないし、模写もしようと思わないで…",
  str_homestory_801501001_20_dialog_content = "PlayerName、遠くを見すえねえとダメだぜ？",
  str_homestory_801501001_21_dialog_content = "お前はもう、こんな天然100％の展覧会のショバを持ってんだぞ。\n絵の1枚や2枚、何だってんだ？",
  str_homestory_801501001_22_dialog_content = "展覧会？",
  str_homestory_801501001_23_dialog_content = "広々とした自然と人がうまく溶け合った、最高のお手本だ。",
  str_homestory_801501001_24_dialog_content = "自然の中で展覧会をやるにはうってつけだぜ。",
  str_homestory_801501001_25_dialog_content = "PlayerName、オレたち、本当にここが気に入った<sprite=emo_aixin size=60 />んだ。",
  str_homestory_801501001_26_dialog_content = "ってなわけで、俺はさっき非常に難しい決断をした！",
  str_homestory_801501001_27_dialog_content = "オレは――",
  str_homestory_801501001_28_dialog_content = "転職してキュレーターになる！",
  str_homestory_801501001_29_dialog_content = "キュレーター？何をするの？",
  str_homestory_801501001_30_dialog_content = "オッホン、簡単に言うと、芸術作品の鑑定、研究、保存、陳列なんかを担当する…",
  str_homestory_801501001_31_dialog_content = "あとは、展覧会の企画構成なんかもする、芸術専門のマネージャーだ。",
  str_homestory_801501001_32_dialog_content = "聞いてもよくわからないけど、\nまっとうな職業みたいだね。",
  str_homestory_801501001_33_dialog_content = "ということは、同意してくれるのか？",
  str_homestory_801501001_34_dialog_content = "僕が同意しようとしまいと、\n転職してキュレーターになればいいでしょ。",
  str_homestory_801501001_35_dialog_content = "でも、ここの環境を壊さないでよ…？\n苦労して、やっと今の姿にしたんだから。",
  str_homestory_801501001_36_dialog_content = "そうか。",
  str_homestory_801501001_37_dialog_content = "PlayerNameは、ここの建物や草花をいじってほしくねえってワケか。",
  str_homestory_801501001_38_dialog_content = "そうだよ。",
  str_homestory_801501001_39_dialog_content = "PlayerNameは、オレが計画を立てて開催する、\n芸術感にあふれた展覧会と芸術祭もいらねえってのか。",
  str_homestory_801501001_40_dialog_content = "そうだね。",
  str_homestory_801501001_41_dialog_content = "PlayerNameは、展覧会と芸術が目的で、\n胸を膨らませてやって来る観光客も要らねえってのか。",
  str_homestory_801501001_42_dialog_content = "うん…",
  str_homestory_801501001_43_dialog_content = "PlayerNameは、そいつらが落とす大金も要らねえってのか。",
  str_homestory_801501001_44_dialog_content = "うっ…",
  str_homestory_801501001_45_dialog_content = "PlayerNameは、フトコロ事情を改善したくねえのか？",
  str_homestory_801501001_46_dialog_content = "オホン、オホン…ちょっと待って。",
  str_homestory_801501001_47_dialog_content = "この件は、もう少し考えさせて。",
  str_homestory_801501001_48_dialog_content = "ハハハ…PlayerNameもようやく白夜コインの匂いを感じたみたいだな！",
  str_homestory_815401001_0_dialog_content = "またミュージアム？",
  str_homestory_815401001_1_dialog_content = "バイス、最近いつもミュージアムに長居してるね…",
  str_homestory_815401001_2_dialog_content = "何かお金もうけの方法でも隠れてるの？",
  str_homestory_815401001_3_dialog_content = "あなたね…",
  str_homestory_815401001_4_dialog_content = "お金の事は確かに改善が必要だけど…\nもう相談して決めたでしょ？",
  str_homestory_815401001_5_dialog_content = "世の中の人たちに、天空ノ谷の歴史と空の末裔の科学技術を紹介するため、\n公益施設としてミュージアムを作るって。",
  str_homestory_815401001_6_dialog_content = "だから、入館料だってとってないし、\nミュージアムでお金を稼ごうとするなんて、もってのほかでしょ…",
  str_homestory_815401001_7_option_content = "（謝る）",
  str_homestory_815401001_8_dialog_content = "ごめん、バイス…",
  str_homestory_815401001_9_dialog_content = "最近、ずっとそういうことばかり考えてたから、\nとりつかれたみたいになってた…",
  str_homestory_815401001_10_dialog_content = "アハハ、別にいいのよ。私もそういう時があるわ。",
  str_homestory_815401001_11_dialog_content = "そういう時は、ゆっくり休めっていうサインよ！",
  str_homestory_815401001_12_dialog_content = "僕ばかり気づかってないで。君もだよ。",
  str_homestory_815401001_13_dialog_content = "ここ数日、ずっとミュージアムで心配そうにしてるじゃない…？",
  str_homestory_815401001_14_dialog_content = "ちゃんと休んでないでしょ？",
  str_homestory_815401001_15_option_content = "（気づかう）",
  str_homestory_815401001_16_dialog_content = "安心して、そのことは僕もずっと考えてるから…",
  str_homestory_815401001_17_dialog_content = "空の末裔の文明を僕の代で絶やすわけには行かない。",
  str_homestory_815401001_18_dialog_content = "でも…",
  str_homestory_815401001_19_dialog_content = "ここ数日、ずっとなにか考え事してるみたいに\nミュージアムで過ごしてるよね？",
  str_homestory_815401001_20_dialog_content = "はぁ…PlayerNameに隠しごとは出来ないわね。<sprite=emo_wuzui size=60 />",
  str_homestory_815401001_21_dialog_content = "最近、ミュージアムの展示品の調査をしてるの。",
  str_homestory_815401001_22_dialog_content = "調査？啓光からの任務とか？",
  str_homestory_815401001_23_dialog_content = "違うわ、私個人の考えよ。",
  str_homestory_815401001_24_dialog_content = "まぁ、調査ってほどのことでもないけどね。",
  str_homestory_815401001_25_dialog_content = "何かのひらめきにつながる発見はないかって、\n見てみたいだけなの。",
  str_homestory_815401001_26_dialog_content = "あなたも知ってるでしょ、私の身体にいろんな変化があったこと…",
  str_homestory_815401001_27_dialog_content = "それから、断片的にだけど、ずっと昔のことも思い出したの。",
  str_homestory_815401001_28_dialog_content = "でも、自分の生まれについては、\n手がかりになるような情報がまったく得られなくて…",
  str_homestory_815401001_29_dialog_content = "それで…ミュージアムで手がかりを\n見つけようとしてるの？",
  str_homestory_815401001_30_dialog_content = "アハハ、おかしいでしょ？",
  str_homestory_815401001_31_dialog_content = "それもそうよね。空の末裔のミュージアムに、\n私の出生に関する手がかりなんて、あるはずないわよね？",
  str_homestory_815401001_32_dialog_content = "そうとも限らないよ。",
  str_homestory_815401001_33_dialog_content = "世界は広いけど、「偶然」って呼ばれる出来事もあるでしょ。",
  str_homestory_815401001_34_dialog_content = "フフフ、知り合ったばかりの頃に比べると、\nあなたも楽観的になったわね。",
  str_homestory_815401001_35_dialog_content = "ミュージアムを見るの、僕も付き合おうか？",
  str_homestory_815401001_36_dialog_content = "もしかしたら、何か手がかりが見つかるかもしれないよ？\n家族の手紙とか。",
  str_homestory_815401001_37_dialog_content = "そうね。",
  str_homestory_815401001_38_dialog_content = "でも、万が一それで、私があなたの実の姉だって分かったら…<sprite=emo_sikao size=60 />",
  str_homestory_815401001_39_dialog_content = "どうする？",
  str_homestory_815401001_40_dialog_content = "お姉さん？",
  str_homestory_815401001_41_dialog_content = "いやいや、きっと僕が「お兄ちゃん」って呼ばれる側だよ。",
  str_homestory_815401001_42_dialog_content = "PlayerName…",
  str_homestory_815401001_43_dialog_content = "まぁ…考えられないわね。",
  str_homestory_815401001_44_dialog_content = "やっぱりそんな「偶然」、ない方がいいわ！",
  str_homestory_805702001_0_dialog_content = "雨かな？",
  str_homestory_805702001_1_dialog_content = "ミャ～オ…",
  str_homestory_805702001_2_dialog_content = "フィリス、雨が降って来たみたいだよ。早くどこかで雨宿りしよう。",
  str_homestory_805702001_3_dialog_content = "違うにゃ。今のはフィリスが濡れた身体をブルっとしただけにゃ。",
  str_homestory_805702001_4_dialog_content = "あ…ごめんにゃ。水滴が飛んじゃった？",
  str_homestory_805702001_5_dialog_content = "なるほど。それで頭を振ってたんだね…",
  str_homestory_805702001_6_dialog_content = "PlayerName、からかうのは禁止だにゃ～！",
  str_homestory_805702001_7_dialog_content = "あれ？それなら、どうして水に濡れてるの？",
  str_homestory_805702001_8_dialog_content = "うぅ…光るニボシが川の中にあったせいにゃ！<sprite=emo_shengqi size=60 />",
  str_homestory_805702001_9_option_content = "光る？",
  str_homestory_805702001_10_dialog_content = "ニボシが？",
  str_homestory_805702001_11_dialog_content = "フィリスも不思議に思ったから、捕まえようとしたにゃ。",
  str_homestory_805702001_12_option_content = "ニボシ？",
  str_homestory_805702001_13_dialog_content = "ちょっと待て。川の中にニボシって変だよね？",
  str_homestory_805702001_14_dialog_content = "捕まえてお日さまの下で干したら、ニボシだにゃ。",
  str_homestory_805702001_15_dialog_content = "がんばってたら、うっかり川の中に落ちたにゃ～…",
  str_homestory_805702001_16_dialog_content = "くしゅん！川の水、超冷たいにゃ。",
  str_homestory_805702001_17_dialog_content = "早く家に戻って体を温めないと。外にいるとカゼをひいちゃうよ。",
  str_homestory_805702001_18_dialog_content = "でも…",
  str_homestory_805702001_19_dialog_content = "そうだ、PlayerNameはここの主なんだから…",
  str_homestory_805702001_20_dialog_content = "代わりにあの光るニボシを捕まえてにゃ！",
  str_homestory_805702001_21_dialog_content = "えっ？",
  str_homestory_805702001_22_dialog_content = "その後…日に干して…すぅ…すぅ……<sprite=emo_kun size=60 />",
  str_homestory_805702001_23_dialog_content = "外で寝るとカゼをひくって……フィリス？",
  str_homestory_805702001_24_dialog_content = "すぅ…すぅ…<sprite=emo_kun size=60 />ニボシ…",
  str_homestory_814101001_0_dialog_content = "なんだか嬉しそうな寝顔だなぁ…",
  str_homestory_814101001_1_dialog_content = "ハーイ、PlayerName。キミも探検中？",
  str_homestory_814101001_2_option_content = "そうだよ",
  str_homestory_814101001_3_dialog_content = "僕たちが作った天空ノ庭だけど、まだまだ探検できる場所も多いからね。",
  str_homestory_814101001_4_option_content = "違うよ",
  str_homestory_814101001_5_dialog_content = "今は気分転換に来ただけだよ。",
  str_homestory_814101001_6_dialog_content = "せっかくここまでするのに苦労したんだから、なるべく歩き回らないと。",
  str_homestory_814101001_7_dialog_content = "その通りだね！",
  str_homestory_814101001_8_dialog_content = "探検できそうな場所がいっぱいあってワクワクするよ！",
  str_homestory_814101001_9_dialog_content = "ちょうど今、そこの川を探検して来たんだ。",
  str_homestory_814101001_10_dialog_content = "そうなんだ。収穫はあった？",
  str_homestory_814101001_11_dialog_content = "アハハハ～、聞かれると思った！",
  str_homestory_814101001_12_dialog_content = "とにかく小川が見えたから、ザブ～ンと飛び込んでみたんだよ。",
  str_homestory_814101001_13_dialog_content = "それで水草を押しのけたら、泥の中から見たことないコインを拾って<sprite=emo_baiyebi size=60 />…",
  str_homestory_814101001_14_dialog_content = "振り向きざまに魚を捕まえて…",
  str_homestory_814101001_15_dialog_content = "もう何メートルか泳いだら、今度はある古いモノを見つけたんだ。",
  str_homestory_814101001_16_dialog_content = "逆手でつかんで、岸に引き上げたら…何だったと思う？",
  str_homestory_814101001_17_dialog_content = "え…何だろう？",
  str_homestory_814101001_18_dialog_content = "水草に覆われたボロ靴～。アハハハ！",
  str_homestory_814101001_19_dialog_content = "あんなボロ靴、お店に持ち込んでも白夜コイン1枚にもならないね。超笑えるでしょ、アハハ！",
  str_homestory_814101001_20_dialog_content = "魚とコインは？",
  str_homestory_814101001_21_dialog_content = "あっ！そうだった…あれ？確か、ポケットの中に…",
  str_homestory_814101001_22_dialog_content = "ま、いっか！たぶんボロ靴を拾っている最中に落としたんだね。",
  str_homestory_814101001_23_dialog_content = "興味があるなら探してみなよ。",
  str_homestory_814101001_24_dialog_content = "魚はとっくに逃げてると思うけどね～。",
  str_homestory_814101001_25_dialog_content = "ルビー…君って本当に100%楽天家だね…",
  str_homestory_814101001_26_dialog_content = "そうそう！この話、絶対にルージュにはヒミツにしといて？",
  str_homestory_814101001_27_dialog_content = "バレたら、またカゼ予防の苦～い薬を飲まされちゃうから。",
  str_homestory_801001001_0_dialog_content = "寝てるのかな？",
  str_homestory_801001001_1_dialog_content = "ルイス、大丈夫？すごく眠そうだけど？",
  str_homestory_801001001_2_dialog_content = "あ、PlayerName…",
  str_homestory_801001001_3_dialog_content = "やっと会えたと思ったのに…",
  str_homestory_801001001_4_dialog_content = "誰かを待ってたの？",
  str_homestory_801001001_5_dialog_content = "川に住む妖精さんを待ってたの。",
  str_homestory_801001001_6_dialog_content = "妖精？",
  str_homestory_801001001_7_dialog_content = "有名なおとぎ話、聞いたことないの？",
  str_homestory_801001001_8_dialog_content = "静かな小川には、とっても美しい妖精が住んでるの。",
  str_homestory_801001001_9_dialog_content = "通りがかった人がうっかり小川に物を落とすと、その妖精が現れて…",
  str_homestory_801001001_10_dialog_content = "質問に正直に答えた良い子は、ごほうびがもらえるんだよ！",
  str_homestory_801001001_11_option_content = "小川…",
  str_homestory_801001001_12_dialog_content = "この川にも妖精が住んでるって思ってるの？",
  str_homestory_801001001_13_dialog_content = "うん、だって、どの小川にもいるっていうから…",
  str_homestory_801001001_14_dialog_content = "北境の小川には北境の妖精、\n天空ノ谷の小川には天空ノ谷の妖精が住んでるんじゃない？",
  str_homestory_801001001_15_option_content = "おとぎ話…",
  str_homestory_801001001_16_dialog_content = "そういえば、どこかで聞いたことがあるかも…",
  str_homestory_801001001_17_dialog_content = "木こりが鉄の斧を落としたのに、欲張って金の斧を落としたって答えた、みたいな？",
  str_homestory_801001001_18_dialog_content = "でも、その話より…",
  str_homestory_801001001_19_dialog_content = "ルイス、うっかり何かを川に落としたの？",
  str_homestory_801001001_20_dialog_content = "うん…でも、あれは私の物じゃなかったの。",
  str_homestory_801001001_21_dialog_content = "川辺でひろったコインなんだけど、表面に複雑な模様が描かれてて…",
  str_homestory_801001001_22_dialog_content = "でも、よく見ようとしたら小川の中に落としちゃったの。",
  str_homestory_801001001_23_dialog_content = "その後ずっと待ってるんだけど、妖精さんが出てこないから…",
  str_homestory_801001001_24_dialog_content = "PlayerName、この小川には妖精さん、いないのかも……<sprite=emo_sikao size=60 />",
  str_homestory_801001001_25_dialog_content = "拾えるところにないか、僕が探して見るよ。",
  str_homestory_801001001_26_dialog_content = "え、PlayerName、妖精さんだったの！？",
  str_homestory_804102001_0_dialog_content = "まじめな顔で…",
  str_homestory_804102001_1_dialog_content = "Ms.ブラン、こんにちは。",
  str_homestory_804102001_2_dialog_content = "PlayerNameさん、こんにちは。",
  str_homestory_804102001_3_dialog_content = "天空ノ庭の道路や建物の観察ですか？",
  str_homestory_804102001_4_dialog_content = "私の「職業病」を覚えてくださっているのですね。嬉しいです。",
  str_homestory_804102001_5_option_content = "すごいプロ意識ですね！",
  str_homestory_804102001_6_dialog_content = "でも…",
  str_homestory_804102001_7_option_content = "すみません！",
  str_homestory_804102001_8_dialog_content = "どういうことでしょう？",
  str_homestory_804102001_9_dialog_content = "天空ノ庭の建設中、建物や道路をどんどん増設してきたので…",
  str_homestory_804102001_10_dialog_content = "仕事量を増やしちゃってますよね？",
  str_homestory_804102001_11_dialog_content = "PlayerNameさん、プロの意識を過小評価してはいけませんよ。",
  str_homestory_804102001_12_dialog_content = "主な建物や道路の方角、座標さえ頭に入っていれば…",
  str_homestory_804102001_13_dialog_content = "道路や建物がいくら増えても、覚えるのにさほど苦労はしないのです。",
  str_homestory_804102001_14_dialog_content = "すごい記憶力ですね！",
  str_homestory_804102001_15_dialog_content = "じゃあ…さっき眉をひそめていたのは、何か問題があったからですか？",
  str_homestory_804102001_16_dialog_content = "まぁ、見られていたのですね。",
  str_homestory_804102001_17_dialog_content = "確かに少し問題がありました…そうですね、お伝えしておきましょう。",
  str_homestory_804102001_18_dialog_content = "実は、天空ノ庭の案内文をどう書こうか考えているのです。",
  str_homestory_804102001_19_dialog_content = "今は小川について書いているのですが…",
  str_homestory_804102001_20_dialog_content = "魚の他に、光る何かがある気がするのです。",
  str_homestory_804102001_21_dialog_content = "詳しい案内を書くためにも、あれの正体を突き止めたいのですが…",
  str_homestory_804102001_22_dialog_content = "光る何か…",
  str_homestory_804102001_23_dialog_content = "天空ノ庭の主はあなたですから、この件、調べていただけませんか？",
  str_homestory_804102001_24_dialog_content = "もちろん問題ないですよ！",
  str_homestory_801502001_0_dialog_content = "また何か嗅ぎまわってる…？",
  str_homestory_801502001_1_dialog_content = "うっ…ハチ、これって…？",
  str_homestory_801502001_2_dialog_content = "お～、PlayerNameじゃないか！<sprite=emo_yaosu size=60 />",
  str_homestory_801502001_3_dialog_content = "どうだ、気持ちは固まったか？",
  str_homestory_801502001_4_dialog_content = "え、何の話…？",
  str_homestory_801502001_5_dialog_content = "あー。分かるよ。オレたちのVIPは忘れっぽいからな。",
  str_homestory_801502001_6_dialog_content = "つまり…天空ノ庭を展示場にするって話さ。",
  str_homestory_801502001_7_option_content = "考え中",
  str_homestory_801502001_8_dialog_content = "あの話は、まだ考え中だよ…",
  str_homestory_801502001_9_option_content = "あきらめて",
  str_homestory_801502001_10_dialog_content = "いいアイデアだとは思うけど、天空ノ庭は今まで通り、\n静かなままにしておきたいんだ。",
  str_homestory_801502001_11_dialog_content = "そうか？",
  str_homestory_801502001_12_dialog_content = "よく考えろって。チャンスは待っちゃくれないぜ！",
  str_homestory_801502001_13_dialog_content = "うん…",
  str_homestory_801502001_14_dialog_content = "クンクン…",
  str_homestory_801502001_15_dialog_content = "ところで、何を嗅いでるの？",
  str_homestory_801502001_16_dialog_content = "はぁ？分からないのか？このコインの香り…",
  str_homestory_801502001_17_dialog_content = "また…「白夜コイン」<sprite=emo_baiyebi size=60 />？",
  str_homestory_801502001_18_dialog_content = "いや、今回は違う！",
  str_homestory_801502001_19_dialog_content = "これまでにない、名状しがたいコインの香りだ…クンクン…",
  str_homestory_801502001_20_dialog_content = "白夜コインよりもワイルドでしっとりとした…鋳造時期もさらに古い…",
  str_homestory_801502001_21_dialog_content = "模様も複雑で…",
  str_homestory_801502001_22_dialog_content = "模様まで嗅ぎ分けられるの！？",
  str_homestory_801502001_23_dialog_content = "ワンコの鼻をナメるなよ。",
  str_homestory_801502001_24_dialog_content = "ビジネスの風向きだろうと、コインのありかだろうと、\nオレなら正しい方向へ導いてやれるぜ。",
  str_homestory_801502001_25_dialog_content = "まぁ、今回はコインを見つけるチャンス、譲ってやるよ。",
  str_homestory_801502001_26_dialog_content = "えっ？",
  str_homestory_801502001_27_dialog_content = "だから、業務提携の件はまた考えといてくれよな！",
  str_homestory_805602001_0_dialog_content = "コンスタン？",
  str_homestory_805602001_1_dialog_content = "よう、PlayerName。",
  str_homestory_805602001_2_dialog_content = "どこに行ってきたの？",
  str_homestory_805602001_3_dialog_content = "釣りから戻ったところだ。",
  str_homestory_805602001_4_dialog_content = "最近はよく釣りに行ってるよね。",
  str_homestory_805602001_5_dialog_content = "コンスタンはプロのハンターだし、きっと毎日大漁でしょ？",
  str_homestory_805602001_6_dialog_content = "いや、1匹も釣れてねぇ。",
  str_homestory_805602001_7_dialog_content = "えっ、ウソでしょ？コンスタン、狩りの腕前はすごいじゃない…",
  str_homestory_805602001_8_dialog_content = "釣りも狩りの一種とはいえるが、大きな違いがある。<sprite=emo_sikao size=60 />",
  str_homestory_805602001_9_dialog_content = "狩りは狙った獲物を倒しに行くが…",
  str_homestory_805602001_10_dialog_content = "釣りは自分の動きを最小限に抑えて、近寄って来たヤツを捕まえるんだ。",
  str_homestory_805602001_11_option_content = "なるほど",
  str_homestory_805602001_12_dialog_content = "釣りは竿を上げるまで、何が釣れたか分からないけど…",
  str_homestory_805602001_13_dialog_content = "狩りはまずターゲットを見つけて、それから行動を起こすんだね。",
  str_homestory_805602001_14_option_content = "わからない…",
  str_homestory_805602001_15_dialog_content = "狩りには忍耐力が必要だって、いつも言ってたよね。\nでも、釣りにも忍耐力はすごく必要だよ。",
  str_homestory_805602001_16_dialog_content = "釣りはどんな獲物が、いつ釣れるか全く分からないし。",
  str_homestory_805602001_17_dialog_content = "ああ、おまえの言う通りだ。",
  str_homestory_805602001_18_dialog_content = "正直に言うと、そもそもマトモに釣るつもりは無くてな…",
  str_homestory_805602001_19_dialog_content = "獲物を決めてから行動を起こすとはいうが、結局その労力が割に合わないことも多い。",
  str_homestory_805602001_20_dialog_content = "その教訓を忘れないよう、俺は釣り針をまっすぐにしてるんだ。",
  str_homestory_805602001_21_dialog_content = "え？それで魚が釣れるの？",
  str_homestory_805602001_22_dialog_content = "さあな。それは気にしてないんだ。俺は忍耐力を鍛えたいだけだからな。",
  str_homestory_805602001_23_dialog_content = "ずっと続けるつもり？",
  str_homestory_805602001_24_dialog_content = "やめ時は決めてある。",
  str_homestory_805602001_25_dialog_content = "川に落ちてるコインが泥に覆われるか、流されるか…誰かが持っていくまでだ。",
  str_homestory_805602001_26_dialog_content = "それまでは、このまっすぐな針で釣りを続けるさ。",
  str_homestory_805602001_27_dialog_content = "（コイン…？）",
  str_homestory_805602001_28_dialog_content = "(僕もコインが釣れるか挑戦してみようかな)",
  str_homestory_808502001_0_dialog_content = "手の動きが早い…",
  str_homestory_808502001_1_dialog_content = "ジェーン、記録を付けてたの？",
  str_homestory_808502001_2_dialog_content = "はい。私が見た天空ノ庭のすべてを記録しています。",
  str_homestory_808502001_3_dialog_content = "君の職業を知らなかったら、きっと絵を描いてると思っただろうね。",
  str_homestory_808502001_4_dialog_content = "絵も描いていましたよ。",
  str_homestory_808502001_5_dialog_content = "えっ？<sprite=emo_wuzui size=60 />",
  str_homestory_808502001_6_dialog_content = "記録には文字だけではなく、適切なイラストレーションも必要です。",
  str_homestory_808502001_7_dialog_content = "イラストが要るの？",
  str_homestory_808502001_8_dialog_content = "簡単に言うと、言葉では上手く表現できない時に絵の力を借りるのです。",
  str_homestory_808502001_9_dialog_content = "たとえば、さきほどは川の中で見たもの全てを記録していました。",
  str_homestory_808502001_10_dialog_content = "「レッドパーチ」の姿を言葉で説明されても、読者は漠然とした印象しか持てないでしょう。",
  str_homestory_808502001_11_dialog_content = "そんな時、魚の体型や色彩を絵に描いておけば…",
  str_homestory_808502001_12_dialog_content = "一目で魚の詳しい姿を理解できます。",
  str_homestory_808502001_13_dialog_content = "なるほど…",
  str_homestory_808502001_14_dialog_content = "もう1つ例を挙げましょう。「川底にコインが眠っている」と記録すると…",
  str_homestory_808502001_15_dialog_content = "読者は自分が使ったことのあるコインしか想像できません。",
  str_homestory_808502001_16_dialog_content = "ですから、誰も見たことのないコインであれば、その模様を描く必要があるのです。",
  str_homestory_808502001_17_dialog_content = "天空ノ庭の川底にどのようなコインが眠っているのか、読者にはっきりと伝えられます。",
  str_homestory_808502001_18_dialog_content = "じゃあ…そのコインは今どこに？",
  str_homestory_808502001_19_dialog_content = "今も川の底です。",
  str_homestory_808502001_20_dialog_content = "え？せっかく見つけたコインを拾わないの？",
  str_homestory_808502001_21_dialog_content = "私は記録人ですので、干渉はしません。",
  str_homestory_808502001_22_dialog_content = "ですが、あなたがコインを拾いに行くことも止めません。",
  str_homestory_808502001_23_dialog_content = "もちろん、私はそのすべてをありのまま記録します。",
  str_homestory_805502001_0_dialog_content = "怒ってる？",
  str_homestory_805502001_1_dialog_content = "ピアタマン、何かあった？すごく怒ってるように見えるけど…",
  str_homestory_805502001_2_dialog_content = "PlayerName殿、いいタイミングです。探しましたよ。",
  str_homestory_805502001_3_dialog_content = "え…僕に関係あること？",
  str_homestory_805502001_4_dialog_content = "まだ分かりません、ですが…",
  str_homestory_805502001_5_dialog_content = "白夜に捧ぐ！白夜城の法廷の名においてお尋ねしますが…",
  str_homestory_805502001_6_dialog_content = "天空ノ庭で白夜コインを私的に鋳造したりはしていませんか？",
  str_homestory_805502001_7_option_content = "してないよ！",
  str_homestory_805502001_8_dialog_content = "確かにお金は必要だけど、そこまで追い詰められてるわけじゃ…",
  str_homestory_805502001_9_option_content = "考えてはみた",
  str_homestory_805502001_10_dialog_content = "でも、白夜コインを鋳造するための技術や機械は高いよね…\nお金を作ろうとすれば、そのためにお金が必要でしょ。",
  str_homestory_805502001_11_dialog_content = "知ってると思うけど、僕にそこまでの余裕はないよ。",
  str_homestory_805502001_12_dialog_content = "では、宣誓していただけますか？",
  str_homestory_805502001_13_dialog_content = "僕、PlayerNameは絶対に白夜コインを私的に鋳造してません！",
  str_homestory_805502001_14_dialog_content = "もししてたら…好きに処罰してくれていいよ。",
  str_homestory_805502001_15_dialog_content = "では…天空ノ庭を訪れた人の中に疑わしい者はおりませんか？",
  str_homestory_805502001_16_dialog_content = "特に、影ノ街や砂漠から来ている方たちの中に…",
  str_homestory_805502001_17_dialog_content = "みんな僕の友だちだよ。疑いたくはない…",
  str_homestory_805502001_18_dialog_content = "相手が誰であろうと、法の下では平等に扱われるべきです。",
  str_homestory_805502001_19_dialog_content = "でも…いったいなんで疑ってるの？",
  str_homestory_805502001_20_dialog_content = "宣誓もしていただいたことですし…いいでしょう、お話しします。",
  str_homestory_805502001_21_dialog_content = "先ほど、川辺でコインを1枚拾ったのです。\n素材は非常に白夜コインと似ていました。",
  str_homestory_805502001_22_dialog_content = "そのコイン、見せてもらえる?",
  str_homestory_805502001_23_dialog_content = "それが、怒りで手が震えるあまり、コインを川に落としてしまったのです…",
  str_homestory_805502001_24_dialog_content = "あくまで推測だけど…そのコイン、空の末裔の物かもしれないよ。",
  str_homestory_805502001_25_dialog_content = "なんと…そのような物が？",
  str_homestory_805502001_26_dialog_content = "確かに、詳しく観察できたわけではありませんし…",
  str_homestory_805502001_27_dialog_content = "もしそうであれば…先ほどの無礼を謝罪させてください。",
  str_homestory_805502001_28_dialog_content = "たいへん申し訳ございません。",
  str_homestory_805502001_29_dialog_content = "気にしないで。本当のところは僕にも分からないんだし。",
  str_homestory_805502001_30_dialog_content = "コインが見つかったら、しっかり見せてあげるよ。",
  str_homestory_805502001_31_dialog_content = "助かります、PlayerName殿。",
  str_homestory_815701001_0_dialog_content = "どうしたの？",
  str_homestory_815701001_1_dialog_content = "あっ…ナビゲーター様…",
  str_homestory_815701001_2_dialog_content = "私はただ、花を眺めていただけです<sprite=emo_huaduo size=60 />！",
  str_homestory_815701001_3_dialog_content = "決して転んだから、\nそのまま一休みしているわけではありません…",
  str_homestory_815701001_4_dialog_content = "転んだの？ケガは？",
  str_homestory_815701001_5_dialog_content = "慣れてますので大丈夫で…\nあっ、バレてしまいましたか…？",
  str_homestory_815701001_6_dialog_content = "君は分かりやすいからね…",
  str_homestory_815701001_7_dialog_content = "ど、どうか、不器用だからといって、\nクビにしないでください…",
  str_homestory_815701001_8_dialog_content = "そんなことしないよ。でも…\nここで何か考え事でもしてたの？",
  str_homestory_815701001_9_dialog_content = "天空ノ庭の建設に関して、\n何か提案があれば、なんでも言ってね！",
  str_homestory_815701001_10_dialog_content = "いえ…特にありません…",
  str_homestory_815701001_11_dialog_content = "わ、私、PlayerName様が\nここに花を植えられた理由を\n妄想していたわけではありませんから！！",
  str_homestory_815701001_12_dialog_content = "…そう言われると、かえって気になるんだけど…",
  str_homestory_815701001_13_dialog_content = "いえいえ！",
  str_homestory_815701001_14_dialog_content = "ナビゲーター様が愛する人への想いを込めて、\nここに花を植えたなどということは…",
  str_homestory_815701001_15_dialog_content = "わ、私、まったく知りませんので…",
  str_homestory_815701001_16_option_content = "愛する人…？",
  str_homestory_815701001_17_dialog_content = "そうでしょう？きっとその方は\nふとしたきっかけで、\nナビゲーター様と知り合い…",
  str_homestory_815701001_18_dialog_content = "世間のさまざまなしがらみを乗り越え、\nあなたのお側にやって来た…",
  str_homestory_815701001_19_dialog_content = "そして様々なアイディアを出し、\nナビゲーター様のアストラ大陸での旅を支えた…",
  str_homestory_815701001_20_dialog_content = "ああ、その方はきっと、\nとても素晴らしい女性に違いありません！",
  str_homestory_815701001_21_dialog_content = "そして、この花畑に植えられているのは、\nその方の一番好きな花…そうですよね？",
  str_homestory_815701001_22_option_content = "…思いを込めて？",
  str_homestory_815701001_23_dialog_content = "かつて、すべてを捨てて、\nあなたのお側へやって来たその方は…",
  str_homestory_815701001_24_dialog_content = "ずっとナビゲーター様の旅を支え、\n守ってくれた…",
  str_homestory_815701001_25_dialog_content = "しかし今は、色々あって\n一緒にいることができなくなった…",
  str_homestory_815701001_26_dialog_content = "その方への思いを込めて…",
  str_homestory_815701001_27_dialog_content = "その方が一番好きだった花を\nこのお花畑に植えた、ということです！",
  str_homestory_815701001_28_dialog_content = "あの、何を言ってるのかサッパリ…",
  str_homestory_815701001_29_dialog_content = "そ、そうですよね…！<sprite=emo_sikao size=60 />",
  str_homestory_815701001_30_dialog_content = "やはり、私のようなよそ者に、\n簡単にお話しいただけることでは\nありませんよね…",
  str_homestory_815701001_31_dialog_content = "ここに花畑がある理由なら…",
  str_homestory_815701001_32_dialog_content = "そういう景観設計っていうだけの話だよ。",
  str_homestory_815701001_33_dialog_content = "景観設計ですか？難しそうな言葉ですね…",
  str_homestory_815701001_34_dialog_content = "バイスが建築とか設計図に詳しいから、\n天空ノ庭を設計する時、\nいろいろ案を出してくれたんだ。",
  str_homestory_815701001_35_dialog_content = "あとは植物に詳しい、\nガブリエルとナシリス、それからジョラが…",
  str_homestory_815701001_36_dialog_content = "どんな植物を植えたらきれいになるか、\nいろいろ教えてくれたんだ。",
  str_homestory_815701001_37_dialog_content = "そうやってみんなの知恵が集まって、\n今、君が天空ノ庭で見ている風景ができたんだよ。",
  str_homestory_815701001_38_dialog_content = "みなさんの知恵ですか…",
  str_homestory_815701001_39_dialog_content = "そうだよ！\nサナエも自分を「よそ者」だなんて思わないでね。",
  str_homestory_815701001_40_dialog_content = "ここに来た時から、\n君も仲間なんだから！",
  str_homestory_815701001_41_dialog_content = "ぐすっ…ううぅ…",
  str_homestory_815701001_42_dialog_content = "えっ！？なんで泣きだしたの？\n責めたつもりは…",
  str_homestory_815701001_43_dialog_content = "ナビゲーター様は、\n本当にお優しい方です…",
  str_homestory_815701001_44_dialog_content = "私も…自分に出来ることをして\n貢献しなければいけません！",
  str_homestory_815701001_45_dialog_content = "そ、そうだ！今後はこの「愛の花畑<sprite=emo_aixin size=60 />」、\n私が真心こめてお世話しますので！",
  str_homestory_815601001_0_dialog_content = "…見間違いじゃないよね？",
  str_homestory_815601001_1_dialog_content = "今、木馬で遊んでた？",
  str_homestory_815601001_2_dialog_content = "…何のことかしら？",
  str_homestory_815601001_3_dialog_content = "そういうのが好きなタイプじゃ\nないと思ってたけど…",
  str_homestory_815601001_4_dialog_content = "す、好きだなんて言ったことも、なくってよ…",
  str_homestory_815601001_5_dialog_content = "私は歩き疲れたから、\nただ足を休めていただけのこと。",
  str_homestory_815601001_6_dialog_content = "このような物に、\n私が興味を持つはずなくってよ。",
  str_homestory_815601001_7_dialog_content = "そ、そうだね…",
  str_homestory_815601001_8_dialog_content = "それよりも、「私が歩き疲れたというのに、\n一休みする所がない」ことこそ、\n大問題ではなくて？",
  str_homestory_815601001_9_option_content = "（謝る）",
  str_homestory_815601001_10_dialog_content = "ごめん！",
  str_homestory_815601001_11_dialog_content = "石のベンチでもいくつか置いた方がいいかな？",
  str_homestory_815601001_12_dialog_content = "石の？冗談がお上手ね？",
  str_homestory_815601001_13_dialog_content = "そんな硬い物、誰が座るというの？",
  str_homestory_815601001_14_dialog_content = "必要とあらば…",
  str_homestory_815601001_15_dialog_content = "この私が見た目にも美しく、座り心地のよいイスを\nデザインしてあげてもよろしくてよ。",
  str_homestory_815601001_16_dialog_content = "代わりにあの木のオモチャの一体何が面白いのか、\n教えてくださる？",
  str_homestory_815601001_17_option_content = "（感想を聞く）",
  str_homestory_815601001_18_dialog_content = "ニナは今日、いろんな所を見てるよね。",
  str_homestory_815601001_19_dialog_content = "お嬢様の君にも、ここは気に入ってもらえた？",
  str_homestory_815601001_20_dialog_content = "自分から聞いた以上、\n私が厳しい評価を下しても、\n文句はないということね？",
  str_homestory_815601001_21_dialog_content = "…ここ、あまりにも不便すぎるわ！",
  str_homestory_815601001_22_dialog_content = "そこはまったく反論のしようがないね…",
  str_homestory_815601001_23_dialog_content = "ただ、風景は確かに素晴らしいわ。\n私のバカンス先のリストに\n入れてあげてもよくってよ。",
  str_homestory_815601001_24_dialog_content = "私の評価が影ノ街の新聞に載れば、\n多くの人の注目を浴びるでしょうね。",
  str_homestory_815601001_25_dialog_content = "ただし…あの木のオモチャの\n一体何が面白いのか、教えてくださる？",
  str_homestory_815601001_26_dialog_content = "興味ないんじゃなかったの？",
  str_homestory_815601001_27_dialog_content = "…気が変わったの。",
  str_homestory_815601001_28_dialog_content = "大衆の娯楽を理解することも、\n私の課題のうちだもの。",
  str_homestory_815601001_29_dialog_content = "あと、あのオモチャ、不安定だわ。\n乗ったとたんにぐらつくもの。",
  str_homestory_815601001_30_dialog_content = "木馬、乗ったことがないの？",
  str_homestory_815601001_31_dialog_content = "乗ったことぐらい、あるに決まっているでしょう？",
  str_homestory_815601001_32_dialog_content = "でも…木馬って、その揺れる感覚を楽しむものだよ。",
  str_homestory_815601001_33_dialog_content = "…そ、そう…ああ、誤解してもらっては困るわ。\nそれぐらいのことなら、\nとうの昔に知っていたもの！",
  str_homestory_815601001_34_dialog_content = "さっきは…ただ、安全性を検証していただけよ。",
  str_homestory_815601001_35_option_content = "（信じる）",
  str_homestory_815601001_36_dialog_content = "だったら、検証には合格したってことだね…",
  str_homestory_815601001_37_dialog_content = "ふん…あなた、見かけよりは賢いようね。\nおほほほ！",
  str_homestory_815601001_38_option_content = "（信じない）",
  str_homestory_815601001_39_dialog_content = "そんなことがあるワケ…",
  str_homestory_815601001_40_dialog_content = "バカ！空の末裔のバカ！ふんっ…",
  str_homestory_815601001_41_dialog_content = "…",
  str_homestory_815601001_42_dialog_content = "でも…",
  str_homestory_815601001_43_dialog_content = "どうして本物の馬に乗らないのかしら。\nわざわざ木馬なんて作って、どうするの？",
  str_homestory_815601001_44_dialog_content = "僕もそこまでは…",
  str_homestory_815601001_45_dialog_content = "でも、木馬には木馬の面白さがあるし、\n本物の馬に乗るよりは安全でしょ。",
  str_homestory_815601001_46_dialog_content = "それに、皆が皆、本物の馬に乗れるわけじゃないだろうから。",
  str_homestory_815601001_47_dialog_content = "つまり…馬を買うお金がないということかしら？<sprite=emo_wuzui size=60 />",
  str_homestory_815601001_48_dialog_content = "木馬を買うことさえできない人も\n世の中にはいるんだよ…",
  str_homestory_815601001_49_dialog_content = "…",
  str_homestory_815601001_50_dialog_content = "…決めたわ！",
  str_homestory_815601001_51_dialog_content = "何を？",
  str_homestory_815601001_52_dialog_content = "木工を覚えて、\nもっと楽しく遊べる木馬を作るわ…",
  str_homestory_815601001_53_dialog_content = "そして、子どもたちに広めるのよ！",
  str_homestory_810401001_0_dialog_content = "ドーン？",
  str_homestory_810401001_1_dialog_content = "この足音は…",
  str_homestory_810401001_2_dialog_content = "PlayerNameね？",
  str_homestory_810401001_3_dialog_content = "えっ、僕の足音が分かるの？",
  str_homestory_810401001_4_dialog_content = "もちろんよ。<sprite=emo_yaosu size=60 />",
  str_homestory_810401001_5_dialog_content = "ここは巨像の中より、\nいろいろな音であふれてるけど…",
  str_homestory_810401001_6_dialog_content = "よく知っている人の出す音なら、\nいつだってちゃんと聞き分けられるわ。",
  str_homestory_810401001_7_dialog_content = "あなたやイブの足音は、\n少し他とは違うもの。",
  str_homestory_810401001_8_dialog_content = "足音に違いなんてあるの…？",
  str_homestory_810401001_9_option_content = "（自分の足音について聞く）",
  str_homestory_810401001_10_dialog_content = "あなたの足音は少しせわしないわね。\nでも、私に近づくとゆっくりになるの。",
  str_homestory_810401001_11_dialog_content = "そう言っても、よく分からないでしょうね…",
  str_homestory_810401001_12_dialog_content = "とにかく、私は足音で、\nナビゲーターが来たって分かるのよ。",
  str_homestory_810401001_13_dialog_content = "ああ、それから、もう1つ…",
  str_homestory_810401001_14_dialog_content = "あなたが近づいてくると、\n楽しい気分になるわ。",
  str_homestory_810401001_15_dialog_content = "つまり、楽しい気分になったら、\nPlayerNameが来たってことよ。",
  str_homestory_810401001_16_option_content = "（イブの足音について聞く）",
  str_homestory_810401001_17_dialog_content = "イブの足音はかわいらしいのよ！",
  str_homestory_810401001_18_dialog_content = "…「かわいらしい」って言葉、\n足音の説明に使えるのかな？",
  str_homestory_810401001_19_dialog_content = "当然よ、イブは何もかもがかわいいわ！<sprite=emo_aixin size=60 />",
  str_homestory_810401001_20_dialog_content = "ううん…",
  str_homestory_810401001_21_dialog_content = "…分かったわよ。もう少し詳しく説明すると、\nイブは身体が特殊なせいか…",
  str_homestory_810401001_22_dialog_content = "歩く時、ほどんど足音がしないの。",
  str_homestory_810401001_23_dialog_content = "でも、イブが近づいてくると、\n楽しい気持ちになるわ。",
  str_homestory_810401001_24_dialog_content = "つまり、楽しい気分になったら、\nイブが来たってこと。",
  str_homestory_810401001_25_dialog_content = "なるほどね…？",
  str_homestory_810401001_26_dialog_content = "ドーンはすごいなぁ…",
  str_homestory_810401001_27_dialog_content = "目が見えない分、耳が鋭くなるのよ。",
  str_homestory_810401001_28_dialog_content = "あ、そうだ…",
  str_homestory_810401001_29_dialog_content = "サメヤマはどう？",
  str_homestory_810401001_30_dialog_content = "よく知ってる人に入るよね？\nサメヤマの足音も、特徴があるの？",
  str_homestory_810401001_31_dialog_content = "足音なんか聞かなくても、\nもっと簡単な方法で判断できるわ。",
  str_homestory_810401001_32_dialog_content = "どんな方法？",
  str_homestory_810401001_33_dialog_content = "クサいの。",
  str_homestory_810401001_34_dialog_content = "…？",
  str_homestory_810401001_35_dialog_content = "よく動くからか知らないけど…\n汗っかきみたいね。",
  str_homestory_810401001_36_dialog_content = "そ、そうなんだ…",
  str_homestory_810401001_37_dialog_content = "R・Wの中では、まだマシな方だけど…",
  str_homestory_810401001_38_dialog_content = "あなたやイブに比べたら、\n確実にクサいわ。",
  str_homestory_810401001_39_dialog_content = "あなたがクサくなくてよかったわ、ナビゲーター。",
  str_homestory_810401001_40_dialog_content = "えっ、ああ、ありがとう…？",
  str_homestory_810401001_41_dialog_content = "ううん、僕は…サメヤマがそんなに臭うなんて、\n感じたこともなかったなぁ。",
  str_homestory_810401001_42_dialog_content = "そう？",
  str_homestory_810401001_43_dialog_content = "まさか…私ったら、イブを独り占めされるのが\n気に入らなくて…<sprite=emo_sikao size=60 />",
  str_homestory_810401001_44_dialog_content = "余計にクサいって感じてるだけなのかしら？",
  str_homestory_810401001_45_dialog_content = "…あ、それ、なんかありそう…",
  str_homestory_810401001_46_dialog_content = "…知ったことじゃないわ！\nきっとサメヤマが本当にクサいだけよ！",
  str_homestory_810401001_47_dialog_content = "ああ、クサいクサい！\nサメヤマはクサいったらありゃしない<sprite=emo_kulou size=60 />！",
  str_homestory_809001001_0_dialog_content = "バーバラ？",
  str_homestory_809001001_1_dialog_content = "愛はいつだって人を惑わすの～♪",
  str_homestory_809001001_2_dialog_content = "<sprite=emo_aixin size=60 />レディーゼルオイルみたいに、\n心を燃やして～♪",
  str_homestory_809001001_3_dialog_content = "ルルル～…私が欲しいのは、ホントのキモチだけ～♪",
  str_homestory_809001001_4_dialog_content = "バーバラ、新曲の練習？",
  str_homestory_809001001_5_dialog_content = "新曲？えへへ、違うよ～？",
  str_homestory_809001001_6_dialog_content = "新しいアルバムを出すの！",
  str_homestory_809001001_7_option_content = "アルバム？",
  str_homestory_809001001_8_dialog_content = "アルバムって、何曲も入ってるんだよね？",
  str_homestory_809001001_9_dialog_content = "そうだよ～。",
  str_homestory_809001001_10_option_content = "レジーナを越えるような？",
  str_homestory_809001001_11_dialog_content = "ふっふ～ん、トーゼンでしょ！",
  str_homestory_809001001_12_dialog_content = "売上げとサイン会の盛り上がりのためにも、\nしっかりがんばらなくちゃ！",
  str_homestory_809001001_13_dialog_content = "大変そうだね。",
  str_homestory_809001001_14_dialog_content = "努力するのは当たり前、だよ！\nそれに、最近はいろいろ新しい音楽も出てきてるから…",
  str_homestory_809001001_15_dialog_content = "負けるわけにはいかないもんね！",
  str_homestory_809001001_16_dialog_content = "自分の地位が揺らぐんじゃないかって心配してるの？",
  str_homestory_809001001_17_dialog_content = "地位が揺らぐ…？もう、そんなこと心配してないよ！",
  str_homestory_809001001_18_dialog_content = "バーバラも、いろんなタイプの音楽やアーティストを\n知りたいんだよ～。",
  str_homestory_809001001_19_dialog_content = "じゃあ「負けるわけにはいかない」っていうのは…？",
  str_homestory_809001001_20_dialog_content = "バーバラも、もっとがんばろうってこと！<sprite=emo_yinfu size=60 />",
  str_homestory_809001001_21_dialog_content = "新人さんたちと一緒に成長して、\n一緒にもっといい作品を作るの！",
  str_homestory_809001001_22_dialog_content = "取り残されるのは大っキライ！",
  str_homestory_809001001_23_dialog_content = "うーん、僕もがんばらないといけない気がしてきた…",
  str_homestory_809001001_24_dialog_content = "でしょ？私は人気とか、\nあんまり気にしないけど～…",
  str_homestory_809001001_25_dialog_content = "もし長年応援してくれてたファンが\n別のアーティストに乗り換えちゃったりしたら…",
  str_homestory_809001001_26_dialog_content = "やっぱり悲しくなっちゃうもんね！",
  str_homestory_809001001_27_dialog_content = "レジーナとかに？",
  str_homestory_809001001_28_dialog_content = "PlayerName…はっきり言うね～！",
  str_homestory_809001001_29_dialog_content = "やっぱり、心の中ではレジーナのこと、気にしてるんだね？",
  str_homestory_809001001_30_dialog_content = "なんて言ったらいいのかな？",
  str_homestory_809001001_31_dialog_content = "「まったく気にしてない」って言ったら、\nウソになるよね<sprite=emo_tanqi size=60 />…",
  str_homestory_809001001_32_dialog_content = "あ、そっか！",
  str_homestory_809001001_33_dialog_content = "私はね、「音楽の多様性を広げる」ために、\nレジーナの音楽を聴いてるの。",
  str_homestory_809001001_34_dialog_content = "ほら、ファンの数で言ったら\nバーバラの方が勝ってるけど、\nレジーナのファンって…すごく熱心でしょ？",
  str_homestory_809001001_35_dialog_content = "音楽の質で勝負するのがいちばん大事ではあるけど、\nやっぱり気になるでしょ…",
  str_homestory_809001001_36_dialog_content = "レジーナはどうやって、\nファンの心をつかんでるんだろ～？",
  str_homestory_809001001_37_dialog_content = "一人で考えるより、\n直接レジーナに聞いてみたら？",
  str_homestory_809001001_38_dialog_content = "うう～ん…",
  str_homestory_809001001_39_dialog_content = "PlayerNameが言うなら、\n考えてみてもいいかな…",
  str_homestory_809001001_40_dialog_content = "直接聞いてみるぐらいなら、\n大したことないよね！",
  str_homestory_809001001_41_dialog_content = "まぁ…20年ぐらいしたら聞いてみようかな～<sprite=emo_emo size=60 />",
  str_homestory_809001001_42_dialog_content = "…それじゃ聞かないのと同じでしょ！？",
  str_homestory_807001001_0_dialog_content = "リオナ…",
  str_homestory_807001001_1_dialog_content = "あら、坊や。",
  str_homestory_807001001_2_dialog_content = "何か用？",
  str_homestory_807001001_3_dialog_content = "悪いけど、今は時間がないの。",
  str_homestory_807001001_4_dialog_content = "見ての通り、私は今、\nストレス解消で忙しいから――",
  str_homestory_807001001_5_dialog_content = "サンドバッグを叩くとストレス解消になるの？",
  str_homestory_807001001_6_dialog_content = "当然でしょ<sprite=emo_baiyan size=60 />。",
  str_homestory_807001001_7_dialog_content = "聞いたことないかしら？",
  str_homestory_807001001_8_dialog_content = "運動には、ストレス解消効果があるって。",
  str_homestory_807001001_9_dialog_content = "聞いたことあるよ。",
  str_homestory_807001001_10_dialog_content = "でも、リオナが抱えてるストレスって…",
  str_homestory_807001001_11_option_content = "何が原因？",
  str_homestory_807001001_12_dialog_content = "特に原因なんてないわよ。",
  str_homestory_807001001_13_option_content = "それで解消はされた？",
  str_homestory_807001001_14_dialog_content = "そうね。",
  str_homestory_807001001_15_dialog_content = "ストレスは身体に溜まった「よどみ」みたいなものよ。",
  str_homestory_807001001_16_dialog_content = "「よどみ」…？\n川のどこかが詰まって、濁ってるみたいな…？",
  str_homestory_807001001_17_dialog_content = "そんなところね。",
  str_homestory_807001001_18_dialog_content = "ストレスを感じた時には…",
  str_homestory_807001001_19_dialog_content = "何か自分に合った方法で、\n身体から取り除かないといけないわ。",
  str_homestory_807001001_20_dialog_content = "自分にとって気晴らしになるものなら、\nどんな方法でもいいの。",
  str_homestory_807001001_21_dialog_content = "私には、こういう戦いに近い方法が、\nいちばん性に合ってるわ。",
  str_homestory_807001001_22_dialog_content = "ストレスをずっと身体の中に溜めておくと、\n「よどみ」がますますヒドくなっていくのよ。",
  str_homestory_807001001_23_dialog_content = "最悪、命に関わることもあるわ。",
  str_homestory_807001001_24_dialog_content = "私も長い時間をかけて、\nようやく学んだことだけど。",
  str_homestory_807001001_25_dialog_content = "恨みに心と血脈を惑わされて…",
  str_homestory_807001001_26_dialog_content = "…話がそれたわね。",
  str_homestory_807001001_27_dialog_content = "いや…リオナのいうこと、一理あるね。",
  str_homestory_807001001_28_dialog_content = "今度、あなたも試してみるといいわ。",
  str_homestory_807001001_29_dialog_content = "そうするよ！",
  str_homestory_807001001_30_dialog_content = "この間、キシローナさんがここで練習してたのも、\n同じ理由かもしれないね？",
  str_homestory_807001001_31_dialog_content = "…なんですって？",
  str_homestory_807001001_32_dialog_content = "このサンドバッグ、\nアイツも使ったの？",
  str_homestory_807001001_33_dialog_content = "あっ？えっと、ど、どうだったかな…？",
  str_homestory_807001001_34_dialog_content = "（この雰囲気はまずい…）",
  str_homestory_807001001_35_dialog_content = "…",
  str_homestory_807001001_36_dialog_content = "リオナ、どうしたの？\n急に静かになって…",
  str_homestory_807001001_37_dialog_content = "アハハハ！私ったら、\n「いとしい」妹と同じことをしてたみたいね。",
  str_homestory_807001001_38_dialog_content = "ここを焼き払って<sprite=emo_nuhuo size=60 />しまわないうちに…",
  str_homestory_807001001_39_dialog_content = "影ノ街に戻るわ。",
  str_homestory_807001001_40_dialog_content = "またね、坊や。",
  str_homestory_807001001_41_dialog_content = "あ、ええと…",
  str_homestory_807001001_42_dialog_content = "またいつでも来てね…",
  str_homestory_811501001_0_dialog_content = "ナルセール！",
  str_homestory_811501001_1_dialog_content = "おや、PlayerNameさん。",
  str_homestory_811501001_2_dialog_content = "大自然の力が私とあなたを再会に\n導いてくれたようですね。",
  str_homestory_811501001_3_dialog_content = "シングとポインターとおしゃべり？",
  str_homestory_811501001_4_dialog_content = "ええ。",
  str_homestory_811501001_5_dialog_content = "この子たちの名前を覚えてくださっていたとは…",
  str_homestory_811501001_6_dialog_content = "2人とも喜んでいますよ。",
  str_homestory_811501001_7_dialog_content = "もちろん覚えてるよ。",
  str_homestory_811501001_8_dialog_content = "再びよみがえった天空ノ谷を眺めていると、\nとても感慨深い気持ちになります…<sprite=emo_pugongying size=60 />",
  str_homestory_811501001_9_dialog_content = "今のこの天空ノ庭があるのも…",
  str_homestory_811501001_10_dialog_content = "大自然の恵みと、PlayerNameさんの大変な努力のたまものなのでしょう。",
  str_homestory_811501001_11_dialog_content = "ただ…少し心配しています。",
  str_homestory_811501001_12_dialog_content = "短い間に色々とあったようですね。\n心の方は大丈夫ですか？",
  str_homestory_811501001_13_option_content = "（うなずく）",
  str_homestory_811501001_14_dialog_content = "ここで皆と一緒に暮らせて、とても嬉しいんだ。",
  str_homestory_811501001_15_dialog_content = "ただ時どき、期待されてることが、\n少し重いって感じる時もあるかな。",
  str_homestory_811501001_16_option_content = "（首を振る）",
  str_homestory_811501001_17_dialog_content = "ずっと気分が晴れないってワケじゃないけど…",
  str_homestory_811501001_18_dialog_content = "いつも、妙にあせりとプレッシャーを感じちゃうんだ。",
  str_homestory_811501001_19_dialog_content = "そうですか…",
  str_homestory_811501001_20_dialog_content = "今から私と一緒に、\nちょっとしたリラックス法を試してみませんか？",
  str_homestory_811501001_21_dialog_content = "面白そうだね。",
  str_homestory_811501001_22_dialog_content = "では、「呼吸」の練習をいたしましょう。",
  str_homestory_811501001_23_dialog_content = "「呼吸」の練習？",
  str_homestory_811501001_24_dialog_content = "そうです。",
  str_homestory_811501001_25_dialog_content = "この呼吸を行うことで、いつでも体の中のエネルギーの\nバランスを整えることができます。",
  str_homestory_811501001_26_dialog_content = "言い換えれば…",
  str_homestory_811501001_27_dialog_content = "私たちの体内にある力が、再び体中に流れ出すのです。",
  str_homestory_811501001_28_dialog_content = "分かったよ。じゃあ、始めようか？",
  str_homestory_811501001_29_dialog_content = "では…",
  str_homestory_811501001_30_dialog_content = "まずは肩の力を抜き、深呼吸してください。",
  str_homestory_811501001_31_dialog_content = "そうです、いいですよ。\n次に鼻をつまんでください。",
  str_homestory_811501001_32_dialog_content = "（鼻をつまむ…）",
  str_homestory_811501001_33_dialog_content = "最初は右側を強く抑え、\n左側で息を吸ってみてください。",
  str_homestory_811501001_34_dialog_content = "その後すぐに、左側を強く抑えて、\n右側で息を吐き出します――",
  str_homestory_811501001_35_dialog_content = "（吸って、吐いて…）",
  str_homestory_811501001_36_dialog_content = "こうしてゆっくりと呼吸を整えます。",
  str_homestory_811501001_37_dialog_content = "一定間隔で、吸うと吐くを繰り返していきます…",
  str_homestory_811501001_38_dialog_content = "そうすると、心も体もすっきりしますよ。",
  str_homestory_811501001_39_dialog_content = "確かに、気持ちが落ち着いた気がする…",
  str_homestory_811501001_40_dialog_content = "少し眠くなってくるぐらい<sprite=emo_kun size=60 />…",
  str_homestory_811501001_41_dialog_content = "ふふ…",
  str_homestory_811501001_42_dialog_content = "この呼吸法には気持ちを静めるだけでなく、\n睡眠をうながす効果もあるのです。",
  str_homestory_811501001_43_dialog_content = "お休みになる前に、\nもう一度お試しになってみるのもいいでしょう。",
  str_homestory_811501001_44_dialog_content = "目を閉じて呼吸を整えれば、\nより効果が出るかもしれません。",
  str_homestory_811501001_45_dialog_content = "うん、わかった。",
  str_homestory_811501001_46_dialog_content = "ありがとう、ナルセール！",
  str_homestory_803302001_0_dialog_content = "どうしたの、バイス。",
  str_homestory_803302001_1_dialog_content = "PlayerName！今、時間ある？",
  str_homestory_803302001_2_dialog_content = "もちろんだよ、どうしたの？",
  str_homestory_803302001_3_dialog_content = "水辺を散歩してたら、\n水の中に何かある気がしたの。",
  str_homestory_803302001_4_dialog_content = "しばらくがんばってみたけど、結局拾えなかったわ。\nたぶん…図面だと思うのよね。",
  str_homestory_803302001_5_dialog_content = "興味があれば、見に行ってみるといいわ！",
  str_homestory_803302001_6_dialog_content = "うん、分かった。",
  str_homestory_803303001_0_dialog_content = "何してるの？",
  str_homestory_803303001_1_dialog_content = "考えてるのよ…どうすれば、アレを釣れるのか…",
  str_homestory_803303001_2_dialog_content = "アレっていうのは？",
  str_homestory_803303001_3_dialog_content = "川の中におかしなものがあったから、\nすごく気になって<sprite=emo_sikao size=60 />。",
  str_homestory_803303001_4_dialog_content = "でも、手が筋肉痛になるまでねばっても、\n釣りあげられなかったのよ。",
  str_homestory_803303001_5_dialog_content = "代わりに試してみてくれない？場所はあそこよ！",
  str_homestory_803303001_6_dialog_content = "うん…やってみるよ。",
  str_homestory_803304001_0_dialog_content = "なにか用？",
  str_homestory_803304001_1_dialog_content = "えっ、どうして分かるの？",
  str_homestory_803304001_2_dialog_content = "まぁいいわ、面白いものを見つけたの！<sprite=emo_yaosu size=60 />",
  str_homestory_803304001_3_dialog_content = "また巨大なクモとかダンスするバッタとかじゃないよね…",
  str_homestory_803304001_4_dialog_content = "違うわ！新しい家具の図面よ！",
  str_homestory_803304001_5_dialog_content = "だけど、水の底に沈んでて、\n取るのが難しそうなのよ。",
  str_homestory_803304001_6_dialog_content = "そういうものなら、僕に任せて。\n慣れてるから。",
  str_homestory_803304001_7_dialog_content = "あそこよ！ほら、あそこ！",
  str_homestory_809301001_0_dialog_content = "その目つきは…",
  str_homestory_809301001_1_dialog_content = "な、なにか用？",
  str_homestory_809301001_2_dialog_content = "何も言ってないのに、用があるって分かるなんて、\nしばらく見ないうちに成長したわね。",
  str_homestory_809301001_3_dialog_content = "さっき背中に寒気が走ったんだよ。\n誰かにずっと見られてる気がして…",
  str_homestory_809301001_4_dialog_content = "それで顔を上げたら、\n君がこっちをじっと見てたってわけ。",
  str_homestory_809301001_5_dialog_content = "「顔を上げたら？」\nやっぱり、身長は伸びてないのね。",
  str_homestory_809301001_6_option_content = "ちょっとは伸びたよ！",
  str_homestory_809301001_7_dialog_content = "そう？私にはそう見えないわね。\n実験室で調べてみる？",
  str_homestory_809301001_8_dialog_content = "あなたの骨が伸びているかどうか、\n解剖して調べてあげるわ。",
  str_homestory_809301001_9_option_content = "うん…",
  str_homestory_809301001_10_dialog_content = "あっさり認められると胸が痛むわね。\n実験室で調べてみる？",
  str_homestory_809301001_11_dialog_content = "成長ホルモンがきちんと分泌されてるか、\n調べてあげるわよ。",
  str_homestory_809301001_12_dialog_content = "そこまでする必要はないんじゃないかな…",
  str_homestory_809301001_13_dialog_content = "安心して。解剖させてくれれば、\nボーヤ専用の身長増加プランを立ててあげるわ。",
  str_homestory_809301001_14_dialog_content = "今は自然に任せることにするよ…",
  str_homestory_809301001_15_dialog_content = "自然に任せる？そんなの良くないわね。",
  str_homestory_809301001_16_dialog_content = "天空ノ庭だって、\n遺伝子改良された木がたくさんあるじゃない。",
  str_homestory_809301001_17_dialog_content = "しかも、あの技術って…",
  str_homestory_809301001_18_dialog_content = "違う種類の種子を混合して、\n別の品種を合成するものでしょう？",
  str_homestory_809301001_19_dialog_content = "えっ、木を見ただけで分かるの？",
  str_homestory_809301001_20_dialog_content = "あら、忘れたの？\n私は啓光最高科学責任者、専門は生物工学よ。",
  str_homestory_809301001_21_dialog_content = "その手の実験なら、\nもう数え切れないくらいやってるわ。",
  str_homestory_809301001_22_dialog_content = "でも、あなたにそっちの才能があったとは、意外ね。",
  str_homestory_809301001_23_dialog_content = "そんな立派なものじゃないよ。\n見よう見まねでやってるだけだし。",
  str_homestory_809301001_24_dialog_content = "ええ、それも分かってるわ。",
  str_homestory_809301001_25_dialog_content = "…",
  str_homestory_809301001_26_dialog_content = "でも、99回の失敗がなければ、\n1回の成功も得られないもの。",
  str_homestory_809301001_27_dialog_content = "それが私が仕事の中で学んだことよ。\nで、見た限り…",
  str_homestory_809301001_28_dialog_content = "珍しい品種を創り出したいなら、\nまだまだ、あれこれ試行錯誤が必要そうね。",
  str_homestory_809301001_29_dialog_content = "「あれこれ試行錯誤」？どういう意味…？",
  str_homestory_809301001_30_dialog_content = "科学研究の経験がないと、分かりづらいでしょうね。\nまた今度、教えてあげるわ。",
  str_homestory_809301001_31_dialog_content = "今からでも大丈夫だよ。",
  str_homestory_809301001_32_dialog_content = "今から？それより、まずはひと眠りしたいもの。",
  str_homestory_809301001_33_dialog_content = "…",
  str_homestory_809301001_34_dialog_content = "あ、ちょっと待って。\n一番大事なことを忘れるところだったわ。",
  str_homestory_809301001_35_dialog_content = "私の部屋、かわいい女の子が多い\n家にしてくれない？",
  str_homestory_809301001_36_option_content = "（同意する）",
  str_homestory_809301001_37_dialog_content = "いいけど…自分で他の皆とちゃんと相談してね。",
  str_homestory_809301001_38_option_content = "（断る）",
  str_homestory_809301001_39_dialog_content = "どこに住むかは、それぞれの自由だから、\n僕は干渉できないよ。",
  str_homestory_809301001_40_dialog_content = "でも、他の皆と相談したうえでなら、\n別に構わないよ。",
  str_homestory_809301001_41_dialog_content = "何だか面倒くさそうね。",
  str_homestory_809301001_42_dialog_content = "でも、試してみる価値はあるわね。\nダメでも、100回挑戦すればいいもの。",
  str_homestory_809301001_43_dialog_content = "（こんなことで研究者らしさを出さなくてもいいのに…）",
  str_homestory_815702001_0_dialog_content = "何を見てるの？",
  str_homestory_815702001_1_dialog_content = "ああああ……",
  str_homestory_815702001_2_dialog_content = "あ、ごめん。また驚かせちゃった？",
  str_homestory_815702001_3_dialog_content = "（…「また」だっけ？）",
  str_homestory_815702001_4_dialog_content = "いえいえ、そんなことはありません…\n考え事をしていた私がいけないんです…",
  str_homestory_815702001_5_dialog_content = "ナビゲーター様が側にいるのに、\nまったく気が付かないなんて…",
  str_homestory_815702001_6_dialog_content = "謝るのは、私の方です…",
  str_homestory_815702001_7_dialog_content = "何もなければ、それでいいよ。\n考えすぎないで。",
  str_homestory_815702001_8_dialog_content = "川の方から来たよね？\n君の考え事って…",
  str_homestory_815702001_9_option_content = "魚釣り？",
  str_homestory_815702001_10_dialog_content = "魚釣りには…高価な釣り道具が必要でしょう？",
  str_homestory_815702001_11_dialog_content = "そ、そんな分不相応なこと、\n考えていません…",
  str_homestory_815702001_12_option_content = "水泳？",
  str_homestory_815702001_13_dialog_content = "川で泳ぐには水着が必要ですが…\n体の線がはっきり出てしまいますから…",
  str_homestory_815702001_14_dialog_content = "は、恥ずかしくて、\nあんなもの着られません…",
  str_homestory_815702001_15_dialog_content = "私が考えていたのは…",
  str_homestory_815702001_16_dialog_content = "昔、天空ノ谷で畑仕事をしていた方たちは、\n雲島の農民と同じく苦労されていたのかな、と…",
  str_homestory_815702001_17_dialog_content = "それは、僕にもよく分からないなぁ。\nでも、天空ノ谷であろうと、雲島であろうと…",
  str_homestory_815702001_18_dialog_content = "豊作の年は、きっと皆同じように喜んだだろうね。",
  str_homestory_815702001_19_dialog_content = "でも、どうして急にそんなことを？",
  str_homestory_815702001_20_dialog_content = "ええと…川辺でキラキラ光る、\nコインのようなもの<sprite=emo_baiyebi size=60 />を拾ったんです。",
  str_homestory_815702001_21_dialog_content = "コインがあれば、交易があります。\n交易があるなら、穀物もあります。\n穀物のある所には…それを作る人がいます！",
  str_homestory_815702001_22_dialog_content = "そんな風に話が広がるんだ…？",
  str_homestory_815702001_23_dialog_content = "ど、どうか怒らないでください！",
  str_homestory_815702001_24_dialog_content = "わわわわわわ、私、\nコインを独り占めする気なんてありません！",
  str_homestory_815702001_25_dialog_content = "今すぐ、お渡ししますので…",
  str_homestory_815702001_26_dialog_content = "そんなにあわてなくても…",
  str_homestory_815702001_27_dialog_content = "…ええと、どこにしまったでしょう？",
  str_homestory_815702001_28_dialog_content = "あれ、見つかりません…",
  str_homestory_815702001_29_dialog_content = "あっ！",
  str_homestory_815702001_30_dialog_content = "どうしたの？",
  str_homestory_815702001_31_dialog_content = "そう言えば、川から戻って来る時に、\nチャリンと音がしてました…",
  str_homestory_815702001_32_dialog_content = "きっとあの時、うっかりコインを\n落としてしまったに違いないです！",
  str_homestory_815702001_33_dialog_content = "大丈夫だよ、僕が探してくるから。",
  str_homestory_815702001_34_dialog_content = "あああああ…よ、よろしいんですか？\nそれでは、お願いします！",
  str_homestory_815602001_0_dialog_content = "何を探してるの？",
  str_homestory_815602001_1_dialog_content = "早く、こっちに来なさい！",
  str_homestory_815602001_2_dialog_content = "ニナ？",
  str_homestory_815602001_3_dialog_content = "見間違いじゃなければ、何かを探してた？",
  str_homestory_815602001_4_dialog_content = "そうよ。",
  str_homestory_815602001_5_dialog_content = "丸いものを見なかったかしら？",
  str_homestory_815602001_6_dialog_content = "もう少し具体的に説明してもらえないかな？",
  str_homestory_815602001_7_dialog_content = "そうね…実は…",
  str_homestory_815602001_8_dialog_content = "見たこともない模様が描かれたものを見つけて…",
  str_homestory_815602001_9_dialog_content = "さっきまでこの手で確かに握っていたのよ。",
  str_homestory_815602001_10_dialog_content = "でも、うっかり手が緩んで、\n川の中に落としてしまって…",
  str_homestory_815602001_11_dialog_content = "待って、もしかして君の言ってるものって…",
  str_homestory_815602001_12_dialog_content = "まずは私の話を聞きなさい。",
  str_homestory_815602001_13_dialog_content = "その時、手のひらに\n不思議な模様が浮かび上がっていたの。",
  str_homestory_815602001_14_option_content = "何かに覚醒した！？",
  str_homestory_815602001_15_dialog_content = "何を言っているの？\n小説の読みすぎではないかしら。",
  str_homestory_815602001_16_option_content = "変身能力でもあったとか！？",
  str_homestory_815602001_17_dialog_content = "何を言っているのかしら？？？",
  str_homestory_815602001_18_dialog_content = "「それ」自体の形や模様が変化していたのよ。",
  str_homestory_815602001_19_dialog_content = "だから握りしめた時、手のひらに\n同じあとが残ったんでしょうね。",
  str_homestory_815602001_20_dialog_content = "手のひらに残った模様、\n神秘を感じるデザインなのよね…",
  str_homestory_815602001_21_dialog_content = "もし、服に活かせたら…",
  str_homestory_815602001_22_dialog_content = "…やっぱり、あのコインは\n何としても見つける必要があるわ！",
  str_homestory_815602001_23_dialog_content = "やっぱりコインだったんだ！",
  str_homestory_815602001_24_dialog_content = "探すの、手伝うよ。",
  str_homestory_815602001_25_dialog_content = "それなら…いえ、待ちなさい！<sprite=emo_wuzui size=60 />",
  str_homestory_815602001_26_dialog_content = "天空ノ庭で見つかったものなら…\nあなたの財産ってことになるわね？",
  str_homestory_815602001_27_dialog_content = "私がしばらく借りて、調べようとするなら…",
  str_homestory_815602001_28_dialog_content = "別に構わないよ。\nでも、まずはそのコインを見つけないとね。",
  str_homestory_815602001_29_dialog_content = "あら、ずいぶん優しいわね！",
  str_homestory_815602001_30_dialog_content = "…オホン！その…\n別にそこまで気になるわけじゃなくてよ！",
  str_homestory_815602001_31_dialog_content = "あくまで服のデザインのためだから！",
  str_homestory_815602001_32_dialog_content = "そこのところはお分かり？",
  str_homestory_815602001_33_dialog_content = "分かってるよ。",
  str_homestory_815602001_34_dialog_content = "フフン、それならいいわ。",
  str_homestory_812601001_0_dialog_content = "何か考え事？",
  str_homestory_812601001_1_dialog_content = "ベセル？",
  str_homestory_812601001_2_dialog_content = "怖い顔で、何か考え事してるみたいだけど…",
  str_homestory_812601001_3_dialog_content = "シーッ…<sprite=emo_chidai size=60 />",
  str_homestory_812601001_4_dialog_content = "総合商会の報告書がようやく片付いたので、\n考え事をしていたのです…",
  str_homestory_812601001_5_dialog_content = "何を考えてるの？",
  str_homestory_812601001_6_dialog_content = "新しいシナリオですよ！",
  str_homestory_812601001_7_dialog_content = "そうです、ここは思いきって\nあなたにお聞きしましょう。",
  str_homestory_812601001_8_dialog_content = "うん、いいよ。僕で役に立てるなら。",
  str_homestory_812601001_9_dialog_content = "オホン…では、聞いてください。\nストーリーの展開はですね…",
  str_homestory_812601001_10_dialog_content = "主人公の男女が川のほとりにやって来ます…",
  str_homestory_812601001_11_dialog_content = "そしてその時、ヒロインがハンカチを\nうっかり川の中に落としてしまうのです！",
  str_homestory_812601001_12_dialog_content = "そこでお聞きしますが、ハンカチを拾うべきなのは\nどちらだと思いますか？",
  str_homestory_812601001_13_option_content = "女の主人公",
  str_homestory_812601001_14_dialog_content = "なるほど…",
  str_homestory_812601001_15_dialog_content = "確かにその方が、「何事も自分でやろうとする」\nというヒロインの自立性を表現できますね。",
  str_homestory_812601001_16_option_content = "男の主人公",
  str_homestory_812601001_17_dialog_content = "なるほど…",
  str_homestory_812601001_18_dialog_content = "その方がストーリーの展開が速いですし、\nハンカチの話も広げられますね。",
  str_homestory_812601001_19_dialog_content = "分かりました！",
  str_homestory_812601001_20_dialog_content = "それで行きましょう。<sprite=emo_yaosu size=60 />",
  str_homestory_812601001_21_dialog_content = "ところで、どうしてそんな場面を作ろうと思ったの？",
  str_homestory_812601001_22_dialog_content = "先ほど、川の中にちょうど\n物が落ちるのを見て…",
  str_homestory_812601001_23_dialog_content = "そういうのも悪くないかと思いまして。",
  str_homestory_812601001_24_dialog_content = "えっ？何が落ちたの？",
  str_homestory_812601001_25_dialog_content = "私もはっきり見たわけではありませんが、\n小さくて丸いもののようでした。<sprite=emo_sikao size=60 />",
  str_homestory_812601001_26_dialog_content = "小さくて丸いもの…",
  str_homestory_812601001_27_dialog_content = "何か分かった気がするよ。",
  str_homestory_816401001_0_dialog_content = "カレン？",
  str_homestory_816401001_1_dialog_content = "PlayerName？",
  str_homestory_816401001_2_dialog_content = "何してるの？",
  str_homestory_816401001_3_dialog_content = "少し…考えごとをね。",
  str_homestory_816401001_4_dialog_content = "何だか元気がないみたいだけど…？",
  str_homestory_816401001_5_dialog_content = "そうね…",
  str_homestory_816401001_6_dialog_content = "最近、白夜城で自然災害が続いているの。",
  str_homestory_816401001_7_dialog_content = "ごめん。カレン…",
  str_homestory_816401001_8_dialog_content = "今はどんな様子なの？\n何か手伝えることはある？",
  str_homestory_816401001_9_dialog_content = "心配ありがとう、PlayerName。",
  str_homestory_816401001_10_dialog_content = "損害については、決められているとおりの\n災害対応と統計が進んでいるわ。",
  str_homestory_816401001_11_dialog_content = "でも、犠牲となった人たちを、\n家族のもとへ「帰す」時だけは…",
  str_homestory_816401001_12_dialog_content = "どうすれば残された人たちの心の傷を\nやわらげられるか、分からないの。",
  str_homestory_816401001_13_dialog_content = "気持ちは分かるよ。",
  str_homestory_816401001_14_dialog_content = "ふぅ…<sprite=emo_tanqi size=60 />",
  str_homestory_816401001_15_dialog_content = "口に出してみたら、\n少し、考えを整理できたような気がする。",
  str_homestory_816401001_16_dialog_content = "災害が起きないようにする方法？",
  str_homestory_816401001_17_dialog_content = "そうではないわ。",
  str_homestory_816401001_18_dialog_content = "私たちのような小さな存在が\nそれほど大きなことにあらがうのは無理な話よ。",
  str_homestory_816401001_19_dialog_content = "私にできるのは、ただ黙って祈ることだけ。\nそして、改めて確認するの…",
  str_homestory_816401001_20_option_content = "自分の信仰を？",
  str_homestory_816401001_21_dialog_content = "ええ…",
  str_homestory_816401001_22_option_content = "祈りの効果を？",
  str_homestory_816401001_23_dialog_content = "何と言えばいいのかしら…",
  str_homestory_816401001_24_dialog_content = "内なる心の安らぎが祈りによって\n得られるものかどうか、確認したいだけよ。",
  str_homestory_816401001_25_dialog_content = "なるほど…",
  str_homestory_816401001_26_dialog_content = "僕たちは自分たちではどうにもできないことに、\nどうしてもおそれを感じてしまう。",
  str_homestory_816401001_27_dialog_content = "だけど、そういうことに解決の方法なんて無くて、\nただ起こっていることを見守ることしかできない。",
  str_homestory_816401001_28_dialog_content = "だから、カレンは何となく、\n挫折を感じてるんだね？",
  str_homestory_816401001_29_dialog_content = "そうね…",
  str_homestory_816401001_30_dialog_content = "挫折を感じるたびに、\n心の中で静かに祈りを捧げて…",
  str_homestory_816401001_31_dialog_content = "考えるの。\n祈りが本当にもたらすものは、何なのか。",
  str_homestory_816401001_32_dialog_content = "結局のところ、\n祈りはある種の精神的な支えで…",
  str_homestory_816401001_33_dialog_content = "人が前に進むための力になるものだと思うの。",
  str_homestory_816401001_34_dialog_content = "確かに。",
  str_homestory_816401001_35_dialog_content = "カレンの暗い気分も晴らしてくれるかもしれないね。",
  str_homestory_816401001_36_dialog_content = "ええ…それで、気づいたことがあるの。",
  str_homestory_816401001_37_dialog_content = "人が万物に神が宿ると信じる理由が分かる？",
  str_homestory_816401001_38_dialog_content = "この世界には分からないことがたくさんあるのに、\n答えが少なすぎるから…",
  str_homestory_816401001_39_dialog_content = "つまるところ、祈りとは妥協なの。<sprite=emo_sikao size=60 />",
  str_homestory_816401001_40_dialog_content = "祈りは問題を解決しないし、\n答えも与えてくれない。",
  str_homestory_816401001_41_dialog_content = "けれど、ひとまず心の平静を手に入れられれば、\nその後はもとの生活に戻って行ける。",
  str_homestory_816401001_42_dialog_content = "うん…確かに、前に進むためには大事なことだね。",
  str_homestory_816401001_43_dialog_content = "今度は僕も試しにお祈りをしてみようかな。",
  str_homestory_816401001_44_dialog_content = "祈りとは何か、あなたと意見交換できることを\n楽しみにしているわ。",
  str_homestory_811101001_0_dialog_content = "ベリエ…",
  str_homestory_811101001_1_dialog_content = "…",
  str_homestory_811101001_2_dialog_content = "ベリエ！",
  str_homestory_811101001_3_dialog_content = "どうしたの？",
  str_homestory_811101001_4_dialog_content = "ずっと川を見つめてるけど、\n何かイヤなことでもあった？",
  str_homestory_811101001_5_dialog_content = "私の心配…？",
  str_homestory_811101001_6_option_content = "そうだよ",
  str_homestory_811101001_7_dialog_content = "私、川辺に立っているだけで、\nイヤなことを抱えているように見える…？<sprite=emo_wuzui size=60 />",
  str_homestory_811101001_8_dialog_content = "いや、その…そういうわけじゃないよ。",
  str_homestory_811101001_9_dialog_content = "僕も散歩に来ただけなんだ。\nほら、今日は天気がいいから。アハハ…",
  str_homestory_811101001_10_dialog_content = "…",
  str_homestory_811101001_11_option_content = "違うよ",
  str_homestory_811101001_12_dialog_content = "君がずっと川岸に立ってるから、\n何をしてるのかなと思って。",
  str_homestory_811101001_13_dialog_content = "僕が川に来る時は散歩か釣りのためがほとんどで、\nじっと立ってたりはしないから…",
  str_homestory_811101001_14_dialog_content = "だから…ベリエは何をしてるのかなと思って。",
  str_homestory_811101001_15_dialog_content = "晶石と天空ノ庭のことを考えていたの。",
  str_homestory_811101001_16_dialog_content = "晶石…",
  str_homestory_811101001_17_dialog_content = "ええ。バイスが言ってたわ…\n最近、あなたが天空ノ庭のことで頭を抱えているって…",
  str_homestory_811101001_18_dialog_content = "特にお金のこと…<sprite=emo_baiyebi size=60 />困っているみたいだから、\n何かしてあげられないかと思って…",
  str_homestory_811101001_19_dialog_content = "それで、思いついたのだけど、\n私の能力なら…",
  str_homestory_811101001_20_dialog_content = "天空ノ庭の石を晶石に変えて、\n影ノ街の宝石商に売れる…",
  str_homestory_811101001_21_dialog_content = "そんなことができるの？",
  str_homestory_811101001_22_dialog_content = "ええ…砕けたかけらでも、\nかなりの値段がつくらしいわ…",
  str_homestory_811101001_23_dialog_content = "ほ、本当に！？",
  str_homestory_811101001_24_dialog_content = "ウソよ…",
  str_homestory_811101001_25_dialog_content = "や、やっぱり！\nベリエが冗談を言えるようになったなんて！",
  str_homestory_811101001_26_dialog_content = "天空ノ庭に来てから、少し変わったのかもね…\nここはとても、落ち着くから。",
  str_homestory_811101001_27_dialog_content = "特に、川を泳ぐ魚を見てると…",
  str_homestory_811101001_28_dialog_content = "ベリエ、魚を見たいなら\n願いの泉の方がいいよ。",
  str_homestory_811101001_29_dialog_content = "あそこはきれいな魚が\nいっぱいいるから。",
  str_homestory_811101001_30_dialog_content = "ここだと…小さい魚しかいないんじゃない？",
  str_homestory_811101001_31_dialog_content = "ええ…小さい魚を見ているの。",
  str_homestory_811101001_32_dialog_content = "水草の間を縫って、\n石のかげで休んでいる様子が…",
  str_homestory_811101001_33_dialog_content = "自然に溶け込んでいて、落ち着くの…",
  str_homestory_811101001_34_dialog_content = "ベリエ、目がいいんだね…",
  str_homestory_811101001_35_dialog_content = "すごい速さで泳いでる小さな魚が、\nしっかり見えるんだ。",
  str_homestory_811101001_36_dialog_content = "魚はずっと泳いでいるわけじゃない…\n川底で休んでいることの方が多いわ。",
  str_homestory_811101001_37_dialog_content = "石のすき間から、顔だけ出している魚もいるし…",
  str_homestory_811101001_38_dialog_content = "水草といっしょに踊って、気ままに泳ぐ魚もいる。\nとても…自由を感じるわ。",
  str_homestory_811101001_39_dialog_content = "なるほどね。ベリエは魚じゃなくて、\n魚の生活を見てたんだね。",
  str_homestory_811101001_40_dialog_content = "生活？",
  str_homestory_811101001_41_dialog_content = "つまり、魚の自由でのんびりした生き方だよ。",
  str_homestory_811101001_42_dialog_content = "そうかも…他の場所では、\nこんな気持ちになったことがないわ。",
  str_homestory_811101001_43_dialog_content = "天空ノ庭の川辺で、魚を見ている時だけ、\nこみ上げてくる気持ち…",
  str_homestory_811101001_44_dialog_content = "これが天空ノ庭の魅力…？",
  str_homestory_811101001_45_dialog_content = "魅力というか、解放感かもね…",
  str_homestory_811101001_46_dialog_content = "あ、そうね…解放感<sprite=emo_pugongying size=60 />…",
  str_homestory_816501001_0_dialog_content = "シエル…",
  str_homestory_816501001_1_dialog_content = "ナビゲーター！仕事はない？",
  str_homestory_816501001_2_option_content = "あるよ",
  str_homestory_816501001_3_dialog_content = "どんな仕事？報酬は？",
  str_homestory_816501001_4_dialog_content = "でも、君には向いてないかも…\n建物を飾り付ける仕事なんだけど…",
  str_homestory_816501001_5_dialog_content = "シエルにとっては簡単すぎるでしょ。",
  str_homestory_816501001_6_option_content = "ないよ",
  str_homestory_816501001_7_dialog_content = "本当に？何も？",
  str_homestory_816501001_8_dialog_content = "もともと天空ノ庭にはあまり仕事がないし、\nほとんどキューブたちがやってくれるからね。",
  str_homestory_816501001_9_dialog_content = "じゃあ大規模工事でもしない？\n山を切り開くとか、トンネルを掘るとか…",
  str_homestory_816501001_10_dialog_content = "このままじゃ、\nあたしのメカの持ち腐れだよ！<sprite=emo_dianzan size=60 />",
  str_homestory_816501001_11_dialog_content = "今のところ必要は無いかな…\nどうしてそんなに働きたいの？ゆっくり休めば？",
  str_homestory_816501001_12_dialog_content = "休んでる場合じゃないんだよ。\nお金がなくて…",
  str_homestory_816501001_13_dialog_content = "お金？啓光って配給制なんでしょ？\n何か特別なものでも欲しいの？",
  str_homestory_816501001_14_dialog_content = "じ、実は、新型の機械式計算機が欲しくて…\nこの前、研究室で一度だけ見たんだ。",
  str_homestory_816501001_15_dialog_content = "自分で作るのは？\n天空ノ庭にいる時は、時間がたっぷりあるんだし。",
  str_homestory_816501001_16_dialog_content = "ムリだよ…規格外の部品ばっかりだし、\nすごく精密な装置だから。",
  str_homestory_816501001_17_dialog_content = "自分で部品から作ってたら、\n時間がいくらあっても足りないよ…",
  str_homestory_816501001_18_dialog_content = "誰かにお願いして作るにも、\nお金がかかるし…",
  str_homestory_816501001_19_dialog_content = "でも、すごく欲しいの。\nだからバイトして、お金を稼がないと。",
  str_homestory_816501001_20_dialog_content = "なんでそんなにその計算機が欲しいの？",
  str_homestory_816501001_21_dialog_content = "今やってる設計に問題があるんだ…\n何度やっても計算が合わない場所があって。",
  str_homestory_816501001_22_dialog_content = "複雑な計算なんだよ。頭でやるとミスするかもしれないけど、\n計算機なら絶対に間違えないでしょ。",
  str_homestory_816501001_23_dialog_content = "設計の検証作業ってやつ？",
  str_homestory_816501001_24_dialog_content = "それそれ。\n前、図面通りにパワードスーツを作ろうとして…",
  str_homestory_816501001_25_dialog_content = "でも、あたしのミスのせいで壊れちゃって、\n図面もあやうく焼けるところだったの。",
  str_homestory_816501001_26_dialog_content = "何とか火の中から引っ張り出したんだけど…",
  str_homestory_816501001_27_dialog_content = "どうしても合わない部分があるんだよね。\nだから、図面が欠けてるんじゃないかと思って… <sprite=emo_daomei size=60 />",
  str_homestory_816501001_28_dialog_content = "今の図面通りに作ると、\nどうしてもどこか調子が悪くなるんだ。",
  str_homestory_816501001_29_dialog_content = "普通に考えれば…\n図面が欠けてたら、そもそも作れないんじゃないの？",
  str_homestory_816501001_30_dialog_content = "まあ、普通はね。",
  str_homestory_816501001_31_dialog_content = "じゃあ…図面の見かたが間違ってるとか？",
  str_homestory_816501001_32_dialog_content = "昔、巨像の回路がおかしくなって、\nいくらいじっても直せなかったことがあるんだ。",
  str_homestory_816501001_33_dialog_content = "でも、蛍灯が来て、\nちょっと動かしただけで直しちゃったんだよ。",
  str_homestory_816501001_34_dialog_content = "図面の見かた…",
  str_homestory_816501001_35_dialog_content = "そっか！あのコインと<sprite=emo_baiyebi size=60 />同じなんだ！",
  str_homestory_816501001_36_dialog_content = "コイン？",
  str_homestory_816501001_37_dialog_content = "昨日、川の近くでコインを見つけたの。\nあ、もしかしたらビンのフタとか、\nただの金属片かもしれないけど。",
  str_homestory_816501001_38_dialog_content = "ま、そこはどうでもいいの。\n大事なのは、それが水面で跳ねてたこと…",
  str_homestory_816501001_39_dialog_content = "今思えば、水面は穏やかそうに見えて、\nその下は激流だったのかも…",
  str_homestory_816501001_40_dialog_content = "そうだよ、あの公式、\nそういうことだったんだ！",
  str_homestory_816501001_41_dialog_content = "待って。川でコインを見つけたって言った？",
  str_homestory_816501001_42_dialog_content = "えっ？うん、そうだよ。\nあたし、設計を見直してくる！じゃあね！",
  str_homestory_816501001_43_dialog_content = "えっ、うん…",
  str_homestory_810001001_0_dialog_content = "何か考えごと？",
  str_homestory_810001001_1_dialog_content = "スカーレイ？",
  str_homestory_810001001_2_dialog_content = "あら、ボーヤ。\nちょうど聞きたいことがあったの。",
  str_homestory_810001001_3_dialog_content = "なに？",
  str_homestory_810001001_4_dialog_content = "天空ノ庭のことよ。\nあなたはどう思っている？",
  str_homestory_810001001_5_dialog_content = "えっ？その質問、いつもは僕がするんだけど。\n急に聞かれると…ちょっと考えさせて。",
  str_homestory_810001001_6_option_content = "僕の故郷",
  str_homestory_810001001_7_dialog_content = "もちろん、ここは僕の故郷だよ。",
  str_homestory_810001001_8_option_content = "休む場所",
  str_homestory_810001001_9_dialog_content = "のんびり休むのにもってこいの場所だよ。",
  str_homestory_810001001_10_dialog_content = "そう…",
  str_homestory_810001001_11_dialog_content = "ボーヤはこの天空ノ庭が、\n檻のようだとは思わない？",
  str_homestory_810001001_12_dialog_content = "私が守っている、\n星空の墓所のように…",
  str_homestory_810001001_13_dialog_content = "言ってることがよく分からないんだけど…",
  str_homestory_810001001_14_dialog_content = "ここは居ごこちがよすぎるの。\n他のことを考えられなくなるほどに。",
  str_homestory_810001001_15_dialog_content = "他の人からも言われたことがある気がする…",
  str_homestory_810001001_16_dialog_content = "ここはある意味、とても快適よ。\nでも、この大陸に伝わることわざがあるの。",
  str_homestory_810001001_17_dialog_content = "「最高のベッドこそ、\n最も鋭き剣、無数の英雄の墓場」",
  str_homestory_810001001_18_dialog_content = "人は居ごこちが良すぎれば、\n自分の務めを忘れてしまうものよ。\n特に目の前のことしか見えていない虫ケラはね<sprite=emo_wuyu size=60 />。",
  str_homestory_810001001_19_dialog_content = "そんなことを考えるなんて、何かあったの？",
  str_homestory_810001001_20_dialog_content = "昨日、川の中で揺られる水草を見ていたの。",
  str_homestory_810001001_21_dialog_content = "でも、何か金属のかけらがあって…\n水草といっしょに揺られていたわ。",
  str_homestory_810001001_22_dialog_content = "その時ふと、さっきの言葉の意味を\n理解できた気がしたの。",
  str_homestory_810001001_23_dialog_content = "大丈夫だよ。その言葉を思い出したってことは、\n君がその金属のかけらとは違うってことだから。",
  str_homestory_810001001_24_dialog_content = "僕たちは自分の意志で行動できる。\nそうでしょ？",
  str_homestory_810001001_25_dialog_content = "私の目に狂いはなかったわ。\nあなたは虫ケラたちと違うようね、ボーヤ。",
  str_homestory_816601001_0_dialog_content = "よかった…",
  str_homestory_816601001_1_dialog_content = "フィアは今日も楽しそうだね。",
  str_homestory_816601001_2_dialog_content = "ここでの生活にもすっかり慣れた？",
  str_homestory_816601001_3_dialog_content = "珍獣マスターの気持ちを勝手に予想しないで！",
  str_homestory_816601001_4_dialog_content = "あたし、なにも言ってないでしょ…<sprite=emo_shengqi size=60 />",
  str_homestory_816601001_5_dialog_content = "でも、君の行動を見てれば、\n「楽しそう」ってことは分かるよ。",
  str_homestory_816601001_6_dialog_content = "えっ？",
  str_homestory_816601001_7_dialog_content = "ど、どこが…？\nそんなの、信じないもんね！",
  str_homestory_816601001_8_dialog_content = "ううん…まあ、いいか。\nところで、ちょうどその、専門家に聞きたかったことがあるんだけど。",
  str_homestory_816601001_9_dialog_content = "あたしに？",
  str_homestory_816601001_10_dialog_content = "ふん、聞いてあげなくもないよ！",
  str_homestory_816601001_11_dialog_content = "子犬<sprite=emo_goutou size=60 />が楽しい時って、\nどんな動きをするか、分かる？",
  str_homestory_816601001_12_dialog_content = "そんなことも知らないの？",
  str_homestory_816601001_13_dialog_content = "ワンちゃんはね…\n楽しい時はしっぽを振ってるから、すぐにわかるよ。",
  str_homestory_816601001_14_dialog_content = "じゃあ、ネコ<sprite=emo_baimao size=60 />は、\n楽しい時どんな感じなのかな?",
  str_homestory_816601001_15_dialog_content = "そんなの、簡単だよ。",
  str_homestory_816601001_16_dialog_content = "ネコちゃんは普段は警戒心が強いけど、\n楽しいって感じてる時は…",
  str_homestory_816601001_17_dialog_content = "ネコちゃんの方から寄って来て、\n「ゴロゴロ」ってのどを鳴らすんだよ。",
  str_homestory_816601001_18_dialog_content = "じゃあ、珍獣は？\n例えば、キャロとか…",
  str_homestory_816601001_19_dialog_content = "キャロも楽しい時は\nすっごく分かりやすいの、アハハ！",
  str_homestory_816601001_20_dialog_content = "あたしなら目をつぶっててもわかるよ！",
  str_homestory_816601001_21_dialog_content = "なるほど、珍獣でも、そうでなくても…",
  str_homestory_816601001_22_dialog_content = "楽しい気分の時は、\n目に見える特徴があるんだね。",
  str_homestory_816601001_23_dialog_content = "…なんだか怪しい言い方だな～。\nこんな質問して…何かたくらんでるでしょ？",
  str_homestory_816601001_24_dialog_content = "そんなことはないよ。",
  str_homestory_816601001_25_dialog_content = "僕のフィアに対する観察が正しかったかどうか、\n確かめたかっただけだよ。",
  str_homestory_816601001_26_dialog_content = "え…あたしの観察？",
  str_homestory_816601001_27_dialog_content = "珍獣マスターはフィアの方だよ？\n観察するのはあたしなのに…",
  str_homestory_816601001_28_dialog_content = "な、なんであたしのことなんか観察してるの！？",
  str_homestory_816601001_29_dialog_content = "それはたぶん…",
  str_homestory_816601001_30_option_content = "興味があるから",
  str_homestory_816601001_31_dialog_content = "フィアって感情の表現が豊富でしょ。\n興味があったんだよね。",
  str_homestory_816601001_32_option_content = "タイクツだったから",
  str_homestory_816601001_33_dialog_content = "フィアは見てて面白いから、観察しようかなって。",
  str_homestory_816601001_34_dialog_content = "とにかく、僕の観察によれば…",
  str_homestory_816601001_35_dialog_content = "フィアは楽しい時、ウサギ耳がピンと立つんだ。",
  str_homestory_816601001_36_dialog_content = "えええええ！？<sprite=emo_hanshui size=60 />…や、やめて！\nフィアの耳を見ないで！",
  str_homestory_816601001_37_dialog_content = "…",
  str_homestory_816601001_38_dialog_content = "…待って？",
  str_homestory_816601001_39_dialog_content = "フィアのウサ耳、カチューシャだよ。\nいつだってピンと立ってるでしょ？",
  str_homestory_816601001_40_dialog_content = "今、ウサギ耳を押さえたけど…それって、\n楽しいと思ってるって認めたことになるんじゃない？",
  str_homestory_816601001_41_dialog_content = "PlayerName、あたしをからかってたの！？",
  str_homestory_816601001_42_dialog_content = "ごめんごめん！",
  str_homestory_816601001_43_dialog_content = "お詫びのしるしに…一緒に滑り台で遊ぼう。\nそれでいい？",
  str_homestory_816601001_44_dialog_content = "…し、しょうがないな～。",
  str_homestory_816701001_0_dialog_content = "寝てるのかな…",
  str_homestory_816701001_1_dialog_content = "いい質問です。",
  str_homestory_816701001_2_dialog_content = "風がこの世界の呼吸だというのなら…",
  str_homestory_816701001_3_dialog_content = "今この時、世界はまさに\nまどろんでいるのでしょうね<sprite=emo_kun size=60 />。",
  str_homestory_816701001_4_dialog_content = "あっ、起きてたんだね？",
  str_homestory_816701001_5_dialog_content = "寝てるのかと思ったよ。",
  str_homestory_816701001_6_dialog_content = "海は今だ目覚めぬ暴君のようなもの…",
  str_homestory_816701001_7_dialog_content = "もしあなたも海の上で、\n狂ったように吹きすさぶ風に\n髪を揺らすことがあるのなら…",
  str_homestory_816701001_8_dialog_content = "あの…ジェノ？",
  str_homestory_816701001_9_dialog_content = "何でしょう？\n我が親愛なるお客様。",
  str_homestory_816701001_10_dialog_content = "何の話？\nあんまりよく分からないんだけど…",
  str_homestory_816701001_11_dialog_content = "…いや、違う。\n何も分からなかった。",
  str_homestory_816701001_12_dialog_content = "言葉というものは、口から出た瞬間、\nその声を出した肉体のものではなくなるのです。",
  str_homestory_816701001_13_dialog_content = "そして別の誰かの耳に入った瞬間、\nその者の頭脳によって、\n望む姿に曲解されるのです。",
  str_homestory_816701001_14_dialog_content = "この世界はまさに、\n盛大なる幻想のカーニバル…",
  str_homestory_816701001_15_dialog_content = "僕は何度そう思ったことか。",
  str_homestory_816701001_16_option_content = "（分からない）",
  str_homestory_816701001_17_dialog_content = "奥深い話だね…\n僕にはジェノの言っていること、まったく理解できないよ。",
  str_homestory_816701001_18_option_content = "（分かった）",
  str_homestory_816701001_19_dialog_content = "この世で人が本当に分かりあえることなんて\n永遠にないって言いたいんだね。",
  str_homestory_816701001_20_dialog_content = "親愛なるお客様…",
  str_homestory_816701001_21_dialog_content = "実のところ、\nそのようなことはどうでもいいのです。\n僕たちは、ただ楽しめばいいだけ。",
  str_homestory_816701001_22_dialog_content = "うーん、いつも思うんだけど…",
  str_homestory_816701001_23_dialog_content = "君って自分が一体何を言ってるのか、\n自分でも分かってないんじゃない？",
  str_homestory_816701001_24_dialog_content = "そうかもしれませんね。\n確かにうまく伝えられない時があります。",
  str_homestory_816701001_25_dialog_content = "しかし、僕のマジックは決して\n皆様の期待を裏切りません<sprite=emo_mojing size=60 />。",
  str_homestory_816701001_26_dialog_content = "うん…それは間違いないね。",
  str_homestory_816701001_27_dialog_content = "…あ、待って！",
  str_homestory_816701001_28_dialog_content = "もしかして、これも君のマジック！？",
  str_homestory_816701001_29_dialog_content = "本当の君はまだリクライニングで寝てる、そうでしょ？",
  str_homestory_816701001_30_dialog_content = "ほう、お気づきですか？",
  str_homestory_816701001_31_dialog_content = "やっぱり！？",
  str_homestory_816701001_32_dialog_content = "あわててはなりません。\n僕の話はまだ終わっていませんよ。",
  str_homestory_816701001_33_dialog_content = "あなたが見事に言い当てたことは、1つだけ…\nここには眠っている者がいます。",
  str_homestory_816701001_34_dialog_content = "しかし…",
  str_homestory_816701001_35_dialog_content = "それがあなた自身ではないと、\nどうして分かるのですか？",
  str_homestory_816701001_36_dialog_content = "僕じゃないのは当然でしょ！",
  str_homestory_816701001_37_dialog_content = "僕はさっき遠くから\n君がリクライニングで寝てるのをこの目で見たんだ！",
  str_homestory_816701001_38_dialog_content = "では、それより前のことは\n覚えていらっしゃいますか？",
  str_homestory_816701001_39_dialog_content = "さっき僕は…",
  str_homestory_816701001_40_dialog_content = "あれ？僕は何をしてたんだっけ？",
  str_homestory_816701001_41_dialog_content = "ハハハ…",
  str_homestory_816701001_42_dialog_content = "まさか…知らないうちに\n催眠術をかけられてたの？",
  str_homestory_816701001_43_dialog_content = "お、起こしてくれないかな…<sprite=emo_tanqi size=60 />",
  str_homestory_816701001_44_dialog_content = "それはたやすいことです。\nもう一度眠ればいい。",
  str_homestory_816701001_45_dialog_content = "そ、そうなんだ…",
  str_homestory_816801001_0_dialog_content = "何してるの？",
  str_homestory_816801001_1_dialog_content = "PlayerName、こんにちはー！",
  str_homestory_816801001_2_dialog_content = "ここってすごくいいところだね～。\n特にコレ…",
  str_homestory_816801001_3_dialog_content = "いろんな音楽が流せるんだね！<sprite=emo_yinfu size=60 />！",
  str_homestory_816801001_4_dialog_content = "本当に？よかった…",
  str_homestory_816801001_5_dialog_content = "場所をとるだけじゃないかって、\n心配してたんだ。",
  str_homestory_816801001_6_dialog_content = "気に入ってくれる人なんていないかと思ってたよ。",
  str_homestory_816801001_7_dialog_content = "そう？",
  str_homestory_816801001_8_dialog_content = "あたしはすっごく気に入ったよ！",
  str_homestory_816801001_9_dialog_content = "PlayerName、詳しい使い方を教えてくれる？",
  str_homestory_816801001_10_dialog_content = "実は、僕もよく知らないんだ。",
  str_homestory_816801001_11_dialog_content = "それじゃあ、説明書みたいなものはある？",
  str_homestory_816801001_12_dialog_content = "ええと、ないと思う…",
  str_homestory_816801001_13_dialog_content = "自分で調べるしかないってこと？",
  str_homestory_816801001_14_dialog_content = "自分のカンを頼りに使い方を探るなんて、\nますますおもしろそう！",
  str_homestory_816801001_15_dialog_content = "レインボーも音楽が好きだったんだね。",
  str_homestory_816801001_16_dialog_content = "きれいなものには、\n心が引き付けられるものでしょ？\nそれに…",
  str_homestory_816801001_17_dialog_content = "この機械の使い方を完全にものにして、\nショーで使ったら…",
  str_homestory_816801001_18_dialog_content = "もっとたくさんの人が\nサーカスの前座ショーを楽しんでくれるかも！",
  str_homestory_816801001_19_dialog_content = "レインボーはいつでもどこでも、\nサーカス団のことを考えてるんだね。",
  str_homestory_816801001_20_dialog_content = "サーカス団の仕事が心から好きなんだね？",
  str_homestory_816801001_21_dialog_content = "う～ん…実はあたし、\nそんなことは考えたこともないな～<sprite=emo_wuzui size=60 />。",
  str_homestory_816801001_22_dialog_content = "あたしはただ、自分がエメラルド号を守るために\n生まれて来たんだって思ってるだけ。",
  str_homestory_816801001_23_dialog_content = "船の機械のメンテナンスをするのは、\nエメラルド号を守ることでしょ？",
  str_homestory_816801001_24_dialog_content = "船の上で悪いことする人を\nウォーターガンでこらしめることも、\nエメラルド号を守ることだし…",
  str_homestory_816801001_25_dialog_content = "サーカス団でショーをやって、\nエメラルド号をたくさんの人に見てもらって、\n好きになってもらうことも…",
  str_homestory_816801001_26_dialog_content = "やっぱり、エメラルド号を守ることなんだ。",
  str_homestory_816801001_27_dialog_content = "そうだったんだ…",
  str_homestory_816801001_28_dialog_content = "「守る」って、いろんな形があっていいんだね。",
  str_homestory_816801001_29_dialog_content = "PlayerNameだって、\n天空ノ庭をとってもよく守ってるよ！",
  str_homestory_816801001_30_dialog_content = "あ…でも、川の掃除、\nもうちょっとがんばった方がいいかも。",
  str_homestory_816801001_31_dialog_content = "さっき、川でウォーターガンに水を入れてたら…",
  str_homestory_816801001_32_dialog_content = "川の底にキラキラ光るものが落ちてたんだ。",
  str_homestory_816801001_33_dialog_content = "「キラキラ光るもの」…？",
  str_homestory_816801001_34_dialog_content = "そうそう、川と言えば…\n涼しくなりたい気分だったりしな～い？",
  str_homestory_816801001_35_option_content = "涼しくなりたい",
  str_homestory_816801001_36_dialog_content = "さっきまでずっと忙しくしてて、\nちょっと暑いなって思ってたところなんだ。",
  str_homestory_816801001_37_dialog_content = "だったら簡単だよ！",
  str_homestory_816801001_38_dialog_content = "準備はいい～？",
  str_homestory_816801001_39_dialog_content = "えっ！？",
  str_homestory_816801001_40_option_content = "別にいい",
  str_homestory_816801001_41_dialog_content = "…ウォーターガンで僕に水をかけるつもりでしょ？",
  str_homestory_816801001_42_dialog_content = "えヘヘ…そうだったらどうする？",
  str_homestory_816801001_43_dialog_content = "本当に大丈夫だよ。",
  str_homestory_816801001_44_dialog_content = "川で風に吹かれれば<sprite=emo_pugongying size=60 />十分だから！",
  str_homestory_801602001_0_dialog_content = "カフカ？",
  str_homestory_801602001_1_dialog_content = "うわっ！？",
  str_homestory_801602001_2_dialog_content = "PlayerNameか、驚かせやがって。",
  str_homestory_801602001_3_dialog_content = "ごめん、驚かせちゃった…？",
  str_homestory_801602001_4_dialog_content = "何か用か？",
  str_homestory_801602001_5_option_content = "うん",
  str_homestory_801602001_6_dialog_content = "ここに長い間立ってるから…",
  str_homestory_801602001_7_dialog_content = "熱中症が心配だなって。",
  str_homestory_801602001_8_dialog_content = "心配するな、見張りをしてるだけだ。",
  str_homestory_801602001_9_option_content = "用はないよ",
  str_homestory_801602001_10_dialog_content = "ただ、長い間ここに立ってるから…",
  str_homestory_801602001_11_dialog_content = "何をしてるのか、不思議に思ったんだ。",
  str_homestory_801602001_12_dialog_content = "見れば分かるだろ、見張りだ。",
  str_homestory_801602001_13_dialog_content = "「見張り」？",
  str_homestory_801602001_14_dialog_content = "ありがたいけど、カフカ…\n天空ノ庭に危険はないから…",
  str_homestory_801602001_15_dialog_content = "そんなに警戒する必要はないよ。",
  str_homestory_801602001_16_dialog_content = "天空ノ庭の見張りをしてるわけじゃない…",
  str_homestory_801602001_17_dialog_content = "ウサギのためにやってるんだ。",
  str_homestory_801602001_18_dialog_content = "ウサギ？どこにいるの？",
  str_homestory_801602001_19_dialog_content = "巣に戻らせた。",
  str_homestory_801602001_20_dialog_content = "探すのはあきらめろ、\n簡単には見つけられんぞ。",
  str_homestory_801602001_21_dialog_content = "僕がウサギに悪さをするって思ってるの…？",
  str_homestory_801602001_22_dialog_content = "それはともかく、\nカフカって小動物のことが本当に好きなんだね。",
  str_homestory_801602001_23_dialog_content = "オホン、オホン…！\nなんだって？",
  str_homestory_801602001_24_dialog_content = "私はただあいつらに、入ってはいけない場所に\n入ってもらいたくないだけだ。",
  str_homestory_801602001_25_dialog_content = "急にカフカが羊飼いみたいに思えてきたよ。",
  str_homestory_801602001_26_dialog_content = "大型犬<sprite=emo_goutou size=60 />を連れていて、\n動物の群れを危険のない所に導く…",
  str_homestory_801602001_27_dialog_content = "フン、どうだっていいさ。",
  str_homestory_801602001_28_dialog_content = "そういえば…さっき川で光るものを見たんだ。",
  str_homestory_801602001_29_dialog_content = "何なのか、確かめておいてくれないか？",
  str_homestory_801602001_30_dialog_content = "小動物どもが怖がるといけないからな。",
  str_homestory_801602001_31_dialog_content = "分かったよ！",
  str_homestory_817001001_0_dialog_content = "めずらしいな…",
  str_homestory_817001001_1_dialog_content = "誰！？",
  str_homestory_817001001_2_dialog_content = "僕だよ、PlayerName…",
  str_homestory_817001001_3_dialog_content = "あら…ごめんなさい。\n近くで急に足音が止まると、\nどうしても警戒してしまうの。",
  str_homestory_817001001_4_dialog_content = "安心して、天空ノ庭は安全だよ。",
  str_homestory_817001001_5_dialog_content = "ええ、だいぶ前から話は聞いていたわ…",
  str_homestory_817001001_6_dialog_content = "突然現れた空の末裔の生き残りが、\n天空ノ谷に「楽園」を造ってるって。",
  str_homestory_817001001_7_dialog_content = "この目で見るまで、\n本当の話だとは思わなかったけどね。",
  str_homestory_817001001_8_dialog_content = "その若さで、これだけのものが\n管理できるなんてね。",
  str_homestory_817001001_9_option_content = "（素直に認める）",
  str_homestory_817001001_10_dialog_content = "エへへ、ありがとう。",
  str_homestory_817001001_11_dialog_content = "あら、謙そんしないのね。",
  str_homestory_817001001_12_dialog_content = "でも、そういう駆け出しらしい恐れ知らず、\nキライじゃないわ。",
  str_homestory_817001001_13_option_content = "（否定する）",
  str_homestory_817001001_14_dialog_content = "実は、友だちがたくさん手伝ってくれたんだ。",
  str_homestory_817001001_15_dialog_content = "あら、そうなの？",
  str_homestory_817001001_16_dialog_content = "あなたみたいに謙虚な子は、\n今どき珍しいわね。",
  str_homestory_817001001_17_dialog_content = "天空ノ庭がなぜこんなに静かでいられるのか、\n納得がいったわ。",
  str_homestory_817001001_18_dialog_content = "暗鬼に襲われることも、\n裏の組織が暗躍することもない…",
  str_homestory_817001001_19_dialog_content = "思い返してみると、こんな風にゆったりと、\n日差しがまぶたに当たるのを楽しむ日々なんて…",
  str_homestory_817001001_20_dialog_content = "もう、ひと昔前のことのようだわ。",
  str_homestory_817001001_21_dialog_content = "だったら、ポルクスも息抜きするといいよ。",
  str_homestory_817001001_22_dialog_content = "息抜き…？",
  str_homestory_817001001_23_dialog_content = "今、初めて気付いたわ…",
  str_homestory_817001001_24_dialog_content = "私にとって、警戒することが、\n呼吸と同じぐらい当たり前になっていたのね。",
  str_homestory_817001001_25_dialog_content = "ユーフォリアを出ても…",
  str_homestory_817001001_26_dialog_content = "あそこで身に着いた習慣を、\n身体がまだ覚えている…",
  str_homestory_817001001_27_dialog_content = "展望台から周りの人や物を眺めるのも…",
  str_homestory_817001001_28_dialog_content = "ユーフォリアでついた習慣？",
  str_homestory_817001001_29_dialog_content = "客の一挙一動を観察するのも、\n招待主の礼儀のうち？",
  str_homestory_817001001_30_dialog_content = "あなどれないわね…",
  str_homestory_817001001_31_dialog_content = "あ…誤解しないで。",
  str_homestory_817001001_32_dialog_content = "たまたま通りかかったら、\n展望台にいるのを見かけただけなんだ。",
  str_homestory_817001001_33_dialog_content = "フフフ…緊張しないで。\n私はルールを守らない客じゃないわ。",
  str_homestory_817001001_34_dialog_content = "ユーフォリアにいた時は、\nあそこで起こっていることを\n高い所から眺めるのが好きだったの。",
  str_homestory_817001001_35_dialog_content = "そうすると、見えてくるの…",
  str_homestory_817001001_36_dialog_content = "重くて分厚い雨雲の下で、\n好き放題にふくらんでる、色々な欲望が。",
  str_homestory_817001001_37_dialog_content = "でも、ここは違うわ。",
  str_homestory_817001001_38_dialog_content = "静けさとおだやかさが、\n目の届くところ全てに広がってる。",
  str_homestory_817001001_39_dialog_content = "PlayerName、お願いがあるの。",
  str_homestory_817001001_40_dialog_content = "かしこまらないでいいよ。\n何でも言って。",
  str_homestory_817001001_41_dialog_content = "今度、教会の子どもたちを\n連れてきてもいいかしら？",
  str_homestory_817001001_42_dialog_content = "もちろんいいよ！",
  str_homestory_817001001_43_dialog_content = "ああ、そういえば…",
  str_homestory_817001001_44_dialog_content = "私が川で見かけたもの、\nあなたなら興味があるかも知れないわね。",
  str_homestory_817001001_45_dialog_content = "今から行けば、きっと見つかるはずよ。",
  str_homestory_817001001_46_dialog_content = "え？じゃあ、今から行ってくるよ！",
  str_homestory_817101001_0_dialog_content = "キャスタ？",
  str_homestory_817101001_1_dialog_content = "あ、あんたか。",
  str_homestory_817101001_2_dialog_content = "天空ノ庭には、もう慣れた？",
  str_homestory_817101001_3_dialog_content = "慣れない。",
  str_homestory_817101001_4_dialog_content = "え？不満があるの？",
  str_homestory_817101001_5_dialog_content = "言ってくれればちゃんと改善するよ！",
  str_homestory_817101001_6_dialog_content = "ここには…",
  str_homestory_817101001_7_dialog_content = "ずっと晴れない霧が出ない。",
  str_homestory_817101001_8_dialog_content = "日差しが強いせいで目が乾く。",
  str_homestory_817101001_9_dialog_content = "いちゃもんをつけて\nからんでくるヤツらもいない…",
  str_homestory_817101001_10_dialog_content = "平和ボケしちゃって、\n手足から力が抜けてく気分だよ。",
  str_homestory_817101001_11_dialog_content = "このままじゃ、射撃の腕が落ちちゃいそう<sprite=emo_daomei size=60 />。",
  str_homestory_817101001_12_option_content = "（謝る）",
  str_homestory_817101001_13_dialog_content = "ご、ごめん…",
  str_homestory_817101001_14_dialog_content = "天空ノ庭は、退屈すぎるかな？",
  str_homestory_817101001_15_option_content = "（どうしようもない）",
  str_homestory_817101001_16_dialog_content = "でも…",
  str_homestory_817101001_17_dialog_content = "それはどうにもできそうにないね…",
  str_homestory_817101001_18_dialog_content = "分かってないね。\nわたし、ほめてるんだよ？",
  str_homestory_817101001_19_dialog_content = "えっ？",
  str_homestory_817101001_20_dialog_content = "わたしは掃きだめみたいな場所で\n暮らすのに慣れてるから。",
  str_homestory_817101001_21_dialog_content = "こんなにゆったりしたところは、\nかえって落ち着かないんだ。",
  str_homestory_817101001_22_dialog_content = "おかしな話だよね。",
  str_homestory_817101001_23_dialog_content = "天空ノ庭にだって、\nいろいろ面白いことがあるよ！",
  str_homestory_817101001_24_dialog_content = "うん、それは気付いてる。",
  str_homestory_817101001_25_dialog_content = "この看板だよね。\nこの色使いとパターン…",
  str_homestory_817101001_26_dialog_content = "カジノの広告でしょ？",
  str_homestory_817101001_27_dialog_content = "…",
  str_homestory_817101001_28_dialog_content = "どうしてそんな顔してるの<sprite=emo_baiyan size=60 />？",
  str_homestory_817101001_29_dialog_content = "ちょっと稼いで、教会の子どもたちに\nお土産をもって帰りたいだけ…",
  str_homestory_817101001_30_dialog_content = "あんたの天空ノ庭を\n破産させるつもりはないよ。",
  str_homestory_817101001_31_dialog_content = "いや、それ…ただの飾りなんだ。",
  str_homestory_817101001_32_dialog_content = "天空ノ庭にカジノはないよ…",
  str_homestory_817101001_33_dialog_content = "え？",
  str_homestory_817101001_34_dialog_content = "それより、釣りなんかどうかな？",
  str_homestory_817101001_35_dialog_content = "釣り？",
  str_homestory_817101001_36_dialog_content = "針を落として、魚がかかるのをじっと待つんだよ。",
  str_homestory_817101001_37_dialog_content = "魚釣りも運試しって言えるんじゃないかな。",
  str_homestory_817101001_38_dialog_content = "運試しなら、\nやってみないワケにはいかないね。",
  str_homestory_817101001_39_dialog_content = "あ、忘れてた…",
  str_homestory_817101001_40_dialog_content = "キャスタは「幸運の女神の申し子」だったね<sprite=emo_dianzan size=60 />！",
  str_homestory_817101001_41_dialog_content = "川の魚たち、今日はとんだ災難だろうな…",
  str_homestory_813001001_0_dialog_content = "きれいでしょ？",
  str_homestory_813001001_1_dialog_content = "む！？",
  str_homestory_813001001_2_dialog_content = "オホン、オホン…",
  str_homestory_813001001_3_dialog_content = "PlayerNameであったか。",
  str_homestory_813001001_4_dialog_content = "次にあいさつをする時は声を抑えたまえ。\nそれでは相手を驚かしかねんぞ。",
  str_homestory_813001001_5_dialog_content = "よいか、吾輩は確かに忠告したからな。",
  str_homestory_813001001_6_dialog_content = "誰かを驚かせて\n心臓発作でも起こそうものなら…",
  str_homestory_813001001_7_dialog_content = "終身禁固刑に処されるぞ！",
  str_homestory_813001001_8_dialog_content = "ちゅ、忠告、ありがとう…",
  str_homestory_813001001_9_dialog_content = "うむ、分かればよい。\nそれでお主、吾輩に何か用か？",
  str_homestory_813001001_10_dialog_content = "天空ノ庭で吾輩の裁きが\n必要な事件でも起きたか？",
  str_homestory_813001001_11_dialog_content = "あ…そうじゃないんだ。",
  str_homestory_813001001_12_dialog_content = "彫像の前で何か考え事しながら、\n何か手まねをしてたから…",
  str_homestory_813001001_13_dialog_content = "ちょっと気になっただけだよ。",
  str_homestory_813001001_14_dialog_content = "わ、吾輩が何かのマネだと！？",
  str_homestory_813001001_15_dialog_content = "この清く太平な世で、\n根拠のない中傷は許されんぞ！",
  str_homestory_813001001_16_dialog_content = "『白夜城名誉法』の規定により、\n根拠のない中傷を行った者は…",
  str_homestory_813001001_17_dialog_content = "100日間の禁固刑、\nまたは100万白夜コインの罰金を処す！",
  str_homestory_813001001_18_dialog_content = "えっ？",
  str_homestory_813001001_19_option_content = "（反論する）",
  str_homestory_813001001_20_dialog_content = "でも、ここは天空ノ庭で、白夜城じゃないよ？",
  str_homestory_813001001_21_dialog_content = "おおおお…お主、何を言っておるのだ！",
  str_homestory_813001001_22_dialog_content = "天空ノ庭が無法状態で\nよいというのか！？",
  str_homestory_813001001_23_option_content = "（話を合わせる）",
  str_homestory_813001001_24_dialog_content = "へぇ、そうなんだ？\nじゃあ、僕が見間違えたのかな…",
  str_homestory_813001001_25_dialog_content = "PlayerName、お主はまだまだ\n修練を積まねばならん。",
  str_homestory_813001001_26_dialog_content = "だから何を見ても、\n汚れて見えてしまうのだ。",
  str_homestory_813001001_27_dialog_content = "そのような状態が続けば、\n天空ノ庭もおしまいだ！",
  str_homestory_813001001_28_dialog_content = "うん…",
  str_homestory_813001001_29_dialog_content = "では…",
  str_homestory_813001001_30_dialog_content = "示談と行こうか。\nこの彫像を吾輩にくれたまえ。",
  str_homestory_813001001_31_dialog_content = "それで吾輩たちの間に\nいざこざは無いものとする。",
  str_homestory_813001001_32_dialog_content = "え？でも…",
  str_homestory_813001001_33_dialog_content = "この彫像は大切なものなんだよ。",
  str_homestory_813001001_34_dialog_content = "空の末裔の祖先の姿を彫ったものらしくて、\n僕にとっては重要な意味のあるものなんだ。",
  str_homestory_813001001_35_dialog_content = "無法の地では、\nやはり道理が通じんな…",
  str_homestory_813001001_36_dialog_content = "この彫像、本当に気に入ったなら…",
  str_homestory_813001001_37_dialog_content = "土から新しく、1体造ってあげるよ。",
  str_homestory_813001001_38_dialog_content = "ううむ…",
  str_homestory_813001001_39_dialog_content = "よろしい。示談成立だ<sprite=emo_woshou size=60 />。",
  str_homestory_813001001_40_dialog_content = "オホン！あまり長く待たせるでないぞ。",
  str_homestory_812101001_0_dialog_content = "パロマ？",
  str_homestory_812101001_1_dialog_content = "あら、あなただったの。",
  str_homestory_812101001_2_dialog_content = "ごめん…",
  str_homestory_812101001_3_dialog_content = "起こしちゃったかな？",
  str_homestory_812101001_4_dialog_content = "分かってるでしょ。あたしと話す時に、\n見せかけの気遣いは必要ないわ。",
  str_homestory_812101001_5_dialog_content = "さっさと本題に入りなさい。",
  str_homestory_812101001_6_dialog_content = "天空ノ庭に満足してるか、\n聞きたいんでしょう？",
  str_homestory_812101001_7_option_content = "（否定する）",
  str_homestory_812101001_8_dialog_content = "そうじゃないよ…",
  str_homestory_812101001_9_dialog_content = "あいさつしたかっただけなんだ。",
  str_homestory_812101001_10_option_content = "（認める）",
  str_homestory_812101001_11_dialog_content = "お見通しみたいだね…",
  str_homestory_812101001_12_dialog_content = "パロマの評価が気になっちゃって。",
  str_homestory_812101001_13_dialog_content = "そう…まぁ、あなたが聞きたいかは\nどうでもいいわ。\n伝えておこうと思ったことがあるの…",
  str_homestory_812101001_14_dialog_content = "…",
  str_homestory_812101001_15_dialog_content = "ここ、嫌いじゃないわ。",
  str_homestory_812101001_16_dialog_content = "よかった！",
  str_homestory_812101001_17_dialog_content = "厳しいことでも言われるのかと思ったよ…",
  str_homestory_812101001_18_dialog_content = "何か言った？",
  str_homestory_812101001_19_dialog_content = "ええと、つまり…",
  str_homestory_812101001_20_dialog_content = "パロマから建設的な意見を聞けるんじゃないかって、\n期待してたんだ！",
  str_homestory_812101001_21_dialog_content = "意見ね…ないわけじゃないわ。",
  str_homestory_812101001_22_dialog_content = "そんなに開発とか建設とか、管理が得意なら…",
  str_homestory_812101001_23_dialog_content = "白夜城の貴族どもを追い出して、\n浮空島の管理を引き継ぐつもりはない？",
  str_homestory_812101001_24_dialog_content = "えっ！？",
  str_homestory_812101001_25_dialog_content = "そんなこと、僕は考えたこともないよ。",
  str_homestory_812101001_26_dialog_content = "口では「その気はない」なんて言いながら、\n裏でこそこそ手を回す連中…",
  str_homestory_812101001_27_dialog_content = "あたしは数えきれない程、見てきたわ。",
  str_homestory_812101001_28_dialog_content = "僕は…自分の家を守りたいだけだよ。",
  str_homestory_812101001_29_dialog_content = "白夜城の人たちも、きっと僕と同じように、\n自分の家を守りたいはずだよね？",
  str_homestory_812101001_30_dialog_content = "家？",
  str_homestory_812101001_31_dialog_content = "あたしはその「家」から追い出されたの。",
  str_homestory_812101001_32_dialog_content = "あたしにとって、「家」なんてものは\nとうの昔に、何の意味もない、\n空っぽの言葉よ。",
  str_homestory_812101001_33_dialog_content = "パロマ…忘れないで、君には天空ノ庭がある。",
  str_homestory_812101001_34_dialog_content = "君さえよければ…",
  str_homestory_812101001_35_dialog_content = "天空ノ庭を自分の家だと思っていいんだ。",
  str_homestory_812101001_36_dialog_content = "へえ？自分の家が\n奪われることは心配してないの？",
  str_homestory_812101001_37_dialog_content = "天空ノ庭の今日があるのは、\n皆の助けがあったから…",
  str_homestory_812101001_38_dialog_content = "だから、天空ノ庭は皆にとっても、\n心の休まる家であってほしいんだ。",
  str_homestory_812101001_39_dialog_content = "ああ、空の末裔…\nあなたは評判通りの「お人よし」だわ。<sprite=emo_baiyan size=60 />",
  str_homestory_812101001_40_dialog_content = "そうね…",
  str_homestory_812101001_41_dialog_content = "あたしの辞書に、「家」って言葉の解釈を\n増やしていいかも知れない。",
  str_homestory_812101001_42_dialog_content = "どんな解釈？",
  str_homestory_812101001_43_dialog_content = "…「天空ノ庭」。",
  str_homestory_812001001_0_dialog_content = "ヘイディ、ここにいたんだね。",
  str_homestory_812001001_1_dialog_content = "あ…",
  str_homestory_812001001_2_dialog_content = "ヘイディ、どうしたの？",
  str_homestory_812001001_3_dialog_content = "白夜に捧ぐ…",
  str_homestory_812001001_4_dialog_content = "この機械がわたくしを見てからずっと、\n悪意に満ちたうなりをあげ続けているのです！",
  str_homestory_812001001_5_dialog_content = "PlayerName、\nこれは邪悪なる旧時代の遺産ですか？",
  str_homestory_812001001_6_dialog_content = "そういうことであれば…",
  str_homestory_812001001_7_dialog_content = "「明光の騎士」を呼び出し、\n破壊するほかありません<sprite=emo_shengqi size=60 />。",
  str_homestory_812001001_8_option_content = "（安心させる）",
  str_homestory_812001001_9_dialog_content = "ヘイディ、心配いらないよ。",
  str_homestory_812001001_10_dialog_content = "ただの自動アイスクリームメーカーだよ。",
  str_homestory_812001001_11_option_content = "（謝る）",
  str_homestory_812001001_12_dialog_content = "ごめん、言っておくのを忘れてた。",
  str_homestory_812001001_13_dialog_content = "これ、自動アイスクリームメーカーなんだ！",
  str_homestory_812001001_14_dialog_content = "自動…アイスクリームメーカー？<sprite=emo_wuzui size=60 />",
  str_homestory_812001001_15_dialog_content = "うん、カップを置いて、ボタンを押すと…",
  str_homestory_812001001_16_dialog_content = "おいしいアイスクリームが自動で出てくるんだ。",
  str_homestory_812001001_17_dialog_content = "…なるほど、この機械に描かれている\n雪の結晶の絵を見て、\nそうではないかと思っていたのです。",
  str_homestory_812001001_18_dialog_content = "ですが、アイスクリームが一向に出てこないので…",
  str_homestory_812001001_19_dialog_content = "アイスクリームメーカーに見せかけた、\n邪悪な科学技術の産物なのではないか\nと疑っていたのです。",
  str_homestory_812001001_20_dialog_content = "え？またアイスクリームが切れちゃったのかな…？",
  str_homestory_812001001_21_dialog_content = "「切れた」？",
  str_homestory_812001001_22_dialog_content = "この機械で作ったアイスクリームがおいしすぎて…",
  str_homestory_812001001_23_dialog_content = "早めに来て並ばないと、食べられないんだ。",
  str_homestory_812001001_24_dialog_content = "ここ数日は涼しいから、\nアイスクリームを食べる人も少し減ったかと思ってたけど…",
  str_homestory_812001001_25_dialog_content = "まだそんなに人気とは思わなかったよ。",
  str_homestory_812001001_26_dialog_content = "ヘイディは、何味が好き？",
  str_homestory_812001001_27_dialog_content = "材料を買ってくるよ。",
  str_homestory_812001001_28_dialog_content = "何味…？",
  str_homestory_812001001_29_dialog_content = "…コホン。貴方は何味がお好みですか？",
  str_homestory_812001001_30_dialog_content = "う～ん、バニラ、チョコ、抹茶、\nユズ、小豆、それから、いろいろ…",
  str_homestory_812001001_31_dialog_content = "僕は全部好きだよ！",
  str_homestory_812001001_32_dialog_content = "そんなに多くの味が…",
  str_homestory_812001001_33_dialog_content = "ヘイディ、アイスクリームを食べたことないの？\n僕が言ったのは、よくある味だけだけど…",
  str_homestory_812001001_34_dialog_content = "今、なんと？",
  str_homestory_812001001_35_dialog_content = "ア…アイスクリーム程度、\nもちろん食べたことはございます！",
  str_homestory_812001001_36_dialog_content = "ただ、貴方のおっしゃった味が\nあまりも平凡すぎて驚いたのです。",
  str_homestory_812001001_37_dialog_content = "わたくしは「古書」味しか\n食べたことがありませんでしたから。",
  str_homestory_812001001_38_dialog_content = "ですが、このアイスクリームメーカーでは、\n作れないでしょうね。<sprite=emo_emo size=60 />",
  str_homestory_812001001_39_dialog_content = "「古書」味…？",
  str_homestory_812001001_40_dialog_content = "それは食べたことないね。",
  str_homestory_812001001_41_dialog_content = "でも、作れるか、試してみるよ！",
  str_homestory_812001001_42_dialog_content = "いえ、その必要はありません…",
  str_homestory_812001001_43_dialog_content = "どうしたの？",
  str_homestory_812001001_44_dialog_content = "わたくしも、たまには…",
  str_homestory_812001001_45_dialog_content = "普通のアイスクリームを\n味わってみようかと思います。",
  str_homestory_806801001_0_dialog_content = "ウェンディ？",
  str_homestory_806801001_1_dialog_content = "何しようとしてるの？",
  str_homestory_806801001_2_dialog_content = "あ、PlayerName。",
  str_homestory_806801001_3_dialog_content = "垂直飛行の練習ができる所を探してるの。",
  str_homestory_806801001_4_dialog_content = "垂直飛行？",
  str_homestory_806801001_5_dialog_content = "そうだよ、まっすぐ上に飛んで、\nまっすぐ降りてくるの。",
  str_homestory_806801001_6_dialog_content = "飛行技術の高さが\n試される飛び方なんだよ。",
  str_homestory_806801001_7_dialog_content = "実は僕、いつも君がすごく高く飛んでるのを見て、\n落ちないかハラハラしてるんだ。",
  str_homestory_806801001_8_dialog_content = "え？そんなこと心配してたの？",
  str_homestory_806801001_9_dialog_content = "安心して、あれぐらいの高さ、\n私には何でもないから。",
  str_homestory_806801001_10_dialog_content = "忘れたの？\n私は砂漠の爆風ミサイルだよ<sprite=emo_mojing size=60 />！",
  str_homestory_806801001_11_option_content = "忘れてた",
  str_homestory_806801001_12_dialog_content = "だったら、もう1回言ってあげる！",
  str_homestory_806801001_13_option_content = "忘れてないよ",
  str_homestory_806801001_14_dialog_content = "そんな大事なこと、\n忘れるはずないでしょ？",
  str_homestory_806801001_15_dialog_content = "念のため、もう1回言ってあげる！",
  str_homestory_806801001_16_dialog_content = "あたしこそ、\n砂漠の爆風ミサイル、ウェンディ！",
  str_homestory_806801001_17_dialog_content = "スピードこそ私の目印、\n勇敢さは私の代名詞！",
  str_homestory_806801001_18_dialog_content = "わかった、わかった。",
  str_homestory_806801001_19_dialog_content = "ところで、どうして垂直飛行なんて練習してるの？",
  str_homestory_806801001_20_dialog_content = "もちろん、配達のためだよ！",
  str_homestory_806801001_21_dialog_content = "配達？",
  str_homestory_806801001_22_dialog_content = "PlayerName、\n長～い触手の生えたやつを見かけなかった？",
  str_homestory_806801001_23_dialog_content = "まさか、クラゲバルーンのこと？",
  str_homestory_806801001_24_dialog_content = "バルーンかどうかは、\nどうでもいいんだよ。",
  str_homestory_806801001_25_dialog_content = "お客さんに頼まれた手紙は、\n絶対に届けないと！",
  str_homestory_806801001_26_dialog_content = "ねえ、PlayerNameは\nあのバルーンと知り合い？",
  str_homestory_806801001_27_dialog_content = "ああいうインテリアグッズが\nあることは知ってるから…知り合い、かな？？？",
  str_homestory_806801001_28_dialog_content = "あのバルーンの名前って、\nもしかして「クレーケン」？",
  str_homestory_806801001_29_dialog_content = "ええと、もし君の届けようとしてる\n手紙の宛名が「クレーケン」なら…",
  str_homestory_806801001_30_dialog_content = "たぶん思い違いだよ。\nクレーケンはバルーンじゃないよ。",
  str_homestory_806801001_31_dialog_content = "え！？そうなの？",
  str_homestory_806801001_32_dialog_content = "依頼人から「クレーケン」には、\n長～い触手がたくさん生えてるって聞いたよ。",
  str_homestory_806801001_33_dialog_content = "それによく黒い帽子をかぶってるって。",
  str_homestory_806801001_34_dialog_content = "あのバルーンは帽子、かぶってないよ。",
  str_homestory_806801001_35_dialog_content = "どっちにしても、\nバルーンが受け取り人のはずないでしょ…",
  str_homestory_806801001_36_dialog_content = "うっ、そうなると…この手紙、\n私の「配達完了時間」最長記録を\n塗り替えることになりそう。",
  str_homestory_806801001_37_dialog_content = "となれば、話してるヒマはないね！",
  str_homestory_806801001_38_dialog_content = "さっき飛んでる時、\n川の中に何か光るものがあったから、\n気になるけど…",
  str_homestory_806801001_39_dialog_content = "まずは手紙を届けなきゃ！<sprite=emo_dianzan size=60 />",
  str_homestory_817201001_0_dialog_content = "あれ、リリカ…",
  str_homestory_817201001_1_dialog_content = "PlayerName、見て見て！",
  str_homestory_817201001_2_dialog_content = "どうしたの？",
  str_homestory_817201001_3_dialog_content = "このおもちゃ、すっごく楽しい！",
  str_homestory_817201001_4_dialog_content = "バットで叩くと、中からカラフルな紙が\nいっぱい飛び出すの！<sprite=emo_caitiao size=60 />",
  str_homestory_817201001_5_dialog_content = "で、キャンディが入ってたりするのよ。",
  str_homestory_817201001_6_dialog_content = "こんなおもちゃ、見たことないわ。",
  str_homestory_817201001_7_dialog_content = "それはそうだよ。\n天空ノ谷の伝統的なかざりだからね。",
  str_homestory_817201001_8_dialog_content = "他の場所では見られないと思うよ。",
  str_homestory_817201001_9_dialog_content = "ファルベプッペ？天空ノ谷に伝わる…",
  str_homestory_817201001_10_dialog_content = "そう言われてみれば、\n聞いたことあるかも！",
  str_homestory_817201001_11_dialog_content = "お祭りの前に、種を陶器のつぼに入れて…",
  str_homestory_817201001_12_dialog_content = "そしてお祭りのときに、「バーン」って叩き割る…",
  str_homestory_817201001_13_dialog_content = "そうすると、大自然からの祝福を受けられる！",
  str_homestory_817201001_14_dialog_content = "…みたいな感じだったよね？",
  str_homestory_817201001_15_dialog_content = "へぇ、リリカが天空ノ谷について\n詳しいとは思わなかったよ。",
  str_homestory_817201001_16_dialog_content = "エヘヘ…それほどでもないけどね。",
  str_homestory_817201001_17_dialog_content = "前に撮影した映画で、歴史の先生の役をやったのよ。",
  str_homestory_817201001_18_dialog_content = "ま、アップになることはなかったけど、\n後ろでずっと講義してる演技をしてたから。",
  str_homestory_817201001_19_dialog_content = "そのときのセリフが、ちょうど\n天空ノ谷の伝統の解説だったってワケ！",
  str_homestory_817201001_20_dialog_content = "えっ、そんな映画があるの！？",
  str_homestory_817201001_21_dialog_content = "何て言うタイトル？",
  str_homestory_817201001_22_dialog_content = "いや、あたしのセリフ、\n本当にただの背景音だから…",
  str_homestory_817201001_23_dialog_content = "実際の作品だと、\n何を話してるか聞き取れないの…",
  str_homestory_817201001_24_option_content = "（ガッカリする）",
  str_homestory_817201001_25_dialog_content = "そっか…",
  str_homestory_817201001_26_dialog_content = "天空ノ谷が映画に出て来ると思ったのに…",
  str_homestory_817201001_27_dialog_content = "しっかりしてよ、PlayerName。\nあたしの職業、忘れたの？",
  str_homestory_817201001_28_option_content = "（感動する）",
  str_homestory_817201001_29_dialog_content = "背景音でもいいよ。\n天空ノ谷が映画のワンシーンに登場するなんて…",
  str_homestory_817201001_30_dialog_content = "それだけで感動だよ！",
  str_homestory_817201001_31_dialog_content = "登場って言えるほどでもないでしょ…\nそれにPlayerName、あたしの仕事が何か忘れてない？",
  str_homestory_817201001_32_dialog_content = "あたしは新進気鋭の若手監督なのよ！",
  str_homestory_817201001_33_dialog_content = "いっそ…",
  str_homestory_817201001_34_dialog_content = "天空ノ谷を題材にした映画を撮ればいいじゃない？",
  str_homestory_817201001_35_dialog_content = "えっ、本当に？",
  str_homestory_817201001_36_dialog_content = "もちろんよ！",
  str_homestory_817201001_37_dialog_content = "もう撮りたいテーマとか、決まってるの？",
  str_homestory_817201001_38_dialog_content = "それは…今から考えるわ。<sprite=emo_sikao size=60 />",
  str_homestory_817201001_39_dialog_content = "あっ、そうだ！",
  str_homestory_817201001_40_dialog_content = "あたしが天空ノ谷で踊るって言うのは？",
  str_homestory_817201001_41_dialog_content = "えっ？",
  str_homestory_817201001_42_dialog_content = "いちお、映画に天空ノ谷が出て来るって言えるでしょ？",
  str_homestory_817201001_43_dialog_content = "…だめ？",
  str_homestory_817201001_44_dialog_content = "うーん…難しいわね。",
  str_homestory_817201001_45_dialog_content = "じゃあ、PlayerNameが天空ノ谷で踊る映画にする？",
  str_homestory_817201001_46_dialog_content = "そんなの見たい人、いるかな…",
  str_homestory_817301001_0_dialog_content = "ミノス…",
  str_homestory_817301001_1_dialog_content = "ごきげんよう、PlayerName様<sprite=emo_mojing size=60 />。",
  str_homestory_817301001_2_dialog_content = "こんにちは、ミノス。",
  str_homestory_817301001_3_dialog_content = "何かご用でしょうか？",
  str_homestory_817301001_4_option_content = "（そうだよ）",
  str_homestory_817301001_5_dialog_content = "ええと…ミノスに聞きたいことがあるんだ。",
  str_homestory_817301001_6_dialog_content = "どうぞ、お話しください。",
  str_homestory_817301001_7_dialog_content = "ミノスにも天空ノ庭でくつろいでほしいんだ…",
  str_homestory_817301001_8_dialog_content = "私にそのようなお気づかいは不要です。",
  str_homestory_817301001_9_option_content = "（違うよ）",
  str_homestory_817301001_10_dialog_content = "いや、そういうわけじゃないよ…",
  str_homestory_817301001_11_dialog_content = "ミノスが天空ノ庭にいる時は、ほとんど何も心配してない…",
  str_homestory_817301001_12_dialog_content = "でも、僕はミノスにリラックスしていて欲しいんだ。",
  str_homestory_817301001_13_dialog_content = "だって、天空ノ庭にはお客さんとして来てもらってるからね。",
  str_homestory_817301001_14_dialog_content = "確かに…それも道理ですね。",
  str_homestory_817301001_15_dialog_content = "客人は主人の立場や、\n客をもてなすという楽しみを奪ってはならない…",
  str_homestory_817301001_16_dialog_content = "ご指摘の件、書き留めておきましょう。",
  str_homestory_817301001_17_dialog_content = "今後は、完璧な客人となれるように努力いたします。",
  str_homestory_817301001_18_dialog_content = "いや、「完璧」じゃなくていいんだ。",
  str_homestory_817301001_19_dialog_content = "では、「完璧ではない客人」になるべき、と？",
  str_homestory_817301001_20_dialog_content = "難しい問題でございますね。",
  str_homestory_817301001_21_dialog_content = "アハハ、考えるようなことでもないと思うけど…\nそれより…",
  str_homestory_817301001_22_dialog_content = "さっき、手を上げただけでロウソクがついたよね。",
  str_homestory_817301001_23_dialog_content = "不思議だなぁ…どうやったの？",
  str_homestory_817301001_24_dialog_content = "よく観察されていらっしゃいますね。",
  str_homestory_817301001_25_dialog_content = "ロウソクを調教していたのですが、\nちょうど終わったところで貴方が来られたのです。",
  str_homestory_817301001_26_dialog_content = "ロウソクを…調教？",
  str_homestory_817301001_27_dialog_content = "ええ。執事の経験が長い者にしか\nできないことですが…",
  str_homestory_817301001_28_dialog_content = "どんなに貴重な家具や、精巧な置物でも…",
  str_homestory_817301001_29_dialog_content = "ちょっとした「調教」をして、\n環境になじませる必要があるのです。",
  str_homestory_817301001_30_dialog_content = "まさに、このロウソク立てのように。",
  str_homestory_817301001_31_dialog_content = "ロウソクの内部には\n自動で点灯と消灯を行う機能がありますね。",
  str_homestory_817301001_32_dialog_content = "何もしなければ、\nロウソクたちは勝手についたり消えたりするでしょう。",
  str_homestory_817301001_33_dialog_content = "ですが、ご安心ください。\n今や貴方は順番に、ロウソクの前を通るだけでいいのです。",
  str_homestory_817301001_34_dialog_content = "順序よく点灯していくことでしょう。",
  str_homestory_817301001_35_dialog_content = "す、すごいね。",
  str_homestory_817301001_36_dialog_content = "ああ、申し訳ございません…",
  str_homestory_817301001_37_dialog_content = "家具の調教は、\n客人の身分でするべきことではございませんでした。",
  str_homestory_817301001_38_dialog_content = "いや、大丈夫だよ。",
  str_homestory_817301001_39_dialog_content = "そもそもミノスが言ってくれなかったら、\nこんな機能があるなんて知らなかったし！",
  str_homestory_817301001_40_dialog_content = "お赦しいただき感謝します。",
  str_homestory_817301001_41_dialog_content = "ですが、この過ちのおかげで…",
  str_homestory_817301001_42_dialog_content = "私は完璧な「完璧でない客人」になることができました。",
  str_homestory_817301001_43_dialog_content = "PlayerName様に喜んでいただけるとよいのですが…<sprite=emo_baimao size=60 />",
  str_homestory_815901001_0_dialog_content = "やぁ、サディ！",
  str_homestory_815901001_1_dialog_content = "まさか、仕事の依頼？",
  str_homestory_815901001_2_dialog_content = "違うよ。さっきの音楽<sprite=emo_yinfu size=60 />が気になって、来てみたんだ。",
  str_homestory_815901001_3_dialog_content = "あのリズム感と盛り上がるドラム音…",
  str_homestory_815901001_4_dialog_content = "思わず身体が動いちゃうね。",
  str_homestory_815901001_5_dialog_content = "ヒップホップの魅力が伝わってるみたいだね。",
  str_homestory_815901001_6_dialog_content = "ま、それがトーゼン！\nヒップホップを嫌いになる人はいないよ。",
  str_homestory_815901001_7_dialog_content = "なるほど、これがヒップホップなんだね。",
  str_homestory_815901001_8_dialog_content = "PlayerName…\nまさか初めて聞いたとか言わないよね？",
  str_homestory_815901001_9_option_content = "（そうだよ）",
  str_homestory_815901001_10_dialog_content = "ヒップホップなんてあまり聞かないから、\n知ってることも少なくて。",
  str_homestory_815901001_11_option_content = "（違うよ）",
  str_homestory_815901001_12_dialog_content = "そんなことないよ。どんな音楽にも興味はあるけど…",
  str_homestory_815901001_13_dialog_content = "今まで君のラップしか聞いたことなかったからね。",
  str_homestory_815901001_14_dialog_content = "ヒップホップのリズムは知らなくて。",
  str_homestory_815901001_15_dialog_content = "こういうものだとは思ってなかったんだ。",
  str_homestory_815901001_16_dialog_content = "もったいないね～！\n天空ノ庭に来たばかりの時、\nここには何かが足りないと思ったの。",
  str_homestory_815901001_17_dialog_content = "このドラムを見て、\nここにはヒップホップがないんだって気づいたよ！",
  str_homestory_815901001_18_dialog_content = "ドラムひとつでダイナミックな音楽になるんだね…",
  str_homestory_815901001_19_dialog_content = "PlayerNameも、すっかりハマっちゃったみたいだね…",
  str_homestory_815901001_20_dialog_content = "なら、義賊としては「助け」ないと！",
  str_homestory_815901001_21_dialog_content = "助ける？",
  str_homestory_815901001_22_dialog_content = "そ。ドラムの叩き方、レクチャーしたげるよ。",
  str_homestory_815901001_23_dialog_content = "そうすれば、聞きたい時にいつでもどこでも\nヒップホップできるでしょ。",
  str_homestory_815901001_24_dialog_content = "あ、ちょっと待って、もしあんたに教えたら…",
  str_homestory_815901001_25_dialog_content = "天空ノ庭に来た人みんなが、\nあんたのヒップホップを聞くかもってこと！？",
  str_homestory_815901001_26_dialog_content = "あたしの手で、アストラに\nヒップホップのブームを起こせるなんて…",
  str_homestory_815901001_27_dialog_content = "あの、サディ。\n想像をふくらませてるところ、悪いんだけど…",
  str_homestory_815901001_28_dialog_content = "ドラムもヒップホップも、\n一切経験がないんだ。",
  str_homestory_815901001_29_dialog_content = "そんなに簡単には覚えられないと思うよ。",
  str_homestory_815901001_30_dialog_content = "いーからいーから。\n好きこそ物の上手なれ、って言うでしょ<sprite=emo_dianzan size=60 />。",
  str_homestory_815901001_31_dialog_content = "ヒップホップで大事なのは、\nドラムのリズムとメロディーね。",
  str_homestory_815901001_32_dialog_content = "ドラムが正確なら、\n音楽にメロディーが生まれてくるの。",
  str_homestory_815901001_33_dialog_content = "スティックになったつもりで、\n心のままに刻めばいいよ。",
  str_homestory_815901001_34_dialog_content = "自由で気ままに、\nそれがヒップホップの原点！",
  str_homestory_815901001_35_dialog_content = "自分の心に従うだけで、\n君みたいにヒップホップを演奏できるってこと？",
  str_homestory_815901001_36_dialog_content = "そのとーり！試してみたくなったでしょ？",
  str_homestory_815901001_37_dialog_content = "ドラムを止めないで叩き続けてれば、\nフローができるの！",
  str_homestory_815901001_38_dialog_content = "と、止まらず叩き続ける…？\nフロー…？",
  str_homestory_815901001_39_dialog_content = "たくさんの人にヒップホップの魅力を\n知ってほしいと思うよね？ね？",
  str_homestory_815901001_40_dialog_content = "それはもちろん…\nただ、まだそんな技術はないよ。",
  str_homestory_815901001_41_dialog_content = "PlayerName、\n一流のヒップホップアーティストになる日はまだ遠そうだね。",
  str_homestory_815901001_42_dialog_content = "じゃあ、今日はここまでにしとこっか。",
  str_homestory_815901001_43_dialog_content = "あ…ありがとうございました…？",
  str_homestory_807901001_0_dialog_content = "ミジェンニ…",
  str_homestory_807901001_1_dialog_content = "ミジェンニ？",
  str_homestory_807901001_2_dialog_content = "PlayerNameさんでしたか。",
  str_homestory_807901001_3_dialog_content = "あ、ミジェンニもこれ、気に入った？",
  str_homestory_807901001_4_dialog_content = "理性的な税務官として、\n「気に入る」という行為は感情的に過ぎます。",
  str_homestory_807901001_5_dialog_content = "私はこの物品の価値を裁定していただけです。",
  str_homestory_807901001_6_dialog_content = "えっと…ここは白夜城じゃないんだし、\nミジェンニもたまには息抜きしなよ<sprite=emo_sikao size=60 />。",
  str_homestory_807901001_7_dialog_content = "理性的な思考を鍛え上げるのは、\nそれほど容易なことではありません。",
  str_homestory_807901001_8_dialog_content = "税法の分野で一流の学者になることは、\n極めて難しいのです。",
  str_homestory_807901001_9_dialog_content = "これまで積み重ねてきた学術的な鍛錬を、\n一時の怠惰で無駄にしたくはありません。",
  str_homestory_807901001_10_dialog_content = "ですが、今は時間があります。\n天空ノ庭の税務業務をお手伝いいたしましょう。",
  str_homestory_807901001_11_dialog_content = "天空ノ庭では必要ないと思うよ…",
  str_homestory_807901001_12_dialog_content = "口調はやわらかいですが、「確固たる態度」から\n<sprite=emo_baiyebi size=60 />10白夜コインほどの距離ですね。",
  str_homestory_807901001_13_dialog_content = "どうやら断られてしまったようですね。",
  str_homestory_807901001_14_option_content = "（認める）",
  str_homestory_807901001_15_dialog_content = "せっかくの申し出を断りたくはないんだけど…\n天空ノ庭では税務官なんて、本当に雇えないよ。",
  str_homestory_807901001_16_dialog_content = "費用の問題でしたか。",
  str_homestory_807901001_17_dialog_content = "構いません。\n無料で税務相談を承ります。",
  str_homestory_807901001_18_dialog_content = "「天空ノ庭の価値を裁定すること」も、\n私に感情的な付加価値をもたらすでしょうから。",
  str_homestory_807901001_19_option_content = "（否定する）",
  str_homestory_807901001_20_dialog_content = "そ、そんなことないよ！",
  str_homestory_807901001_21_dialog_content = "天空ノ庭で税務官が必要になったら、\nきっとミジェンニにお願いするから！",
  str_homestory_807901001_22_dialog_content = "取引や管理が行われる場所には、\n必ず税金が発生するものです。",
  str_homestory_807901001_23_dialog_content = "私を信用してくださるのであれば、\nこれからも天空ノ庭の価値を裁定いたしましょう。",
  str_homestory_807901001_24_dialog_content = "わ、分かったよ…",
  str_homestory_807901001_25_dialog_content = "話を戻しますと、この装飾物について、\n何かご存じなのですか？",
  str_homestory_807901001_26_dialog_content = "価値を裁定するには、より多くの情報が必要です。",
  str_homestory_807901001_27_dialog_content = "これは「ウィンデリオンの鳥の巣」だよ。",
  str_homestory_807901001_28_dialog_content = "卵はただの飾りだけど、小動物<sprite=emo_gezitou size=60 />を引き寄せて巣を作らせたり、\n卵を産ませたりするんだって。",
  str_homestory_807901001_29_dialog_content = "つまり、経済的価値は何ら生み出さず、\n土地資源を浪費しているわけですね。",
  str_homestory_807901001_30_dialog_content = "小動物の卵がかえった後は、\nさらに天空ノ庭の食料を消費しますね…",
  str_homestory_807901001_31_dialog_content = "中の卵には何の価値もないと裁定できます。",
  str_homestory_807901001_32_dialog_content = "ここに置いたままでは、\n天空ノ庭にとって損失となりますね。",
  str_homestory_807901001_33_dialog_content = "え？でも…\n卵だって、どれも小さな命を宿してるんだよ。",
  str_homestory_807901001_34_dialog_content = "理性だけで命の価値を\n裁定するわけにはいかないでしょ？",
  str_homestory_807901001_35_dialog_content = "どうしても裁定するって言うなら、\nあの卵はどれも、僕にとって計り知れない価値があるんだよ。",
  str_homestory_807901001_36_dialog_content = "計り知れない価値ですか？",
  str_homestory_807901001_37_dialog_content = "あっ、そうだ！",
  str_homestory_807901001_38_dialog_content = "ミジェンニ、いっそ「ウィンデリオンの鳥の巣」、\n君がお世話してあげてよ。",
  str_homestory_807901001_39_dialog_content = "構いません。何をすればよいでしょうか？",
  str_homestory_807901001_40_dialog_content = "動物たちが殻を破って出てくるのを待って、\n成長を見守ってほしいんだ。",
  str_homestory_807901001_41_dialog_content = "後で本をあげるよ。\n卵をかえす方法が書いてあるから。",
  str_homestory_807901001_42_dialog_content = "参考書があるのでしたら、とても助かります。",
  str_homestory_807901001_43_dialog_content = "ご安心ください。期待に応えてみせましょう。",
  str_homestory_817601001_0_dialog_content = "ベルタ！",
  str_homestory_817601001_1_dialog_content = "何してるの？",
  str_homestory_817601001_2_dialog_content = "PlayerNameじゃない。",
  str_homestory_817601001_3_dialog_content = "トレーニングよ。",
  str_homestory_817601001_4_dialog_content = "でも、走っていたら、\n急にラファエル様の顔が見えたような気がして…",
  str_homestory_817601001_5_dialog_content = "立ち止まって、探していたの。",
  str_homestory_817601001_6_dialog_content = "そうしたら、このハガキに\nラファエル様の写真が貼ってあったわ！",
  str_homestory_817601001_7_dialog_content = "ああ、このスタンドにあるのは、\n皆が僕に送ってくれた絵はがきだね！",
  str_homestory_817601001_8_dialog_content = "僕が新しい場所へ行った時に、\n記念に買ってきたのもあるけどね。",
  str_homestory_817601001_9_dialog_content = "これはラファエルが遠出した時、\n無理やりミカエルと一緒に撮ったものかな。",
  str_homestory_817601001_10_dialog_content = "それでミカエル様がイヤそうな顔をしてるわけね！<sprite=emo_wuzui size=60 />",
  str_homestory_817601001_11_dialog_content = "それにしても、PlayerNameの人脈、\n本当にすごいのね。",
  str_homestory_817601001_12_dialog_content = "数もすごく多いし、\nヘイディ様の署名まである…",
  str_homestory_817601001_13_dialog_content = "あら？この風景写真は…R・W砂漠かしら？",
  str_homestory_817601001_14_dialog_content = "うん、そうだよ。",
  str_homestory_817601001_15_dialog_content = "R・Wの人たちと遊びに行った時に、\n記念に持って帰ってきたんだ。",
  str_homestory_817601001_16_option_content = "北境のもあるよ",
  str_homestory_817601001_17_dialog_content = "わぁ！砂漠も雪原も、すごくきれいね。",
  str_homestory_817601001_18_option_content = "海のもあるよ",
  str_homestory_817601001_19_dialog_content = "わぁ！砂漠とビーチなんて、すごくきれいね。",
  str_homestory_817601001_20_dialog_content = "PlayerNameはいろいろな場所に行ってるのね。\nうらやましいわ！",
  str_homestory_817601001_21_dialog_content = "ベルタは普段、旅行に行ったりしないの？",
  str_homestory_817601001_22_dialog_content = "ええ、仕事が仕事だから、\n安心して休める機会がほとんどないわ。",
  str_homestory_817601001_23_dialog_content = "休暇中だろうと、\nケガをする人はいるもの。",
  str_homestory_817601001_24_dialog_content = "出かけるとしても、\nほとんどが応援のための出張ね。",
  str_homestory_817601001_25_dialog_content = "なるほど。医者って本当に大変なんだね…",
  str_homestory_817601001_26_dialog_content = "大変は大変だけど…",
  str_homestory_817601001_27_dialog_content = "人の苦しみを和らげてあげられる、\n命だって救えるかもしれない、って考えれば…",
  str_homestory_817601001_28_dialog_content = "そんなことはどうでもよくなるわ！",
  str_homestory_817601001_29_dialog_content = "今のうちに努力すれば、\nもっと早く成長できるし。",
  str_homestory_817601001_30_dialog_content = "そうすれば、もっと早く自分の医療団を作って、\n大陸各地を回って治療できるようになるわ。",
  str_homestory_817601001_31_dialog_content = "その時こそ、もっと大勢の人を助けられるし、\n見たことのない風景も見られるようになるの！",
  str_homestory_817601001_32_dialog_content = "一挙両得でしょ！<sprite=emo_guilian size=60 />",
  str_homestory_817601001_33_dialog_content = "…ベルタって、すごいね…",
  str_homestory_817601001_34_dialog_content = "今の話をしてる時の君、\n輝いてるような気さえしたよ！",
  str_homestory_817601001_35_dialog_content = "アハハハ。私なんてまだまだよ！",
  str_homestory_817601001_36_dialog_content = "ラファエル様やヨハネス先生みたいな、\nすごい医者になることが目標だもの。",
  str_homestory_817601001_37_dialog_content = "勉強しなきゃいけないことが\nまだまだいっぱいあるの。",
  str_homestory_817601001_38_dialog_content = "医学と治療技術だけじゃなくって、\n体力や精神力ももっと向上させないと！",
  str_homestory_817601001_39_dialog_content = "ヨハネス先生が私の手術をしてくださった時は、\n3日間も手術台に立ってたんだもの！",
  str_homestory_817601001_40_dialog_content = "今の私じゃ、到底マネできないわ。",
  str_homestory_817601001_41_dialog_content = "あっ、こんなことを言ってる場合じゃないわ。\nおしゃべりはここまで！トレーニングに戻るわね！",
  str_homestory_817601001_42_dialog_content = "またね、PlayerName！",
  str_homestory_817601001_43_dialog_content = "将来、大陸を巡って治療するようになったら、\n私もあなたに絵はがきを出すわ！",
  str_homestory_817601001_44_dialog_content = "アハハ。相変わらずせっかちだね…",
  str_homestory_817601001_45_dialog_content = "その日を楽しみにしてるよ。\n頑張ってね、ベルタ。",
  str_homestory_817501001_0_dialog_content = "アクセリア？",
  str_homestory_817501001_1_dialog_content = "こんにちは、アクセリア。",
  str_homestory_817501001_2_dialog_content = "こんにちは、PlayerName。",
  str_homestory_817501001_3_dialog_content = "最近、体の具合はどう？",
  str_homestory_817501001_4_dialog_content = "天空ノ庭でよく君を見かける気がするから。",
  str_homestory_817501001_5_dialog_content = "良好です。<sprite=emo_chidai size=60 />\nしかし、アクセリアは天空ノ庭を散策した後、\n休眠カプセルに戻って休まなければなりません。",
  str_homestory_817501001_6_dialog_content = "ですが、ここにはアクセリアの\n興味を引くものが多くあります。",
  str_homestory_817501001_7_dialog_content = "たとえば、よく見てる、\nそのドラムとか？",
  str_homestory_817501001_8_dialog_content = "…オホン…",
  str_homestory_817501001_9_dialog_content = "PlayerName、\nアクセリアの行動を見ていたのですか？",
  str_homestory_817501001_10_option_content = "もちろん！",
  str_homestory_817501001_11_dialog_content = "キュービックがいつも君のそばにいるから、\nトラブルは起こらないと思うけど…",
  str_homestory_817501001_12_dialog_content = "それでも、アクセリアの体の具合には、\n気を配っておかないとね。",
  str_homestory_817501001_13_dialog_content = "…心配ありがとうございます。",
  str_homestory_817501001_14_option_content = "そうじゃないよ",
  str_homestory_817501001_15_dialog_content = "でも、たまたま君を見かけた時は、\nいつもこのドラムの近くにいるから。",
  str_homestory_817501001_16_dialog_content = "はい…",
  str_homestory_817501001_17_dialog_content = "アクセリアはこのようなドラムに興味があります。",
  str_homestory_817501001_18_dialog_content = "うん、アクセリアが音楽に興味があるって\n言ってたのは覚えてるよ。",
  str_homestory_817501001_19_dialog_content = "でも、アクセリアが「テクノ」系の音楽を\n好きな理由は何なの？",
  str_homestory_817501001_20_dialog_content = "理由ですか…",
  str_homestory_817501001_21_dialog_content = "歌詞がないからかもしれません。<sprite=emo_sikao size=60 />",
  str_homestory_817501001_22_dialog_content = "歌詞がないから？",
  str_homestory_817501001_23_dialog_content = "はい。",
  str_homestory_817501001_24_dialog_content = "歌詞がなければ、\n聞き手が想像する余地を十分に残せます。",
  str_homestory_817501001_25_dialog_content = "純粋にリズムを感じるだけでよく、\n曲に感情を投入する必要がありません。",
  str_homestory_817501001_26_dialog_content = "やっぱり、すごく「アクセリア」らしい理由だね…",
  str_homestory_817501001_27_dialog_content = "これを言うと父には嫌がられますが、\nアクセリアは他の音楽よりも…",
  str_homestory_817501001_28_dialog_content = "そうした音楽の方が、作り手と冷たい音符の一体化した、\n理性的な光を放てると思います。",
  str_homestory_817501001_29_dialog_content = "分かるような気がするような…",
  str_homestory_817501001_30_dialog_content = "そういう音楽って、落ち着くみたいなもの？",
  str_homestory_817501001_31_dialog_content = "そうです。",
  str_homestory_817501001_32_dialog_content = "じゃあ…",
  str_homestory_817501001_33_dialog_content = "アクセリアがよくこのドラムの近くにいるのは、\nそういう音楽の中にこのドラムが入ってるから？",
  str_homestory_817501001_34_dialog_content = "それとも、そういう音楽に\nこのドラムの音を足してみたいの？",
  str_homestory_817501001_35_dialog_content = "アクセリアは、\n音をもっと聞きたいと思っているだけです。",
  str_homestory_817501001_36_dialog_content = "ですが、PlayerNameの指摘通り、\nアクセリアにとっては一種の啓発となっています。",
  str_homestory_817501001_37_dialog_content = "アクセリアは…\nこれからもここに来るでしょう。",
  str_homestory_817501001_38_dialog_content = "うん！何か必要なことがあれば、\nいつでも僕に言ってよ。",
  str_homestory_817501001_39_dialog_content = "ありがとうございます、PlayerName。",
  str_homestory_805401001_0_dialog_content = "ナディーン？",
  str_homestory_805401001_1_dialog_content = "PlayerNameさん、いらっしゃいましたか。",
  str_homestory_805401001_2_dialog_content = "ナディーン、1人でここに立って、何してるの？",
  str_homestory_805401001_3_dialog_content = "皆と一緒に中で休んだり、\n釣りに行ったりしないの？",
  str_homestory_805401001_4_dialog_content = "私の仕事を終わらせるためです！",
  str_homestory_805401001_5_dialog_content = "君の仕事？",
  str_homestory_805401001_6_dialog_content = "そうです。\n天空ノ庭で最初のナイトガーディアンとして…",
  str_homestory_805401001_7_dialog_content = "自分の担当はしっかり見張っているのが当然です！",
  str_homestory_805401001_8_dialog_content = "えっ、待って…",
  str_homestory_805401001_9_dialog_content = "天空ノ庭のナイトガーディアン<sprite=emo_yueliang size=60 />なんて、\n誰にも頼んだ覚えはないけど？",
  str_homestory_805401001_10_dialog_content = "PlayerNameさんは私を\n天空ノ庭に客人として招き、遊ばせてくださいました。",
  str_homestory_805401001_11_dialog_content = "住居と食事どころか、\n興味深い家具やインテリアまで用意されていて…",
  str_homestory_805401001_12_dialog_content = "本当に感動したのです！",
  str_homestory_805401001_13_dialog_content = "PlayerNameさんのような\n偉大な方の友人になれるとは思ってもいませんでした。",
  str_homestory_805401001_14_dialog_content = "ましてや、白夜城を出て、天空ノ庭のような\n遠い場所に来られるとは、夢にも思いませんでした。",
  str_homestory_805401001_15_dialog_content = "とはいえ、私にはお金も能力もありません…\nどうお返ししていいのか分からないのです。",
  str_homestory_805401001_16_dialog_content = "いろいろ考えた結果、\n私にはナイトガーディアンの仕事しかないと\n思い至りました。",
  str_homestory_805401001_17_dialog_content = "ですから…このような形で\nPlayerNameさんに恩返ししたいのです！",
  str_homestory_805401001_18_option_content = "（感謝する）",
  str_homestory_805401001_19_dialog_content = "ありがとう、ナディーン。\nそう言ってくれて、とてもうれしいよ。",
  str_homestory_805401001_20_dialog_content = "だけど、僕のお客さんを\n働かせるわけにはいかないよ。",
  str_homestory_805401001_21_option_content = "（落ち着ける）",
  str_homestory_805401001_22_dialog_content = "喜んでもらえるのが、僕にとっては一番のお返しだよ！",
  str_homestory_805401001_23_dialog_content = "そんな大変なことをする必要はないって。",
  str_homestory_805401001_24_dialog_content = "大丈夫です。慣れていますから。\n大変だとは思っていません。",
  str_homestory_805401001_25_dialog_content = "それに…",
  str_homestory_805401001_26_dialog_content = "天空ノ庭は本当に美しいです！",
  str_homestory_805401001_27_dialog_content = "いつも皆の好みに合わせた家具が置いてありますし…",
  str_homestory_805401001_28_dialog_content = "だんだんと\nここが「家」という感覚さえしてきました。",
  str_homestory_805401001_29_dialog_content = "「家」だって言うなら、\nナディーンもなおさら遠慮しないでよ。",
  str_homestory_805401001_30_dialog_content = "お返しなんて考えなくていいから。",
  str_homestory_805401001_31_dialog_content = "「家」だからこそ、\nなおさら責任を感じるのです…",
  str_homestory_805401001_32_dialog_content = "天空ノ庭が傷ひとつつかないよう、\n私たちの「家」を守りたいと！",
  str_homestory_805401001_33_dialog_content = "私にとっては、\n仕事などという単純なものではありません。",
  str_homestory_805401001_34_dialog_content = "これは…守りたいという本能と使命なのです！",
  str_homestory_805401001_35_dialog_content = "ナディーン…",
  str_homestory_805401001_36_dialog_content = "ありがとう！",
  str_homestory_805401001_37_dialog_content = "どうにかして、君に報酬が出せるようにするよ。",
  str_homestory_805401001_38_dialog_content = "えっ！？",
  str_homestory_817801001_0_dialog_content = "こんにちは、ヴィック。",
  str_homestory_817801001_1_dialog_content = "外にいるなんてめずらしいね！",
  str_homestory_817801001_2_dialog_content = "今日はどうして飲んだくれて\n部屋で寝てないの<sprite=emo_kun size=60 />？",
  str_homestory_817801001_3_dialog_content = "PlayerName、俺のことを\nそんなヤツだと思ってたのか？",
  str_homestory_817801001_4_dialog_content = "傷つくね～、これでも珍獣の研究者なんだぞ。",
  str_homestory_817801001_5_dialog_content = "部屋ではな、資料を整理したり、\n新しい本を書いたりしてるんだ。",
  str_homestory_817801001_6_dialog_content = "ちゃ～んとまじめに仕事してるんだぞ。\n酒は脳の活性化のために飲んでるだけさ！",
  str_homestory_817801001_7_dialog_content = "そうなの？\nじゃあ、新しい本はどのくらい書けた？",
  str_homestory_817801001_8_dialog_content = "そりゃそうと、\nここはどんどん環境が良くなってくな。",
  str_homestory_817801001_9_dialog_content = "強引に話をそらそうとしてるね…",
  str_homestory_817801001_10_dialog_content = "そんなこたぁないさ。\n今、俺が何やってるか分かるか？",
  str_homestory_817801001_11_dialog_content = "う～ん…散歩しながら、ぼうっとしてる？",
  str_homestory_817801001_12_dialog_content = "…",
  str_homestory_817801001_13_dialog_content = "森にどんな生物が、どれくらいいるのか、調べてたのさ。",
  str_homestory_817801001_14_dialog_content = "そんなの調べてどうするの？",
  str_homestory_817801001_15_dialog_content = "おいおい、バカにしちゃいけないぜ？",
  str_homestory_817801001_16_dialog_content = "生物の種類と数ってのは、いろんなことを教えてくれるんだ。",
  str_homestory_817801001_17_dialog_content = "たとえば、ここの環境はどんな生物の生息に適してるか…",
  str_homestory_817801001_18_dialog_content = "動植物はどんな食物連鎖をつくってるのか…とかな。",
  str_homestory_817801001_19_dialog_content = "…でもって、今さっき<sprite=emo_wuzui size=60 />――",
  str_homestory_817801001_20_dialog_content = "ここは研究所として最高だってことに気づいた！",
  str_homestory_817801001_21_dialog_content = "…で、珍獣を連れてこようと考えてたのさ。",
  str_homestory_817801001_22_dialog_content = "そうすれば、新しい本の裏付けになるデータが…",
  str_homestory_817801001_23_dialog_content = "ちょっと待って、何をする気？",
  str_homestory_817801001_24_dialog_content = "あ？データを収集して、本を書くんだが？",
  str_homestory_817801001_25_dialog_content = "違うよ、その前に言ったこと。",
  str_homestory_817801001_26_dialog_content = "ここの森で珍獣を育てるつもりなの？",
  str_homestory_817801001_27_dialog_content = "珍獣用の部屋なら、もうたくさん用意したでしょ！？\nまだ足りないの？",
  str_homestory_817801001_28_dialog_content = "おいおい、それとこれとは別なんだよ。",
  str_homestory_817801001_29_dialog_content = "室内じゃ、外の実際の環境と\n完全に同じものは造り出せないだろ。",
  str_homestory_817801001_30_dialog_content = "本物の生態系の中でこそ、\n実際に最も近い様子を観察できるんだ。",
  str_homestory_817801001_31_dialog_content = "重要なのはそこじゃないよ！",
  str_homestory_817801001_32_dialog_content = "君が巨像で珍獣をたくさん飼ってるせいで、\n皆から苦情がたくさん来てるんだ。",
  str_homestory_817801001_33_dialog_content = "朝早くから鳴いて他の皆の睡眠を妨げてる問題も、\nまだ解決してないでしょ。",
  str_homestory_817801001_34_dialog_content = "フンや毛も散らかしっぱなしだし…",
  str_homestory_817801001_35_dialog_content = "これ以上の面倒は困るよ！",
  str_homestory_817801001_36_dialog_content = "PlayerNameは冷たいね～。",
  str_homestory_817801001_37_dialog_content = "「面倒」なんて言い方はないだろ？",
  str_homestory_817801001_38_dialog_content = "珍獣研究界への貢献じゃないか！",
  str_homestory_817801001_39_dialog_content = "ヘリクツはいいよ！<sprite=emo_shengqi size=60 />",
  str_homestory_817801001_40_dialog_content = "とにかく、森で珍獣を飼うのはダメだよ。",
  str_homestory_817801001_41_dialog_content = "芝生も、谷も、川もダメだからね！",
  str_homestory_817801001_42_dialog_content = "やれやれ、分かったよ。",
  str_homestory_817801001_43_dialog_content = "まったく、今どきの若者ってのは、\n年寄りに厳しいんだなぁ。",
  str_homestory_817701001_0_dialog_content = "ゴルディだ！",
  str_homestory_817701001_1_dialog_content = "ゴルディ！<sprite=emo_yaosu size=60 />",
  str_homestory_817701001_2_dialog_content = "あら、PlayerName。\n今ステージで新曲を歌ってたの。",
  str_homestory_817701001_3_dialog_content = "ふぅ～…なんだかすっごく緊張しちゃうわ。\nみんな気に入ってくれるかしら…",
  str_homestory_817701001_4_dialog_content = "あなたはどう思った？",
  str_homestory_817701001_5_dialog_content = "いい曲だったよ。",
  str_homestory_817701001_6_dialog_content = "みんな、きっと気に入るよ！",
  str_homestory_817701001_7_dialog_content = "ふふ、そう言ってもらえて、安心したわ～。",
  str_homestory_817701001_8_dialog_content = "…実はね、ずっと悩んでることがあるの。",
  str_homestory_817701001_9_dialog_content = "PlayerNameの意見を聞きたいわ。",
  str_homestory_817701001_10_dialog_content = "どんなこと？ゴルディが悩むなんて、めずらしいね。",
  str_homestory_817701001_11_dialog_content = "ニューアルバムのメインに考えてる曲なんだけど…",
  str_homestory_817701001_12_dialog_content = "1つは、いつもの私らしく、明るく元気な<sprite=emo_taiyang size=60 />曲で…",
  str_homestory_817701001_13_dialog_content = "もう1つは、新しくチャレンジしてみた、\nクールな雰囲気<sprite=emo_mojing size=60 />の曲なの。",
  str_homestory_817701001_14_dialog_content = "ねえ、PlayerNameはどう思う？\nイメージを変えてみた方がいいかしら？",
  str_homestory_817701001_15_option_content = "変えてみるといいよ",
  str_homestory_817701001_16_dialog_content = "時どき新しいスタイルの曲を試すのもいいわね！",
  str_homestory_817701001_17_option_content = "変える必要ないよ",
  str_homestory_817701001_18_dialog_content = "それもそうね。\n慣れてるスタイルだからこそ、\nステキな曲に歌いあげられるもの！",
  str_homestory_817701001_19_dialog_content = "ただ、アルバム全体のテーマにもよるんじゃないかな？",
  str_homestory_817701001_20_dialog_content = "確かにそうね！\n今度のニューアルバムのテーマは「成長」で…",
  str_homestory_817701001_21_dialog_content = "うちのプロダクションが\nそうとうな大金をかけて作ってる、\nフルアルバムなの。",
  str_homestory_817701001_22_dialog_content = "そうなんだ。\nで、マネージャーさんは何て言ってるの？",
  str_homestory_817701001_23_dialog_content = "今のスタイルでいいって言ってるわ。",
  str_homestory_817701001_24_dialog_content = "新しいスタイルが受けないファンもいるでしょ…",
  str_homestory_817701001_25_dialog_content = "守りに入った意見だね。",
  str_homestory_817701001_26_dialog_content = "でも僕は、ファンの皆はありのままの\nゴルディのことが好きなんだと思うよ。",
  str_homestory_817701001_27_dialog_content = "だから、君がどんなふうに変わろうと、\n今まで通り応援してくれるよ！",
  str_homestory_817701001_28_dialog_content = "君は自分の思う通りに――",
  str_homestory_817701001_29_dialog_content = "本当にやりたいことをやればいいと思う。",
  str_homestory_817701001_30_dialog_content = "ありがとう！",
  str_homestory_817701001_31_dialog_content = "私、決めたわ！メイン曲は――",
  str_homestory_817701001_32_dialog_content = "メイン曲は――",
  str_homestory_817701001_33_dialog_content = "明るく元気な方にするわ！",
  str_homestory_817701001_34_dialog_content = "えっ？",
  str_homestory_817701001_35_dialog_content = "だって、それがありのままの私だもの。",
  str_homestory_817701001_36_dialog_content = "私に一番ふさわしいのは、明るく元気な曲よね！",
  str_homestory_817701001_37_dialog_content = "マネージャーさんはさすがだよ。\nゴルディのこと、よく分かってるんだね…",
  str_homestory_818001001_0_dialog_content = "ブランディ？",
  str_homestory_818001001_1_dialog_content = "スティックバルーンは\nこちらに置いた方がいいでしょうか？\nうう～ん…しっくり来ませんね…",
  str_homestory_818001001_2_dialog_content = "何してるの？",
  str_homestory_818001001_3_dialog_content = "ああ！\nちょうどいいところに！",
  str_homestory_818001001_4_dialog_content = "ちょっと意見をいただけますか？\nこのスティックバルーン、左に置いた方がいいでしょうか？\nそれとも右でしょうか？",
  str_homestory_818001001_5_option_content = "左の方がいい",
  str_homestory_818001001_6_dialog_content = "うーん…やはり右の方がよさそうですね。",
  str_homestory_818001001_7_option_content = "どっちもいいと思うよ",
  str_homestory_818001001_8_dialog_content = "確かにそうですね。では、右にしましょう。",
  str_homestory_818001001_9_dialog_content = "…",
  str_homestory_818001001_10_dialog_content = "何をしてるの？",
  str_homestory_818001001_11_dialog_content = "「ゴルディ、天空ノ庭コンサート大成功」\nという記事に載せる、写真を撮っているのです。",
  str_homestory_818001001_12_dialog_content = "今は応援グッズを撮影しているのですが――",
  str_homestory_818001001_13_dialog_content = "ペンライト、光る応援ボード、\nそれからシールにカード…",
  str_homestory_818001001_14_dialog_content = "ゴルディさんのプリントTシャツまで揃えました！\n本当に可愛いですよね！",
  str_homestory_818001001_15_dialog_content = "そういえば、等身大パネルはありませんね…",
  str_homestory_818001001_16_dialog_content = "こっそり部屋に持ち帰ろうと思っていたのですが…<sprite=emo_sikao size=60 />",
  str_homestory_818001001_17_dialog_content = "ああっ！もしかして、\n最初は等身大パネルもあったのではないでしょうか！？",
  str_homestory_818001001_18_dialog_content = "それをどこかのモラルに欠けたファンが\n持ち帰ったのでは…？",
  str_homestory_818001001_19_dialog_content = "なんと許しがたい行いでしょう！",
  str_homestory_818001001_20_dialog_content = "今、自分がやろうとしてたって言わなかった…？",
  str_homestory_818001001_21_dialog_content = "まあ、いいでしょう。\nまずはあるものを撮ってしまいます。",
  str_homestory_818001001_22_dialog_content = "本人がいるのに、どうして応援グッズを撮るの？",
  str_homestory_818001001_23_dialog_content = "それって、本末転倒じゃない？",
  str_homestory_818001001_24_dialog_content = "分かっていませんね。\nこういう手法は引き立て効果といって…",
  str_homestory_818001001_25_dialog_content = "あ、待ってください！",
  str_homestory_818001001_26_dialog_content = "急にどうしたの？おどかさないでよ。",
  str_homestory_818001001_27_dialog_content = "ちょうど木の影が応援ボードにかかっていました。",
  str_homestory_818001001_28_dialog_content = "光と影が重なり合い、木の模様がかすかに浮かび上がって、\nいきいきとした情景を作り出していました。",
  str_homestory_818001001_29_dialog_content = "まさにシャッターチャンスと言うわけです！",
  str_homestory_818001001_30_dialog_content = "すばらしいデキです！\nこれほどの写真、なかなか撮れませんよ！",
  str_homestory_818001001_31_dialog_content = "今回の記事に採用です！",
  str_homestory_818001001_32_dialog_content = "…だから、なんでゴルディ本人の写真を使わないの！？",
  str_homestory_818001001_33_dialog_content = "よし、撮影も終わりましたし、\nさっそく現像しなくては！",
  str_homestory_818001001_34_dialog_content = "あ、そういえば、川で何かを見かけました。\n見に行ってはどうですか？",
  str_homestory_818001001_35_dialog_content = "僕の話を全然聞いてない…",
  str_homestory_818101001_0_dialog_content = "シュウさん？",
  str_homestory_818101001_1_dialog_content = "シュウさん、何を見ているんですか？",
  str_homestory_818101001_2_dialog_content = "この棚の中を見ていたところだ。",
  str_homestory_818101001_3_dialog_content = "棚の中を…？どうかしたんですか？<sprite=emo_sikao size=60 />",
  str_homestory_818101001_4_dialog_content = "あっ、シンが中にいる！",
  str_homestory_818101001_5_dialog_content = "うむ、それがしが目を離した隙に、中に入ったのだ。",
  str_homestory_818101001_6_dialog_content = "なるほどそれで…シンって、いたずらっ子だったんですね。",
  str_homestory_818101001_7_dialog_content = "実のところ、メンとダクも中に入ってしまっていてな。",
  str_homestory_818101001_8_dialog_content = "えっ？猫たち、そんなにこの棚を気に入っているんですか？",
  str_homestory_818101001_9_dialog_content = "猫は狭く、暗い場所を好む習性があるからだろうな。",
  str_homestory_818101001_10_dialog_content = "そう言われてみれば…確かに棚の中って暗いですし、\n何段にも分かれているし…",
  str_homestory_818101001_11_dialog_content = "うん、まさに新しいキャットハウスといったところですね！",
  str_homestory_818101001_12_dialog_content = "新しいキャットハウス…？ふむ、一理あるな。",
  str_homestory_818101001_13_dialog_content = "近々職人を呼び、これをまねたものを\n作ってもらうのも良いかもしれぬな。",
  str_homestory_818101001_14_dialog_content = "わあ、いい考えですね。いつでもどうぞ！",
  str_homestory_818101001_15_dialog_content = "僕も、この棚にそんな使い道があるとは思っていなかったので…",
  str_homestory_818101001_16_dialog_content = "良い物に出会えた。礼を言う。",
  str_homestory_818101001_17_dialog_content = "だが、貴公の迷惑にならぬか？",
  str_homestory_818101001_18_option_content = "そんなことありませんよ！",
  str_homestory_818101001_19_option_content = "少しだけ…",
  str_homestory_818101001_20_dialog_content = "申し訳ない。あやつらにはしっかりと仕置きをしておこう。",
  str_homestory_818101001_21_dialog_content = "とりあえず…今の問題は、\nこの子たちをどうやって外に出すかですよね…",
  str_homestory_818101001_22_dialog_content = "うーん…すごく気持ちよさそうに寝ていますね。",
  str_homestory_818101001_23_dialog_content = "普段ならば、それがしが名を呼ぶだけで来るのだが…\n今日は反応を示さぬのだ。",
  str_homestory_818101001_24_dialog_content = "うーん…猫たちがシュウさんのことを\nよく分かっているせいかもしれませんね…",
  str_homestory_818101001_25_dialog_content = "と、言うと？<sprite=emo_wuzui size=60 />",
  str_homestory_818101001_26_dialog_content = "普段、シュウさんが猫たちを呼ぶのは\n用があるときですよね？",
  str_homestory_818101001_27_dialog_content = "でも、今日のシュウさんは、\n猫たちを棚から出すためだけに呼んだと思うので…",
  str_homestory_818101001_28_dialog_content = "だから、猫たちは呼びかけを無視したんじゃないかなと。",
  str_homestory_818101001_29_dialog_content = "うーん、3匹とも頭がいいなあ…",
  str_homestory_818101001_30_dialog_content = "…この棚には、実に不思議な魔力があるようだな。",
  str_homestory_818101001_31_dialog_content = "やはり、猫たちに1つ用意してやらねば。",
  str_homestory_818101001_32_dialog_content = "それで…猫たちはどうしましょうか？",
  str_homestory_818101001_33_dialog_content = "こうなった以上、目を覚ますまで待つほかあるまい。",
  str_homestory_818101001_34_dialog_content = "あはは、猫たちの粘り勝ちですね。",
  str_homestory_818101001_35_dialog_content = "それにしても、この不思議な光景…",
  str_homestory_818101001_36_dialog_content = "事情を知らない人が見たら、シュウさんがまた何か\n哲学的なことを考えているように見えるんだろうな…",
  str_homestory_818301001_0_dialog_content = "リンセイ？",
  str_homestory_818301001_1_dialog_content = "うーん、どこに行ったんだろう…",
  str_homestory_818301001_2_dialog_content = "やあ、リンセイ。何してるの？",
  str_homestory_818301001_3_dialog_content = "や、やあ、PlayerName。",
  str_homestory_818301001_4_dialog_content = "チビシッポを探しているんだけど、見かけなかった？",
  str_homestory_818301001_5_dialog_content = "うーん、見てないなあ…どうかしたの？",
  str_homestory_818301001_6_dialog_content = "フンッ、どうもこうもないよ。\nまたいつものサボり癖が出たのさ！<sprite=emo_shengqi size=60 />",
  str_homestory_818301001_7_dialog_content = "薬草を摘むためにチビシッポを連れて庭に行ったんだけど…",
  str_homestory_818301001_8_dialog_content = "気づいたら、目を離した隙にいなくなっちゃったんだよ！",
  str_homestory_818301001_9_dialog_content = "天空ノ庭にも薬草があるの？",
  str_homestory_818301001_10_dialog_content = "もちろん！",
  str_homestory_818301001_11_dialog_content = "良薬っていうのはね、思いもよらない場所にあるものなんだよ。",
  str_homestory_818301001_12_dialog_content = "大事なのは、それを見つけるための眼力なんだ<sprite=emo_mojing size=60 />。",
  str_homestory_818301001_13_dialog_content = "へええ、さすがリンセイ！",
  str_homestory_818301001_14_dialog_content = "ところで…",
  str_homestory_818301001_15_option_content = "どれくらい探しているの？",
  str_homestory_818301001_16_dialog_content = "その…えっと…30分くらいかな…？",
  str_homestory_818301001_17_dialog_content = "えっ、そんなに？",
  str_homestory_818301001_18_dialog_content = "間違えた！10分くらいかも！",
  str_homestory_818301001_19_option_content = "どんな薬草を手に入れたの？",
  str_homestory_818301001_20_dialog_content = "そ、それは…とにかく薬草だよ！",
  str_homestory_818301001_21_dialog_content = "リンセイ、どうしてもごもごしてるの？",
  str_homestory_818301001_22_dialog_content = "そんなことないって！",
  str_homestory_818301001_23_dialog_content = "まさか…",
  str_homestory_818301001_24_dialog_content = "リンセイもサボってた、とか？",
  str_homestory_818301001_25_dialog_content = "そ、そそそそんなはずないでしょ！",
  str_homestory_818301001_26_dialog_content = "ボクとチビシッポがここに来たのは、\n薬草を摘むためなんだ！",
  str_homestory_818301001_27_dialog_content = "でも…",
  str_homestory_818301001_28_dialog_content = "でも？",
  str_homestory_818301001_29_dialog_content = "ここ、本当に居心地がよくて…",
  str_homestory_818301001_30_dialog_content = "それで少し、<sprite=emo_kun size=60 />寝ちゃったんだ。ほ、ほんのちょっとだよ！",
  str_homestory_818301001_31_dialog_content = "そうして目が覚めたら、チビシッポがいなくなっていて…",
  str_homestory_818301001_32_dialog_content = "あはは、兄弟そろって怠け者みたいだね。",
  str_homestory_818301001_33_dialog_content = "ボ、ボクは違うよ！",
  str_homestory_818201001_0_dialog_content = "何をしてるの？",
  str_homestory_818201001_1_dialog_content = "水の呼吸を感じているのよ。",
  str_homestory_818201001_2_dialog_content = "意味はよく分からないけど…なんだかすごそうだね。",
  str_homestory_818201001_3_dialog_content = "あなたは水の呼吸を感じたこと、ある？",
  str_homestory_818201001_4_option_content = "あるよ",
  str_homestory_818201001_5_dialog_content = "本当？どうだったかしら？",
  str_homestory_818201001_6_dialog_content = "冷たくて、爽やかで…のどの渇きを癒やせたかな？",
  str_homestory_818201001_7_dialog_content = "それは水の味よ。呼吸ではないわ。",
  str_homestory_818201001_8_option_content = "ないよ",
  str_homestory_818201001_9_dialog_content = "やってみたければ、教えてあげるわ。",
  str_homestory_818201001_10_dialog_content = "じゃあ、よかったらお願いしてもいいかな？",
  str_homestory_818201001_11_dialog_content = "では、始めましょう。",
  str_homestory_818201001_12_dialog_content = "えっ、今から？でも水着を持ってきてないし…",
  str_homestory_818201001_13_dialog_content = "今日は岸辺で、基本動作を練習するだけでいいわ。",
  str_homestory_818201001_14_dialog_content = "立って、胸をはって顔をあげて、\n深呼吸し…そして水の流れを感じるの。",
  str_homestory_818201001_15_dialog_content = "難しくはなさそうだね、やってみるよ。",
  str_homestory_818201001_16_dialog_content = "すぅ――",
  str_homestory_818201001_17_dialog_content = "ふぅ――",
  str_homestory_818201001_18_dialog_content = "ところで、いつまでこうして立っていればいいの？",
  str_homestory_818201001_19_dialog_content = "ざっと1万時間かしら。",
  str_homestory_818201001_20_dialog_content = "1万時間！？",
  str_homestory_818201001_21_dialog_content = "誰でも平凡から非凡になるには、\n1万時間の鍛錬が必要なのよ。",
  str_homestory_818201001_22_dialog_content = "そうは言っても、いくらなんでもこれは退屈すぎちゃうよ<sprite=emo_xinsui size=60 />…",
  str_homestory_818201001_23_dialog_content = "やめたいなら、今すぐやめていいわよ。",
  str_homestory_818201001_24_dialog_content = "面白いことはたくさんあるけれど、成功への道は\nそれほど楽しいものじゃないから。",
  str_homestory_818201001_25_dialog_content = "ご、ごめん。もう少し頑張るよ！",
  str_homestory_818201001_26_dialog_content = "君もこんなつらい修行を乗り越えて、\n泳ぎが得意になったの？",
  str_homestory_818201001_27_dialog_content = "いいえ、修行なんてしたことないわ。私のは生まれつきよ。",
  str_homestory_818201001_28_dialog_content = "？？？",
  str_homestory_818201001_29_dialog_content = "じゃあ1万時間も立たせるたのは、僕をからかっていたの！？",
  str_homestory_818201001_30_dialog_content = "いいえ。私が最初に泳ぎを習ったとき、\nリン家の長老からそう教わったの。",
  str_homestory_818201001_31_dialog_content = "ただ、私は生まれながらにして水と共鳴できたから、\n修行なんて必要なかっただけ。",
  str_homestory_818201001_32_dialog_content = "そっか…リン家の長老がそう教えたのなら、\nきっと意味があるはずだよね。",
  str_homestory_818201001_33_dialog_content = "立ち続けよう…",
  str_homestory_818201001_34_dialog_content = "す、少し休もう…足が痛くなってきた…<sprite=emo_tanqi size=60 />",
  str_homestory_818201001_35_dialog_content = "それじゃ、もうやめなさい。",
  str_homestory_818201001_36_dialog_content = "えっ？でも、リン家の長老は…",
  str_homestory_818201001_37_dialog_content = "長老は泳げないの。\nおそらく、適当に言っただけなんだと思うわ。",
  str_homestory_818201001_38_dialog_content = "！！！",
  str_homestory_818201001_39_dialog_content = "あなたが水辺で1万時間立っていられたとしても、\n水と共鳴できないでしょうし。",
  str_homestory_818201001_40_dialog_content = "才能が必要なことも世の中にはあるのよ。\nないなら、無理しないことね。",
  str_homestory_818201001_41_dialog_content = "それを早く言ってよ！",
  str_homestory_818201001_42_dialog_content = "あなたがあまりにも真剣になっているものだから、\n邪魔するのも忍びなくて。",
  str_homestory_818201001_43_dialog_content = "もう！",
  str_homestory_818201001_44_dialog_content = "あっ…足がつっちゃった…",
  str_homestory_818201001_45_dialog_content = "なら、おんぶしてあげるわ。",
  str_homestory_818201001_46_dialog_content = "い、いいよ。男たるもの…",
  str_homestory_818201001_47_dialog_content = "そう。じゃあ、私は行くわね。",
  str_homestory_818201001_48_dialog_content = "ま、待って…うう…じゃあ、しゃがんでもらってもいいかな…",
  str_homestory_816001001_0_dialog_content = "ミカエル？",
  str_homestory_816001001_1_dialog_content = "何を見てるの？",
  str_homestory_816001001_2_dialog_content = "（あ、PlayerNameさん…）",
  str_homestory_816001001_3_dialog_content = "（このロウソクの台を見ていました）",
  str_homestory_816001001_4_dialog_content = "そのロウソクの台、気に入ったの？\nよければプレゼントしようか？",
  str_homestory_816001001_5_dialog_content = "（いいえ、買わせてください。いくらでしょうか？）",
  str_homestory_816001001_6_dialog_content = "（ここに1000白夜コインありますが<sprite=emo_baiyebi size=60 />、\n足りますか？）",
  str_homestory_816001001_7_dialog_content = "いやいや、そんなにいらないよ。",
  str_homestory_816001001_8_dialog_content = "もしお金を払おうとするなら、売らないからね？",
  str_homestory_816001001_9_dialog_content = "（どうしてですか？）",
  str_homestory_816001001_10_dialog_content = "えっ、どうしてそんなにがっかりしてるの…？",
  str_homestory_816001001_11_dialog_content = "うーん…あ、分かった！\n昔から小物集めを趣味にしていたから、がっかりさせちゃったのかな。",
  str_homestory_816001001_12_dialog_content = "たしか、ミカエルの部屋には\n変わったものがいろいろ山積みになってたよね。",
  str_homestory_816001001_13_dialog_content = "（この趣味はおかしいでしょうか…？）",
  str_homestory_816001001_14_option_content = "（認める）",
  str_homestory_816001001_15_dialog_content = "中にはもうゴミ箱行きようなものもあるのに、\n君はそういうのもわざわざ保管しているよね。",
  str_homestory_816001001_16_dialog_content = "そういうところは、他の人とは少し違っているかも。",
  str_homestory_816001001_17_option_content = "（否定する）",
  str_homestory_816001001_18_dialog_content = "人それぞれ違う趣味があるだろうし、\n僕は変だと思わないよ。",
  str_homestory_816001001_19_dialog_content = "僕はただ、ミカエルが好んで集める品物の種類って\n幅広いなあと思っているだけだよ。",
  str_homestory_816001001_20_dialog_content = "（私は、このようなものを面白く感じるので…\nそれで集めたいと思っているだけなんです）",
  str_homestory_816001001_21_dialog_content = "（ただ、このロウソクの台を買いたいのは、\n他にも理由があります）",
  str_homestory_816001001_22_dialog_content = "その理由って…？",
  str_homestory_816001001_23_dialog_content = "（ロウソクの台のロウソクは燃えていますから、\n火事を引き起こすのではないかと心配で<sprite=emo_nuhuo size=60 />）",
  str_homestory_816001001_24_dialog_content = "（あまたある災いの根源は、ほとんどが小さなものですから）",
  str_homestory_816001001_25_dialog_content = "（こういった考えは…分かりにくいでしょうか？）",
  str_homestory_816001001_26_dialog_content = "うーん、理解はできるけど…",
  str_homestory_816001001_27_dialog_content = "つまり、ミカエルは僕の安全を考えてくれてたってこと？",
  str_homestory_816001001_28_dialog_content = "（白夜城を守ることは私の役目です）",
  str_homestory_816001001_29_dialog_content = "（そして、あなたにはたくさん助けられました。\nPlayerNameさんを守ることは、私の望みでもあります）",
  str_homestory_816001001_30_dialog_content = "僕の方こそ、ミカエルにはたくさん助けられてるよ。",
  str_homestory_816001001_31_dialog_content = "でも、それって…\nロウソクの台を買うための口実とかじゃないよね？",
  str_homestory_816001001_32_dialog_content = "（もちろん違います！）",
  str_homestory_816001001_33_dialog_content = "（守護者たるもの、物事には慎重になるべきです）",
  str_homestory_816001001_34_dialog_content = "ミカエル？どうして顔が赤くなってるの？",
  str_homestory_816001001_35_dialog_content = "（それは…ロウソクの光に照らされているせいです）",
  str_homestory_816001001_36_dialog_content = "（…そういえば、先ほど川の中で光るものを見つけたのですが…）",
  str_homestory_816001001_37_dialog_content = "（それが、このロウソクの光のようだったなと…）",
  str_homestory_816001001_38_dialog_content = "話題をそらそうとしているように聞こえる…",
  str_homestory_818401001_0_dialog_content = "おーい、イェリア～。",
  str_homestory_818401001_1_dialog_content = "…",
  str_homestory_818401001_2_dialog_content = "イェリア？ねえってば。",
  str_homestory_818401001_3_dialog_content = "あら、空の末裔くんじゃな～い。",
  str_homestory_818401001_4_dialog_content = "イェリア、何してるの？ずいぶん集中してるみたいだけど…",
  str_homestory_818401001_5_dialog_content = "別に…ただボーッとしていただけよぉ。",
  str_homestory_818401001_6_dialog_content = "ボーッと…？",
  str_homestory_818401001_7_dialog_content = "そうねえ、前に話さなかったかしら。\n以前、この近くの天空ノ谷遺跡に行ったことがあるのよ。",
  str_homestory_818401001_8_dialog_content = "その頃はまだ、あなたはここに帰ってきてなかったのよねぇ。",
  str_homestory_818401001_9_dialog_content = "あの頃ここにあったのは、\n廃墟と暗鬼<sprite=emo_kulou size=60 />だけだったわ。",
  str_homestory_818401001_10_dialog_content = "うっ、それ以上言わないで。ここをきれいにするために、\nどれだけ骨を折ったことやら…",
  str_homestory_818401001_11_dialog_content = "ふふ、大変だったわねぇ。",
  str_homestory_818401001_12_dialog_content = "…そのことで、あなたに聞きたいのだけど…",
  str_homestory_818401001_13_dialog_content = "天空ノ庭を築くのは、意義のあることだと思う？",
  str_homestory_818401001_14_dialog_content = "今の天空ノ庭は確かに美しいけど、\nもし襲撃されたり、100年後にあなたもいなくなったりしたら…",
  str_homestory_818401001_15_dialog_content = "ここのすべてが廃墟に戻るかもしれないのよ。",
  str_homestory_818401001_16_option_content = "意義はある",
  str_homestory_818401001_17_dialog_content = "あるよ！少なくとも今は、皆がここに来て楽しんでいるし…",
  str_homestory_818401001_18_dialog_content = "敵が来ても、僕が追い払うさ。",
  str_homestory_818401001_19_dialog_content = "もし自分でここの世話ができなくなったら、\nそのときは信頼できる人に任せるつもりだよ。",
  str_homestory_818401001_20_dialog_content = "とにかく、絶対なんとかなる！",
  str_homestory_818401001_21_dialog_content = "空の末裔くんはポジティブねぇ。",
  str_homestory_818401001_22_option_content = "多分ないかな",
  str_homestory_818401001_23_dialog_content = "天空ノ庭を永遠に残すことが目的だとしたら…\nあまり意味はないのかもしれないね。",
  str_homestory_818401001_24_dialog_content = "自分の能力はよくわきまえているから…",
  str_homestory_818401001_25_dialog_content = "でも、少なくとも今は、僕も皆も楽しんでいる。",
  str_homestory_818401001_26_dialog_content = "なら、それで十分だよ！",
  str_homestory_818401001_27_dialog_content = "「今を生きる」という考え方は、悪くはないわねぇ。",
  str_homestory_818401001_28_dialog_content = "初めて天空ノ谷に来たとき、\nここはなんて悲しい場所なのかしらと思ったものだわ。",
  str_homestory_818401001_29_dialog_content = "ひっくり返された食器、半開きのドア、ボロボロの衣服…",
  str_homestory_818401001_30_dialog_content = "人々はそれまで平和で幸せな日々を送っていたんだなって、\n容易に想像できたわ。",
  str_homestory_818401001_31_dialog_content = "そんな日々が、タンポポの綿毛<sprite=emo_pugongying size=60 />のように、\nフーッとひと吹きで散ってしまった。",
  str_homestory_818401001_32_dialog_content = "うん…",
  str_homestory_818401001_33_dialog_content = "でもタンポポは、希望の種を\nもっと遠くに運んでいくこともできるよね。",
  str_homestory_818401001_34_dialog_content = "だから…全部が無意味だなんて、僕は思わないよ。",
  str_homestory_818401001_35_dialog_content = "…そうね、あなたのような小さな種が、\n今ここに戻って…再び芽を出しているものね。",
  str_homestory_818401001_36_dialog_content = "ふふ、あなたとお話するたびに、\n何かしらの新鮮な感銘を受けるわねぇ。",
  str_homestory_818401001_37_dialog_content = "えへへ、それほどでも…",
  str_homestory_818401001_38_dialog_content = "そうねぇ…お礼に、面白いことを教えてあげるわぁ。",
  str_homestory_818401001_39_dialog_content = "さっき川のほとりにいたら、\n川の中で何かが光っているのが見えたの。",
  str_homestory_818401001_40_dialog_content = "「探検」だと思って、行ってみてもいいかもしれないわね？",
  str_homestory_818401001_41_dialog_content = "光るものかぁ、ちょっと気になるな…ありがとう、イェリア！",
  str_homestory_818501001_0_dialog_content = "どうしたの？",
  str_homestory_818501001_1_dialog_content = "さっきコーヒーカップに乗ったら、\n頭がクラクラしてしまって<sprite=emo_xuanyun size=60 />…",
  str_homestory_818501001_2_dialog_content = "頭がクラクラする…？\nどうしてだろう、設備の調整がいまいちなのかな…？",
  str_homestory_818501001_3_dialog_content = "たしか回転数は最低にしてあったはずなんだけど…\nちょっと後で試してみるね。",
  str_homestory_818501001_4_dialog_content = "危険な遊具ですから、気をつけてくださいね！",
  str_homestory_818501001_5_dialog_content = "き、危険？",
  str_homestory_818501001_6_dialog_content = "コーヒーカップの対象年齢は、\n確か4歳以上の子どもだったと思うけど…？",
  str_homestory_818501001_7_dialog_content = "つまり、20歳の大きな子どもには\n向かないということなのかもしれませんね…",
  str_homestory_818501001_8_dialog_content = "あの回転に適応できない人もいるのは、当たり前のことだよ。",
  str_homestory_818501001_9_dialog_content = "ちょっと休めば、多少は不調も和らぐはずだから。",
  str_homestory_818501001_10_dialog_content = "そうですね…それではひとまず、帰って休みますね。\nあとで北へ配達に行かなきゃいけませんので…",
  str_homestory_818501001_11_dialog_content = "ん？南…北…",
  str_homestory_818501001_12_dialog_content = "た、大変です！方角が分からなくなってしまいました！",
  str_homestory_818501001_13_dialog_content = "私の自慢の方向感覚が…なくなって…！？",
  str_homestory_818501001_14_dialog_content = "うう…<sprite=emo_daku size=60 />これでは配達できません…\n私のキャリアは、ここでおしまいなのでしょうか…？",
  str_homestory_818501001_15_dialog_content = "えっ？そんなに深刻な状態なの…？",
  str_homestory_818501001_16_dialog_content = "PlayerNameさん、\nどの方角が北か教えてもらえませんか？",
  str_homestory_818501001_17_option_content = "左が北",
  str_homestory_818501001_18_dialog_content = "そうなんですか？ふぅ、全く判断がつきません…",
  str_homestory_818501001_19_option_content = "僕も分からない",
  str_homestory_818501001_20_dialog_content = "やっぱり、あなたまで…",
  str_homestory_818501001_21_dialog_content = "私たち、ここに閉じ込められて死ぬのでしょうか？",
  str_homestory_818501001_22_dialog_content = "？？？",
  str_homestory_818501001_23_dialog_content = "いや…普通の人は自分の家にいて、\n閉じ込められて死ぬことはないよね…？",
  str_homestory_818501001_24_dialog_content = "でも、そう言われてみれば、\n確かに自分がどこにいるのかも分からないかも…",
  str_homestory_818501001_25_dialog_content = "クーリエ隊の規則では、\n常に方向感覚を保っていなければならないのです。",
  str_homestory_818501001_26_dialog_content = "方向を見失って危険に陥り、\nその状況から抜け出せなかったクーリエはたくさんいます。",
  str_homestory_818501001_27_dialog_content = "その状況っていうのは、\n野外やジャングルを指すんじゃないかな…？",
  str_homestory_818501001_28_dialog_content = "僕たちは天空ノ庭にいるわけだし…ほら、あのゲートが見える？",
  str_homestory_818501001_29_dialog_content = "すぐそこにあるし、何歩か歩けば出られるよね。",
  str_homestory_818501001_30_dialog_content = "ですがもし、野外にいる際に今みたいにふらふらしていたら…？",
  str_homestory_818501001_31_dialog_content = "…野外にもコーヒーカップがあるの？",
  str_homestory_818501001_32_dialog_content = "はうっ、それもそうですね…",
  str_homestory_818501001_33_dialog_content = "それに本当にあったとしても、乗らなければいいんだよ。",
  str_homestory_818501001_34_dialog_content = "た、確かに！冴えていますね！",
  str_homestory_818501001_35_dialog_content = "あはは、それほどでも…",
  str_homestory_818501001_36_dialog_content = "こうしてはいられません、今すぐ帰って\nクーリエ隊の規則にこう書き加えましょう――",
  str_homestory_818501001_37_dialog_content = "「野外でコーヒーカップを見かけても、絶対に乗らないこと」！",
  str_homestory_818501001_38_dialog_content = "見かける確率自体、きっと低いだろうけどね…",
  str_homestory_818501001_39_dialog_content = "「――以上、空の末裔からの忠告」。",
  str_homestory_818501001_40_dialog_content = "！！！",
  str_homestory_818501001_41_dialog_content = "って、待って！お金なら出すから！\nいくら払えば書かないでもらえる…！？",
  str_homestory_818501001_42_dialog_content = "えっ、どうしてですか？\nこれは紛れもなく役に立つ忠告ですよ！では、お先に失礼しますね！",
  str_homestory_818501001_43_dialog_content = "うう、どうしよう…\nこのままじゃクーリエ隊の笑いものになっちゃうよ…<sprite=emo_tanqi size=60 />",
  str_homestory_802901001_0_dialog_content = "ガブリエル？",
  str_homestory_802901001_1_dialog_content = "何してるの？",
  str_homestory_802901001_2_dialog_content = "木の下でひと休みしてるの<sprite=emo_kun size=60 />。\nついでに木の呼吸を感じてるのよ。",
  str_homestory_802901001_3_dialog_content = "木の呼吸？",
  str_homestory_802901001_4_dialog_content = "そうよ…木も生きものだもの。",
  str_homestory_802901001_5_dialog_content = "私には木の呼吸のリズムが分かるの。\nPlayerNameはどう？",
  str_homestory_802901001_6_option_content = "（肯定する）",
  str_homestory_802901001_7_dialog_content = "葉っぱが揺れてる時は\n息づかいが荒くなってるみたいに感じるね。",
  str_homestory_802901001_8_dialog_content = "…いや、ただ風が吹いただけだね…",
  str_homestory_802901001_9_option_content = "（否定する）",
  str_homestory_802901001_10_dialog_content = "うーん、僕には分からないな…",
  str_homestory_802901001_11_dialog_content = "植物を理解する特殊な能力は、\nやっぱりガブリエルにしかないみたいだね。",
  str_homestory_802901001_12_dialog_content = "木にも個性があるの。\n人に個性があるのと同じようにね。",
  str_homestory_802901001_13_dialog_content = "心で感じようとすれば…\n木たちの息づかいを感じられるわ。",
  str_homestory_802901001_14_dialog_content = "ほら、この子は呼吸が少し乱れてる。\nう～ん、どこか悪いみたいね…",
  str_homestory_802901001_15_dialog_content = "そう言われてみれば、この木の葉っぱは\n他の木の葉っぱより黄色っぽい気がするね。",
  str_homestory_802901001_16_dialog_content = "ちょっと元気がなさそうに見える。",
  str_homestory_802901001_17_dialog_content = "周りの木がよく茂ってるせいで、\n日差しが遮られてるのね<sprite=emo_taiyang size=60 />。",
  str_homestory_802901001_18_dialog_content = "この子はきちんと光合成ができてないのね。",
  str_homestory_802901001_19_dialog_content = "そうだったんだ…じゃあ、別の場所に植え替える？",
  str_homestory_802901001_20_dialog_content = "その必要はないわ。植物には植物の生き方があるの。",
  str_homestory_802901001_21_dialog_content = "この子が頑張って大きくならなかったから、\n他の子に太陽の光をとられちゃったのよ…",
  str_homestory_802901001_22_dialog_content = "自分の力で生き抜いてこそ本当に成長できるの…\n甘やかしすぎはいけないわ。",
  str_homestory_802901001_23_dialog_content = "そうだね。ガブリエルの言う通りだ！",
  str_homestory_802901001_24_dialog_content = "ええ。PlayerNameには\n分かってもらえないかと思ってたけど…",
  str_homestory_802901001_25_dialog_content = "そんなことないよ。むしろ驚いてるんだ――",
  str_homestory_802901001_26_dialog_content = "いつもぼーっとしてるガブリエルが\n急にしっかりしたこと言うから。",
  str_homestory_802901001_27_dialog_content = "あら、「気まま」と言ってもらいたいわ…",
  str_homestory_802901001_28_dialog_content = "植物にも「運命」ってものがあるの…",
  str_homestory_802901001_29_dialog_content = "「運命」…？",
  str_homestory_802901001_30_dialog_content = "ええ。木の下であなたと出会ったのも「運命」よ。",
  str_homestory_802901001_31_dialog_content = "そういえば、さっき川沿いを歩いてた時、\n何か光るものが見えたわ…",
  str_homestory_802901001_32_dialog_content = "何が光ってるのか確かめてはみなかったの？",
  str_homestory_802901001_33_dialog_content = "ええ。だって、私の目的は森でひと休みすることだもの。",
  str_homestory_802901001_34_dialog_content = "川の中をのぞかなかったのも、「運命」よ。",
  str_homestory_802901001_35_dialog_content = "ガブリエルの言う「運命」が何か、分かった気がする…",
  str_homestory_818901001_0_dialog_content = "ライン、何してるんだろう？",
  str_homestory_818901001_1_dialog_content = "お～い、ライン！",
  str_homestory_818901001_2_dialog_content = "ウイスキーボンボン、ジャム入りチョコ<sprite=emo_sikao size=60 />…おや？",
  str_homestory_818901001_3_dialog_content = "ごきげんよう。",
  str_homestory_818901001_4_dialog_content = "そんなに真剣に何を見てるの？",
  str_homestory_818901001_5_dialog_content = "大したものではありません。\nチョコレートを見ていただけです。",
  str_homestory_818901001_6_dialog_content = "冠月祭限定のチョコレートだね。",
  str_homestory_818901001_7_dialog_content = "食べたければ、好きなだけ食べるといいよ！",
  str_homestory_818901001_8_dialog_content = "いいえ、食べたいわけではありません。\nずいぶんと手の込んだチョコレートだ\nとただ感心していたのです。",
  str_homestory_818901001_9_dialog_content = "私もよくチョコレート菓子を作るもので。",
  str_homestory_818901001_10_dialog_content = "ただ私の場合、溶かしたチョコレートを\n飾りにするだけでして…",
  str_homestory_818901001_11_dialog_content = "街で売られているお菓子の技術が、\nまさかここまで進んでいるとは思いませんでした…",
  str_homestory_818901001_12_dialog_content = "それはそうと、チョコレートはお好きですか？",
  str_homestory_818901001_13_option_content = "好きだよ！",
  str_homestory_818901001_14_dialog_content = "でしたら、新しい作り方を学び、\n出来たものを召し上がっていただくことにしましょう。",
  str_homestory_818901001_15_dialog_content = "ウイスキーボンボンは少々早いでしょうから…",
  str_homestory_818901001_16_dialog_content = "ジャム入りチョコレートにしましょう。",
  str_homestory_818901001_17_option_content = "好きじゃないんだ…",
  str_homestory_818901001_18_dialog_content = "そうですか…それは残念ですね。",
  str_homestory_818901001_19_dialog_content = "では、今度別のお菓子をお持ちしますね。",
  str_homestory_818901001_20_dialog_content = "何か食べたいものがあれば、\nいつでもおっしゃってください。",
  str_homestory_818901001_21_dialog_content = "うん、ありがとう、ライン！",
  str_homestory_818901001_22_dialog_content = "ううむ…",
  str_homestory_818901001_23_dialog_content = "ライン、どうしたの？\nなんでまだチョコレートを眺めてるの？",
  str_homestory_818901001_24_dialog_content = "もしかして…チョコレート、食べてみたいの？",
  str_homestory_818901001_25_dialog_content = "ち、違います！どのような味なのか\n少々興味があっただけです！<sprite=emo_hanshui size=60 />",
  str_homestory_818901001_26_dialog_content = "今度自分で一箱買ってきます！",
  str_homestory_818901001_27_dialog_content = "そんな遠慮しなくていいんだよ。",
  str_homestory_818901001_28_dialog_content = "食べたければ食べるといいよ！",
  str_homestory_818901001_29_dialog_content = "誰にだって、どうしても食べたい時はあるでしょ？",
  str_homestory_818901001_30_dialog_content = "ええと、それは…",
  str_homestory_818901001_31_dialog_content = "ご好意に感謝いたします。それでは、遠慮なく…",
  str_homestory_818601001_0_dialog_content = "ティナ？",
  str_homestory_818601001_1_dialog_content = "どうしてここに？",
  str_homestory_818601001_2_dialog_content = "PlayerNameさん、ごきげんよう。",
  str_homestory_818601001_3_dialog_content = "この椅子、とても面白いですわね。",
  str_homestory_818601001_4_dialog_content = "あ、ビーチチェアのこと？",
  str_homestory_818601001_5_dialog_content = "ええ…これ、ビーチチェアだったのですね…",
  str_homestory_818601001_6_dialog_content = "実は私、海のことはよく知りませんの。\nほとんどの時間を白夜城の法廷で過ごしていますから。",
  str_homestory_818601001_7_dialog_content = "PlayerNameさんはよく海に行かれるのですか？",
  str_homestory_818601001_8_option_content = "よく行くよ",
  str_homestory_818601001_9_dialog_content = "僕はよく海に行くんだ。",
  str_homestory_818601001_10_dialog_content = "本当に面白いところだよ！",
  str_homestory_818601001_11_option_content = "めったに行かないよ",
  str_homestory_818601001_12_dialog_content = "実は僕もよく行くわけじゃないんだ。",
  str_homestory_818601001_13_dialog_content = "でも、海は面白いところだよ。すごく印象に残ってる。",
  str_homestory_818601001_14_dialog_content = "そうですか。",
  str_homestory_818601001_15_dialog_content = "では、今度是非ご一緒したいですわ。",
  str_homestory_818601001_16_dialog_content = "ただ、処理しなければいけない案件がたくさんあって、\nとても忙しいのです。",
  str_homestory_818601001_17_dialog_content = "またチャンスはあるよ。",
  str_homestory_818601001_18_dialog_content = "ただ、海では水着を着るのが普通だけど…\nティナは抵抗ない？",
  str_homestory_818601001_19_dialog_content = "水着ですか…本で読んだことがあります。\n肌の露出の多い服のようですね<sprite=emo_qunzi size=60 />？",
  str_homestory_818601001_20_dialog_content = "そうなんだ。白夜城貴族の服は、\n海ではちょっと堅苦しすぎるから…",
  str_homestory_818601001_21_dialog_content = "時や場所が変われば、\n服装も変えるべきということですね。\n私は気にしませんわ。",
  str_homestory_818601001_22_dialog_content = "ただ、一族の年長者たちは\n私を「恥知らず」と責めるでしょう。\nそれが少々厄介ですわ。",
  str_homestory_818601001_23_dialog_content = "はは…今はそんな先のことまで\n心配しなくても大丈夫だよ…",
  str_homestory_818601001_24_dialog_content = "まだいつ行けるかも分からないし…",
  str_homestory_818601001_25_dialog_content = "それもそうですわね。",
  str_homestory_818601001_26_dialog_content = "それより、ビーチチェアに座ってみたら？",
  str_homestory_818601001_27_dialog_content = "ええ！先程からずっと座ってみたかったんです。",
  str_homestory_818601001_28_dialog_content = "私のあつらえものの寝椅子ほど\nふかふかはしていませんが、\nこれも心地よいですわ。",
  str_homestory_818601001_29_dialog_content = "海ではこの材質の方が使い勝手がいいんだよ。",
  str_homestory_818601001_30_dialog_content = "あれ、ティナ？聞いてる？",
  str_homestory_818601001_31_dialog_content = "寝ちゃってる…",
  str_homestory_819001001_0_dialog_content = "マシュー？",
  str_homestory_819001001_1_dialog_content = "ちょうどよいところに来た。",
  str_homestory_819001001_2_dialog_content = "このガゼボ、古式ゆかしく実に素晴らしいではないか。\n茶や読書を楽しむのにふさわしい。",
  str_homestory_819001001_3_dialog_content = "だが、まだ足りぬものがある――",
  str_homestory_819001001_4_dialog_content = "何が足りないの？",
  str_homestory_819001001_5_dialog_content = "今のままではあまりにも\n味気無さすぎるとは思わんのか？",
  str_homestory_819001001_6_option_content = "思わないよ",
  str_homestory_819001001_7_option_content = "飾りっ気がないね",
  str_homestory_819001001_8_dialog_content = "あとでクッションを持ってくるよ。\nそうすれば、さみしくないでしょ。",
  str_homestory_819001001_9_dialog_content = "いや、珍しい草花や金銀を施した\n茶器を置かねばならん。\n私のような貴族にふさわしいようにな。",
  str_homestory_819001001_10_dialog_content = "珍しい草花に金銀を施した茶器…\nちょっとぜいたくすぎない？",
  str_homestory_819001001_11_dialog_content = "金の心配をしておるのか<sprite=emo_baiyebi size=60 />？\nまったく、空の末裔とはしみったれた一族だ。",
  str_homestory_819001001_12_dialog_content = "金のことは心配するな。私に任せておけばよい。",
  str_homestory_819001001_13_dialog_content = "お金の問題じゃないよ。\nもちろん、お金がかかるのは困るから…",
  str_homestory_819001001_14_dialog_content = "君が出してくれるっていうなら、\nそれでもいいんだけど…",
  str_homestory_819001001_15_dialog_content = "では、いったい何が言いたい！？",
  str_homestory_819001001_16_dialog_content = "ここは天空ノ庭だよ。\n皆で一緒に暮らしてる場所なんだ。",
  str_homestory_819001001_17_dialog_content = "皆が皆はなやかな草花や金銀を施した食器が\n好きなわけじゃないでしょ。",
  str_homestory_819001001_18_dialog_content = "だから、あまり豪華にしたくないんだ。\n居心地が悪いって思う仲間もいるだろうから。",
  str_homestory_819001001_19_dialog_content = "まともな生活を送ったことのない者どもを\n気遣っておるのか？",
  str_homestory_819001001_20_dialog_content = "花や金銀に囲まれた生活が\nまともってこともないと思うけど…",
  str_homestory_819001001_21_dialog_content = "とにかく、すぐに用意させる。",
  str_homestory_819001001_22_dialog_content = "ちょっと待って。ここの主は僕だよ。\n決定権は僕にあるんだ。",
  str_homestory_819001001_23_dialog_content = "皆と一緒に暮らすなら、自分と違う人とも\nうまく付き合えるようにならなきゃ。",
  str_homestory_819001001_24_dialog_content = "むむ、なぜ急にそんな真面目くさったことを\n言い出すのだ？",
  str_homestory_819001001_25_dialog_content = "それとも…<size=45>シュワーベのマネ</size>してるの！？",
  str_homestory_819001001_26_dialog_content = "なに？今何と言ったか？",
  str_homestory_819001001_27_dialog_content = "シュワーベも花に囲まれたガゼボで本を読むのが好きで、\nそれを見かけた女の子たちは\n皆シュワーベに夢中になっちゃったって聞いたよ。",
  str_homestory_819001001_28_dialog_content = "マシューも同じことをすれば、\n女の子たちの注意が引けるって思ってるの？",
  str_homestory_819001001_29_dialog_content = "シュワーベみたいにモテたいから、\nマネしようとしてるんだね。",
  str_homestory_819001001_30_dialog_content = "なるほど…",
  str_homestory_819001001_31_dialog_content = "何を言っておるのだ！勝手に「謎は解けた」\nと言わんばかりの顔をするでない！<sprite=emo_shengqi size=60 />",
  str_homestory_819001001_32_dialog_content = "そんなわけないであろう！\n誰があんなバカ者のマネをするか！？",
  str_homestory_819001001_33_dialog_content = "「バカ者」って一瞬罵ってるように聞こえるけど…",
  str_homestory_819001001_34_dialog_content = "実は好感をもってる相手にもよく使うよね。",
  str_homestory_819001001_35_dialog_content = "まったく吐き気がする…",
  str_homestory_819001001_36_dialog_content = "私は黎明学院の歴史に残る天才であるぞ！",
  str_homestory_819001001_37_dialog_content = "女の前で格好つけることしか\n頭にないバカ者のマネなど、\nするはずないではないか！",
  str_homestory_819001001_38_dialog_content = "じゃあ、どうしてガゼボに花と茶器を置きたいの？",
  str_homestory_819001001_39_dialog_content = "貴族のたしなみだからに決まっておろうが！",
  str_homestory_819001001_40_dialog_content = "話にならん！\nどう飾り付けしようとお前の好きにするがいい！",
  str_homestory_819001001_41_dialog_content = "私の知ったことか！",
  str_homestory_819001001_42_dialog_content = "（あんなに怒るってことは…\nまさか本当にただ本を読むためだったのかな？）",
  str_homestory_819101001_0_dialog_content = "ハーティ？",
  str_homestory_819101001_1_dialog_content = "何してるの？",
  str_homestory_819101001_2_dialog_content = "本棚の本と会話していたんだ。",
  str_homestory_819101001_3_dialog_content = "えっ？どうやって本と会話するの？<sprite=emo_yihuo size=60 />",
  str_homestory_819101001_4_dialog_content = "質問するだけで、本がページに答えを示してくれる。\nおまけにその答えは恐ろしいほど正しい。",
  str_homestory_819101001_5_dialog_content = "どんな質問をしたの？",
  str_homestory_819101001_6_dialog_content = "物語を聞きたかったから、\n答えの本に物語を話してくれるよう頼んだんだ。",
  str_homestory_819101001_7_dialog_content = "どんな物語？ホラー？",
  str_homestory_819101001_8_dialog_content = "怖くないのか？",
  str_homestory_819101001_9_option_content = "ちょっと怖い",
  str_homestory_819101001_10_dialog_content = "でも、ちょっと興味あるんだ。",
  str_homestory_819101001_11_option_content = "怖くない",
  str_homestory_819101001_12_dialog_content = "男なのに本を怖がるはずないでしょ？",
  str_homestory_819101001_13_dialog_content = "その本の語った物語とはこんな感じだ――",
  str_homestory_819101001_14_dialog_content = "「寒い冬の夜、1人で本棚の前で本を読んでいた時…」",
  str_homestory_819101001_15_dialog_content = "「ふと背後で気配を感じた。\nその時、目の前にある答えの本に\nゆっくりと文字が浮かび上がった――」",
  str_homestory_819101001_16_dialog_content = "「振り向いてはいけない。背後に<size=45>誰かいる</size>」",
  str_homestory_819101001_17_dialog_content = "「すごく怖かったが、\nそれでも振り返らずにはいられなかった」",
  str_homestory_819101001_18_dialog_content = "そこまで読んで、\n振り向くとアンタがやって来るのが見えたんだ。",
  str_homestory_819101001_19_dialog_content = "アハハ。お決まりのサスペンス小説の出だしだね。\nでも、実際の場景と結び合わせるとは意外だね。\nそれでどうなったの？",
  str_homestory_819101001_20_dialog_content = "「背後にいるのは誰かではなく、大家だ」",
  str_homestory_819101001_21_dialog_content = "「安心するといい。大家は弱く、ワンパンで倒せる」",
  str_homestory_819101001_22_dialog_content = "どういうこと！？その答えの本はデタラメだよ！",
  str_homestory_819101001_23_dialog_content = "実際の状況ととても合っていると言わざるを得ない。\nだから夢中になってしまったんだ――",
  str_homestory_819101001_24_dialog_content = "「背後から脅してきた大家を非難し、軽く殴った」",
  str_homestory_819101001_25_dialog_content = "「あなたは大家を殴り倒し、部屋から追い出される。\nそして路上をさまよい、風邪をひいて野垂れ死ぬ」",
  str_homestory_819101001_26_dialog_content = "ほら。この物語はリアルで怖いだろ。\n大家さん、ボクはアンタを殴ったりしないよ。",
  str_homestory_819101001_27_dialog_content = "僕だって君を追い出したりしないよ。\nいや、君にワンパンで倒されたりしないよ！",
  str_homestory_819101001_28_dialog_content = "試してみる？",
  str_homestory_819101001_29_dialog_content = "もちろん！<sprite=emo_dianzan size=60 />",
  str_homestory_819101001_30_dialog_content = "待ってて、ちょっと体をほぐすから。",
  str_homestory_819101001_31_dialog_content = "ぼ、僕が言っているのは、この答えの本のことだよ。",
  str_homestory_819101001_32_dialog_content = "何を聞きたいんだ？",
  str_homestory_819101001_33_dialog_content = "本当にどんな質問にも答えてくれるの？",
  str_homestory_819101001_34_dialog_content = "実は最近、ちょっと悩んでいるんだよ。\nバイスから今月の巨像の収支をまとめるように\nせっつかれていて…",
  str_homestory_819101001_35_dialog_content = "さっき食堂で、\nアンタたちがそのことを話しているのを聞いたよ。",
  str_homestory_819101001_36_dialog_content = "だから真っ先にそのことを答えの本に聞いたよ。\n答えは――",
  str_homestory_819101001_37_dialog_content = "「私はただの本です。資産を持たないため、\n収支表をまとめる手助けはできません」だとさ。",
  str_homestory_819101001_38_dialog_content = "ちぇっ。本当にすごい本なのかと思ったのに。",
  str_homestory_819101001_39_dialog_content = "その質問に答えの本はいらないよ。\nボクがアンタに答えてあげる。",
  str_homestory_819101001_40_dialog_content = "どういうこと？",
  str_homestory_819101001_41_dialog_content = "巨像の収支はバランスを著しく損なっている。\nアンタはもうすぐ破産して、\n路上をさまよい、風邪をひいて野垂れ死ぬ。",
  str_homestory_819101001_42_dialog_content = "答えの本の回答をそのまま使わないでよ！",
  str_homestory_819101001_43_dialog_content = "だって本当にその通りだから。",
  str_homestory_819101001_44_dialog_content = "全然その通りじゃない…でしょ？ううう…",
  str_homestory_817702001_0_dialog_content = "ゴルディが歌ってる！",
  str_homestory_817702001_1_dialog_content = "ラララ～♪",
  str_homestory_817702001_2_dialog_content = "…あら？PlayerNameじゃないの。\nこんにちは。",
  str_homestory_817702001_3_dialog_content = "やあ、ゴルディ。",
  str_homestory_817702001_4_dialog_content = "ごめん、邪魔しちゃったかな？",
  str_homestory_817702001_5_dialog_content = "そんなことないよ！",
  str_homestory_817702001_6_dialog_content = "このバイオリンを見ていたら、\n思わず歌いたくなっちゃっただけだから。",
  str_homestory_817702001_7_dialog_content = "それにしても、PlayerNameが\nバイオリンを持っているなんて意外だわ。",
  str_homestory_817702001_8_dialog_content = "まさか…実は楽器に興味があるとか？",
  str_homestory_817702001_9_option_content = "興味あるよ",
  str_homestory_817702001_10_dialog_content = "うん、楽器が好きなんだ！",
  str_homestory_817702001_11_dialog_content = "でも、興味があるだけで、何一つ弾けないけどね。\nアハハ…",
  str_homestory_817702001_12_dialog_content = "それはよかったわ！",
  str_homestory_817702001_13_dialog_content = "PlayerNameと共有できる話題がまた増えたわ！",
  str_homestory_817702001_14_option_content = "普通",
  str_homestory_817702001_15_dialog_content = "うん、まあ普通かな。好きってほどでは…",
  str_homestory_817702001_16_dialog_content = "でも楽器を弾けるようになったら…\nゴルディに演奏してあげるよ！",
  str_homestory_817702001_17_dialog_content = "本当？うふふ、ありがとう！",
  str_homestory_817702001_18_dialog_content = "でも…",
  str_homestory_817702001_19_dialog_content = "このバイオリンはただの楽器じゃないんだよ。",
  str_homestory_817702001_20_dialog_content = "実はある名探偵と同タイプのコレクションなんだ！",
  str_homestory_817702001_21_dialog_content = "名探偵？",
  str_homestory_817702001_22_dialog_content = "うん。その名探偵は、推理の合間にバイオリンを弾くのが大好きなんだって。",
  str_homestory_817702001_23_dialog_content = "詳しいことは僕も知らないんだ…",
  str_homestory_817702001_24_dialog_content = "でも、そんな多芸多才な探偵って、\nなんだかロマンチック<sprite=emo_aixin size=60 />だよね！",
  str_homestory_817702001_25_dialog_content = "そうだったのね～。",
  str_homestory_817702001_26_dialog_content = "理性的で冷酷そうな探偵でありながら、\n静かな夜更けに1人でバイオリンを奏でる…",
  str_homestory_817702001_27_dialog_content = "その光景は…\nうん、インスピレーションが湧いてきたわ！",
  str_homestory_817702001_28_dialog_content = "なんのインスピレーション？",
  str_homestory_817702001_29_dialog_content = "新しい曲<sprite=emo_yinfu size=60 />のインスピレーションよ！",
  str_homestory_817702001_30_dialog_content = "そのときには新しい公演衣装を作れるし、\n特別な振り付けも合わせられるわ。",
  str_homestory_817702001_31_dialog_content = "考えただけでワクワクしてきた！",
  str_homestory_817702001_32_dialog_content = "探偵をテーマとしたアイドルのライブ…",
  str_homestory_817702001_33_dialog_content = "すごくよさそう！",
  str_homestory_817702001_34_dialog_content = "さすがゴルディだね！",
  str_homestory_817702001_35_dialog_content = "エヘヘ、その時はあなたも盛り上げに来てよね！",
  str_homestory_811602001_0_dialog_content = "フェラール、何しているの？",
  str_homestory_811602001_1_dialog_content = "やあ、フェラール！何しているの？",
  str_homestory_811602001_2_dialog_content = "やあ、ナビゲーター！",
  str_homestory_811602001_3_dialog_content = "この置物を直しているんだ。",
  str_homestory_811602001_4_dialog_content = "何気なく手に取って見たんだが…",
  str_homestory_811602001_5_dialog_content = "どうもこいつの音がおかしくてな。",
  str_homestory_811602001_6_dialog_content = "音？",
  str_homestory_811602001_7_dialog_content = "ああ。どこかのネジがきつく締まりすぎているのか、\nあるいは潤滑油が足りないのかもしれないな。",
  str_homestory_811602001_8_dialog_content = "車輪からずっと「ガガガ」という音がするんだ。",
  str_homestory_811602001_9_option_content = "そうだったんだ",
  str_homestory_811602001_10_dialog_content = "たしかにその置物には問題があるみたいだね…",
  str_homestory_811602001_11_dialog_content = "そんな音がするってことは、\n部品の状態がおかしいのかな？",
  str_homestory_811602001_12_dialog_content = "そうなんだ！",
  str_homestory_811602001_13_dialog_content = "こういう問題は普通の人には理解しにくいんだ。\nどうやらキミにも機械修理の才能があるようだな。",
  str_homestory_811602001_14_dialog_content = "そうかな？ヘヘヘ。",
  str_homestory_811602001_15_option_content = "分からないな",
  str_homestory_811602001_16_dialog_content = "そうなんだ…",
  str_homestory_811602001_17_dialog_content = "フェラールみたいなプロはすごいね。\n僕のような素人にはさっぱり分からないよ。",
  str_homestory_811602001_18_dialog_content = "そうか…\nキミと機械の問題について話せると思っていたんだが…",
  str_homestory_811602001_19_dialog_content = "大丈夫だ。俺だけでも直せるから。",
  str_homestory_811602001_20_dialog_content = "うーん…\nここのネジをきつく締めすぎているみたいだな…",
  str_homestory_811602001_21_dialog_content = "残念ながら、適した工具が手元にない。",
  str_homestory_811602001_22_dialog_content = "工具が見つかったら、また修理に戻ってくる。",
  str_homestory_811602001_23_dialog_content = "じゃあよろしくね！",
  str_homestory_811602001_24_dialog_content = "大丈夫だ。大した問題ではないからな。",
  str_homestory_811602001_25_dialog_content = "だが、機械にとっては、\nこのような小さな見落としも命取りになることがある。",
  str_homestory_811602001_26_dialog_content = "これがただの置物でよかった。\nもし本物のワゴンだったら…",
  str_homestory_811602001_27_dialog_content = "今頃は車輪が壊れてしまっていたかもしれないな。\nハハハ。",
  str_homestory_811602001_28_dialog_content = "うん。僕たちみたいな普通の人は、本当に壊れるまで、\n直さないといけないって分からないよ。",
  str_homestory_811602001_29_dialog_content = "どの機械もソラヴァンみたいに、\n自分の問題点を話せればいいのにな。",
  str_homestory_811602001_30_dialog_content = "そうか…？",
  str_homestory_811602001_31_dialog_content = "俺に言わせれば、\n皆の言うことの方が分かりにくいがな<sprite=emo_sikao size=60 />。",
  str_homestory_811602001_32_dialog_content = "機械に「人格」を与えられれば、\nたしかに快挙だろうな…",
  str_homestory_811602001_33_dialog_content = "だが、機械までもがあんなお茶を濁した話し方を\nするなんて、まっぴらごめんだぜ！",
  str_homestory_811602001_34_dialog_content = "アハハ…それもそうだね。",
  str_homestory_811602001_35_dialog_content = "いつの日か、機械も個性を持つようになったら、\nフェラールはきっと頭が痛くなるだろうね！",
  str_homestory_808401001_0_dialog_content = "イスタバンさんも謎解きが好きなんですか？",
  str_homestory_808401001_1_dialog_content = "ちょうどいいところに来たな。",
  str_homestory_808401001_2_dialog_content = "この手掛かりの図面をどう思う？",
  str_homestory_808401001_3_dialog_content = "僕がどう思うかですか？僕は…",
  str_homestory_808401001_4_option_content = "ヒントがあると思います",
  str_homestory_808401001_5_dialog_content = "この中の手掛かりのいくつかが怪しいと思います<sprite=emo_sikao size=60 />。",
  str_homestory_808401001_6_dialog_content = "もう少し時間をください。\n答えにたどり着けるかもしれません！",
  str_homestory_808401001_7_option_content = "分かりません",
  str_homestory_808401001_8_dialog_content = "うーん…僕、謎解きは苦手なんです<sprite=emo_tanqi size=60 />。",
  str_homestory_808401001_9_dialog_content = "さっぱり分かりません…",
  str_homestory_808401001_10_dialog_content = "そうか。",
  str_homestory_808401001_11_dialog_content = "すまない。お前が先に聞いてきたのに、\n質問で返してしまったな。",
  str_homestory_808401001_12_dialog_content = "お前の疑問に答えてやろう…",
  str_homestory_808401001_13_dialog_content = "俺は謎解きが嫌いだ。",
  str_homestory_808401001_14_dialog_content = "えっ？じゃあ、イスタバンさんはどうして\n推理の黒板をじっと見つめているんですか？",
  str_homestory_808401001_15_dialog_content = "焦るな、若者よ。\nゆっくりとお前の疑問に答えさせてくれ。",
  str_homestory_808401001_16_dialog_content = "先ほどの話からして、お前はこの手掛かりの図面を\n「謎」と見なしているようだな。",
  str_homestory_808401001_17_dialog_content = "つまり、お前は気付かないうちに\n「探偵」の視野で物事を見ていたのだ。",
  str_homestory_808401001_18_dialog_content = "ええ、そうです。",
  str_homestory_808401001_19_dialog_content = "だが実際には、この「対局」の中には、\nさまざまな役割がある。",
  str_homestory_808401001_20_dialog_content = "「探偵」、「犯人」、「被害者」…",
  str_homestory_808401001_21_dialog_content = "そして「黒幕」。",
  str_homestory_808401001_22_dialog_content = "「黒幕」ですか？",
  str_homestory_808401001_23_dialog_content = "黒幕は羊飼いのような者で、すべての創造者であり、\n受益者でもあるべき存在だ。",
  str_homestory_808401001_24_dialog_content = "犬を使って羊を放し飼いし、羊の群れを集め、\nオオカミから羊を守る…",
  str_homestory_808401001_25_dialog_content = "優れた羊飼いは、\n決して牧場の管理を運任せにしないものだ。",
  str_homestory_808401001_26_dialog_content = "だから黒幕も謎を解くのではなく、\n自分に有利な真相を自ら選ぶのだ。",
  str_homestory_808401001_27_dialog_content = "は、はぁ…複雑ですね！",
  str_homestory_808401001_28_dialog_content = "イスタバンさんがおっしゃりたいことって、つまり…",
  str_homestory_808401001_29_dialog_content = "イスタバンさんみたいなリーダーは、\n真相よりも結果を重視しているということですか？",
  str_homestory_808401001_30_dialog_content = "いかにも。その理解で正しい。",
  str_homestory_808401001_31_dialog_content = "お前はまだ若いが、多様な可能性を持っているな。",
  str_homestory_808401001_32_dialog_content = "だが、お前のようなナビゲーターには、\n駒を自分のために動かせるようになってもらいたい。",
  str_homestory_808401001_33_dialog_content = "子羊とは違い、\n賢さのもたらす心地よさに溺れないでほしい。",
  str_homestory_808401001_34_dialog_content = "ハハ、アハハ…\nそんなの、僕にはまだ早すぎると思いますよ…",
  str_homestory_808401001_35_dialog_content = "…それもそうだな。\n焦ってお前の意気込みをくじくこともあるまい。",
  str_homestory_808401001_36_dialog_content = "では、少年らしい冒険をするがいい。",
  str_homestory_808401001_37_dialog_content = "先ほど川の中にキラキラ光るコインが見えたぞ<sprite=emo_baiyebi size=60 />。",
  str_homestory_808401001_38_dialog_content = "はっきりとは見えなかったが、\n俺が思うに、あれは貴重な代物だろう。",
  str_homestory_808401001_39_dialog_content = "探しにいってみるといい。",
  str_homestory_808401001_40_dialog_content = "ありがとうございます、イスタバンさん！",
  str_homestory_819301001_0_dialog_content = "クリステン？",
  str_homestory_819301001_1_dialog_content = "クリステン、何をしてるの？",
  str_homestory_819301001_2_dialog_content = "ふんふんふ～ん<sprite=emo_yinfu size=60 />。",
  str_homestory_819301001_3_dialog_content = "音楽を聴いています。",
  str_homestory_819301001_4_dialog_content = "あなたのレコードプレーヤーがきれいだったので、\n聴いてみたのです。",
  str_homestory_819301001_5_dialog_content = "どうだった？",
  str_homestory_819301001_6_dialog_content = "最高です！きれいで感動的な音質です。\n素晴らしいレコードプレーヤーですね。",
  str_homestory_819301001_7_dialog_content = "PlayerNameさんは\nいつからこの趣味をお持ちになったのですか？",
  str_homestory_819301001_8_dialog_content = "時々、各地で見かけた美しい品を集めるんだよ。",
  str_homestory_819301001_9_dialog_content = "でも、クリステンは似たような\nレコードプレーヤーをたくさん見てきたでしょ？",
  str_homestory_819301001_10_dialog_content = "はい。私の一族の農場では、たくさんの\nレコードプレーヤーのコレクションがあるのですが、\nその中に特別なものもございます。",
  str_homestory_819301001_11_dialog_content = "おそらく――",
  str_homestory_819301001_12_dialog_content = "法廷の正面玄関の廊下ほどの高さがあります。",
  str_homestory_819301001_13_dialog_content = "え、ええ？",
  str_homestory_819301001_14_dialog_content = "法廷の正面玄関の廊下って…\nものすごく高さがあるんじゃない？",
  str_homestory_819301001_15_dialog_content = "ショーのステージにできるくらいだよね！",
  str_homestory_819301001_16_dialog_content = "父のような貴族の好みは、\n時としてまったく理解できません。",
  str_homestory_819301001_17_dialog_content = "クリステンも貴族なのに…",
  str_homestory_819301001_18_dialog_content = "あっ、私は父とは違いますから。",
  str_homestory_819301001_19_dialog_content = "PlayerNameさんは、\n私があのような古い貴族と同じだと思いますか？",
  str_homestory_819301001_20_option_content = "違うと思う",
  str_homestory_819301001_21_dialog_content = "クリステンは新しい流行を追いかけるのが好きだよね。",
  str_homestory_819301001_22_dialog_content = "たとえば音楽の分野とかでは。",
  str_homestory_819301001_23_option_content = "同じに見える時もある",
  str_homestory_819301001_24_dialog_content = "クリステンは僕が会った貴族たちみたいに、\nとても教養があるからね。",
  str_homestory_819301001_25_dialog_content = "なるほど。PlayerNameさんは\nそうお考えだったのですね。",
  str_homestory_819301001_26_dialog_content = "ですが、あなたのおっしゃる通りだと思います。",
  str_homestory_819301001_27_dialog_content = "私の体には貴族の血が流れていますが――",
  str_homestory_819301001_28_dialog_content = "心では貴族とは異なる道を歩みたいと願っています。",
  str_homestory_819301001_29_dialog_content = "新しい流行の音楽から、\n新しいインスピレーションを得ました！",
  str_homestory_819301001_30_dialog_content = "待って！",
  str_homestory_819301001_31_dialog_content = "クリステン、ここで歌うつもり？",
  str_homestory_819301001_32_dialog_content = "はい。レコードプレーヤーの音楽に合わせて\n歌えばちょうどいいですからね。あ～<sprite=emo_yinfu size=60 />",
  str_homestory_819301001_33_dialog_content = "ちょっと待って！",
  str_homestory_819301001_34_dialog_content = "もうこんな時間だ。用があった気がするので、\nお先に失礼するよ。",
  str_homestory_819301001_35_dialog_content = "今からですか？",
  str_homestory_819301001_36_dialog_content = "うん…君は自由にやってよ！存分に歌っていいから！",
  str_homestory_819201001_0_dialog_content = "レオ？",
  str_homestory_819201001_1_dialog_content = "ちょうどルーペを探していたところだ。\nここにあったとはな。",
  str_homestory_819201001_2_dialog_content = "何に使うの？",
  str_homestory_819201001_3_dialog_content = "地図を見るのだ。",
  str_homestory_819201001_4_dialog_content = "少し前に辺境地域の各軍事要塞の位置を部下に調べさせたのだ。",
  str_homestory_819201001_5_dialog_content = "今日その地図が完成した。",
  str_homestory_819201001_6_dialog_content = "だが、雑な小さな字で書き込みがしてあってな。\n頭を悩ませていたところだ<sprite=emo_xuanyun size=60 />。",
  str_homestory_819201001_7_dialog_content = "地図に書き込み？",
  str_homestory_819201001_8_dialog_content = "見るがいい。",
  str_homestory_819201001_9_dialog_content = "「トワイライトシティ周囲80km以内にある軍事要塞の調査によって判明した…」",
  str_homestory_819201001_10_dialog_content = "2行ある。",
  str_homestory_819201001_11_dialog_content = "「…分布状況、数、質や特徴および相互関係についての地図」",
  str_homestory_819201001_12_dialog_content = "はぁ…はぁ…<sprite=emo_kun size=60 />",
  str_homestory_819201001_13_dialog_content = "地図の…名前って…皆こんなに…長いの？",
  str_homestory_819201001_14_dialog_content = "一気に読み上げたら、息が切れちゃった。",
  str_homestory_819201001_15_dialog_content = "もちろん違う。ただ今回地図を描いた奴がバカ真面目でな。\nその結果…",
  str_homestory_819201001_16_dialog_content = "不必要に長くなった。",
  str_homestory_819201001_17_dialog_content = "どうりで軍師とか指揮官はルーペを持ち歩いてるわけだね。",
  str_homestory_819201001_18_dialog_content = "万が一「真面目」な人の描いた地図にあたっても、\n文字までちゃんと読めるもんね。",
  str_homestory_819201001_19_dialog_content = "（でも、読めたら読めたで、もっと腹が立つかな…）",
  str_homestory_819201001_20_dialog_content = "確かにルーペを使う将校は多い。",
  str_homestory_819201001_21_dialog_content = "文字や図を見たり、観察に使えるだけでなく、\n昼間なら火を起せるからな。",
  str_homestory_819201001_22_dialog_content = "多機能アイテムと言っていい。行軍には必須だ。",
  str_homestory_819201001_23_dialog_content = "だが、私はかならずしもそうは思っていない。",
  str_homestory_819201001_24_dialog_content = "どうして？",
  str_homestory_819201001_25_dialog_content = "お前も指揮官だろう？私の考えを当ててみろ。",
  str_homestory_819201001_26_option_content = "光に依存するから",
  str_homestory_819201001_27_dialog_content = "夜間や暗面にいる場合は使えない。",
  str_homestory_819201001_28_dialog_content = "確かにそれも問題だ。\nだが、照明などの光源を用意しておけばよいだけのことだ。",
  str_homestory_819201001_29_option_content = "視野が狭くなるから",
  str_homestory_819201001_30_dialog_content = "なかなか鋭いではないか。",
  str_homestory_819201001_31_dialog_content = "ルーペはある特定の部分を拡大する。\nそれによって観察者は細かい情報を正確につかむことができる。",
  str_homestory_819201001_32_dialog_content = "だが同時に視野はルーペで見られる範囲に限られてしまい――",
  str_homestory_819201001_33_dialog_content = "周囲の広く大きな環境を観察できなくなる。",
  str_homestory_819201001_34_dialog_content = "だが、戦闘配備には広い視野が必要なのだ。",
  str_homestory_819201001_35_dialog_content = "視野がある一点に過度に集中してしまうのを避けるため、\n私は時々ルーペをあえて使わないようにしている。",
  str_homestory_819201001_36_dialog_content = "さすがは一流の戦略家だね。",
  str_homestory_819201001_37_dialog_content = "ただの習慣にすぎない。\n今のようにルーペを使わなくてはならないこともあるしな。",
  str_homestory_819201001_38_dialog_content = "ここのルーペはいつでも自由に使っていいよ。",
  str_homestory_819201001_39_dialog_content = "ただ、使い終わったら必ず専用の箱の中に戻しておいてね。",
  str_homestory_819201001_40_dialog_content = "もし直射日光にあたりでもしたら、\n火事になるかもしれないから<sprite=emo_nuhuo size=60 />。",
  str_homestory_819201001_41_dialog_content = "ハハハ、防災意識が高いようだな。",
  str_homestory_819201001_42_dialog_content = "うん。だって苦労して再建した故郷だから。",
  str_homestory_819201001_43_dialog_content = "火事で燃えちゃったら、これまで費やしてきたお金…\nいや、苦労が台無しだよ。",
  str_homestory_819901001_0_dialog_content = "インゲル？",
  str_homestory_819901001_1_dialog_content = "PlayerNameでしたか。\nコーヒーをいただこうと思っていたところです。",
  str_homestory_819901001_2_dialog_content = "インゲルが自分で淹れたの？",
  str_homestory_819901001_3_dialog_content = "そうです。",
  str_homestory_819901001_4_dialog_content = "さきほどこの素敵なコーヒーカップを見かけたので、\n1杯淹れてみようと思ったのです。",
  str_homestory_819901001_5_dialog_content = "いい香りだね<sprite=emo_dianzan size=60 />！",
  str_homestory_819901001_6_dialog_content = "カフェラテを淹れました。\n模様が浮かび出ているのが分かりますか？",
  str_homestory_819901001_7_dialog_content = "あ、本当だ。きれいな模様だね！",
  str_homestory_819901001_8_dialog_content = "これは…アオハかな？",
  str_homestory_819901001_9_dialog_content = "アオハだと分かりましたか？\nどうやらうまく出来たようですね。",
  str_homestory_819901001_10_dialog_content = "もちろん、うまく出来てるよ！すごいな！",
  str_homestory_819901001_11_dialog_content = "どうやったの？",
  str_homestory_819901001_12_dialog_content = "カフェラテの材料はシンプルで、作り方も簡単です。",
  str_homestory_819901001_13_dialog_content = "まずはカップにエスプレッソを注ぎ…",
  str_homestory_819901001_14_dialog_content = "その上に泡立てたミルクを注ぎます。",
  str_homestory_819901001_15_dialog_content = "注ぐ時にカップを動かし、ミルクの泡の形を調整すれば――",
  str_homestory_819901001_16_dialog_content = "模様の浮かんだカフェラテが出来上がるのです。",
  str_homestory_819901001_17_dialog_content = "簡単そうに聞こえるけど、実際に作るとなると難しいんじゃないかな…",
  str_homestory_819901001_18_dialog_content = "慣れればうまく出来るようになります。\n何回も練習すればいいのです。",
  str_homestory_819901001_19_dialog_content = "仕事中疲れを感じた時、\n私はよくカフェラテを淹れて飲みます。",
  str_homestory_819901001_20_dialog_content = "滑らかなミルクと香り高いコーヒーは、\nまさに完璧な組み合わせですよ。",
  str_homestory_819901001_21_dialog_content = "PlayerNameも飲んでみますか？<sprite=emo_yaosu size=60 />",
  str_homestory_819901001_22_option_content = "飲んでみたい",
  str_homestory_819901001_23_dialog_content = "だってインゲルが入れたコーヒーだもん。",
  str_homestory_819901001_24_option_content = "あまり飲みたくない",
  str_homestory_819901001_25_dialog_content = "コーヒーを飲んだら、夜眠れなくなりそうだから。",
  str_homestory_819901001_26_dialog_content = "カフェラテは3分の2以上がミルクなので、\n飲んでも眠れなくなったりはしませんよ。",
  str_homestory_819901001_27_dialog_content = "そうなの？だったら飲んでみたいな。",
  str_homestory_819901001_28_dialog_content = "味はどうですか？",
  str_homestory_819901001_29_dialog_content = "すごくおいしいよ！",
  str_homestory_819901001_30_dialog_content = "僕もこんなにおいしいカフェラテを淹れられたらいいのにな。",
  str_homestory_819901001_31_dialog_content = "作ってみたらいかがですか。きっとうまく淹れられますよ。",
  str_homestory_819901001_32_dialog_content = "ただ、ミルクは私が全部使ってしまいましたが…",
  str_homestory_819901001_33_dialog_content = "え？もうなくなっちゃったの？",
  str_homestory_819901001_34_dialog_content = "さきほどとてものどが渇いていたので、\n全部飲んでしまいました。",
  str_homestory_819901001_35_dialog_content = "オホン…インゲル。ミルクは水じゃないんだよ…",
  str_homestory_820001001_0_dialog_content = "アナトリアが街灯をじっと見てる！？",
  str_homestory_820001001_1_dialog_content = "アナトリア、何してるの？",
  str_homestory_820001001_2_dialog_content = "街灯を観察しているのです。",
  str_homestory_820001001_3_option_content = "街灯を観察してるの？",
  str_homestory_820001001_4_dialog_content = "この街灯は昼間でも点いたままですね。",
  str_homestory_820001001_5_dialog_content = "太陽の光ほどの輝きはありませんが、\nそれでも消えることはありません。",
  str_homestory_820001001_6_dialog_content = "いったい誰が灯油を足し続けているのでしょう？",
  str_homestory_820001001_7_dialog_content = "それは…僕も分からないな…",
  str_homestory_820001001_8_option_content = "どうして？",
  str_homestory_820001001_9_dialog_content = "昼夜を問わず、ずっと点いたままだからです。",
  str_homestory_820001001_10_dialog_content = "昼間は目立ちませんが、夜になると暗闇を照らしてくれます<sprite=emo_taiyang size=60 />。",
  str_homestory_820001001_11_dialog_content = "確かに！",
  str_homestory_820001001_12_dialog_content = "夜に街灯が道を照らしてくれると便利だよね！",
  str_homestory_820001001_13_dialog_content = "ただ、この街灯は昼間も点いたままなんだ。\nなんかもったいないな。",
  str_homestory_820001001_14_dialog_content = "はい…確かにその通りですね。",
  str_homestory_820001001_15_dialog_content = "ここは極夜ではありませんから、\n照明を点けたままにしておく必要はありません。",
  str_homestory_820001001_16_dialog_content = "じゃあ、まずは消しておこう。\n夜になったらまた点ければいいよ。",
  str_homestory_820001001_17_dialog_content = "点けたままにしておくのがよいでしょう。",
  str_homestory_820001001_18_dialog_content = "え？どうして？",
  str_homestory_820001001_19_dialog_content = "誰が街灯に油を足しているのか存じ上げませんが、\nおそらく目的があってしていることでしょう。",
  str_homestory_820001001_20_dialog_content = "その方の邪魔をしないほうがいいと思います。",
  str_homestory_820001001_21_dialog_content = "確かにそうだね。",
  str_homestory_820001001_22_dialog_content = "それにしても誰なんだろう？\n興味わいちゃうな！",
  str_homestory_820001001_23_dialog_content = "でしたら、足しげく見にいらしては？\nいつかばったり出会えるかもしれませんよ。",
  str_homestory_820001001_24_dialog_content = "確かアナトリアは推理と分析が得意だったよね…",
  str_homestory_820001001_25_dialog_content = "君はその人物はどんな人だと思う？",
  str_homestory_820001001_26_dialog_content = "いくつかの特徴が思い浮かびます。",
  str_homestory_820001001_27_dialog_content = "聞かせてもらえる？",
  str_homestory_820001001_28_dialog_content = "その人物はおそらく非常に辛抱強く、\n長い間一つのことに取り組むことができます。",
  str_homestory_820001001_29_dialog_content = "しかも、記憶力がよく、\nこうした煩雑な物事も忘れはしません。",
  str_homestory_820001001_30_dialog_content = "そして最後に、その人物はわずかな光を発する物体を好むはずです。",
  str_homestory_820001001_31_dialog_content = "うーん、確かに…",
  str_homestory_820001001_32_dialog_content = "何人か思い当たる人がいるよ。",
  str_homestory_820001001_33_dialog_content = "あ、でもちょっと待って。分かった！",
  str_homestory_820001001_34_dialog_content = "今言った人って、君自身じゃないの？",
  str_homestory_820001001_35_dialog_content = "正解です。",
  str_homestory_820001001_36_dialog_content = "でも、どうして街灯をずっと点けたままにしてるの？",
  str_homestory_820001001_37_dialog_content = "今は昼間だし、照明は必要ないよ。",
  str_homestory_820001001_38_dialog_content = "太陽の光に埋もれてしまうわずかな光にも、\nそれにしかできないことがあります。",
  str_homestory_820001001_39_dialog_content = "私はそう信じているのです。",
  str_homestory_802801001_0_dialog_content = "この声はまさか？",
  str_homestory_802801001_1_dialog_content = "やっぱりラファエルだったんだね！",
  str_homestory_802801001_2_dialog_content = "エヘヘへ！",
  str_homestory_802801001_3_dialog_content = "PlayerName、ちょうどいい時に来たね！",
  str_homestory_802801001_4_dialog_content = "新発明の「不思議なエナジータブレット」を試してみて！",
  str_homestory_802801001_5_dialog_content = "これを食べれば、一瞬でエネルギーがみなぎるんだ！\nとっておきの宝物を感知できちゃうかもしれないよ！",
  str_homestory_802801001_6_dialog_content = "数量限定だよ。たった1粒しかないんだから！",
  str_homestory_802801001_7_option_content = "いや、僕には必要ないかな…",
  str_homestory_802801001_8_dialog_content = "ラファエルはあちこち探し回って、\nようやく実験対象を見つけたんだよ！",
  str_homestory_802801001_9_dialog_content = "あなただって、新発明が失敗に終わるのはイヤでしょ！",
  str_homestory_802801001_10_dialog_content = "正直言うと、僕はどうでもいいかな…",
  str_homestory_802801001_11_option_content = "試してみたい！",
  str_homestory_802801001_12_dialog_content = "へへ！今日のPlayerNameは思い切りがいいね！",
  str_homestory_802801001_13_dialog_content = "じゃあ明日また多めに持ってきてあげるね！",
  str_homestory_802801001_14_dialog_content = "いや、いいよ。ラファエルってそんなにヒマなの？",
  str_homestory_802801001_15_dialog_content = "いいから早く口を開けて。あーん…",
  str_homestory_802801001_16_dialog_content = "ちょ、ちょっと待った！",
  str_homestory_802801001_17_dialog_content = "この匂い…バイスの作った料理じゃないよね？",
  str_homestory_802801001_18_dialog_content = "（うーん、何かを焦がしちゃった時のあの匂い…<sprite=emo_hanshui size=60 />）",
  str_homestory_802801001_19_dialog_content = "ええ！？ラファエルって、そんなに信用あるの？",
  str_homestory_802801001_20_dialog_content = "いや、僕が言いたいのは…そういうことじゃなくて…",
  str_homestory_802801001_21_dialog_content = "わかってるって。PlayerNameは信頼できる仲間が好きなんだよね！",
  str_homestory_802801001_22_dialog_content = "ラファエルも頑張って「誰よりも頼れる仲間」になって見せるよ！",
  str_homestory_802801001_23_dialog_content = "「不思議なエナジータブレット」を作れるような――",
  str_homestory_802801001_24_dialog_content = "エヘヘ…なんだか照れちゃうな。",
  str_homestory_802801001_25_dialog_content = "（並外れて前向きだな…）",
  str_homestory_802801001_26_dialog_content = "ねえ、ラファエル、こうしようよ。\nもっとたくさん作ってから、日を改めてカレンも一緒に試そう！",
  str_homestory_802801001_27_dialog_content = "カレンはいつも忙しいから、\n「不思議なエナジータブレット」が必要かもしれないよ。",
  str_homestory_802801001_28_dialog_content = "え？カレンちゃん…？",
  str_homestory_802801001_29_dialog_content = "ラファエルはそうは思わないな。",
  str_homestory_802801001_30_dialog_content = "どうして？",
  str_homestory_802801001_31_dialog_content = "だって、カレンちゃんならきっとこう言うよ――",
  str_homestory_802801001_32_dialog_content = "「ラファエル！二度と私に奇妙なものを食べさせないで。\n理由は聞かないで」",
  str_homestory_802801001_33_dialog_content = "どうして？",
  str_homestory_802801001_34_dialog_content = "ラファエルだって知りたいよ<sprite=emo_sikao size=60 />。\nでも、カレンちゃんが聞いちゃダメって言うんだよ。",
  str_homestory_802801001_35_dialog_content = "それにね――",
  str_homestory_802801001_36_dialog_content = "これは感知能力のあるPlayerNameのためだけに、\nわざわざ作ったものなんだ！",
  str_homestory_802801001_37_dialog_content = "そうなんだ。分かった、僕にちょうだい！",
  str_homestory_802801001_38_dialog_content = "（ただのお菓子だよね…）",
  str_homestory_802801001_39_dialog_content = "へへッ！PlayerNameにあげるのが一番だって思ってたんだ！",
  str_homestory_802801001_40_dialog_content = "どうどう？何か変化はあった！？",
  str_homestory_802801001_41_dialog_content = "何か光るものが見えない？",
  str_homestory_802801001_42_dialog_content = "確かに視野がはっきりして、遠くの方がよく見えるようになった気がする――",
  str_homestory_802801001_43_dialog_content = "川だ！川の中に確かに光るものがある！",
  str_homestory_802801001_44_dialog_content = "でしょでしょ！ラファエルにはわかってたよ！",
  str_homestory_802801001_45_dialog_content = "「不思議なエナジータブレット」実験成功！<sprite=emo_aixin size=60 />",
  str_homestory_820201001_0_dialog_content = "どうしてここにいるんですか？",
  str_homestory_820201001_1_dialog_content = "お主か。",
  str_homestory_820201001_2_dialog_content = "この王座は余のために特別に用意したものか？",
  str_homestory_820201001_3_dialog_content = "は、はい…その通りです。",
  str_homestory_820201001_4_dialog_content = "左様か。そなたは気遣いができるようだな。",
  str_homestory_820201001_5_dialog_content = "白夜城の正統な王座とは比べ物にならぬが…",
  str_homestory_820201001_6_dialog_content = "この等級のものこそ、余の身分にふさわしい。",
  str_homestory_820201001_7_dialog_content = "ご満足いただければ幸いです！",
  str_homestory_820201001_8_dialog_content = "他に何か必要なものはありますか？",
  str_homestory_820201001_9_dialog_content = "ここに白夜城のような宮殿を建てるのはどうか？<sprite=emo_sikao size=60 />",
  str_homestory_820201001_10_dialog_content = "王座には、それにふさわしい宮殿がなければならぬ。",
  str_homestory_820201001_11_dialog_content = "宮殿を建てたいんですか？",
  str_homestory_820201001_12_dialog_content = "ここでは狭すぎるんじゃないでしょうか？",
  str_homestory_820201001_13_dialog_content = "ううむ…改めて見てみると、ここは粗末なだけでなく、確かに広さが足らぬ。",
  str_homestory_820201001_14_dialog_content = "余が出資してやる。一度土地を整備してみてはどうか？",
  str_homestory_820201001_15_option_content = "遠慮しておきます",
  str_homestory_820201001_16_dialog_content = "お気持ちだけで嬉しいです。",
  str_homestory_820201001_17_option_content = "よろしいんですか？",
  str_homestory_820201001_18_dialog_content = "土地を整備するとなると、物資だけでなく、人手もたくさん必要になります…",
  str_homestory_820201001_19_dialog_content = "ただひと休みに来られるだけなら、そこまで手を掛ける必要はないと思いますよ。",
  str_homestory_820201001_20_dialog_content = "これしきのこと余には朝飯前だ。",
  str_homestory_820201001_21_dialog_content = "だが、そなたが要らぬというのなら、無理強いはせぬ。",
  str_homestory_820201001_22_dialog_content = "おや待て。何か香りが…<sprite=emo_wuzui size=60 />",
  str_homestory_820201001_23_dialog_content = "香りですか？おかしな匂いですか？",
  str_homestory_820201001_24_dialog_content = "うーん…僕には何も匂いませんが…",
  str_homestory_820201001_25_dialog_content = "それでよいのだ。欠けているものとはそれだ。",
  str_homestory_820201001_26_dialog_content = "ここに優美な香りを足すがよい。清潔で、秩序ある香りを漂わせるのだ。",
  str_homestory_820201001_27_dialog_content = "ええと…香りにはあまり興味がなくて…",
  str_homestory_820201001_28_dialog_content = "客が訪れた時、まずは優雅な香りがその者を出迎えなければ――",
  str_homestory_820201001_29_dialog_content = "沽券に関わる！",
  str_homestory_820201001_30_dialog_content = "そうとなれば、余が香りのするものをもってこさせよう。",
  str_homestory_820201001_31_dialog_content = "再びこの地を訪れた時、香りが出迎えてくれることを楽しみにしている。",
  str_homestory_820201001_32_dialog_content = "分かりました…",
  str_homestory_820301001_0_dialog_content = "ジャキーニ？",
  str_homestory_820301001_1_dialog_content = "なるほど…",
  str_homestory_820301001_2_dialog_content = "何してるの？",
  str_homestory_820301001_3_dialog_content = "うわあ！いつからいたんですか？",
  str_homestory_820301001_4_dialog_content = "今の占いの結果、聞こえてました？",
  str_homestory_820301001_5_dialog_content = "来たばかりだから、何も知らないよ。",
  str_homestory_820301001_6_dialog_content = "何か個人的な事でも占ってたの？",
  str_homestory_820301001_7_dialog_content = "そうとは知らなくてごめんね。僕は外すよ。",
  str_homestory_820301001_8_dialog_content = "個人的な事ではあるんですけど――",
  str_homestory_820301001_9_dialog_content = "あなたと関係あるんです。",
  str_homestory_820301001_10_dialog_content = "え？僕と？",
  str_homestory_820301001_11_dialog_content = "ええ、さっきあなたとバイスがおしゃべりしてるのを聞きました。",
  str_homestory_820301001_12_dialog_content = "ここのところ懐具合が良くないみたいですね。",
  str_homestory_820301001_13_dialog_content = "それは…確かにちょっと厳しいかな。",
  str_homestory_820301001_14_dialog_content = "そうでしょう？心配になって代わりに占ってみたんです。",
  str_homestory_820301001_15_dialog_content = "もし気に障ったなら、占い結果は秘密にして墓まで持って行きますよ。",
  str_homestory_820301001_16_dialog_content = "いいや、気にしないよ。で、占い結果は…",
  str_homestory_820301001_17_dialog_content = "えーと、これから先の財運は――",
  str_homestory_820301001_18_dialog_content = "ちょっと待って。まだ心の準備ができてない…万が一良くない結果だったら…",
  str_homestory_820301001_19_dialog_content = "結果は、超お金持ちになって、何不自由なく、毎日楽しく暮らせる、ですって！<sprite=emo_yaosu size=60 />",
  str_homestory_820301001_20_dialog_content = "本当！？本当にそんないい結果だったの！？",
  str_homestory_820301001_21_dialog_content = "信じますか？",
  str_homestory_820301001_22_dialog_content = "え？つまり、今言ったことはウソってこと？",
  str_homestory_820301001_23_dialog_content = "まずは信じるか信じないか答えてください。",
  str_homestory_820301001_24_option_content = "信じる",
  str_homestory_820301001_25_dialog_content = "正解！そんな風に考えられるなんて素晴らしいです！",
  str_homestory_820301001_26_option_content = "信じない",
  str_homestory_820301001_27_dialog_content = "なんで信じないんですか？怒りますよ！",
  str_homestory_820301001_28_dialog_content = "「信じる」ことはとても大きな力なんですよ！",
  str_homestory_820301001_29_dialog_content = "信じさえすれば、どんなこともいい方向に進むんです！",
  str_homestory_820301001_30_dialog_content = "でも、それと占いと何の関係があるの？",
  str_homestory_820301001_31_dialog_content = "だって占いの結果は――",
  str_homestory_820301001_32_dialog_content = "今を大事に、なんです！",
  str_homestory_820301001_33_dialog_content = "うーん…占いって何だかどちらともとれて、うまい話術に乗せられてるみたいだね。",
  str_homestory_820301001_34_dialog_content = "人生というのはそもそも長い道のりなんです。",
  str_homestory_820301001_35_dialog_content = "その道にはいくつもの分かれ道が待っています。",
  str_homestory_820301001_36_dialog_content = "つまり、あなたの下す決定が今後の道を決めるってことです。",
  str_homestory_820301001_37_dialog_content = "とにかく、私はあなたの道に光を見ましたよ<sprite=emo_taiyang size=60 />。",
  str_homestory_820301001_38_dialog_content = "分かった。",
  str_homestory_820301001_39_dialog_content = "未来はまだ決まっていない。そしてそのすべてが今にかかってるってことだね。",
  str_homestory_820301001_40_dialog_content = "うわぁ、いいコト言いますね。占い手ほどきにメモしておきましょう。",
  str_homestory_820301001_41_dialog_content = "あはは、いずれにせよ、君と話したら気分が良くなったよ。",
  str_homestory_809801001_0_dialog_content = "クスッタ？",
  str_homestory_809801001_1_dialog_content = "クスッタ、何を見てるの？",
  str_homestory_809801001_2_dialog_content = "花よ<sprite=emo_huaduo size=60 />。",
  str_homestory_809801001_3_dialog_content = "花畑の中には、顔を上げて空を眺める花もあれば、人に愛でられるのを拒絶している花もある。",
  str_homestory_809801001_4_dialog_content = "人に愛でられるのを拒む花の中に「クロアヤメ」という花があるの。あなたは聞いたことある？",
  str_homestory_809801001_5_option_content = "聞いたことある",
  str_homestory_809801001_6_dialog_content = "でも…どうして「人に愛でられるのを拒んでいる」の？",
  str_homestory_809801001_7_option_content = "聞いたことない",
  str_homestory_809801001_8_dialog_content = "どんな花なの？",
  str_homestory_809801001_9_dialog_content = "「クロアヤメ」は珍しい花なの。",
  str_homestory_809801001_10_dialog_content = "花びらはとても柔らかく、深い色をしてるから、日の光を吸収しやすいの<sprite=emo_taiyang size=60 />。",
  str_homestory_809801001_11_dialog_content = "だから高温で花が傷つくことがないように、いつも葉の下に隠れているのよ。",
  str_homestory_809801001_12_dialog_content = "それで、愛でられるのを拒む花の一つに数えられるのよ。",
  str_homestory_809801001_13_dialog_content = "そういうことだったんだ…",
  str_homestory_809801001_14_dialog_content = "クスッタは「クロアヤメ」が好きなんだね？",
  str_homestory_809801001_15_dialog_content = "好き…？どうしたら好きかどうか、わかるの？",
  str_homestory_809801001_16_dialog_content = "うーん…クスッタは「クロアヤメ」に独特の評価をしたし、生息環境や特徴をよく知ってるでしょ？",
  str_homestory_809801001_17_dialog_content = "それって好きだからできることじゃないかな？",
  str_homestory_809801001_18_dialog_content = "…そう…",
  str_homestory_809801001_19_dialog_content = "実は「クロアヤメ」は屍に咲く花なの。",
  str_homestory_809801001_20_dialog_content = "え！？屍！？",
  str_homestory_809801001_21_dialog_content = "ええ、そうなの。だから…",
  str_homestory_809801001_22_dialog_content = "ここにもうすぐ…「クロアヤメ」が咲くと思うわ。",
  str_homestory_809801001_23_dialog_content = "そ、それって…ここに…死体が埋まってるってこと！？",
  str_homestory_809801001_24_dialog_content = "心配しないで、ちゃんと確認したから。",
  str_homestory_809801001_25_dialog_content = "私が言ってるのは、私のこの――今にも枯れようとしてる身体のことよ。",
  str_homestory_809801001_26_dialog_content = "ああ、私もうすぐ眠りにつくの。それはつまり「クロアヤメ」が咲くということ。",
  str_homestory_809801001_27_dialog_content = "そ、そんなはずないよ、クスッタ！",
  str_homestory_809801001_28_dialog_content = "キューブが言ってたんだ。天空ノ庭の土壌には特殊な物質が含まれてるって。",
  str_homestory_809801001_29_dialog_content = "だ、だから…「クロアヤメ」が咲いても、おかしくないよ…",
  str_homestory_809801001_30_dialog_content = "そ、それだけじゃない…色とりどりの花だって咲くかもしれない！",
  str_homestory_809801001_31_dialog_content = "「色とりどり」…",
  str_homestory_809801001_32_dialog_content = "今言ったこと、本当？<sprite=emo_yundao size=60 />",
  str_homestory_809801001_33_dialog_content = "うん！一緒に色とりどりの花を育てない？",
  str_homestory_809801001_34_dialog_content = "「一緒に育てる」…それは、仕事？",
  str_homestory_809801001_35_dialog_content = "うーん、ちょっと違うわね…",
  str_homestory_809801001_36_dialog_content = "PlayerNameも花が好きなの？",
  str_homestory_809801001_37_dialog_content = "だと思うよ！",
  str_homestory_809801001_38_dialog_content = "天空ノ庭の景観はちょっと単調だなって思ってたんだ。",
  str_homestory_809801001_39_dialog_content = "君のおかげで思いついたよ。お花で色を添えればいいんだね！",
  str_homestory_809801001_40_dialog_content = "それは…色どりを添えると、人は喜ぶってこと？",
  str_homestory_809801001_41_dialog_content = "もちろんだよ！あちこち見て回って、別の色の花を探すのはどう？",
  str_homestory_809801001_42_dialog_content = "そうね…いいかもしれないわ。",
  str_homestory_809801001_43_dialog_content = "ただ、あなたの言う「色とりどり」　には、金色も含まれる？",
  str_homestory_809801001_44_dialog_content = "水の中で光ってるものは、花かしら？",
  str_homestory_820101001_0_dialog_content = "何を見てるの？",
  str_homestory_820101001_1_dialog_content = "もし…",
  str_homestory_820101001_2_dialog_content = "邪魔しちゃった？",
  str_homestory_820101001_3_dialog_content = "い、いいえ、ただ思いついたことがあるんだけど、決めれらず迷ってたの。",
  str_homestory_820101001_4_dialog_content = "僕で力になれるかな？",
  str_homestory_820101001_5_dialog_content = "ええ。まず一つ聞いてもいいかしら？",
  str_homestory_820101001_6_dialog_content = "もちろんだよ。",
  str_homestory_820101001_7_dialog_content = "もし1日だけ、その日の記憶を永遠にとっておけるとしたら、あなたはどの日を選ぶ？",
  str_homestory_820101001_8_dialog_content = "永遠にとっておきたい日か…確かに難しいね。",
  str_homestory_820101001_9_dialog_content = "君はそれで悩んでたんだね。",
  str_homestory_820101001_10_dialog_content = "これを見て、それで…",
  str_homestory_820101001_11_dialog_content = "ううん…そうだなあ。",
  str_homestory_820101001_12_option_content = "巨像が起動した日…",
  str_homestory_820101001_13_dialog_content = "巨像の起動に成功した日の記憶をとっておきたいな。",
  str_homestory_820101001_14_dialog_content = "あの日、僕は初めてアストラ大陸を目の当たりにしたんだ。",
  str_homestory_820101001_15_dialog_content = "あれが僕の人生の始まりだったのかもしれない。",
  str_homestory_820101001_16_option_content = "回帰の塔が現れた日…",
  str_homestory_820101001_17_dialog_content = "回帰の塔が現れた日のことを覚えていたいな。",
  str_homestory_820101001_18_dialog_content = "感知能力が強化されて、ありとあらゆる角度からアストラ大陸を俯瞰できるような感覚だった。",
  str_homestory_820101001_19_dialog_content = "本当に衝撃的な経験だったんだ。",
  str_homestory_820101001_20_dialog_content = "確かに、とても素敵な日ね。",
  str_homestory_820101001_21_dialog_content = "PlayerNameはすぐに思いついたのね。",
  str_homestory_820101001_22_dialog_content = "巨像の起動が成功するまでは、僕は毎日同じ日を繰り返してたようなものだった。",
  str_homestory_820101001_23_dialog_content = "皆に会ってようやく、僕の記憶は少しずつ豊かになっていったんだよ。",
  str_homestory_820101001_24_dialog_content = "だから僕は全ての思い出を大切にしてるんだ。その気持ちが強くなるほど、皆のことがもっとはっきり思い浮かぶようになるんだ。",
  str_homestory_820101001_25_dialog_content = "僕は頑張って、全部覚えておくよ。一日一日を永遠にずっと覚えてる。",
  str_homestory_820101001_26_dialog_content = "そう…<sprite=emo_sikao size=60 />",
  str_homestory_820101001_27_dialog_content = "君はどう思ってるの、ミヤ？",
  str_homestory_820101001_28_dialog_content = "私は…",
  str_homestory_820101001_29_dialog_content = "一度大切なことを忘れてしまって、最近になってようやく思い出したから…",
  str_homestory_820101001_30_dialog_content = "この先も忘れてしまうかもしれないって心配で…だから、とっておきたいのは…",
  str_homestory_820101001_31_dialog_content = "でも、いくら考えても、お母様に妹…思い出がたくさんありすぎて、どうしても決められないの。",
  str_homestory_820101001_32_dialog_content = "ミヤ…",
  str_homestory_820101001_33_dialog_content = "あ、ごめんなさい。あなたまで困らせてしまって…",
  str_homestory_820101001_34_dialog_content = "謝るのは僕の方だよ。ヘンなこと言っちゃったね…",
  str_homestory_820101001_35_dialog_content = "あら、いいのよ、PlayerName。",
  str_homestory_820101001_36_dialog_content = "あなたの話を聞いて、逆に気持ちがすごく楽になったわ。",
  str_homestory_820101001_37_dialog_content = "本当に？",
  str_homestory_820101001_38_dialog_content = "ええ！忘れることを心配するよりも、今目の前のことを大切にする方が大事よね<sprite=emo_yaosu size=60 />。",
  str_homestory_820401001_0_dialog_content = "ヨシュア夫人？",
  str_homestory_820401001_1_dialog_content = "何してるんですか？",
  str_homestory_820401001_2_dialog_content = "あら、PlayerName。ご覧になって。",
  str_homestory_820401001_3_dialog_content = "この鉢植え、とてもよく育っているわね。",
  str_homestory_820401001_4_dialog_content = "何の品種か、観察していたのよ。",
  str_homestory_820401001_5_dialog_content = "そうだったんですか。\nそれで、何の品種か分かりましたか？",
  str_homestory_820401001_6_dialog_content = "いいえ。まだ何という植物か分からないでいるの…",
  str_homestory_820401001_7_dialog_content = "あなたはご存じかしら？",
  str_homestory_820401001_8_option_content = "（うなずく）",
  str_homestory_820401001_9_dialog_content = "僕が少し前に影ノ街から買ってきたんです。",
  str_homestory_820401001_10_dialog_content = "いくつか適当に選んで買ったんですけど…",
  str_homestory_820401001_11_dialog_content = "お店のご主人は確か…\nマナーグリーンと言っていたような…",
  str_homestory_820401001_12_dialog_content = "そう、マナーグリーンです。",
  str_homestory_820401001_13_dialog_content = "変わった名前ではないようだけど、\nとてもよく世話しているのね。",
  str_homestory_820401001_14_dialog_content = "あはは、お店のご主人が\nこの品種は元気でよく育つと言ってました。",
  str_homestory_820401001_15_option_content = "（首を振る）",
  str_homestory_820401001_16_dialog_content = "ええと、僕もよく知らないんです。",
  str_homestory_820401001_17_dialog_content = "確か店のご主人が一年中緑の葉をつけると\n言っていたのは覚えてるんですが…",
  str_homestory_820401001_18_dialog_content = "しかも室内でも育てられるんです。",
  str_homestory_820401001_19_dialog_content = "あら、とても育てやすい品種のようね。",
  str_homestory_820401001_20_dialog_content = "PlayerNameの所には緑がたくさんあるわね。",
  str_homestory_820401001_21_dialog_content = "お花を植える気はないのかしら<sprite=emo_huaduo size=60 />？",
  str_homestory_820401001_22_dialog_content = "そうすれば、変化のある景色を楽しめると思うわ。",
  str_homestory_820401001_23_dialog_content = "それはいい考えですね！",
  str_homestory_820401001_24_dialog_content = "ただ、花を育てるのはあまり得意ではないので…",
  str_homestory_820401001_25_dialog_content = "緑の植物の方が僕には育てやすいんです。",
  str_homestory_820401001_26_dialog_content = "白夜城にいた頃、\nわたくしは庭に色々なお花を植えていたの。",
  str_homestory_820401001_27_dialog_content = "手持ち無沙汰になると、\nよく水やりや剪定をしていたのよ。",
  str_homestory_820401001_28_dialog_content = "そうすると、気持ちが落ち着いたわ。",
  str_homestory_820401001_29_dialog_content = "花を育てるのが趣味だったんですね！",
  str_homestory_820401001_30_dialog_content = "僕に花の育て方を教えてくれませんか？",
  str_homestory_820401001_31_dialog_content = "もちろん、構わないわ。",
  str_homestory_820401001_32_dialog_content = "お花を育てるのはそう難しい事ではないわ。\nただ辛抱強さが必要よ。",
  str_homestory_820401001_33_dialog_content = "植えたばかりの頃は、お花たちはとても繊細なの。",
  str_homestory_820401001_34_dialog_content = "この植木鉢は植えたてのお花を世話するのにいいわ。",
  str_homestory_820401001_35_dialog_content = "種をまいたら、決められた時間に水やりをして<sprite=emo_hanshui size=60 />、\n芽が出るのを待つ…",
  str_homestory_820401001_36_dialog_content = "ただし、水のあげ過ぎは禁物よ。",
  str_homestory_820401001_37_dialog_content = "分かりました。その後はどうすればいいんですか？",
  str_homestory_820401001_38_dialog_content = "芽が出た後、さらに1か月間じっくり育てるの。",
  str_homestory_820401001_39_dialog_content = "芽吹いた後の1か月間は、\n栄養をたっぷりあげて大丈夫よ。",
  str_homestory_820401001_40_dialog_content = "苗木にまで育てたら、\nもっと広々とした場所へ植え替えできるわ。",
  str_homestory_820401001_41_dialog_content = "植え替えが必要なんですね…",
  str_homestory_820401001_42_dialog_content = "そうよ。PlayerNameも小さな赤ちゃんから\n勇敢な立派な男の子に育った後――",
  str_homestory_820401001_43_dialog_content = "色々な所へ冒険の旅に出たでしょう？",
  str_homestory_820401001_44_dialog_content = "外に出るのは成長に必要なことなのよ。",
  str_homestory_820401001_45_dialog_content = "た、確かにその通りですね…",
  str_homestory_820401001_46_dialog_content = "少し照れくさいですけど…",
  str_homestory_820401001_47_dialog_content = "ふふ、PlayerNameはいい子ね。",
  str_homestory_820501001_0_dialog_content = "Ms.ブラン？",
  str_homestory_820501001_1_dialog_content = "さっき目を閉じてたみたいですけど、\n眠ってたんですか<sprite=emo_kun size=60 />？",
  str_homestory_820501001_2_dialog_content = "いいえ。瞑想をしていました。",
  str_homestory_820501001_3_dialog_content = "瞑想ですか？",
  str_homestory_820501001_4_dialog_content = "はい。瞑想が何か知っていますか？",
  str_homestory_820501001_5_option_content = "大体知っています",
  str_homestory_820501001_6_dialog_content = "瞑想すると心身が休まって、\n痛みを癒すことができるんですよね。",
  str_homestory_820501001_7_dialog_content = "ええ、その通りです。\n瞑想にはそのような効果があります。",
  str_homestory_820501001_8_option_content = "よく知りません",
  str_homestory_820501001_9_dialog_content = "瞑想は精神の鍛練のようなものです。\n心身を休め、傷を癒すことができるのです。",
  str_homestory_820501001_10_dialog_content = "何か困った事でもあったんですか？\n気持ちが休まらないような？",
  str_homestory_820501001_11_dialog_content = "だったら、独りで瞑想する以外にも、\n友達に話すっていう方法もあります。例えば、僕とか…",
  str_homestory_820501001_12_dialog_content = "さっき1人でいる姿が何だかさみしそうでしたし…",
  str_homestory_820501001_13_dialog_content = "気に掛けてくださってありがとうございます。",
  str_homestory_820501001_14_dialog_content = "私ももちろんあなたとお話しするのは好きですよ。\nただ今瞑想していたことはお話できないんです。",
  str_homestory_820501001_15_dialog_content = "もしくは、\nお話ししても意味がないと言ったらいいでしょうか。",
  str_homestory_820501001_16_dialog_content = "そんなに深刻な問題なんですか？\nだったら何か方法を考えないと…",
  str_homestory_820501001_17_dialog_content = "ふふ。あなたのようなお友達は確かに\n私の願っていることの助けになるかもしれませんね。",
  str_homestory_820501001_18_dialog_content = "あなたに会えば、\nとても楽しい気分になれるのですから。",
  str_homestory_820501001_19_dialog_content = "それも美容の秘訣でしょう。",
  str_homestory_820501001_20_dialog_content = "美容、ですか？",
  str_homestory_820501001_21_dialog_content = "そうです。私は先程瞑想で老化を防ぎ、\nお肌のケアをしていたのです。",
  str_homestory_820501001_22_dialog_content = "そういうのって…瞑想で実現するものなんですか？",
  str_homestory_820501001_23_dialog_content = "精神の力はとても大きいんですよ。",
  str_homestory_820501001_24_dialog_content = "どうです？あなたも試してみませんか？",
  str_homestory_820501001_25_dialog_content = "瞑想で強く、高い戦闘力を持てるようになりますか？",
  str_homestory_820501001_26_dialog_content = "それがあなたの望みですか？",
  str_homestory_820501001_27_dialog_content = "はい。だって、強くなれば守りたい人や物を\n守ることができますよね？",
  str_homestory_820501001_28_dialog_content = "あなたの考えには賛成です。\n私もずっと「守る」ために戦ってきましたから。",
  str_homestory_820501001_29_dialog_content = "ただ、「守る」にも色々な形があるのですよ。",
  str_homestory_820501001_30_dialog_content = "たとえば、私は普段ガイドでしかありませんが、\nそれも白夜城を守る一つの形です。",
  str_homestory_820501001_31_dialog_content = "どうしてその話を？つまり…\n僕の望みはかなわないってことですか？",
  str_homestory_820501001_32_dialog_content = "瞑想で訓練や筋肉増強ができるか、\n私には分かりません。",
  str_homestory_820501001_33_dialog_content = "ただ、試してみてもいいかもしれませんね。",
  str_homestory_820501001_34_dialog_content = "うう…やっぱり無理なんですね…",
  str_homestory_807501001_0_dialog_content = "オティ？",
  str_homestory_807501001_1_dialog_content = "こんなところにこんないいモノがあるなんて！",
  str_homestory_807501001_2_dialog_content = "私のレンチはどこだっけ？解体を始めなきゃ！",
  str_homestory_807501001_3_dialog_content = "ちょっと待って！何を解体するつもり！？",
  str_homestory_807501001_4_dialog_content = "この街灯だよ。ダメなの？",
  str_homestory_807501001_5_option_content = "ダメだよ",
  str_homestory_807501001_6_option_content = "街灯壊れちゃったの？",
  str_homestory_807501001_7_dialog_content = "壊れてないよ。ただ解体したいだけ。",
  str_homestory_807501001_8_dialog_content = "だったらダメだよ<sprite=emo_shengqi size=60 />。",
  str_homestory_807501001_9_dialog_content = "なんでよ！？どうしてダメなの？\nただのつまんない街灯じゃない！",
  str_homestory_807501001_10_dialog_content = "壊れてないのに、どうして解体する必要があるの？",
  str_homestory_807501001_11_dialog_content = "もちろん、研究に決まってるでしょ。",
  str_homestory_807501001_12_dialog_content = "ほら、この街灯、ほかの照明とぜんぜん違うじゃない。",
  str_homestory_807501001_13_dialog_content = "大して違わないよ。",
  str_homestory_807501001_14_dialog_content = "私には外側を見ただけで、\n中の歯車と電気回路の複雑な構造が分かるの。",
  str_homestory_807501001_15_dialog_content = "白夜城の街灯は確かそういう構造じゃないんじゃ…",
  str_homestory_807501001_16_dialog_content = "だから素人は困るのよ。",
  str_homestory_807501001_17_dialog_content = "君だってまだ分かってないでしょ。",
  str_homestory_807501001_18_dialog_content = "あれあれ～、なかなか強気じゃない。",
  str_homestory_807501001_19_dialog_content = "わかったわ。絶対にこの街灯を守るって言うのね？",
  str_homestory_807501001_20_dialog_content = "だったら、今すぐここで勝負しましょ。",
  str_homestory_807501001_21_dialog_content = "故障するまでたたきのめされても知らないんだから！",
  str_homestory_807501001_22_dialog_content = "僕は機械じゃないから、故障なんかしないよ。",
  str_homestory_807501001_23_dialog_content = "故障するとしたら、君の改造ケーブルでしょ？",
  str_homestory_807501001_24_dialog_content = "挑発しようっていうの？",
  str_homestory_807501001_25_dialog_content = "いや…事実を言ったまでなんだけど…",
  str_homestory_807501001_26_dialog_content = "エンジニアをバカにしないでよね。\n空の末裔だからって…ええと…",
  str_homestory_807501001_27_dialog_content = "？？？",
  str_homestory_807501001_28_dialog_content = "ええっと…この後なんて言うのかド忘れしちゃった<sprite=emo_sikao size=60 />。",
  str_homestory_807501001_29_dialog_content = "プッ…",
  str_homestory_807501001_30_dialog_content = "ちょっと、次笑ったら通信設備で他人を呼ぶわよ！",
  str_homestory_807501001_31_dialog_content = "ハハハ。",
  str_homestory_807501001_32_dialog_content = "まだ笑う気？サメヤマさんを呼ぶわよ、どう？",
  str_homestory_807501001_33_dialog_content = "サメヤマが絶対味方してくれるとは限らないよ。",
  str_homestory_807501001_34_dialog_content = "ううっ…それは確かに…",
  str_homestory_807501001_35_dialog_content = "つまり、この街灯を研究したいんだよね？",
  str_homestory_807501001_36_dialog_content = "そうよ。この精巧な作りを見てたら、\n解体したくてウズウズしてくるの。",
  str_homestory_807501001_37_dialog_content = "でも、この街灯今のところ安定して使えてるし、\n内部の構造も問題ないと思うんだ。",
  str_homestory_807501001_38_dialog_content = "だから、壊れた時に君に修理を頼むっていうのはどう？",
  str_homestory_807501001_39_dialog_content = "それはいい考えね！\nガラクタを修理するのは得意なの！",
  str_homestory_807501001_40_dialog_content = "よし、じゃあ今日は解体しないでいてあげる。",
  str_homestory_807501001_41_dialog_content = "街灯に代わってお礼を言うよ。",
  str_homestory_807501001_42_dialog_content = "そう言えば、さっき水の中にキラッと光るものが\n見えたけど、機械の部品かもしれない！",
  str_homestory_807501001_43_dialog_content = "引き上げて解体してみましょ！",
  str_homestory_807501001_44_dialog_content = "うーん、水の中の物を助けに行った方がよさそう。",
  str_homestory_820601001_0_dialog_content = "彼女、何してるんだろう？",
  str_homestory_820601001_1_dialog_content = "何を見てるの？<sprite=emo_yihuo size=60 />",
  str_homestory_820601001_2_dialog_content = "上からの眺めは最高ね！",
  str_homestory_820601001_3_dialog_content = "ずっとそこにいるけど、本当に景色を眺めてるだけ？",
  str_homestory_820601001_4_dialog_content = "景色のことは置いといて、私と事業をやってみない？",
  str_homestory_820601001_5_dialog_content = "空の末裔の鋭い感覚、\n今後の商戦で必ず私の役に立つわ！",
  str_homestory_820601001_6_dialog_content = "商戦？役に立つ？",
  str_homestory_820601001_7_dialog_content = "よく「ビジネスは戦場」と言うでしょう？\n今の私に必要なのはあなたのような人材よ！",
  str_homestory_820601001_8_dialog_content = "報奨金も出すし、株も分配する。\nどう？やってみない？",
  str_homestory_820601001_9_dialog_content = "事業展開と株数によるかな…",
  str_homestory_820601001_10_dialog_content = "ちょっと待って、やるとは言ってないよ！",
  str_homestory_820601001_11_dialog_content = "それに商戦の件は？\n景色を眺めていたことと何か関係があるの？",
  str_homestory_820601001_12_dialog_content = "実はね、すごい商売のアイデアを思いついたの…\n誰にも言わないでね。",
  str_homestory_820601001_13_dialog_content = "うっ、うん。",
  str_homestory_820601001_14_dialog_content = "それは…ブルーオーシャンに突撃！",
  str_homestory_820601001_15_option_content = "ブルーオーシャン？",
  str_homestory_820601001_16_dialog_content = "その名の通り、大海原よ！",
  str_homestory_820601001_17_dialog_content = "それって…海運業を始めるってこと？",
  str_homestory_820601001_18_option_content = "造船業？",
  str_homestory_820601001_19_dialog_content = "違うわ！",
  str_homestory_820601001_20_dialog_content = "ブルーオーシャンは1つの比喩、比喩よ！",
  str_homestory_820601001_21_dialog_content = "…なんの比喩？",
  str_homestory_820601001_22_dialog_content = "ビジネスの世界では、\n競争相手のいない未開拓の市場を表す言葉なの！",
  str_homestory_820601001_23_dialog_content = "でも、それと展望台からの眺めと何の関係があるの？",
  str_homestory_820601001_24_dialog_content = "あの海上の小さな島々は開発されていないな～\nと気づいたのよ！",
  str_homestory_820601001_25_dialog_content = "現実的にもビジネス的な意味でも、\nブルーオーシャンだって！",
  str_homestory_820601001_26_dialog_content = "もし小島を発見して、\nそれをリゾート地として開発できたら…",
  str_homestory_820601001_27_dialog_content = "避暑、探検、宝探し、スポーツ、\n水着、ファミリーパーク…",
  str_homestory_820601001_28_dialog_content = "テーマに関することだけでも次々に思いついちゃう！",
  str_homestory_820601001_29_dialog_content = "ローレライは島の開発がしたいんだね？\n具体的な目標はあるの？",
  str_homestory_820601001_30_dialog_content = "船を手に入れて、\nふさわしい島を探しに行きたいと思ってる。",
  str_homestory_820601001_31_dialog_content = "海はあんなに広いもの、\nどこかに無人島だってあるはずよ！",
  str_homestory_820601001_32_dialog_content = "最初に発見すれば島は私たちのもの。\n好きなように開発できるわ！",
  str_homestory_820601001_33_dialog_content = "私たち！？僕も行くの？",
  str_homestory_820601001_34_dialog_content = "そうよ！その人並外れた視力と聴力…\n絶対に役に立つわ。",
  str_homestory_820601001_35_dialog_content = "その言い方だと僕はまるで超人だね。",
  str_homestory_820601001_36_dialog_content = "つまり、まずはふさわしい島を見つける？",
  str_homestory_820601001_37_dialog_content = "そうよ！あの展望台を船に運んだら、\nより遠くまで見渡せるか確かめたいの。",
  str_homestory_820601001_38_dialog_content = "ちょうどいいところに来たわ。\nついでに値段を教えて。",
  str_homestory_820601001_39_dialog_content = "売るつもりはないよ…<sprite=emo_tanqi size=60 />",
  str_homestory_820601001_40_dialog_content = "あれを出資金代わりにするってこと？\nこの事業にかなり乗り気みたいね。",
  str_homestory_820601001_41_dialog_content = "そういう意味じゃなくて…",
  str_homestory_820601001_42_dialog_content = "もっと考える？\nいいわよ、どうせ企画書もまだ書いていないし。\nサインする前なら話し合いには応じるわ。",
  str_homestory_820601001_43_dialog_content = "具体的なプランを早く固めたいから、\nあなたも早く決めなさいよね！",
  str_homestory_820601001_44_dialog_content = "…うん、じゃあね。",
  str_homestory_820701001_0_dialog_content = "彼、遊んでるの？",
  str_homestory_820701001_1_dialog_content = "なんだか楽しそうだね。",
  str_homestory_820701001_2_dialog_content = "新しいアイテムを素早く天空ノ庭に導入するなんて、\nなかなかやるねー！超スリリングだ！",
  str_homestory_820701001_3_dialog_content = "でも、この遊具は2人向きって聞いてるけど。",
  str_homestory_820701001_4_dialog_content = "2人で遊ぶ場合は一種のテストみたいなもんだな。\n特にカップルにとっちゃな…<sprite=emo_sikao size=60 />",
  str_homestory_820701001_5_dialog_content = "テスト？",
  str_homestory_820701001_6_dialog_content = "交際を始めた2人がこれに乗る。\nそしてグルグル回って…",
  str_homestory_820701001_7_dialog_content = "降りた後、すぐに相手の気持ちを\n聞いたり、気遣えたら…",
  str_homestory_820701001_8_dialog_content = "その関係は大丈夫。そうじゃない場合は…",
  str_homestory_820701001_9_dialog_content = "じゃあセナは何のために乗ってるの？\n将来のテストの準備？",
  str_homestory_820701001_10_dialog_content = "ブーッ、不正解！",
  str_homestory_820701001_11_dialog_content = "乗ってると目が回るけど、すごく刺激的だ。",
  str_homestory_820701001_12_dialog_content = "その刺激のおかげで過去の日々を思い出した…",
  str_homestory_820701001_13_dialog_content = "過去に何があったの…\nなにか物語があるみたいだね。",
  str_homestory_820701001_14_dialog_content = "オレは以前「ハンター」だった。\n特定の悪党を狙って狩ってたんだ。",
  str_homestory_820701001_15_dialog_content = "保安官みたいな？\nでも、セナはたしかR・W砂漠の出身…",
  str_homestory_820701001_16_dialog_content = "あの辺をうろついてるのはR・Wくらいで、\nそんな連中はいないでしょう？",
  str_homestory_820701001_17_dialog_content = "オレの個人的行動だから、\n「ボランティア保安官」ではなく\n「ハンター」と言ったんだ。",
  str_homestory_820701001_18_dialog_content = "じゃあターゲットの「悪党」って誰？\nこの先の話に関係があるの？",
  str_homestory_820701001_19_dialog_content = "以前デヌオ渓谷で村が破壊されたって聞いたけど、\nそれと関係があるの？",
  str_homestory_820701001_20_dialog_content = "どこから話そうか…まぁ、聞いてくれ。",
  str_homestory_820701001_21_dialog_content = "分かった。",
  str_homestory_820701001_22_dialog_content = "むかしむかし、超絶技術を持った腕のいい漁師がいた。",
  str_homestory_820701001_23_dialog_content = "彼が編む網はとても丈夫で、網目もすごく小さかった。\nだからどんな魚も逃さなかったんだよ。",
  str_homestory_820701001_24_dialog_content = "漁に出るたびに大漁だったから、\n一家はかなり裕福になった。",
  str_homestory_820701001_25_dialog_content = "だが…徐々に魚が捕れなくなった。",
  str_homestory_820701001_26_dialog_content = "魚がいなくなったから？",
  str_homestory_820701001_27_dialog_content = "正解！網目が小さいから、\n毎回、稚魚まで捕ってたんだ。",
  str_homestory_820701001_28_dialog_content = "だんだんと魚が減って、\n漁師の家は飯も食えないほど困窮した。\nそして、その日が来た…",
  str_homestory_820701001_29_dialog_content = "何かが起きるんだね。<sprite=emo_yaosu size=60 />",
  str_homestory_820701001_30_dialog_content = "漁師の息子が秘密の岩礁で美しい魚を見つけたんだ。",
  str_homestory_820701001_31_dialog_content = "大きさからみて幼魚のようだが、とにかく美しかった。",
  str_homestory_820701001_32_dialog_content = "家に帰ると、彼はすぐに漁師、つまり父親に話した。",
  str_homestory_820701001_33_dialog_content = "きっと急いで捕まえに行くと思うよ。",
  str_homestory_820701001_34_dialog_content = "漁師は最も丈夫で最も網目が細かい網を持って、\n魚を捕らえに行った。",
  str_homestory_820701001_35_dialog_content = "市場に出せば高値がつく貴重な観賞魚だと\n知っていたからね。",
  str_homestory_820701001_36_dialog_content = "彼は息子に案内させて、\nその秘密の岩礁に向かった…",
  str_homestory_820701001_37_dialog_content = "失敗するんじゃない？",
  str_homestory_820701001_38_dialog_content = "正解！彼らは魚を見つけたが、\nその魚はさらに大きく、さらに美しかった。",
  str_homestory_820701001_39_dialog_content = "その魚は息子が見た魚の親だった？",
  str_homestory_820701001_40_dialog_content = "たぶん、そうだろうね。",
  str_homestory_820701001_41_dialog_content = "その美しい大きな魚はボートを見ると、\nすぐに暗礁の中を逃げ回った。",
  str_homestory_820701001_42_dialog_content = "漁師もボートで追いかけ、\n追っては逃げる展開に…",
  str_homestory_820701001_43_dialog_content = "だがボートは岩礁に衝突した。",
  str_homestory_820701001_44_dialog_content = "ボートは沈み、漁師も息子も死んだ。",
  str_homestory_820701001_45_dialog_content = "ああ…",
  str_homestory_820701001_46_dialog_content = "さっき言ってた悪党は誰なの？\nこの物語では漁師も息子も死んでしまった。",
  str_homestory_820701001_47_dialog_content = "なので、これは単なるお話。\nあまり深く追求しないでくれ。",
  str_homestory_820801001_0_dialog_content = "ずっとぼーっとしてる…",
  str_homestory_820801001_1_dialog_content = "何をしてるの？",
  str_homestory_820801001_2_dialog_content = "あっ、PlayerName！？まさか気付かれるとは！<sprite=emo_wuzui size=60 />",
  str_homestory_820801001_3_dialog_content = "この記念碑をずっと見てたよね、\n目が疲れてない？",
  str_homestory_820801001_4_dialog_content = "そういえば、確かにちょっと痛いかも…",
  str_homestory_820801001_5_dialog_content = "そうじゃなくて！\n大事なのはなぜ私に気付いたかってこと！",
  str_homestory_820801001_6_dialog_content = "それがこれの力なのかな？\n存在感の薄い人間を目立たせる能力？",
  str_homestory_820801001_7_dialog_content = "いやいや。バップが長時間ここに立っていたからだよ。",
  str_homestory_820801001_8_dialog_content = "記念碑の文様を見て！\nPlayerNameには意味がわかる？",
  str_homestory_820801001_9_dialog_content = "よくわからないな…古代のものみたいだけど。",
  str_homestory_820801001_10_dialog_content = "歳月が経ちすぎて、\nもう意味を理解する方法はないかもしれないね。",
  str_homestory_820801001_11_dialog_content = "そっか…はぁ…",
  str_homestory_820801001_12_dialog_content = "突然どうしたの？なんだか寂しそうだよ。",
  str_homestory_820801001_13_dialog_content = "R・Wの未来について考えてたの…",
  str_homestory_820801001_14_option_content = "未来？",
  str_homestory_820801001_15_dialog_content = "今はまだ思いつかないけど、\n長期的な目標が必要かなって…\n今みたいにダラダラしてちゃダメだよ。",
  str_homestory_820801001_16_dialog_content = "それがR・Wのスタイルでしょ？\nみんなそれが気に入って参加してる。",
  str_homestory_820801001_17_dialog_content = "そうなんだけど…\nでもビジョンはあったほうがいい！\n今は無理でも必ずちゃんと見つける！",
  str_homestory_820801001_18_option_content = "なぜそこまで考えるの？",
  str_homestory_820801001_19_dialog_content = "…",
  str_homestory_820801001_20_dialog_content = "バップ？",
  str_homestory_820801001_21_dialog_content = "理由はわからない。\nでも、誰かがちゃんと考えないとダメだと思う！",
  str_homestory_820801001_22_dialog_content = "目先のことしか考えずに、\n毎日ダラダラと遊びまわるだけ…\nそれで良いわけない。",
  str_homestory_820801001_23_dialog_content = "真剣に考えてるんだね。バップも大変だ…",
  str_homestory_820801001_24_dialog_content = "サメヤマもそこまで考えてないかもしれないね。",
  str_homestory_820801001_25_dialog_content = "だよね。彼は今のまま\n豪放磊落なリーダーでいれば、それで十分。",
  str_homestory_820801001_26_dialog_content = "この手の事は軍師の私が考えて計画すべきなんだ。",
  str_homestory_820801001_27_dialog_content = "でも、それと記念碑と何の関係があるの？",
  str_homestory_820801001_28_dialog_content = "連想しちゃったのよ！",
  str_homestory_820801001_29_dialog_content = "白夜城、啓光連邦、北境にさえ\n記念碑はあると聞いた。",
  str_homestory_820801001_30_dialog_content = "その目的は、その地の有名人、偉大な業績、\n大事件なんかを記念するため。",
  str_homestory_820801001_31_dialog_content = "でもR・Wにはそういう物はない…",
  str_homestory_820801001_32_dialog_content = "しかもR・Wには自分たちの地盤もない…",
  str_homestory_820801001_33_dialog_content = "この先、うまく進まなくなったり、\n大喧嘩が起こったりして、\n一気に解散になったらどうしようって！",
  str_homestory_820801001_34_dialog_content = "確かに一理あるよね。",
  str_homestory_820801001_35_dialog_content = "そうでしょう！？",
  str_homestory_820801001_36_dialog_content = "でも、記念碑の形について考えたことある？",
  str_homestory_820801001_37_dialog_content = "形？",
  str_homestory_820801001_38_dialog_content = "記念碑の形をしていなくても、\nR・Wを象徴できる物ならいいんじゃない？",
  str_homestory_820801001_39_dialog_content = "それって…",
  str_homestory_820801001_40_dialog_content = "たとえば車体のペイントとか？",
  str_homestory_820801001_41_dialog_content = "それが君たちのスタイルだよね。\n地の果てまで行っても一目でR・Wだとわかる。",
  str_homestory_820801001_42_dialog_content = "たとえばサンドワームを撃退したら、\nサンドワームの絵を描いて\nその上にバツ印を付けるとか。",
  str_homestory_820801001_43_dialog_content = "いい！それはいいアイデアよ！",
  str_homestory_820801001_44_dialog_content = "しかもR・Wにはペイントの達人が、\nそれこそ腐るほどいるわ！",
  str_homestory_820801001_45_dialog_content = "「R・Wカーペイント王決定戦」\nの開催方法を考えてみるね！<sprite=emo_yaosu size=60 />",
  str_homestory_820901001_0_dialog_content = "何を見てるんだろう…？",
  str_homestory_820901001_1_dialog_content = "ラス、ここで何をしてるの？",
  str_homestory_820901001_2_dialog_content = "特に何も。面白いものを見つけただけよ。",
  str_homestory_820901001_3_dialog_content = "啓光はこういう方法で兵力を拡大していたのね。",
  str_homestory_820901001_4_dialog_content = "君は大元帥でしょ？どうして今さら…？",
  str_homestory_820901001_5_dialog_content = "兵士の徴集は大元帥の仕事じゃないの。",
  str_homestory_820901001_6_dialog_content = "たぶんね。",
  str_homestory_820901001_7_option_content = "確かにそうだね",
  str_homestory_820901001_8_dialog_content = "大元帥がそんなことに構ってる暇はないよね。",
  str_homestory_820901001_9_option_content = "たぶん！？",
  str_homestory_820901001_10_dialog_content = "たぶんって…自分の仕事のことでしょ！？",
  str_homestory_820901001_11_dialog_content = "大元帥になって初めての任務からして、\n兵士を連れて戦場へ出ることだったもの。",
  str_homestory_820901001_12_dialog_content = "でも確かに、そろそろ他の職務についても\n聞かなきゃいけない頃ね。",
  str_homestory_820901001_13_dialog_content = "これ、どこで見つけたの？",
  str_homestory_820901001_14_dialog_content = "影ノ街だよ…確か映画を撮る時に見つけたんだ。",
  str_homestory_820901001_15_dialog_content = "映画？…思いついたわ<sprite=emo_sikao size=60 />。",
  str_homestory_820901001_16_dialog_content = "何を？",
  str_homestory_820901001_17_dialog_content = "徴兵の公告よ。こんな板一枚じゃ人なんて集まらないわ。",
  str_homestory_820901001_18_dialog_content = "私が大元帥の間に、啓光をもっと強くしないと。",
  str_homestory_820901001_19_dialog_content = "それで？",
  str_homestory_820901001_20_dialog_content = "啓光の軍人をテーマにした映画を撮って、\n広告にするのはどう？",
  str_homestory_820901001_21_option_content = "それ、本気で言ってるの？",
  str_homestory_820901001_22_dialog_content = "君がそのつもりでも…啓光の人たちに映画なんて撮れるのかな…？",
  str_homestory_820901001_23_dialog_content = "もっともな心配ね。啓光の教育って理工学の応用と戦場のことばっかりで、\n芸術はサッパリだし。",
  str_homestory_820901001_24_dialog_content = "でしょ？",
  str_homestory_820901001_25_dialog_content = "だから、あんたに頼もうかと思ったのよ。",
  str_homestory_820901001_26_option_content = "分かった、撮ろう！",
  str_homestory_820901001_27_dialog_content = "どんなにいいキャッチコピーでも、\n確かに映画には負けるよね。",
  str_homestory_820901001_28_dialog_content = "啓光の戦士たちの勇ましい姿がスクリーンに映し出されたら、\nきっとものすごい印象を与えられるよ。",
  str_homestory_820901001_29_dialog_content = "僕も楽しみだ！",
  str_homestory_820901001_30_dialog_content = "いいじゃない。じゃ、この件はあんたに頼んだわ。\n報酬はきちんと用意しておくから。",
  str_homestory_820901001_31_dialog_content = "僕が？無理だよ。",
  str_homestory_820901001_32_dialog_content = "空の末裔って創作が得意なんでしょ？\n確か詩を書いてたじゃない。",
  str_homestory_820901001_33_dialog_content = "詩を書くのと映画を撮るのはまた別ものだよ。\nそれに詩だって上手なわけじゃないし。",
  str_homestory_820901001_34_dialog_content = "どっちも芸術なんだから、通じるものがあるはずよ。",
  str_homestory_820901001_35_dialog_content = "そういうわけにはいかないよ。",
  str_homestory_820901001_36_dialog_content = "それに啓光には映画館、ないよね？",
  str_homestory_820901001_37_dialog_content = "スクリーンホールならあるわ。\n休日にしか開かないけど。",
  str_homestory_820901001_38_dialog_content = "つまり、映画を見る時間のある人もいないってことだね。",
  str_homestory_820901001_39_dialog_content = "啓光はもともと全員が兵士だし。\nこういう広告は全部、外向けよ。",
  str_homestory_820901001_40_dialog_content = "ただ…そう言われてみると、\n啓光内部でも映画を観せれば士気は上げられそうね。",
  str_homestory_820901001_41_dialog_content = "そうとなれば…またとないチャンスだわ。\n私も出演しないと。",
  str_homestory_820901001_42_dialog_content = "レインハトも出すっていうのはどう？\nどっちがより観客の心を動かせるか勝負するの。",
  str_homestory_820901001_43_dialog_content = "軍団長たちも出たら、軍団同士の競い合いも促せるかもしれないわ。",
  str_homestory_820901001_44_dialog_content = "そこまで大々的にする必要はないよ。",
  str_homestory_820901001_45_dialog_content = "そうだ、あんたも監督だけじゃなく、出演しなさい。",
  str_homestory_820901001_46_dialog_content = "この世でたった1人の空の末裔兼監督として、\n役を与えられるべきだわ。",
  str_homestory_820901001_47_dialog_content = "僕の話をまったく聞いてない…\n抵抗はあきらめた方がいいかな…<sprite=emo_yundao size=60 />",
  str_homestory_820901001_48_dialog_content = "映画のタイトルも決めたわ。",
  str_homestory_820901001_49_dialog_content = "『空の末裔PlayerNameを救え』なんてどう？",
  str_homestory_821001001_0_dialog_content = "ジョセリンが旗槍の前でお祈りをしてる…",
  str_homestory_821001001_1_dialog_content = "ジョセリン？",
  str_homestory_821001001_2_dialog_content = "お待ちいただかなくても結構でしたのに。\n遠慮なく呼んでいただいて構いませんよ。",
  str_homestory_821001001_3_dialog_content = "邪魔しちゃいけないと思って。",
  str_homestory_821001001_4_dialog_content = "祈りが遮られたくらいのことで、\n光の神が光の民の信仰を疑うことはございません。",
  str_homestory_821001001_5_dialog_content = "私はなおさら腹を立てたりいたしませんよ。\n何かお困りのことでも？",
  str_homestory_821001001_6_dialog_content = "いや、君がずっと旗槍の前に立ってるのを見かけたから…",
  str_homestory_821001001_7_dialog_content = "お祈りしてるのかなって思って。旗槍にお祈りしてたの？",
  str_homestory_821001001_8_dialog_content = "お祈り？確かに特定の媒体に対してお祈りをすると、\n神の御声がよりはっきりと聞こえてきます。",
  str_homestory_821001001_9_option_content = "旗槍とか？",
  str_homestory_821001001_10_dialog_content = "光の神を信仰するのは、白夜城の伝統だよね？",
  str_homestory_821001001_11_dialog_content = "白夜城の旗槍を媒体にお祈りするのは、\n確かにふさわしい方法かもしれないね。",
  str_homestory_821001001_12_option_content = "聖物とか？",
  str_homestory_821001001_13_dialog_content = "神と対話するなら、聖物を使うのが普通だよね。",
  str_homestory_821001001_14_dialog_content = "神と直接会うのと同じようなことだから、\n効果がある気がする。",
  str_homestory_821001001_15_dialog_content = "実際はどのようなものを媒体としてもよいのですよ。",
  str_homestory_821001001_16_dialog_content = "光<sprite=emo_taiyang size=60 />の恩恵は大地をあまねく照らします。\n太陽の光の下にあるものは全て神の御光とつながっているのです。",
  str_homestory_821001001_17_dialog_content = "畑を耕している時、私はよくトマトの花に向かって、\n祈りを捧げています。",
  str_homestory_821001001_18_dialog_content = "そういうのもアリなんだね。",
  str_homestory_821001001_19_dialog_content = "ただ、何か特定の祈りを捧げる時には、\nそれにふさわしい対象を選ばなければなりません。",
  str_homestory_821001001_20_dialog_content = "じゃあ白夜城の旗槍の場合、どういうお祈りなの？",
  str_homestory_821001001_21_dialog_content = "…",
  str_homestory_821001001_22_dialog_content = "ごめん、ちょっと興味があっただけなんだ。",
  str_homestory_821001001_23_dialog_content = "聞いちゃいけない質問だったら、\n無視してくれればいいから。",
  str_homestory_821001001_24_dialog_content = "そんなことはありません。\n光の神の恩恵を全ての人に伝えるのは私の使命でもありますから。",
  str_homestory_821001001_25_dialog_content = "信仰に関わることは、\n知っている限り全てお話しします。",
  str_homestory_821001001_26_dialog_content = "ただ先程私は…",
  str_homestory_821001001_27_dialog_content = "ただ？",
  str_homestory_821001001_28_dialog_content = "旗槍の仕立て具合を近くで見たかっただけなのです。",
  str_homestory_821001001_29_dialog_content = "白夜城で作られた信仰に関わる物は、\nどれもとても精巧に出来ています。",
  str_homestory_821001001_30_dialog_content = "特に旗槍は人々を導く目印です。\n丈夫でなければなりません。",
  str_homestory_821001001_31_dialog_content = "私も仕立ての腕を上げることができれば、\nさらに皆さんのお役に立てます。",
  str_homestory_821001001_32_dialog_content = "ジョセリンが旗槍を掲げる勇姿を見たくなっちゃったな。",
  str_homestory_821001001_33_dialog_content = "私には無理ですよ。\n旗槍の扱いはそう簡単ではありませんから。",
  str_homestory_821001001_34_dialog_content = "皆さんから恐れ多くも「聖女」と呼ばれていますが、\n私にはまだ人々を導く力はございません。",
  str_homestory_821001001_35_dialog_content = "今はまずアイアンソーン騎士団のために、\nよい軍旗を仕立てることから始めるべきでしょう。",
  str_homestory_821001001_36_dialog_content = "そうだね。いい旗を作ることは\nそれを振るうのと同じくらい重要だよね。僕も手伝うよ。",
  str_homestory_821001001_37_dialog_content = "あなたも裁縫が得意なのですか？",
  str_homestory_821001001_38_dialog_content = "小さい頃ソラヴァンに少し教わったんだ…",
  str_homestory_821001001_39_dialog_content = "私もお教えしましょう。\n教えることは私自身の技術の基礎固めと向上にもつながります。",
  str_homestory_821001001_40_dialog_content = "まずはお洋服を全て持ってきてください。",
  str_homestory_821001001_41_dialog_content = "ぜ、全部…？",
  str_homestory_821001001_42_dialog_content = "たくさん練習しなければ、基礎は身に付きません。",
  str_homestory_821001001_43_dialog_content = "理屈だけ知って実践しなければ、\nたとえ光の神であっても、なすすべがありません。",
  str_homestory_821001001_44_dialog_content = "あなたはそういう方ではありませんよね。",
  str_homestory_821001001_45_dialog_content = "分かった。すぐに持ってくるよ！",
  str_homestory_821201001_0_dialog_content = "アントニー？",
  str_homestory_821201001_1_dialog_content = "アントニー、「ボーンコリドー」のそばに立って30分になるよ。",
  str_homestory_821201001_2_dialog_content = "それに興味があるの？",
  str_homestory_821201001_3_dialog_content = "やあ、PlayerName。",
  str_homestory_821201001_4_dialog_content = "正直に言うと、たしかに興味はある。",
  str_homestory_821201001_5_dialog_content = "初めてこれを見たとき、確信したんだ。",
  str_homestory_821201001_6_dialog_content = "これは絶対に研究する価値があるってね！",
  str_homestory_821201001_7_dialog_content = "聞いてもいいかな？これは何の骨なんだい？",
  str_homestory_821201001_8_dialog_content = "それはちょっと難しい質問だな…",
  str_homestory_821201001_9_dialog_content = "まだ統一見解はなくて、さまざまな説があるんだよ。",
  str_homestory_821201001_10_dialog_content = "君の視点からだと、どう判断する？",
  str_homestory_821201001_11_dialog_content = "俺は君の判断を信じる。",
  str_homestory_821201001_12_dialog_content = "そうだな<sprite=emo_sikao size=60 />…おそらく…",
  str_homestory_821201001_13_option_content = "何かの動物の骨",
  str_homestory_821201001_14_dialog_content = "動物の骨なの？",
  str_homestory_821201001_15_dialog_content = "俺はいろいろな場所に行ったけど、こんな骨は見たことないよ。",
  str_homestory_821201001_16_dialog_content = "ということは、絶滅した生物の骨かもしれない！",
  str_homestory_821201001_17_dialog_content = "…本当に？",
  str_homestory_821201001_18_option_content = "巨像の竜骨",
  str_homestory_821201001_19_dialog_content = "何だって！？",
  str_homestory_821201001_20_dialog_content = "PlayerName、だまさないでくれよ！",
  str_homestory_821201001_21_dialog_content = "こ、こ、これは本当に巨像を作るのに使った竜骨なの！？",
  str_homestory_821201001_22_dialog_content = "僕もうわさで聞いただけだよ。",
  str_homestory_821201001_23_dialog_content = "いやいや、君は空の末裔だろ！\n君がいうことなら絶対に間違いはないよ！",
  str_homestory_821201001_24_dialog_content = "いずれにせよ、「ボーンコリドー」をしっかり研究しなくちゃ！",
  str_homestory_821201001_25_dialog_content = "これの一部を部屋に持っていって研究してもいい！？",
  str_homestory_821201001_26_dialog_content = "ちょっと、何であろうと部屋には持っていかないでよ！",
  str_homestory_821201001_27_dialog_content = "いずれにせよ、それは公共のものだからね…",
  str_homestory_821201001_28_dialog_content = "でも、それが一体何なのか僕も興味があるな。",
  str_homestory_821201001_29_dialog_content = "こうしよう。ここでなら研究をしていいよ。\n人手が足りないようなら助っ人を見つけてあげる。",
  str_homestory_821201001_30_dialog_content = "安心してよ！",
  str_homestory_821201001_31_dialog_content = "これが一体何なのか必ず突き止めてみせるよ！<sprite=emo_dianzan size=60 />",
  str_homestory_821101001_0_dialog_content = "ザーリャ？何をしているの？",
  str_homestory_821101001_1_dialog_content = "あら？PlayerName、これは何なの？",
  str_homestory_821101001_2_dialog_content = "「シャーロックの車」と書かれているけど。",
  str_homestory_821101001_3_dialog_content = "「車」…って何？",
  str_homestory_821101001_4_dialog_content = "簡単に言うと、便利な乗り物の一種だよ。",
  str_homestory_821101001_5_dialog_content = "これは乗り物なの？",
  str_homestory_821101001_6_dialog_content = "もう馬車を使わないの…？",
  str_homestory_821101001_7_dialog_content = "場所によっては、まだ馬車を使う風習が残っているよ。\nでも、ほとんどの地域では、お金のある人は車に乗るよ。",
  str_homestory_821101001_8_dialog_content = "そうなのね…",
  str_homestory_821101001_9_dialog_content = "ザーリャは車に興味があるの？",
  str_homestory_821101001_10_dialog_content = "見たことがないものだからね。そりゃ少しは興味があるわよ。",
  str_homestory_821101001_11_dialog_content = "後で「本物」を見せに連れて行ってくれない？",
  str_homestory_821101001_12_option_content = "いいよ",
  str_homestory_821101001_13_dialog_content = "でも、君は後部座席に座ることが条件だよ。",
  str_homestory_821101001_14_dialog_content = "絶対に運転はさせられない。",
  str_homestory_821101001_15_option_content = "ダメだよ",
  str_homestory_821101001_16_dialog_content = "えっ、どうして…<sprite=emo_yihuo size=60 />",
  str_homestory_821101001_17_dialog_content = "すごく危険なことをしそうな気がするからね。",
  str_homestory_821101001_18_dialog_content = "たとえば、車を運転しようとするとかね。",
  str_homestory_821101001_19_dialog_content = "お見事ね、PlayerName。",
  str_homestory_821101001_20_dialog_content = "どうして私がその「機械馬車」に「騎乗」しようとしていると分かったの？",
  str_homestory_821101001_21_dialog_content = "騎乗する？",
  str_homestory_821101001_22_dialog_content = "それは馬車みたいな乗り物だと言っていたでしょう？",
  str_homestory_821101001_23_dialog_content = "それなら原理も同じはずよね？",
  str_homestory_821101001_24_dialog_content = "どこかをムチでたたけば走り出すはずよ。",
  str_homestory_821101001_25_dialog_content = "あるいは何か指示を伝えるとか？",
  str_homestory_821101001_26_dialog_content = "光力術の扱いはうまくないけど、乗馬は得意なのよ。",
  str_homestory_821101001_27_dialog_content = "…",
  str_homestory_821101001_28_dialog_content = "あら？どうして何も言わないの？",
  str_homestory_821101001_29_dialog_content = "君は本当に現代の知識を勉強し直す必要があるみたいだね…",
  str_homestory_821101001_30_dialog_content = "…えっ？",
  str_homestory_821301001_0_dialog_content = "33号？",
  str_homestory_821301001_1_dialog_content = "ピクニックに行こうとしているの？",
  str_homestory_821301001_2_dialog_content = "はい、ご覧の通りです。",
  str_homestory_821301001_3_dialog_content = "そのために支度を調えているところです。",
  str_homestory_821301001_4_dialog_content = "1人で行くつもりじゃないよね？",
  str_homestory_821301001_5_dialog_content = "あなたは私のことを少し誤解されているようですね。",
  str_homestory_821301001_6_dialog_content = "当然、他の光霊の友人も誘っております。",
  str_homestory_821301001_7_dialog_content = "もちろん、その中にはあなたも含まれています。",
  str_homestory_821301001_8_dialog_content = "それは光栄だね。",
  str_homestory_821301001_9_dialog_content = "…",
  str_homestory_821301001_10_dialog_content = "そういえば、どうしてまだバイスたちを誘ってないの？",
  str_homestory_821301001_11_dialog_content = "私は今、重要な分析作業をしています。",
  str_homestory_821301001_12_dialog_content = "他の人から、あなた方のこれまでのピクニックでの食事量を聞きました。",
  str_homestory_821301001_13_dialog_content = "さらに友人たちから送られきたピクニック用の料理と合わせて考えると、\nとても危険な結論に達したのです。",
  str_homestory_821301001_14_dialog_content = "カロリーが高すぎ、健康を大いに損ないます。",
  str_homestory_821301001_15_dialog_content = "えっ？",
  str_homestory_821301001_16_dialog_content = "PlayerName様、どう思われますか？",
  str_homestory_821301001_17_option_content = "その通りだね",
  str_homestory_821301001_18_dialog_content = "栄養学の観点からすると、\nこれらの食べ物はたしかにカロリーが高すぎるね。",
  str_homestory_821301001_19_dialog_content = "私の意見に完全に同意するとは珍しいですね。",
  str_homestory_821301001_20_dialog_content = "でも…",
  str_homestory_821301001_21_option_content = "そんなことはないよ",
  str_homestory_821301001_22_dialog_content = "「そんなことはないよ」という結論について、\nどのような分析で導き出したのですか？",
  str_homestory_821301001_23_dialog_content = "私の今の判断は合理的だと考えます。",
  str_homestory_821301001_24_dialog_content = "ピクニックに行くんだから、\n当然、リラックスするのが主な目的でしょ。",
  str_homestory_821301001_25_dialog_content = "細かいことを考えていたら、リラックスできなくなっちゃうよ。",
  str_homestory_821301001_26_dialog_content = "細かいこと？リラックス？",
  str_homestory_821301001_27_dialog_content = "33号は僕たちのことを考えてくれているんだろうけど、\nそこまで厳しくしなくていい時もあるんだよ。",
  str_homestory_821301001_28_dialog_content = "厳しくするときは厳しく、リラックスするときはリラックスする。\nその方がもっと多くの人たちが君を好きになるよ。",
  str_homestory_821301001_29_dialog_content = "情報を受け取りました。情報を分析します。",
  str_homestory_821301001_30_dialog_content = "分かりました。",
  str_homestory_821301001_31_dialog_content = "それでは、レシピの変更を行います。",
  str_homestory_821301001_32_dialog_content = "招待をお待ちください。",
  str_homestory_821401001_0_dialog_content = "レベッカ？",
  str_homestory_821401001_1_dialog_content = "ナビゲーター…",
  str_homestory_821401001_2_dialog_content = "ハンギングチェアに座りたいの？",
  str_homestory_821401001_3_dialog_content = "いいえ…ただ、少し懐かしくて…",
  str_homestory_821401001_4_dialog_content = "以前……うちの庭にも似たようなものがあったのよ。",
  str_homestory_821401001_5_dialog_content = "あの頃、私と姉、それからエレノアはよくいっしょに座って遊んでいたの。",
  str_homestory_821401001_6_dialog_content = "でもチェアが小さいから……座れるのは2人だけだったわ。",
  str_homestory_821401001_7_dialog_content = "つまり、1人は降りないといけなかったの……",
  str_homestory_821401001_8_dialog_content = "えっ？じゃあ、誰が降りるかどうやって決めたの？",
  str_homestory_821401001_9_dialog_content = "ジャンケンよ。",
  str_homestory_821401001_10_dialog_content = "今思えば不思議だわ。あの頃、私はジャンケンで負けたことがないの。一度もよ。",
  str_homestory_821401001_11_dialog_content = "あとの2人でそう取り決めしてのでは？",
  str_homestory_821401001_12_dialog_content = "そうなのかしら？でも姉とエレノアは……あまり仲が良くなかったし……",
  str_homestory_821401001_13_dialog_content = "そうそう、一度私が自分から降りたら……",
  str_homestory_821401001_14_dialog_content = "姉とエレノアがチェアの上でケンカを始めてしまったの。",
  str_homestory_821401001_15_dialog_content = "あの時はもう少しでハンギングチェアが壊れそうになった……",
  str_homestory_821401001_16_dialog_content = "すごく懐かしいみたいだね<sprite=emo_sikao size=60 />。",
  str_homestory_821401001_17_dialog_content = "乗ってみない？",
  str_homestory_821401001_18_dialog_content = "え？本当に？それなら……",
  str_homestory_821401001_19_dialog_content = "今回は遠慮します。",
  str_homestory_821401001_20_option_content = "どうして？",
  str_homestory_821401001_21_option_content = "試してみようよ",
  str_homestory_821401001_22_dialog_content = "実は……最近、体内の毒液が少し不安定で……",
  str_homestory_821401001_23_dialog_content = "もしチェアの上でうっかり寝てしまったら、きっと溢れた毒液でチェアを壊してしまうわ。",
  str_homestory_821401001_24_dialog_content = "だから見てるだけで十分よ。",
  str_homestory_821401001_25_dialog_content = "ここで目を閉じていれば、まるですべてが昔に戻ったよう……",
  str_homestory_821401001_26_dialog_content = "大丈夫だよ。僕がそばにいるから。",
  str_homestory_821401001_27_dialog_content = "もしレベッカが寝ても、ちゃんと起こすよ。",
  str_homestory_821401001_28_dialog_content = "迷惑かもしれないけど……",
  str_homestory_821401001_29_dialog_content = "大丈夫だよ。",
  str_homestory_821401001_30_dialog_content = "じゃあ……少しだけ待ってもらえる？",
  str_homestory_821401001_31_dialog_content = "診療所に少し雑用が残っているので、終わったら来ますね。",
  str_homestory_821401001_32_dialog_content = "ありがとう、ナビゲーター。",
  str_homestory_821501001_0_dialog_content = "イーサ？",
  str_homestory_821501001_1_dialog_content = "やぁ、あんたか。",
  str_homestory_821501001_2_dialog_content = "その車がどうかしたの？ずっと見てるけど。",
  str_homestory_821501001_3_dialog_content = "うん、いい質問だね。",
  str_homestory_821501001_4_dialog_content = "この車……超クールだと思わない？",
  str_homestory_821501001_5_option_content = "思わない。",
  str_homestory_821501001_6_dialog_content = "華やかな車だとは思うけど。",
  str_homestory_821501001_7_option_content = "確かに。",
  str_homestory_821501001_8_dialog_content = "ある意味、クールかもしれない。",
  str_homestory_821501001_9_dialog_content = "とにかく、この馬車あたしに超お似合いだよ。",
  str_homestory_821501001_10_dialog_content = "もし、あたしがこの車でレベッカを迎えに行ったら……",
  str_homestory_821501001_11_dialog_content = "レベッカは絶対に感動するはず！",
  str_homestory_821501001_12_dialog_content = "この車でレベッカを迎えに行くつもりなの？",
  str_homestory_821501001_13_dialog_content = "そうだよ。レベッカは体が弱いでしょ。",
  str_homestory_821501001_14_dialog_content = "でも毎日歩いて通勤してる。ちょっと可哀想だと思わない？",
  str_homestory_821501001_15_dialog_content = "確かに大変だね。",
  str_homestory_821501001_16_dialog_content = "でしょでしょ。だから必死に考えて思い付いたんだよ。",
  str_homestory_821501001_17_dialog_content = "「欲しいものがわかってない」ってレベッカによく言われるけど、\n今回はニーズにピッタリなはず！",
  str_homestory_821501001_18_dialog_content = "でも……この車すごく派手だよね。レベッカは喜ばないと思うよ。",
  str_homestory_821501001_19_dialog_content = "大丈夫だって。あたしはレベッカの姉だよ。妹の好みなら何でも知ってるよ。",
  str_homestory_821501001_20_dialog_content = "あの子は花が大好きだから、この花だらけの車、嫌がるはずないって！",
  str_homestory_821501001_21_dialog_content = "……ふ～ん、じゃあ試してみれば？",
  str_homestory_821501001_22_dialog_content = "よし！今からレベッカに話に行こう。",
  str_homestory_821501001_23_dialog_content = "きっとすごく喜ぶよ。",
  str_homestory_821501001_24_dialog_content = "がんばって。",
  str_homestory_821601001_0_dialog_content = "センキョク、その機械がどうかしたの？",
  str_homestory_821601001_1_dialog_content = "空の末裔が昔使ってたものなんだけど、興味あるの？",
  str_homestory_821601001_2_dialog_content = "ええ…これって紡績機よね。",
  str_homestory_821601001_3_dialog_content = "うん。ソラヴァンに資料が残ってるんだ。",
  str_homestory_821601001_4_dialog_content = "天空ノ谷ではこういう機械で布を作って、\n自給自足の生活をしてたってわけね。",
  str_homestory_821601001_5_dialog_content = "でも、複雑な手入れが必要みたいで、もう長い間使ってないんだ…",
  str_homestory_821601001_6_dialog_content = "使ってみる？",
  str_homestory_821601001_7_dialog_content = "その必要はないわ。",
  str_homestory_821601001_8_dialog_content = "ただ懐かしく思っていただけだから。",
  str_homestory_821601001_9_dialog_content = "懐かしい？",
  str_homestory_821601001_10_dialog_content = "そうよ。小さい頃に使ってた見本のカラクリを思い出すわ。",
  str_homestory_821601001_11_dialog_content = "流派の師匠が幼い弟子にカラクリ造りを教える時、\nまずは基本となる典型例を学ばせるの。",
  str_homestory_821601001_12_dialog_content = "こういう紡績機はよく教材として使われたわ。\nだから、私の第二の師匠と言えるのよ。",
  str_homestory_821601001_13_dialog_content = "どうりで興味を持つわけだね。",
  str_homestory_821601001_14_dialog_content = "しかも、こういうカラクリは壊れやすいの。",
  str_homestory_821601001_15_dialog_content = "私に与えられた紡績機もそうだったわ。\nこの紡績機の一部の構造はその時のものとそっくり…",
  str_homestory_821601001_16_dialog_content = "師匠もよく見本を使って、\nカラクリを大切にするように教えてくれたわ。",
  str_homestory_821601001_17_dialog_content = "でも…しょっちゅう壊れちゃったのよね。\n私だって大切にしたかったけど…あはは。",
  str_homestory_821601001_18_option_content = "改造したから？",
  str_homestory_821601001_19_dialog_content = "図星ね。",
  str_homestory_821601001_20_option_content = "本当に壊れやすいんだね",
  str_homestory_821601001_21_dialog_content = "違うの。私がしょっちゅう改造してたからよ…",
  str_homestory_821601001_22_dialog_content = "その見本のカラクリは私の修行に最後まで付き合うことはできなかった。",
  str_homestory_821601001_23_dialog_content = "その後成長して、うまくカラクリを扱えるようになった時には、\nもう修理できなくなってたわ。",
  str_homestory_821601001_24_dialog_content = "…そうだったんだね。",
  str_homestory_821601001_25_dialog_content = "この紡績機、直してあげてもいいわよ？",
  str_homestory_821601001_26_dialog_content = "今なら正常に動く状態に直すくらい簡単よ。",
  str_homestory_821601001_27_dialog_content = "構造に手を加えて、出来る限り自動で作業と修理ができるようにすることだって出来るわ。",
  str_homestory_821601001_28_dialog_content = "…うーん<sprite=emo_sikao size=60 />、必要ないかな。",
  str_homestory_821601001_29_dialog_content = "直したとしても、紡績の原料を手に入れるのは大変だから、\n実際に使えそうもないし。",
  str_homestory_821601001_30_dialog_content = "それに今の時代、お店に行けば、\nもっときれいな布を安く買えるからね。",
  str_homestory_821601001_31_dialog_content = "そう…龍州と同じね。",
  str_homestory_821601001_32_dialog_content = "一般の人たちにとっては、匠よりも商人の方が重要な時代になったわ。",
  str_homestory_821601001_33_dialog_content = "それも進歩の証でしょ？",
  str_homestory_821601001_34_dialog_content = "反論できないわ…このカラクリの使命も、もう終わったのね。",
  str_homestory_821601001_35_dialog_content = "ゆっくり休ませてあげましょ。",
  str_homestory_818702001_0_dialog_content = "テンカン？テンカン先生？",
  str_homestory_818702001_1_dialog_content = "こんな所で立ったまま居眠りなんかしてどうしたの？",
  str_homestory_818702001_2_dialog_content = "起きなよ。ルームに戻って休んだ方がいいよ。",
  str_homestory_818702001_3_dialog_content = "おおっと！",
  str_homestory_818702001_4_dialog_content = "今さっきまで天上の宮殿で、\n天界の将軍や兵士さんたちと談笑してたはずですがねぇ。",
  str_homestory_818702001_5_dialog_content = "なんでまた下界にいるのやら…",
  str_homestory_818702001_6_dialog_content = "どうやら、僕の修行が足りなかったようですねぇ。",
  str_homestory_818702001_7_dialog_content = "君って人は…気づいてないの？",
  str_homestory_818702001_8_dialog_content = "君が寄りかかりそうになってた物は…",
  str_homestory_818702001_9_dialog_content = "時計だよ。",
  str_homestory_818702001_10_dialog_content = "こんな大きな時計が近くにあるのに、\nあんなにぐっすり眠れるなんてすごいよ。",
  str_homestory_818702001_11_dialog_content = "おやおや、そりゃあ違いますねぇ。",
  str_homestory_818702001_12_dialog_content = "このアストラ大陸には枕元に時計を置いて寝る人が\nたくさんいるって聞いてますがねぇ？",
  str_homestory_818702001_13_dialog_content = "一方、この僕は天と地に包まれて、\n日時計に寄りかかって眠るのが好きなんです。",
  str_homestory_818702001_14_dialog_content = "郷に入っては何とやら、ですよ。",
  str_homestory_818702001_15_dialog_content = "でも、枕元に時計を置くのは時間通りに起きるためだよ。\n君はただ居眠りしてただけだよね<sprite=emo_kun size=60 />？",
  str_homestory_818702001_16_dialog_content = "時間がどんどん過ぎていく焦りみたいなものは、\nまったく感じないの…？",
  str_homestory_818702001_17_dialog_content = "時の流れは速く、人生は短いからこそ、\n睡眠が大事なんですよ。",
  str_homestory_818702001_18_dialog_content = "眠くなったら寝りゃあいいんです。\n眠気を我慢するなんざ不自然ってもんですよ。",
  str_homestory_818702001_19_dialog_content = "どうです？旦那も一つ寝てみませんか？\nそうすりゃ良さが分かると思いますがねぇ。",
  str_homestory_818702001_20_option_content = "僕はいいよ",
  str_homestory_818702001_21_dialog_content = "お若いんですねぇ。",
  str_homestory_818702001_22_dialog_content = "僕のように東西南北渡り歩くもんにとっちゃ、\n居眠りの時間は貴重なんです。",
  str_homestory_818702001_23_option_content = "試してみてもいいかな",
  str_homestory_818702001_24_dialog_content = "旦那もようやく分かってきましたねぇ！",
  str_homestory_818702001_25_dialog_content = "でも、ここで寝るとしても準備が必要だよ。",
  str_homestory_818702001_26_dialog_content = "寝袋とレジャーシート、それから他の色んな装置も持ってこなきゃ。",
  str_homestory_818702001_27_dialog_content = "さすが、旦那は楽しみ方を分かってらっしゃいますねぇ。\n旗と鳥2匹しか持ってない僕とは大違いです。",
  str_homestory_818702001_28_dialog_content = "いやはや、それにしても\n日時計さんはノンキでいいですねえ。",
  str_homestory_818702001_29_dialog_content = "龍州でも、アストラでも、やる事は同じ。",
  str_homestory_818702001_30_dialog_content = "お天道様が出なけりゃ休めるんですからねぇ。",
  str_homestory_818702001_31_dialog_content = "とうとう石に憧れ出しちゃったよ！？",
  str_homestory_818702001_32_dialog_content = "おおっと旦那、石を甘く見ちゃあいけませんよ。\n石ってのは英雄だって飛び出すんですよ！",
  str_homestory_818702001_33_dialog_content = "残念ながら、僕は夢の中でしか石になれませんがねぇ。",
  str_homestory_818702001_34_dialog_content = "おおっと、話してるうちにまた眠気がやってきました。",
  str_homestory_818702001_35_dialog_content = "君は本当に緊張感がないんだね…",
  str_homestory_818702001_36_dialog_content = "PlayerNameの旦那、人生はトボケてるくらいがちょうどいいんです。",
  str_homestory_818702001_37_dialog_content = "気の向くまま働いて、気の向くまま休んでりゃいいんです<sprite=emo_qingsong size=60 />。",
  str_homestory_818702001_38_dialog_content = "確かにそうかも…さすがテンカンだね。",
  str_homestory_818802001_0_dialog_content = "タンドウ？",
  str_homestory_818802001_1_dialog_content = "この凧…実に趣深いのう。",
  str_homestory_818802001_2_dialog_content = "整った紋様に淡い雅な色使い…",
  str_homestory_818802001_3_dialog_content = "龍州大陸の凧に似ておる。",
  str_homestory_818802001_4_dialog_content = "空の末裔もかような落ち着いた趣を好むのか？\n実に奇遇じゃのう…",
  str_homestory_818802001_5_option_content = "龍州の人たちも凧が好きなの？",
  str_homestory_818802001_6_dialog_content = "当然だ。",
  str_homestory_818802001_7_option_content = "タンドウも凧揚げをしたことある？",
  str_homestory_818802001_8_dialog_content = "むろんじゃ。わらわは凧揚げが好きでのう。",
  str_homestory_818802001_9_dialog_content = "凧揚げは龍州の子どもらが最も好む遊びの一つじゃ。",
  str_homestory_818802001_10_dialog_content = "幼い頃は姉上や妹たちと凧揚げをするのが\nそれは楽しみじゃった。",
  str_homestory_818802001_11_dialog_content = "あの頃はよく互いの凧が絡まってしまってのう。",
  str_homestory_818802001_12_dialog_content = "喧嘩になることもあったのう、ホホホ。",
  str_homestory_818802001_13_dialog_content = "じゃが、すぐに仲直りしたものじゃ。",
  str_homestory_818802001_14_dialog_content = "タンドウが揚げてた凧って、どんなだったの？",
  str_homestory_818802001_15_dialog_content = "わらわが揚げていた凧か？そうじゃな…たくさんあるのう。",
  str_homestory_818802001_16_dialog_content = "姉上や妹たちは鳥の形の凧が好きじゃったが、\nわらわは花の形が好きじゃった。",
  str_homestory_818802001_17_dialog_content = "そうなんだ。鳥の形や花の形の凧は見たことないな。",
  str_homestory_818802001_18_dialog_content = "龍州には色々な凧があるのじゃ。",
  str_homestory_818802001_19_dialog_content = "たとえば、鄴の国の凧には様々なカラクリが付いておってのう――",
  str_homestory_818802001_20_dialog_content = "凧の各所が動くのじゃ。",
  str_homestory_818802001_21_dialog_content = "わらわが幼い頃に揚げていた凧は\n宮廷内の腕利きの匠が造ったものじゃ。",
  str_homestory_818802001_22_dialog_content = "金の縁取りや朱の彩色が施され、\nそれは華やかな凧じゃった。",
  str_homestory_818802001_23_dialog_content = "実に懐かしいのう…今一度凧を揚げてみたいものじゃ。",
  str_homestory_818802001_24_dialog_content = "でも、この凧は君の揚げてた凧とは似ても似つかないよ。",
  str_homestory_818802001_25_dialog_content = "そうではないのじゃ。わらわが懐かしんでおるのは\n何の憂いもなく過ごしていた時間じゃ。",
  str_homestory_818802001_26_dialog_content = "凧そのものではない。",
  str_homestory_818802001_27_dialog_content = "ふぅ…身の回りの煩わしいことも片付いたところじゃし――",
  str_homestory_818802001_28_dialog_content = "ひと休みしても良い頃じゃのう。\n凧でも揚げてみようか。",
  str_homestory_818802001_29_dialog_content = "どうじゃ？共に凧でも揚げぬか？",
  str_homestory_818802001_30_dialog_content = "ひとりで揚げても面白くないからのう。",
  str_homestory_818802001_31_dialog_content = "でも、凧は1つしかないよ…",
  str_homestory_818802001_32_dialog_content = "かまわぬ。代わり番こで揚げるか、わらわがもう一つ作ればよいことじゃ。",
  str_homestory_822001001_0_dialog_content = "バージル？",
  str_homestory_822001001_1_dialog_content = "バージル、ずっとかかしを見つめて、どうしたの？",
  str_homestory_822001001_2_dialog_content = "このかかし…<sprite=emo_sikao size=60 />",
  str_homestory_822001001_3_dialog_content = "かかしがどうかした？まさか骨董品なの？",
  str_homestory_822001001_4_dialog_content = "パッと見た感じ、確かに骨董っぽいんだ…",
  str_homestory_822001001_5_dialog_content = "本当に？何か特徴でもあるの？",
  str_homestory_822001001_6_dialog_content = "かかしが身に付けてる物…もしかしたら骨董かも。",
  str_homestory_822001001_7_dialog_content = "骨董！？本当に？",
  str_homestory_822001001_8_dialog_content = "うん。このベストはおそらく影ノ街のブランドの限定品だね。",
  str_homestory_822001001_9_dialog_content = "50年も前に流行したデザインなんだ。",
  str_homestory_822001001_10_dialog_content = "この限定品の最大の特徴は…",
  str_homestory_822001001_11_dialog_content = "黒い布に白い線状模様を染めて作った模様なんだ。",
  str_homestory_822001001_12_dialog_content = "でも、普通は白い布に黒い線状模様を付けて作るんだよ。",
  str_homestory_822001001_13_dialog_content = "しかも、襟の後ろに金の糸で数字が縫ってあるんだ。",
  str_homestory_822001001_14_dialog_content = "本当だ…<sprite=emo_wuzui size=60 />",
  str_homestory_822001001_15_dialog_content = "それから、よく見ると、このかかしの目は黒曜石で出来てる。",
  str_homestory_822001001_16_dialog_content = "この光沢と色は、黒曜石の中でも宝石グレードのものだね。",
  str_homestory_822001001_17_dialog_content = "白夜城の貴族は数十年前、よくこの宝石でボタンを作ってたんだ。",
  str_homestory_822001001_18_dialog_content = "この2つの石も、なかなかのものだ。",
  str_homestory_822001001_19_dialog_content = "言われなかったら、気づかなかったな。",
  str_homestory_822001001_20_dialog_content = "最後に、かかしを支えてる木だけど…",
  str_homestory_822001001_21_dialog_content = "材質はおそらく香木だね。",
  str_homestory_822001001_22_dialog_content = "細い木材だから分かりにくいけど、\n近づくと微かにいい香りがしてくるよ。",
  str_homestory_822001001_23_dialog_content = "この香木で造った杖はとっても高価なんだ。",
  str_homestory_822001001_24_dialog_content = "わあ…ということは、このかかし、\nものすごく価値があるってこと？",
  str_homestory_822001001_25_dialog_content = "残念だけど…骨董品っていうのは、\n全体のバランスや出来も大切なんだ。",
  str_homestory_822001001_26_dialog_content = "一組のものがきちんとそろっていれば、価値はものすごく高くなるけど、\n一つでも欠ければ、価値が大幅に落ちちゃうんだ。",
  str_homestory_822001001_27_dialog_content = "反対でも同じことだよ。\nこのかかしは、関係のないもの同士が集まってるだけだ。",
  str_homestory_822001001_28_dialog_content = "芸術品として見ても…",
  str_homestory_822001001_29_dialog_content = "現代の三流作品としか言えない。価値はないね。",
  str_homestory_822001001_30_dialog_content = "そう…残念だな…<sprite=emo_tanqi size=60 />",
  str_homestory_822001001_31_dialog_content = "ただ…",
  str_homestory_822001001_32_dialog_content = "ただ、どうしたの？",
  str_homestory_822001001_33_dialog_content = "ただ…解体すれば話は別だよ？\nお兄ちゃん、解体する？",
  str_homestory_822001001_34_dialog_content = "うーん…それはやめておくよ。",
  str_homestory_822001001_35_dialog_content = "僕はやっぱり、このかかしにはこのまま\n僕たちの側にいてもらいたいな。",
  str_homestory_822001001_36_dialog_content = "エヘヘ、PlayerNameお兄ちゃんなら、そういうと思った。",
  str_homestory_821901001_0_dialog_content = "どうかしたんですか？",
  str_homestory_821901001_1_dialog_content = "イスタバンさん…その様子は…",
  str_homestory_821901001_2_dialog_content = "時計が気に入ったんですか？",
  str_homestory_821901001_3_dialog_content = "こういう様式の時計は見たことがなくてな。",
  str_homestory_821901001_4_dialog_content = "空の末裔のものか？",
  str_homestory_821901001_5_dialog_content = "たぶん、そうだと思います。",
  str_homestory_821901001_6_dialog_content = "ソラヴァンの中にあるものは、全部空の末裔の様式ですから。",
  str_homestory_821901001_7_dialog_content = "これは機械ではない。影を利用した時計だな。",
  str_homestory_821901001_8_dialog_content = "まるで…",
  str_homestory_821901001_9_dialog_content = "影の芸術のようだな。",
  str_homestory_821901001_10_dialog_content = "この時計を本当に気に入ったんですね。",
  str_homestory_821901001_11_dialog_content = "過ぎた月日には、畏敬を抱かずにはいられん。",
  str_homestory_821901001_12_dialog_content = "だから、俺は様々な時計を集めているんだ。",
  str_homestory_821901001_13_dialog_content = "え？この世界には、何種類も時計があるんですか？",
  str_homestory_821901001_14_dialog_content = "白夜城の時計は古典的でロマンティックな様式を好む。",
  str_homestory_821901001_15_dialog_content = "北境はシンプルで実用的――",
  str_homestory_821901001_16_dialog_content = "R・W砂漠の時計はこった機械造りが特徴だ。",
  str_homestory_821901001_17_dialog_content = "そして影ノ街の時計は、控えめながら豪華なものが多い。",
  str_homestory_821901001_18_dialog_content = "そうなんですね。\nイスタバンさんは本当にコレクション好きなんですね。",
  str_homestory_821901001_19_dialog_content = "日用品にも、そんなにたくさんこだわりがあるとは知りませんでした。",
  str_homestory_821901001_20_dialog_content = "とても勉強になりました。",
  str_homestory_821901001_21_dialog_content = "コレクションの時計は皆、現代の産物だ。",
  str_homestory_821901001_22_dialog_content = "だが、空の末裔の時計は時の重みを感じさせてくれる。",
  str_homestory_821901001_23_dialog_content = "世界にたった一つというこの感覚は実に格別だ。",
  str_homestory_821901001_24_dialog_content = "うーん、そういうことなら…<sprite=emo_sikao size=60 />",
  str_homestory_821901001_25_dialog_content = "プレゼントします。",
  str_homestory_821901001_26_dialog_content = "なぜだ？",
  str_homestory_821901001_27_option_content = "友人だからです",
  str_homestory_821901001_28_dialog_content = "友情の証だというのか？",
  str_homestory_821901001_29_dialog_content = "実に誠実な答えだな。",
  str_homestory_821901001_30_option_content = "すごく気に入っているみたいなので。",
  str_homestory_821901001_31_dialog_content = "だとしても、他人の大切な物を奪うわけにはいかない。",
  str_homestory_821901001_32_dialog_content = "その気持ちには感謝するぞ。",
  str_homestory_821901001_33_dialog_content = "だが、この時計はこのまま「家」に置いておいてやろう。",
  str_homestory_821901001_34_dialog_content = "よく分かりません…気に入ったんじゃないですか？",
  str_homestory_821901001_35_dialog_content = "ここには他にも時計があるので…",
  str_homestory_821901001_36_dialog_content = "惜しみなく何でも友と分かち合おうとする気持ちは嬉しいが――",
  str_homestory_821901001_37_dialog_content = "この世界には、もっとこの時計にふさわしい場所がある。",
  str_homestory_821901001_38_dialog_content = "過ぎ去った時間は記憶になり、\nそして、記憶は歴史をつづっている。",
  str_homestory_821901001_39_dialog_content = "PlayerName、空の末裔の歴史は、\nこうした小さな物や事の数々の中に残されているのだ。",
  str_homestory_821901001_40_dialog_content = "ここにある物すべてが、お前にとって意味のあることなのさ。",
  str_homestory_821901001_41_dialog_content = "だから、ここから何一つとして持ち去りたくないのだよ。",
  str_homestory_821901001_42_dialog_content = "イスタバンさん…",
  str_homestory_821901001_43_dialog_content = "また会おう。影はいつも見つめている。",
  str_homestory_821801001_0_dialog_content = "シェオルさん？",
  str_homestory_821801001_1_dialog_content = "奇遇ね。ここで会えるなんて、今日はきっといいことがあるわ。",
  str_homestory_821801001_2_dialog_content = "あなたもそう思わない？",
  str_homestory_821801001_3_dialog_content = "奇遇？シェオルさん、ここは天空ノ庭ですけど…",
  str_homestory_821801001_4_dialog_content = "もちろん、分かっているわよ。",
  str_homestory_821801001_5_dialog_content = "でもね、何事も偶然が重なってこそうまくいくの。\n商売も、生活もね。",
  str_homestory_821801001_6_dialog_content = "すみません…よく分からないんですけど…",
  str_homestory_821801001_7_dialog_content = "だったら、説明してあげるわ。",
  str_homestory_821801001_8_dialog_content = "たとえば、天空ノ庭は今ちょうど改造の必要があったとして、\n浮遊商会もちょうど…",
  str_homestory_821801001_9_dialog_content = "その計画がある。",
  str_homestory_821801001_10_dialog_content = "奇遇だと思わない？",
  str_homestory_821801001_11_dialog_content = "つまり…？",
  str_homestory_821801001_12_dialog_content = "天空ノ庭は本当に特別な所ね。\nでも、宿舎が少し普通すぎやしないかしら？",
  str_homestory_821801001_13_option_content = "そうですか？",
  str_homestory_821801001_14_dialog_content = "ええ。でなかったら、わざわざそんなこと口にしないわ。",
  str_homestory_821801001_15_dialog_content = "あなたはもう慣れてしまって、感じないのかもしれないけれど――",
  str_homestory_821801001_16_dialog_content = "この宿舎は普通すぎて、天空ノ庭と合っていないわ。",
  str_homestory_821801001_17_option_content = "僕もそう思います",
  str_homestory_821801001_18_dialog_content = "さすがお得意様ね！",
  str_homestory_821801001_19_dialog_content = "だったら、行動を起こしてみない？",
  str_homestory_821801001_20_dialog_content = "たとえば、宿舎を改造するなんてどう？",
  str_homestory_821801001_21_dialog_content = "つまり、私が宿舎をもっと豪華にするのを手伝ってあげるわ。",
  str_homestory_821801001_22_dialog_content = "もっと…豪華に、ですか？",
  str_homestory_821801001_23_dialog_content = "いい案だとは思うんですが、予算に限りが<sprite=emo_baiyebi size=60 />…",
  str_homestory_821801001_24_dialog_content = "心配いらないわ！改造を浮遊商会に依頼してちょうだい！",
  str_homestory_821801001_25_dialog_content = "そうすれば、無料でこの宿舎を天空ノ庭に合った宿舎に造り変えてあげるわ。",
  str_homestory_821801001_26_dialog_content = "む、むむむ、無料…ですか！？",
  str_homestory_821801001_27_dialog_content = "それは良くないんじゃないですか？",
  str_homestory_821801001_28_dialog_content = "友だちだからって、そんなことすれば、\nシェオルさんが大損しちゃいます。",
  str_homestory_821801001_29_dialog_content = "知っているでしょ？私、損する商売はしないわ。",
  str_homestory_821801001_30_dialog_content = "宿舎の改造が終わったら、\n天空ノ庭全体をリゾートホテルにするの。",
  str_homestory_821801001_31_dialog_content = "リゾートホテル！？",
  str_homestory_821801001_32_dialog_content = "あなたは何もしなくていいわ。私に全部任せてくれればいいのよ。",
  str_homestory_821801001_33_dialog_content = "もしその気があるなら、財務を任せてもいいわ。\n腕が筋肉痛になるほど、お金を数えることになるわよ！",
  str_homestory_821801001_34_dialog_content = "腕が筋肉痛になるほどお金が入るんですか！？",
  str_homestory_821801001_35_dialog_content = "それが、さっき言っていた計画ってことですか！？",
  str_homestory_821801001_36_dialog_content = "確かに…心が揺らぎますね<sprite=emo_aixin size=60 />！",
  str_homestory_821801001_37_dialog_content = "そうでしょ！では、早速――",
  str_homestory_821801001_38_dialog_content = "ちょ、ちょっと待ってください！",
  str_homestory_821801001_39_dialog_content = "すみません。でも…今はまだ天空ノ庭を出来る限り、\nこのままにしておきたいんです。",
  str_homestory_821801001_40_dialog_content = "天空ノ庭の生態系に影響がないかどうかも確かめないうちに…",
  str_homestory_821801001_41_dialog_content = "リゾートホテルなんて建てたら…",
  str_homestory_821801001_42_dialog_content = "そう、分かったわ。",
  str_homestory_821801001_43_dialog_content = "つまり、将来的には観光業を発展させるつもりはあるってことよね？",
  str_homestory_821801001_44_dialog_content = "え？か、観光業ですか！？",
  str_homestory_821801001_45_dialog_content = "辛抱強く待っているわ。",
  str_homestory_822101001_0_dialog_content = "興味あります？",
  str_homestory_822101001_1_dialog_content = "興味津々な様子で、ここに長いこと立ってますよね。",
  str_homestory_822101001_2_dialog_content = "この家具ってまさか<sprite=emo_sikao size=60 />…",
  str_homestory_822101001_3_dialog_content = "自動的に分別回収できるゴミ箱？",
  str_homestory_822101001_4_dialog_content = "えっ！どうして分かるんですか？",
  str_homestory_822101001_5_dialog_content = "これは空の末裔仕様のゴミ箱で、普通のゴミ箱とは違うんです。",
  str_homestory_822101001_6_dialog_content = "そんな簡単には見分けられないと思ってました。",
  str_homestory_822101001_7_dialog_content = "フフン、あたしを見くびらないでね？",
  str_homestory_822101001_8_dialog_content = "じゃあ分析の過程を説明してあげるわ。",
  str_homestory_822101001_9_dialog_content = "まず、さっきこの家具の制御プログラムに侵入してざっと見たら…",
  str_homestory_822101001_10_dialog_content = "人の家具に何してくれるんですか？！",
  str_homestory_822101001_11_dialog_content = "使用したのは別のプログラミング言語で、簡潔で優れているわ。さすが空の末裔のハイテクね！",
  str_homestory_822101001_12_dialog_content = "でも機能的には、啓光食堂の自動配膳システムとの類似性が見られるわね。",
  str_homestory_822101001_13_dialog_content = "ここから、この家具にも同様の「分類」機能が搭載されていることがわかる。",
  str_homestory_822101001_14_dialog_content = "ちなみに、啓光食堂のプログラムはあたしが書いたものよ。",
  str_homestory_822101001_15_dialog_content = "栄養成分に基づいて自動的に食べ物を分類できるのよ！",
  str_homestory_822101001_16_dialog_content = "すごいですね。",
  str_homestory_822101001_17_dialog_content = "友人の家具に対する破壊欲求を下げてくれる栄養成分ってないですかね…",
  str_homestory_822101001_18_dialog_content = "…とにかく、「分類」からゴミ箱を連想できるだけでもすごいです。",
  str_homestory_822101001_19_dialog_content = "もう一つ決定的な理由があるの。",
  str_homestory_822101001_20_dialog_content = "へえ？",
  str_homestory_822101001_21_dialog_content = "この家具には、大きなゴミ箱のマークが描かれているのよ。",
  str_homestory_822101001_22_dialog_content = "…",
  str_homestory_822101001_23_dialog_content = "本当に不思議だわ！",
  str_homestory_822101001_24_dialog_content = "「自動分類」は大した技術ではないけれど。",
  str_homestory_822101001_25_dialog_content = "でも、これほどコンパクトなボディに自動分類システムを搭載するには――",
  str_homestory_822101001_26_dialog_content = "しかもこんなに細かく分類できるなんて…今の啓光の技術ではそこまでできない。",
  str_homestory_822101001_27_dialog_content = "空の末裔って、本当にすごい一族ね！",
  str_homestory_822101001_28_dialog_content = "…はぁ。",
  str_homestory_822101001_29_option_content = "本当にそんなにすごいんですか？",
  str_homestory_822101001_30_dialog_content = "ただのゴミ箱ですけど。",
  str_homestory_822101001_31_dialog_content = "「ただのゴミ箱」、一番すごいのがその部分よ。",
  str_homestory_822101001_32_option_content = "そんなに「自動リサイクル箱」が好きだったなんて",
  str_homestory_822101001_33_dialog_content = "おかげで僕まで鼻が高いです、へへ。",
  str_homestory_822101001_34_dialog_content = "誇りに思っていいのよ！",
  str_homestory_822101001_35_dialog_content = "最先端の科学技術は、誕生した当初はどれも軍事分野に応用されるの。",
  str_homestory_822101001_36_dialog_content = "それがうんと広く、当たり前のようになるまで普及してこそ、一般市民に恩恵がもたらされるのよ。",
  str_homestory_822101001_37_dialog_content = "この…「自動リサイクル箱」だっけ？はただのゴミ箱だからこそ…",
  str_homestory_822101001_38_dialog_content = "空の末裔文明の偉大さを存分に示しているんじゃない！",
  str_homestory_822101001_39_dialog_content = "おお…！考えてみると、確かにその通りですね！",
  str_homestory_822101001_40_dialog_content = "バックグラウンドプログラムへの侵入行為は少し引っかかりますけど…",
  str_homestory_822101001_41_dialog_content = "でもあなたと話していると、毎回本当にためになります。",
  str_homestory_822101001_42_dialog_content = "ありがとうございます、アルゴルさん。",
  str_homestory_822101001_43_dialog_content = "どういたしまして。お礼より、自動リサイクル箱を分解して徹底的に研究する許可をくれないかしら――",
  str_homestory_822101001_44_dialog_content = "そういうこと考えないでー！",
  str_homestory_822301001_0_dialog_content = "この石像……",
  str_homestory_822301001_1_dialog_content = "PlayerNameの洞窟で彫像を見るなど、珍しいのう。",
  str_homestory_822301001_2_dialog_content = "この彫像は、PlayerNameにとって特別な意味があるのか？",
  str_homestory_822301001_3_dialog_content = "バレちゃったか……これは空の末裔の女性の彫像だよ。",
  str_homestory_822301001_4_dialog_content = "空の末裔……そなたの一族じゃな。大昔の一族じゃ。",
  str_homestory_822301001_5_dialog_content = "この彫像から、わらわは長い歳月の息吹を感じたぞ。",
  str_homestory_822301001_6_dialog_content = "言い伝えでは、彼女は旅人で、大陸の景勝地を巡ったんだって。",
  str_homestory_822301001_7_dialog_content = "シンゲイが言うように、ずっとずっと前のことだよ……",
  str_homestory_822301001_8_dialog_content = "暗鬼<sprite=emo_kulou size=60 />がはびこるこの世界で、空の末裔が一人で旅をするのは危険だったんだ……",
  str_homestory_822301001_9_dialog_content = "わらわが傍にいれば、恐れることはあるまい？",
  str_homestory_822301001_10_dialog_content = "いつの日か、そなたもまた彫像となって後世に語り継がれるかもしれぬぞ。",
  str_homestory_822301001_11_dialog_content = "え？ぼ、僕が？まさか！僕はそんなにすごくないよ……",
  str_homestory_822301001_12_dialog_content = "そんなことはないぞ？例えば干ばつが起き、わらわが雨を降らし恩恵をもたらしたとしよう。",
  str_homestory_822301001_13_dialog_content = "PlayerNameはわらわを導き、麦芽糖を買いに行く……",
  str_homestory_822301001_14_dialog_content = "そうすれば、そなたはわらわと共に「竜神童子」として彫像になる！",
  str_homestory_822301001_15_dialog_content = "具体的で、実際に起きたことのように感じるよ……",
  str_homestory_822301001_16_dialog_content = "別の例として、わらわが冬の難破船から38人をまとめて救ったとしよう。",
  str_homestory_822301001_17_dialog_content = "善良で親切なそなたは、被災者に毛布を掛け、寒さで死なないよう火を焚く……",
  str_homestory_822301001_18_dialog_content = "これでそなたの彫像もわらわの横で、共に後代の供え物を楽しめるのじゃ。",
  str_homestory_822301001_19_dialog_content = "…",
  str_homestory_822301001_20_dialog_content = "どうした、こういう話はつまらないか？",
  str_homestory_822301001_21_option_content = "おもしろい",
  str_homestory_822301001_22_dialog_content = "でも悲しくもあるな。",
  str_homestory_822301001_23_option_content = "何とも言えない……",
  str_homestory_822301001_24_dialog_content = "面白いかどうかでは測り切れない気がする。",
  str_homestory_822301001_25_dialog_content = "だって、これは物語じゃないでしょ？",
  str_homestory_822301001_26_dialog_content = "僕が龍州にいた時、あちこちでシンゲイの彫像を見たよ。",
  str_homestory_822301001_27_dialog_content = "君が龍州各地で多くの人を助け、さっきのような言い伝えをたくさん残してきたのは想像に難くない。",
  str_homestory_822301001_28_dialog_content = "そして過去に君に麦芽糖を買ってくれた人や、人助けを手伝ってくれた人は……",
  str_homestory_822301001_29_dialog_content = "きっともうこの世にいない……君だけを残して。",
  str_homestory_822301001_30_dialog_content = "PlayerName、もしかして同情してくれているのか？",
  str_homestory_822301001_31_dialog_content = "言わせてもらうなら、僕は君が経験した別れを少し悲しんでるんだ……",
  str_homestory_822301001_32_dialog_content = "これってすごく傲慢で、竜神に対して失礼じゃないかな？",
  str_homestory_822301001_33_dialog_content = "そなたは生身の人間であり、そう思うのは自然なことじゃ。",
  str_homestory_822301001_34_dialog_content = "わらわのそなたへの思いもまた、ここにある。",
  str_homestory_822301001_35_dialog_content = "歳月は長く、やがて全てを奪っていく。",
  str_homestory_822301001_36_dialog_content = "たとえわらわが悠久の時を生きようとも、天地に比べれば小さなカゲロウに過ぎぬ。",
  str_homestory_822301001_37_dialog_content = "生きとし生けるもの全てがカゲロウである以上、しばし共に旅ができるということは縁であり、大切にせねばならぬ。",
  str_homestory_822301001_38_dialog_content = "もしわらわが人の短命を憐れむなら、それこそ傲慢というものじゃ。",
  str_homestory_822301001_39_dialog_content = "そう考えると納得がいくな……僕の気持ちも少し明るくなったよ。",
  str_homestory_822301001_40_dialog_content = "「心あれば時の隔たり恐れるに足らず」……龍州のことわざではこう言うんだっけ？",
  str_homestory_822301001_41_dialog_content = "その通りじゃ！PlayerName、このところずいぶん成長したのう。",
  str_homestory_822301001_42_dialog_content = "時とは残酷なものだが、良い面もあるのじゃ。",
  str_homestory_822301001_43_dialog_content = "へへ、<sprite=emo_qingsong size=60 />……やっぱり立ち止まっている時間はもったいないな。",
  str_homestory_822301001_44_dialog_content = "そして、もし時の流れがなかったら、そなたとわらわは出会えただろうか……",
  str_homestory_822301001_45_dialog_content = "またここで過去の話を持ちだしてどうする？",
  str_homestory_822401001_0_dialog_content = "ラショウ？",
  str_homestory_822401001_1_dialog_content = "ラショウ、これ使いたいの？",
  str_homestory_822401001_2_dialog_content = "もちろんだ！こいつは実によくできてる。",
  str_homestory_822401001_3_dialog_content = "よく……できてる？",
  str_homestory_822401001_4_dialog_content = "そうさ、見ろよ、この対戦欲を呼び起こす姿。",
  str_homestory_822401001_5_dialog_content = "柔らかさと硬さがちょうどいい。",
  str_homestory_822401001_6_dialog_content = "どれだけ叩いても元の位置に戻るという不思議な効果……",
  str_homestory_822401001_7_dialog_content = "拳を鍛える道具としては、まさに完璧だ！",
  str_homestory_822401001_8_option_content = "分かるよ",
  str_homestory_822401001_9_dialog_content = "やっぱりな<sprite=emo_guilian size=60 />、PlayerNameなら分かってくれると思ってた。",
  str_homestory_822401001_10_option_content = "よく分からない……",
  str_homestory_822401001_11_dialog_content = "俺もうまく説明できないが<sprite=emo_sikao size=60 />、武人としての直観か？",
  str_homestory_822401001_12_dialog_content = "龍州を旅していた時は、毎日の鍛練に苦労したもんだ。",
  str_homestory_822401001_13_dialog_content = "鍛練、修行、舞拳といったところだが。",
  str_homestory_822401001_14_dialog_content = "1日でも鍛練しないと、なまっちまうかもしれないし。",
  str_homestory_822401001_15_dialog_content = "でもな、鍛練は鍛練、目的は体を強化することだ。",
  str_homestory_822401001_16_dialog_content = "多くの人は鍛練の時、ヒイヒイ言いながらわざと自分を苦しめるのが好きだ。",
  str_homestory_822401001_17_dialog_content = "でもそんなの本末転倒だよ。",
  str_homestory_822401001_18_dialog_content = "その通り！",
  str_homestory_822401001_19_dialog_content = "「鉄山靠」という武術を練習するために、大樹相手にそれを叩き続ける人がいるようだ。",
  str_homestory_822401001_20_dialog_content = "実際、それはケガをしやすいし、とても賢いとは言えない。",
  str_homestory_822401001_21_dialog_content = "なるほど、また知識が増えた……",
  str_homestory_822401001_22_dialog_content = "旅をしていた頃は、適切な道具が見付からなかったから、木を使って練習したこともあった。",
  str_homestory_822401001_23_dialog_content = "若かったから、何も感じなかったのかもしれないけどな。",
  str_homestory_822401001_24_dialog_content = "アテイたちを指導し始めたのは、もっと後のことだ。",
  str_homestory_822401001_25_dialog_content = "俺のやり方で鍛練すると、アテイたちが非常にケガしやすいことに気付いた。",
  str_homestory_822401001_26_dialog_content = "この時ようやく分かったんだ、俺が過去に使ってきた道具や方法は乱暴すぎたんだって。",
  str_homestory_822401001_27_dialog_content = "それで、俺も防具といった守りの部分に気を配り、安全性を追求するようになった。",
  str_homestory_822401001_28_dialog_content = "ひいては、アテイたち専用の訓練道具まで作ったんだ……",
  str_homestory_822401001_29_dialog_content = "俺たちのロジックが通用しないあいつらのために道具をデザインするのは、本当に時間がかかった。",
  str_homestory_822401001_30_dialog_content = "特に梅花椿だ。あいつらの小さくて短い脚に合った間隔を見付けるのに、何度も試行錯誤を繰り返した。",
  str_homestory_822401001_31_dialog_content = "ラショウはこの部分にとても心を砕いてるんだね。",
  str_homestory_822401001_32_dialog_content = "当然さ。俺は体を鍛えることくらいしか趣味がないからな。",
  str_homestory_822401001_33_dialog_content = "友人のために道具を選ぶ時は、もちろん気を配るさ。",
  str_homestory_822401001_34_dialog_content = "今度機会があったら、PlayerNameに合った道具をデザインしてやるよ。",
  str_homestory_822501001_0_dialog_content = "あの明かりは…",
  str_homestory_822501001_1_dialog_content = "ティアラはあの庭園灯が好きなの？",
  str_homestory_822501001_2_dialog_content = "もう少し近くから見る？",
  str_homestory_822501001_3_dialog_content = "…これくらいの距離がちょうどいいの。",
  str_homestory_822501001_4_dialog_content = "ここから眺めてると、\n北境の「灯台」を思い出せるから。",
  str_homestory_822501001_5_dialog_content = "そう言われると確かに似てるね。",
  str_homestory_822501001_6_dialog_content = "でも残念。あれはただの明かりで\n「灯台」みたいに北境の生き物を守っていない。",
  str_homestory_822501001_7_dialog_content = "…",
  str_homestory_822501001_8_dialog_content = "子供の頃、よくスノーシダーの森のてっぺんから\n「灯台」を眺めてたんだ。",
  str_homestory_822501001_9_dialog_content = "灯台はとても明るくて…",
  str_homestory_822501001_10_dialog_content = "どんな夜更けでも、どれほど霧が深くても\nその光は四方を照らしていた。",
  str_homestory_822501001_11_dialog_content = "あの光に守られた森の中はとても静かだった。",
  str_homestory_822501001_12_dialog_content = "暗鬼の咆哮も、光霊の悲鳴もない…\nあの静けさはとても貴重だった。",
  str_homestory_822501001_13_dialog_content = "あれは私たち北境の者だけが持つ、\n特別な「灯台」なの。",
  str_homestory_822501001_14_dialog_content = "北境の人たちが「灯台」に心から感謝し、\n尊敬しているのは感じてたよ。",
  str_homestory_822501001_15_dialog_content = "でもね、みんなが感謝し、尊敬しているのは…\nあの「灯台」じゃないんだよ。",
  str_homestory_822501001_16_dialog_content = "ある日、狡猾な獲物を追っているとき、\n夢中で追いかけてしまい…",
  str_homestory_822501001_17_dialog_content = "暗闇から暗鬼の叫び声が聞こえたとき、\nようやく気づいたの。\n自分がかなり遠くまで来てるって…",
  str_homestory_822501001_18_dialog_content = "ちょうどその時、灯台の光が見えた。",
  str_homestory_822501001_19_dialog_content = "とても遠いところ…\nそこからも「灯台」の光が見えたの？",
  str_homestory_822501001_20_dialog_content = "…いいえ。私が見たのは\n私たちを守っている「灯台」じゃなかったの。",
  str_homestory_822501001_21_dialog_content = "あれは岬に立っている普通の灯台だった…",
  str_homestory_822501001_22_dialog_content = "夜になると、あの辺りは暗鬼の巣窟になる。",
  str_homestory_822501001_23_dialog_content = "たいへんだ…",
  str_homestory_822501001_24_dialog_content = "私は木の間に隠れたまま、身動きできなかった。",
  str_homestory_822501001_25_dialog_content = "灯台の光が時々私を通り過ぎる…",
  str_homestory_822501001_26_dialog_content = "灯台を眺めていると、暗鬼が周囲を歩き回っていた。",
  str_homestory_822501001_27_dialog_content = "その時、私がなにに気づいたか分かる？",
  str_homestory_822501001_28_dialog_content = "なに？",
  str_homestory_822501001_29_dialog_content = "あの灯台は、私が感謝し、尊敬している\n「灯台」と全く同じだったの。",
  str_homestory_822501001_30_dialog_content = "…",
  str_homestory_822501001_31_dialog_content = "同じような明るい光で、\n同じように夜の闇を照らし、濃霧も貫く…",
  str_homestory_822501001_32_dialog_content = "でも私を守ってはくれない。\nあの夜、私が少しでも動けば…",
  str_homestory_822501001_33_dialog_content = "私は暗鬼の群れに引き裂かれていたはず。",
  str_homestory_822501001_34_dialog_content = "ティアラ…",
  str_homestory_822501001_35_dialog_content = "あの夜、私は理解したの。",
  str_homestory_822501001_36_dialog_content = "「灯台」それ自体が、特別なわけじゃない。",
  str_homestory_822501001_37_dialog_content = "今私たちが見ているあの庭園灯が、\nごく普通の庭園灯であるように、\nあの灯台もごく普通の灯台。",
  str_homestory_822501001_38_dialog_content = "明かりを灯し、維持し、\n信念の力で光と成す人がいなければ、\nあれは何ものでもない。",
  str_homestory_822501001_39_dialog_content = "私たち北境の人々を守っているのは、\n北境の「灯台」じゃなくて…",
  str_homestory_822501001_40_dialog_content = "ベツレヘム女王陛下なんだって。",
  str_homestory_822501001_41_dialog_content = "…",
  str_homestory_822501001_42_option_content = "陛下の信念は人々に畏敬の念を抱かせる",
  str_homestory_822501001_43_dialog_content = "たとえ「灯台」がなくても、\n彼女は北境の人々を全力で守るだろう。",
  str_homestory_822501001_44_option_content = "ティアラの人生にとって重要な一夜になったんだ",
  str_homestory_822501001_45_dialog_content = "その夜、自分自身の信念をつかんだんだね。",
  str_homestory_822501001_46_dialog_content = "そうよ。",
  str_homestory_822501001_47_dialog_content = "女王陛下には全く追いつけないだろうけど、\nでも私は陛下の歩みについていくわ。",
  str_homestory_822501001_48_dialog_content = "守るために生きて、守るために戦う。",
  str_homestory_822501001_49_dialog_content = "僕も全く同じ考えだよ。",
  str_homestory_822501001_50_dialog_content = "特に「全く追いつけない」の部分。",
  str_homestory_822501001_51_dialog_content = "あはは、女王陛下に誰が追いつけるのよ？",
  str_homestory_822501001_52_dialog_content = "でも、陛下の後ろ姿が見えていれば、\n私は永遠に道を見失うことはないわ。",
  str_homestory_822601001_0_dialog_content = "あのさ…",
  str_homestory_822601001_1_dialog_content = "レイチェル、この木馬に興味ある？",
  str_homestory_822601001_2_dialog_content = "ちょっと子供っぽいけど、乗って揺らしてみると、意外と面白いよ。",
  str_homestory_822601001_3_dialog_content = "ちょっとやってみない？やってみようよ！",
  str_homestory_822601001_4_dialog_content = "いや…",
  str_homestory_822601001_5_dialog_content = "なんと言おうが、私はもうその歳ではないよ。",
  str_homestory_822601001_6_dialog_content = "君はよく、木馬に乗って遊んでいたのか？",
  str_homestory_822601001_7_dialog_content = "よ、よくってほどじゃないけど…",
  str_homestory_822601001_8_dialog_content = "（レイチェルは木馬に乗るのが\n恥ずかしいんだろうけど、\nこれじゃ僕だけがバカみたいだ！）",
  str_homestory_822601001_9_dialog_content = "しかし、これは確かに洗練された玩具だ。",
  str_homestory_822601001_10_dialog_content = "一見簡単に見えるが、\nデザインは合理的で、作りも精巧だ。",
  str_homestory_822601001_11_dialog_content = "構造力学的にも人間工学的にもお手本と言える。",
  str_homestory_822601001_12_dialog_content = "私も思わず見入ったよ。",
  str_homestory_822601001_13_dialog_content = "あー…君が言ったような視点で見たことがなかったよ。",
  str_homestory_822601001_14_dialog_content = "ちょっと見ただけで、\nそんなにたくさんのことが分かっちゃうんだ？",
  str_homestory_822601001_15_dialog_content = "これは工学の基本的なことだな。",
  str_homestory_822601001_16_dialog_content = "どんな物体でも、一目見れば三面図が描けるんだ。",
  str_homestory_822601001_17_dialog_content = "私には、この木馬がどのように\n作られたのかがほぼ分かる。",
  str_homestory_822601001_18_dialog_content = "それはもうほとんど超能力だよ…",
  str_homestory_822601001_19_dialog_content = "よし、この木馬は君にあげるよ！",
  str_homestory_822601001_20_dialog_content = "…えっ？",
  str_homestory_822601001_21_option_content = "持って帰った方が研究しやすいでしょ。",
  str_homestory_822601001_22_dialog_content = "分かった。私がこれ以上ここにいては\n迷惑だと言うことだな？",
  str_homestory_822601001_23_dialog_content = "そんなことないよ！",
  str_homestory_822601001_24_option_content = "君がそんなに気に入るのは珍しいと思って。",
  str_homestory_822601001_25_dialog_content = "一番気に入っているのは、君の巨像なんだが…",
  str_homestory_822601001_26_dialog_content = "ソラヴァンは持って行かないで！",
  str_homestory_822601001_27_dialog_content = "ふふ…冗談だよ。",
  str_homestory_822601001_28_dialog_content = "君の心遣いには感謝するが…",
  str_homestory_822601001_29_dialog_content = "妹へのプレゼントは、できれば自分の手で作りたい。",
  str_homestory_822601001_30_dialog_content = "…妹？",
  str_homestory_822601001_31_dialog_content = "うむ。この木馬を見たら、\n妹にそっくりなものを作ってあげたくなったんだ。",
  str_homestory_822601001_32_dialog_content = "私が子供の頃は、こんなおもちゃに\n触れる機会はなかったから、せめて妹には…",
  str_homestory_822601001_33_dialog_content = "私の自己満足かもしれないがな。",
  str_homestory_822601001_34_dialog_content = "レイチェル…",
  str_homestory_822601001_35_dialog_content = "さっき、僕が言ったことは本当だよ。",
  str_homestory_822601001_36_dialog_content = "木馬は…本当に面白いよ。\n君が想像もできないほどの面白さだ！",
  str_homestory_822601001_37_dialog_content = "え…ええ？",
  str_homestory_822601001_38_dialog_content = "だから試してみなよ！自分で乗ってみないと、\n妹さんに最高のプレゼントができないでしょ？",
  str_homestory_822601001_39_dialog_content = "さあ、遠慮せずに！",
  str_homestory_822601001_40_dialog_content = "じゃ…じゃあ…やってみるか。",
  str_homestory_822601001_41_dialog_content = "病みつきになること間違いないよ。",
  str_homestory_822701001_0_dialog_content = "ゼタ？",
  str_homestory_822701001_1_dialog_content = "これ一体何なの…？",
  str_homestory_822701001_2_dialog_content = "かわいくてかわいくてしようがない翼、見事な細工…",
  str_homestory_822701001_3_dialog_content = "勇者ゼタの鑑定によると、\nこれはきっと何か大昔の秘宝では？",
  str_homestory_822701001_4_dialog_content = "これはファルベプッペだよ。",
  str_homestory_822701001_5_dialog_content = "あ！空の末裔！奇遇だね。",
  str_homestory_822701001_6_dialog_content = "名前を知ってるってことは、\nこれについて研究してたってことだよね。",
  str_homestory_822701001_7_dialog_content = "ウィンデリオンの飾りだよ。",
  str_homestory_822701001_8_dialog_content = "ウィンデリオン？",
  str_homestory_822701001_9_dialog_content = "光霊にとって聖者をしのび、\n光明を祭る祝日に当たると言われているよ。",
  str_homestory_822701001_10_dialog_content = "聖者をしのび、光明を祭る？\nなんか超かっこよくない！？",
  str_homestory_822701001_11_dialog_content = "あたし、そんなかっこいい祝日が\nこの世にあることを知らなかったの？",
  str_homestory_822701001_12_dialog_content = "僕の友人も、本からこの祝日を知ったそうだよ。",
  str_homestory_822701001_13_dialog_content = "僕たち空の末裔にとっては、とても大事な祝日なんだ。",
  str_homestory_822701001_14_dialog_content = "だからこの日は大自然を祭って、\n盛大なパーティーをするんだ。",
  str_homestory_822701001_15_dialog_content = "うーん…祝日の過ごし方としては普通かな。",
  str_homestory_822701001_16_dialog_content = "ゴホン…とにかく、これは僕たちが\nウィンデリオンのために作った人形なんだ。",
  str_homestory_822701001_17_dialog_content = "このファルベプッペのお腹に、\n願い事とキャンディーを詰めるんだよ。",
  str_homestory_822701001_18_dialog_content = "願い事…そして…キャンディー！",
  str_homestory_822701001_19_dialog_content = "お祭りをやろう！今すぐウィンデリオンを祝いたい！",
  str_homestory_822701001_20_dialog_content = "どうしたの？急に興奮して。",
  str_homestory_822701001_21_dialog_content = "あたしもファルベプッペを作りたいの！",
  str_homestory_822701001_22_option_content = "お祭りの日じゃなくても、ファルベプッペは作れるよ。",
  str_homestory_822701001_23_dialog_content = "そうだね。じゃあ、ファルベプッペの作り方を教えて。",
  str_homestory_822701001_24_option_content = "いいよ、教えてあげる。",
  str_homestory_822701001_25_dialog_content = "本当！？空の末裔、あんた本当にいいやつだね！",
  str_homestory_822701001_26_dialog_content = "ふっふっふ、完成したら中にあたしの傑作を入れて…",
  str_homestory_822701001_27_dialog_content = "みんなが中に何が入っているのか気になってる時に…",
  str_homestory_822701001_28_dialog_content = "バチバチ！ドカーン！ブシュー！って\n煙とキャンディーをプレゼント！",
  str_homestory_822701001_29_dialog_content = "えっ？中に爆弾を入れるつもり？",
  str_homestory_822701001_30_dialog_content = "全部には入れないよ。\nキャンディーが飛び散る衝撃感が欲しいの！",
  str_homestory_822801001_0_dialog_content = "バティア！",
  str_homestory_822801001_1_dialog_content = "やっと出てきたね！",
  str_homestory_822801001_2_dialog_content = "うう～ん…君か…",
  str_homestory_822801001_3_dialog_content = "何か用？",
  str_homestory_822801001_4_dialog_content = "用はないけど、ずっとテントの中でゲームしてるから――",
  str_homestory_822801001_5_dialog_content = "一緒に息抜きでもしようかなって。",
  str_homestory_822801001_6_dialog_content = "すぅ…はぁ…",
  str_homestory_822801001_7_dialog_content = "はい、息したよ。じゃ、戻るね。",
  str_homestory_822801001_8_dialog_content = "ええ？ちょっと待ってよ！\nせめて外を少し散歩してから戻ろうよ。",
  str_homestory_822801001_9_dialog_content = "ううーん、外かぁ…",
  str_homestory_822801001_10_dialog_content = "バティアはそんなに外が嫌い？",
  str_homestory_822801001_11_dialog_content = "ここは…環境がいいと思うんだけど？",
  str_homestory_822801001_12_dialog_content = "違うよ！キライとかそういうんじゃないんだ…",
  str_homestory_822801001_13_dialog_content = "こ、ここは…影ノ街の街中より、ずっといいよ！",
  str_homestory_822801001_14_dialog_content = "そ、そう…影ノ街と比べて、か…",
  str_homestory_822801001_15_dialog_content = "うわぁっ！ご、ごめん、気に障ること言っちゃった！？",
  str_homestory_822801001_16_dialog_content = "でも、私…影ノ街しか知らないから…",
  str_homestory_822801001_17_dialog_content = "だったら、他の場所にも行ってみるといいよ。",
  str_homestory_822801001_18_option_content = "PlayerNameは…どこに行きたい？",
  str_homestory_822801001_19_dialog_content = "川岸",
  str_homestory_822801001_20_dialog_content = "どこか魚の獲れる川を探そうよ。",
  str_homestory_822801001_21_dialog_content = "おおおっ、『釣りマスター』の実戦版だね。",
  str_homestory_822801001_22_dialog_content = "でも…私にホンモノの魚が獲れるかな…",
  str_homestory_822801001_23_dialog_content = "あはは、確かにゲームとは勝手が違うよね。",
  str_homestory_822801001_24_option_content = "森",
  str_homestory_822801001_25_dialog_content = "森の中で木の実を採ったり、\n焚火して、キャンプ飯を作ろうよ！",
  str_homestory_822801001_26_dialog_content = "うーん…ちゃんと戦略を立てなきゃダメそうな遊びだね。",
  str_homestory_822801001_27_dialog_content = "前もって場所と流れを決めておいて、効率を上げないと…",
  str_homestory_822801001_28_dialog_content = "こういう遊びには、功績やポイントの仕組みはないんだよ…",
  str_homestory_822801001_29_dialog_content = "そう、分かった。じゃ、やってみよっか…",
  str_homestory_822801001_30_dialog_content = "ただ、このテントも持って行っていい？",
  str_homestory_822801001_31_dialog_content = "疲れたら、中にこもってゲームできるし…",
  str_homestory_822801001_32_dialog_content = "うーん…特に問題ない気はするな…",
  str_homestory_822901001_0_dialog_content = "ビクトリア、どうしてそのハンギングチェアをずっと見つめているの？",
  str_homestory_822901001_1_dialog_content = "何かおかしなところでもあるの？",
  str_homestory_822901001_2_dialog_content = "真理結社にも同じようなハンギングチェアがあったと思い出していただけよ。",
  str_homestory_822901001_3_dialog_content = "彼らが一番気に入っていた椅子なの。",
  str_homestory_822901001_4_dialog_content = "彼らは？",
  str_homestory_822901001_5_dialog_content = "そのハンギングチェアの前を通り過ぎたりすることがあるが、\n10回中8回はベリエがその中で本を読んでいるわ。",
  str_homestory_822901001_6_dialog_content = "残りの2回は、彼女が本を枕にして眠っているの。",
  str_homestory_822901001_7_dialog_content = "それじゃあベリエに占領されているじゃないか！",
  str_homestory_822901001_8_dialog_content = "たまに、その周りを回るエルシーを見かけたわ。",
  str_homestory_822901001_9_dialog_content = "そして普通の人には理解しがたい言葉をつぶやいているの。\nたとえば……",
  str_homestory_822901001_10_dialog_content = "「クッションと背もたれに鉄のトゲを付ければ、\n完璧な拷問具になるよね！」",
  str_homestory_822901001_11_dialog_content = "……彼女が行動に移す前に、そのハンギングチェア……\nそしてベリエを守ってあげてよ！",
  str_homestory_822901001_12_dialog_content = "エルシーがそう思うのも無理ないわ。",
  str_homestory_822901001_13_dialog_content = "ハンギングチェアにネイルスの血が飛び散ったとき、\nたしかに拷問具に……見えたから。",
  str_homestory_822901001_14_dialog_content = "ネイルスまで！？",
  str_homestory_822901001_15_dialog_content = "ネイルスのことも責められないわ。たしかに快適な椅子だもの。",
  str_homestory_822901001_16_dialog_content = "私たち敬虔な苦行者でも、時には座りたいと思うこともあるわ。",
  str_homestory_822901001_17_dialog_content = "…",
  str_homestory_822901001_18_dialog_content = "それで……ビクトリアだけは一度も座ったことがないの？",
  str_homestory_822901001_19_dialog_content = "思い返してみると、たしかにそうね。",
  str_homestory_822901001_20_dialog_content = "……私は意識的にそれを避けていたのかもしれないわね。",
  str_homestory_822901001_21_dialog_content = "避けるって……椅子を？",
  str_homestory_822901001_22_dialog_content = "それはワラーキの旧宅にあったハンギングチェアで、\n以前は私の父のものだったの。",
  str_homestory_822901001_23_dialog_content = "ファウストが何を思ったのか、わざわざ持ち帰って私に返してくれたのよ。",
  str_homestory_822901001_24_dialog_content = "それを見ると、両親や子ども時代、\nそしてワラーキの避けられない運命を思い出してしまうの。",
  str_homestory_822901001_25_dialog_content = "私は……そうしたことを常に思い出したいわけではないから。",
  str_homestory_822901001_26_dialog_content = "ファウストもお節介がすぎるね",
  str_homestory_822901001_27_dialog_content = "彼は運命に向き合うことも真理の一環だと、\n私に言いたかったのかもしれないわ。",
  str_homestory_822901001_28_dialog_content = "何しろ子ども時代の思い出だからね",
  str_homestory_822901001_29_dialog_content = "思い出には苦痛もあるけど、\n楽しかったこともあるでしょう？",
  str_homestory_822901001_30_dialog_content = "ええ、たしかに。父が私を抱いてハンギングチェアで本を読んでくれたのは、\n素敵な思い出よ。",
  str_homestory_822901001_31_dialog_content = "でも、最近のいろいろな出来事を経験して分かったの。",
  str_homestory_822901001_32_dialog_content = "過去の苦痛は私の心の中にしか存在しないと。",
  str_homestory_822901001_33_dialog_content = "私がそれを克服すれば、\nハンギングチェアはただのハンギングチェアでしかない。",
  str_homestory_822901001_34_dialog_content = "あなたの自然な知恵が示す通り――",
  str_homestory_822901001_35_dialog_content = "私はこれを見つめるのではなく、\n心地よく座るべきなのね。",
  str_homestory_822901001_36_dialog_content = "……そ、そうだよ。それが僕の言いたかったことだよ！",
  str_homestory_822901001_37_dialog_content = "さあ、座って。\n僕のハンギングチェアはいつでも君を歓迎するよ。",
  str_homestory_822901001_38_dialog_content = "じゃあ、先にお礼を言わせてもらうわね、PlayerName。",
  str_homestory_823001001_0_dialog_content = "この家の見た目は奇妙でしょう？",
  str_homestory_823001001_1_dialog_content = "でも、見た目に惑わされないで。\n中は意外と快適なんだよ！",
  str_homestory_823001001_2_dialog_content = "「奇妙」？まさか……",
  str_homestory_823001001_3_dialog_content = "塔のような構造といい、窓の並び方といい、\nまるで小さな城のようです。",
  str_homestory_823001001_4_dialog_content = "もし許してもらえるなら、たまにここで修行したいくらいです。",
  str_homestory_823001001_5_dialog_content = "いいよ！",
  str_homestory_823001001_6_dialog_content = "いつでも来て。",
  str_homestory_823001001_7_dialog_content = "いいけど…",
  str_homestory_823001001_8_dialog_content = "ただ、家の中では流血事件を起こさないと約束してね……",
  str_homestory_823001001_9_dialog_content = "あなたの寛大さに対して心から感謝します。",
  str_homestory_823001001_10_dialog_content = "そういえば、ヴィルヘルムさんはずっと城の中で修行をしているんだよね？",
  str_homestory_823001001_11_dialog_content = "……！ま、まさしく……どうして急に導師の話を？",
  str_homestory_823001001_12_dialog_content = "思ったんだけど、君が「城のような」部屋で修行したいというのは……",
  str_homestory_823001001_13_dialog_content = "ヴィルヘルムさんの影響を受けたからなの？",
  str_homestory_823001001_14_dialog_content = "…",
  str_homestory_823001001_15_dialog_content = "うそをつくのは罪です。見破られた以上は認めるしかありません。",
  str_homestory_823001001_16_dialog_content = "たしかに少しだけ……導師を……真似したいと思いました。",
  str_homestory_823001001_17_dialog_content = "導師にはもうそのようなことはしないと約束したのですが。",
  str_homestory_823001001_18_dialog_content = "私のような小者が導師のようになりたいなど、大きな罪です！\n私は――",
  str_homestory_823001001_19_dialog_content = "そんなことないよ！尊敬する人を真似したいと思うのは普通のことでしょ？",
  str_homestory_823001001_20_dialog_content = "君はどんなことを真似したの？",
  str_homestory_823001001_21_dialog_content = "私…",
  str_homestory_823001001_22_dialog_content = "……髪の毛を……伸ばそうとしてみました。",
  str_homestory_823001001_23_dialog_content = "…",
  str_homestory_823001001_24_dialog_content = "しかし、私の髪質は長髪に向いていないようでした。\nスズメが巣だと勘違いしてしまったのです……",
  str_homestory_823001001_25_dialog_content = "ざんげが終わる頃には、私の頭でひながふ化していました。",
  str_homestory_823001001_26_dialog_content = "そのざんげはすごく長かったんだね……",
  str_homestory_823001001_27_dialog_content = "髪を切った後は、導師のように夜も寝ずに勉強しようとしました。",
  str_homestory_823001001_28_dialog_content = "その結果、歩きながら寝てしまい、階段から転げ落ちました……",
  str_homestory_823001001_29_dialog_content = "ちょっと！",
  str_homestory_823001001_30_dialog_content = "導師の剣「赤流」はとてもカッコいいと思います。",
  str_homestory_823001001_31_dialog_content = "ある日、自分の血で「赤流」を真似しようとしたとき、\nついに導師が止めに入りました。",
  str_homestory_823001001_32_dialog_content = "ああ！きっとヴィルヘルムは君に\n「君は君らしくいればいい」って言ったんでしょう？",
  str_homestory_823001001_33_dialog_content = "導師は私に「ネイルス、顔をあげるのだ。何が見える？」と優しく尋ねました。",
  str_homestory_823001001_34_dialog_content = "私は「空です。導師、真理の主がそこで私たちを見守っています」\nと答えました。",
  str_homestory_823001001_35_dialog_content = "導師はさらに「なぜ私たちに空が見えるか分かるか？」と聞きました。",
  str_homestory_823001001_36_dialog_content = "私は「主がそれを創造したからです」と答えました。",
  str_homestory_823001001_37_dialog_content = "導師は「君の『赤流』が私たちの屋根を削ったからだ」とおっしゃいました。",
  str_homestory_823001001_38_dialog_content = "……",
  str_homestory_823001001_39_dialog_content = "私は自分の罪を深くざんげしました。",
  str_homestory_823001001_40_dialog_content = "そして悟りました。私は導師から最も学ぶべきことを学んでいなかったと。",
  str_homestory_823001001_41_dialog_content = "導師は常に自分の信念を貫き、決して曲げませんでした。",
  str_homestory_823001001_42_dialog_content = "私も導師のように、本来の自分の姿で生きるべきだったのです。",
  str_homestory_823001001_43_dialog_content = "今の一連の災い……\nじゃなくて、出来事からその結論に達したわけだね……",
  str_homestory_823001001_44_dialog_content = "君は悟る能力が非常に高いのかもしれないよ……",
  str_homestory_823001001_45_dialog_content = "温かい言葉に感謝します、PlayerName。",
  str_homestory_823001001_46_dialog_content = "お礼に、私はいつでもこの小さな城で、\nあなたのざんげを聞きましょう。",
  str_homestory_823001001_47_dialog_content = "オホン、思いついたら話すね！",
  str_homestory_823101001_0_dialog_content = "ヴィルヘルムさん、どうしてずっとこの東屋を見ているんですか？\n中には何もありませんよ。",
  str_homestory_823101001_1_dialog_content = "君のこの東屋の下にも、謎が隠されているのではないかと考えていたのだ。",
  str_homestory_823101001_2_dialog_content = "謎？ま、まさか……どうしてそう思うんですか？",
  str_homestory_823101001_3_dialog_content = "荒野にぽつんと立つ東屋は、自然と冒険や謎に結びついているように思える。",
  str_homestory_823101001_4_dialog_content = "多くの伝説や物語に似たような話がある。",
  str_homestory_823101001_5_dialog_content = "そのことに啓発され、昔、ビクトリアに謎を出したことがある。",
  str_homestory_823101001_6_dialog_content = "あ、東屋で？",
  str_homestory_823101001_7_dialog_content = "まず、私は彼女を少し怒らせた――",
  str_homestory_823101001_8_dialog_content = "どうしてそんなことをするんですか！？",
  str_homestory_823101001_9_dialog_content = "それは簡単だ。彼女はもともと私に敵意を抱いていたからだ。",
  str_homestory_823101001_10_dialog_content = "しかし、彼女が「悪魔、地獄に落ちろ！」と叫びながら、\n目を赤くして逃げていったことからすると……",
  str_homestory_823101001_11_dialog_content = "私は少しやりすぎたのかもしれん。",
  str_homestory_823101001_12_dialog_content = "ビクトリアも昔は……元気……だったんですね。",
  str_homestory_823101001_13_dialog_content = "それから、私は故意にいくつかの手がかりを残し、\n彼女にワラーキ家に代々伝わる宝があると思わせた。",
  str_homestory_823101001_14_dialog_content = "それを見つけさえすれば、私を倒し、当主の座を奪い返せると。",
  str_homestory_823101001_15_dialog_content = "二人の関係って、どれだけ歪んでいるんですか……",
  str_homestory_823101001_16_dialog_content = "彼女は私が思った通りに手がかりを解読し、\n正しい結論を導き出した――",
  str_homestory_823101001_17_dialog_content = "「代々伝わる宝」の位置情報は、庭の奥深くにある東屋に刻まれていると。",
  str_homestory_823101001_18_dialog_content = "その後は……",
  str_homestory_823101001_19_dialog_content = "もちろん、東屋を見つけただけで終わりではない。",
  str_homestory_823101001_20_dialog_content = "彼女は東屋の石板に刻まれた謎を解き、\n最終的な宝の場所を見つけなければならなかった。",
  str_homestory_823101001_21_dialog_content = "ついでに言うと、その石板のダメージ加工には非常に満足していた。",
  str_homestory_823101001_22_dialog_content = "…",
  str_homestory_823101001_23_dialog_content = "その石板の謎……ヴィルヘルムさんが出したものなんですか？\nどんな謎だったんですか？",
  str_homestory_823101001_24_dialog_content = "大したものではない。歴史の常識や神話、\nそれといくつかの数学の問題だ。",
  str_homestory_823101001_25_dialog_content = "家で1週間ほど本を読めば、簡単に解けるはずだ。",
  str_homestory_823101001_26_dialog_content = "この話の結末は絶対によくないと思うんですが……",
  str_homestory_823101001_27_dialog_content = "それは君の見方次第だ。彼女は成功した。\n彼女には簡単すぎると分かっていた。",
  str_homestory_823101001_28_dialog_content = "しかし、「宝」を見つけた後、\n彼女がなぜあんなにも怒ったのかはたしかに理解できなかった……",
  str_homestory_823101001_29_dialog_content = "先に聞きますが、何を「宝」として埋めたんですか？",
  str_homestory_823101001_30_dialog_content = "ビクトリアの大好きなハチミツだ。その年の取れたてを丸ごと一瓶。",
  str_homestory_823101001_31_dialog_content = "それだけですか！？",
  str_homestory_823101001_32_dialog_content = "それでは不十分か？\n『反抗期の少女との付き合い方』には、はっきりとこう書かれている――",
  str_homestory_823101001_33_dialog_content = "「彼女の好きなものを用意しましょう。\n甘いものなら絶対に間違いありません」",
  str_homestory_823101001_34_dialog_content = "どこに問題があるのかさっぱり分からぬ。",
  str_homestory_823101001_35_dialog_content = "それならどうして直接ハチミツをあげなかったんですか！？",
  str_homestory_823101001_36_dialog_content = "彼女が私に敵意を抱いていることを忘れたか？",
  str_homestory_823101001_37_dialog_content = "彼女と挑発し合うのは退屈ではないが、疲れるのはたしかだ。",
  str_homestory_823101001_38_dialog_content = "他のことで彼女の注意力を分散させるのは歓迎だ。",
  str_homestory_823101001_39_dialog_content = "ビクトリアは1週間も歴史や神話、数学を勉強し、\n大変な思いをして考え、期待に満ちていたのに……",
  str_homestory_823101001_40_dialog_content = "最後に見つけたものが新しいハチミツだけなんて、\nまるでだまされたことを嘲笑っているようなものですよ……",
  str_homestory_823101001_41_dialog_content = "どうしてビクトリアが怒ったのか、\nまだ分からないんですか？",
  str_homestory_823101001_42_dialog_content = "……たしかに君の言うことにも一理ある。",
  str_homestory_823101001_43_dialog_content = "しかし、だからといって当主会合の前に、\n私の椅子にこっそりハチミツを塗ることはないだろう――",
  str_homestory_823101001_44_dialog_content = "おかげでその日の午前中はずっと、\n素知らぬ顔で会議を開かなければならなかった！",
  str_homestory_823101001_45_dialog_content = "君はどう思う？",
  str_homestory_823101001_46_dialog_content = "自業自得です",
  str_homestory_823101001_47_dialog_content = "因果応報です",
  str_homestory_823101001_48_dialog_content = "ぐぬぬ……"
}
return config
